-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = LegionChineseDB
D.Strings[109744]="我身后的是虚空之光熔炉。它是这个世界的古老遗物，曾为这个世界提供了大量魔力。$B$B虽然它的潜力被许多人视为一种恩赐，但强化它却需要巨大的牺牲……以及光与影的微妙平衡。"
D.Strings[109745]="你被军团战舰发现了。快跑，别被瞄准了。"
D.Strings[109746]="至少腐蚀停止了！"
D.Strings[109747]="麦格尼？你没事吧？麦格尼？"
D.Strings[109748]="必须保住艾泽拉斯……不惜一切！"
D.Strings[109749]="我们的胜利毫无意义。只要阿古斯之魂还在萨格拉斯手里，艾泽拉斯就依然危险。"
D.Strings[109750]="将一块拉长石放进空洞。"
D.Strings[109751]="你看到了一个空洞，刚好能放进一块阿古斯晶石。"
D.Strings[109752]="你看到了一个空洞，刚好能放进一块拉长石。"
D.Strings[109753]="我们将共同组成燃烧军团，击败想要吞噬我们的饥饿虚空。"
D.Strings[109754]="请你……保护好我的家人。"
D.Strings[109755]="生命的缚誓者很快就会现身。她逃不掉的，主人！"
D.Strings[109756]="一旦他们堕落，萨格拉斯就有足够的力量夺取最后一位泰坦了。"
D.Strings[109757]="我受够那个蝼蚁的唠叨了！让我烧焦他的血肉吧！"
D.Strings[109758]="它们马上就能投入使用了。感谢你找回它们。"
D.Strings[109759]="我的最高指挥官洛萨克森被派去协助白银之手保卫艾泽拉斯……并带你们来此。"
D.Strings[109760]="没有希望。只有痛苦。痛苦！"
D.Strings[109761]="但你的盟友从军团手中救出了许多我的同胞。或许你也变了。"
D.Strings[109762]="你们让我……想要……"
D.Strings[109763]="烈焰……会……吞噬你们……"
D.Strings[109764]="暗影饿了！"
D.Strings[109765]="必须让安托鲁斯的恶魔明白，我们是无所不能的。带上战争机甲，到敌后去打击目标吧！"
D.Strings[109766]="每少一个飞行员，就能少一艘飞船，维迪卡尔的护盾就能少受一次轰击。干得好！"
D.Strings[109767]="你烧掉了那些军团渣滓的破屋子，为我们肃清了道路。干得好！"
D.Strings[109768]="黑暗的爪牙！见识一下泰坦的力量吧！"
D.Strings[109769]="我们部队的勇气从未动摇，但即使最有经验的士兵也会疲惫。去前线展示你的实力，鼓舞一下士气吧！"
D.Strings[109770]="滚开，入侵者！滚回你主子那去！"
D.Strings[109771]="自由……自由……"
D.Strings[109772]="要反抗、要战斗、要活下去。"
D.Strings[109773]="……召唤那些想占有这些力量的人。"
D.Strings[109774]="小心，不要单独挑战征服者。我在这里都能感应到他们的力量。"
D.Strings[109775]="你们清除了这一带的虚空力量。干得好。"
D.Strings[109776]="这里游荡着某个邪恶的存在。英雄们，去找到并消灭它。"
D.Strings[109777]="我们已经胜利了。"
D.Strings[109778]="天启降临了！"
D.Strings[109779]="来吧，我带你去圣光穹顶。其他人正在等着我们呢。"
D.Strings[109780]="那就这样吧。军团的大军分散在他们征服的各个世界中。在完成任务前，我们得防止他们回防阿古斯。"
D.Strings[109781]="我们可以行动了。准备开火！"
D.Strings[109782]="我们不能因此而止步。圣光裁决者是我们获胜的关键。"
D.Strings[109783]="它就快完成了，但还缺个能量源。我们需要非常强大的能量源。"
D.Strings[109784]="让他们感受你的怒火吧！"
D.Strings[109785]="部落满足你们的这个要求了吗？"
D.Strings[109786]="入侵者正在给武器充能。快！用传送门登上他们的船，阻止他们进攻！"
D.Strings[109787]="那个结果让我相信，我们一定会胜利。"
D.Strings[109788]="我们的世界正命悬一线。"
D.Strings[109789]="不要无所事事。"
D.Strings[109790]="那我得趁机好好体会这种感觉。感谢你的忠告，卡德加。"
D.Strings[109791]="我从来没见过这样的地方，卡德加。这里流淌的力量……"
D.Strings[109792]="阿古斯是个充满力量的世界。军团利用过它……现在该轮到我们了。"
D.Strings[109793]="维迪卡尔将成为我们复仇的武器。但不管你选择什么武器，都得在再次投入战斗前彻底了解它。"
D.Strings[109794]="那家伙没什么好吹的，除了死得够快之外。"
D.Strings[109795]="敌人也将尝到我们的痛苦。"
D.Strings[109796]="现在，高声欢呼，赞美萨格拉斯吧！"
D.Strings[109797]="军团以为自己已经牢牢占据了阿古斯。去用痛苦回敬他们的傲慢吧！"
D.Strings[109798]="萨格拉斯抢走了那么多。现在该轮到他倒霉了！"
D.Strings[109799]="我们夺不回曾属于我们的一切，但能让他们付出代价。"
D.Strings[109800]="了不起的战术。难怪军团会害怕你。"
D.Strings[109801]="我们将逐步蚕食军团的中坚力量。"
D.Strings[109802]="斥候发现一个重要目标。拿起武器！"
D.Strings[109803]="恶魔聚集到了他们的勇士身后。去打倒它！"
D.Strings[109804]="我们的部分士兵被军团俘虏了。恶魔会折磨他们……甚至更糟。你必须带头去营救他们！"
D.Strings[109805]="我们不会倒下。"
D.Strings[109806]="我们绝不放弃。"
D.Strings[109807]="不可能。她是纳鲁！是圣光生物！"
D.Strings[109808]="就是它。"
D.Strings[109809]="许多来此寻找力量的冒险者都最后都埋骨沙漠了。去让这些恶魔也加入他们的行列吧。"
D.Strings[109810]="军团自以为控制了这些岛屿。去让这个渣滓明白，我们可以夺走他们的一切。"
D.Strings[109811]="许多来此寻找力量的冒险者最后都埋骨沙漠了。让这些恶魔也加入他们的行列吧。"
D.Strings[109812]="这个冰封的世界拥有危险的力量。不能让军团得到它。"
D.Strings[109813]="很好，勇士们。无论他们的腐蚀传播到哪里，都会被我们阻止。"
D.Strings[109814]="黑夜之中，仍有希望闪耀。"
D.Strings[109815]="我们的事业是正义的，我们的目标是高尚的。"
D.Strings[109816]="目前，你的努力还……不够。"
D.Strings[109817]="他们掌握着超乎想象的力量。维迪卡尔抵挡不住他们的攻击。"
D.Strings[109818]="这些机器的主人隐藏了它们的真实实力。小心点。"
D.Strings[109819]="击溃它，驯服它。如果你没这本事，就毁了它。"
D.Strings[109820]="你还不明白吗？没有邪能，暗影就会获胜！"
D.Strings[109821]="部队坚持要我花点时间来照顾伤员。你就代我上阵杀敌吧。"
D.Strings[109822]="这些炸药经过了改装，能够增强邪能。效果应该会非常……壮观。"
D.Strings[109823]="你做什么都无所谓，凡人。我们的军团无穷无尽。"
D.Strings[109824]="先别急。我们得测试一下这种新力量的极限。来吧。"
D.Strings[109825]="即使被击败了，它依然涌动着能量。我听到暗影在召唤我。"
D.Strings[109826]="虚空是一种转换之力。暗影是流动的，不断变幻的。"
D.Strings[109827]="对，这很有用。你能在神殿的入口附近找到他们的总督，但他进不去的。"
D.Strings[109828]="影卫就盘踞在附近的神殿里。"
D.Strings[109829]="这是一个转折点。如果能激活竞技场的防御系统，战斗就结束了。"
D.Strings[109830]="我们必须帮助这些幽灵成功逃离。"
D.Strings[109831]="你们不配自称艾瑞达！"
D.Strings[109832]="我不是一个人。艾瑞达……必胜……"
D.Strings[109833]="我……要……杀光你们！"
D.Strings[109834]="让痛苦拥抱你！"
D.Strings[109835]="啊，阴影的痛苦！"
D.Strings[109836]="算了吧。你们仍然对身边的黑暗视而不见。"
D.Strings[109837]="算了吧。你们仍然对于身边真正的黑暗视而不见。"
D.Strings[109838]="废物！这点痛苦都受不了，还不及我承受的万分之一。"
D.Strings[109839]="拔剑吧！来尝尝痛苦的滋味！"
D.Strings[109840]="这家伙一定能成为我们的杰出勇士。他或许还可以被转化。"
D.Strings[109841]="虽然我渴望力量，但这家伙对它的摸索还很业余。"
D.Strings[109842]="你闻到了吗？疯狂的甜美香气！唔……这地方已经被它吞噬了。"
D.Strings[109843]="这块石头散发着能量。"
D.Strings[109844]="祝你早日见到麦格尼。希望他能有好消息。"
D.Strings[109845]="让我看看你们能跑多快。"
D.Strings[109846]="需要先肢解。"
D.Strings[109847]="去跟维迪卡尔汇合，为最后一战做准备吧。"
D.Strings[109848]="我将重返……虚空。"
D.Strings[109849]="排气口"
D.Strings[109850]="提示一下：那是个具有力量的古老词汇。如果我在你耳边说出它，你就会陷入疯狂。还想玩下去吗？"
D.Strings[109851]="勇士们，我们拖住这些会飞的野兽，你们来打开通道。"
D.Strings[109852]="我查到你的坐标了，勇士。校准传送矩阵需要一点时间。在那之前，别让它落入军团之手！"
D.Strings[109853]="是的，我当然还爱他。你非要这么八卦吗？"
D.Strings[109854]="他们的阵型崩溃了。我们得再接再厉。"
D.Strings[109855]="阿克蒙德还是个学徒时就能做到了。这能有多难？"
D.Strings[109856]="我们最好还是私下讨论。"
D.Strings[109857]="我们得到了石头才能休息！"
D.Strings[109858]="安托鲁斯注视着你们。找到先知，否则后果自负！"
D.Strings[109859]="毁灭者会找到你……"
D.Strings[109860]="肯定轮到你了。不要质疑精灵的记性……哪怕是过去了一千年。"
D.Strings[109861]="我同意。虽然过去好久了，但我记得该你买单了，卡德加。"
D.Strings[109862]="无处可逃了！"
D.Strings[109863]="库德兰和达纳斯也没事吧？"
D.Strings[109864]="我太累了。"
D.Strings[109865]="我们没能逃走。"
D.Strings[109866]="维伦……为什么？"
D.Strings[109867]="我会不断……重生……"
D.Strings[109868]="安托鲁斯向你问好！"
D.Strings[109869]="你以为能击败我们？在这里？哈！"
D.Strings[109870]="我要把你们切成两半，换取双倍的赏金！"
D.Strings[109871]="我是不会浪费这个向前辈学习的机会的。感谢你的帮助。"
D.Strings[109872]="哼，我还以为你这次肯定完不成试炼了。按照规则，我必须承认你成功了。恭喜。"
D.Strings[109873]="这里的强大野兽足以让任何猎人心痒难耐，但影卫还想用虚空进一步强化他们。阻止那些虚灵，让那些野兽重归荒野吧。"
D.Strings[109874]="军团的部队占据了玛凯雷的土地。去激活那些贵族的卫兵帮我们战斗吧。它们的能量水晶肯定是被艾瑞达偷走了。"
D.Strings[109875]="我盼着有一天能够彻底离开这个破碎之地。或许只有那样，他们才能安息。"
D.Strings[109876]="没有时间庆祝胜利了。鲁拉的黑暗颂歌还在我脑海中回响。"
D.Strings[109877]="起码我们知道它去哪儿了。"
D.Strings[109878]="我们距离解锁维迪卡尔的真正力量又近了一步。现在只剩知识桂冠了。然后执政团之冠就能复原。"
D.Strings[109879]="当阿古斯在视线中变得越来越小的时候，我曾乞求纳鲁返航。"
D.Strings[109880]="我把逃跑的计划告诉他，让他带着我的家人来找我。可他去找了基尔加丹。"
D.Strings[109881]="蠢货，你竟敢来这儿！"
D.Strings[109882]="阿古斯将成为你的坟墓。"
D.Strings[109883]="痛苦不算什么……"
D.Strings[109884]="我也不喜欢那样。"
D.Strings[109885]="说出你的目的。"
D.Strings[109886]="盯紧你的目标。"
D.Strings[109887]="圣光欢迎你，勇士。"
D.Strings[109888]="我随身携带着它的三个部件之一，就是先知之眼，从不离身。"
D.Strings[109889]="无处可逃了。"
D.Strings[109890]="需要我帮忙消灭敌人吗？"
D.Strings[109891]="你们都没救了，叛徒！"
D.Strings[109892]="我们会不惜一切代价消灭你！"
D.Strings[109893]="敌人又进攻了！小心！"
D.Strings[109894]="好吧。一路走好，塔尔加斯。"
D.Strings[109895]="<维伦目不转睛地凝视着面前的雕像。>"
D.Strings[109896]="占据她的暗影，奥蕾莉亚！按我教的做！"
D.Strings[109897]="损失太惨重了……我们得扩编部队了。"
D.Strings[109898]="如果你掩护我们撤退，或许能够成功。"
D.Strings[109899]="你的尸体我收下了。"
D.Strings[109900]="烧焦了。"
D.Strings[109901]="你们还是死在这里比较好，起码不会被她控制。"
D.Strings[109902]="别动，小家伙。我们在这里很安全。"
D.Strings[109903]="<特拉蒙放下长剑，期待地看着你。>"
D.Strings[109904]="你们的尖叫能让我的赏金翻倍。"
D.Strings[109905]="看来我是……多余的。"
D.Strings[109906]="这就是你们的计划？"
D.Strings[109907]="又有军团的走狗来挑战我们了。干脆利落地打消它的野心吧。"
D.Strings[109908]="给我点时间。我会尽力解释的……"
D.Strings[109909]="只要思路正确，万物都能成为武器。"
D.Strings[109910]="有事要报告吗？"
D.Strings[109911]="我们会尽力守住阵线。去吧，找到伊米拉，帮我们扭转战局！"
D.Strings[109912]="伊米拉，你不能参加。但我不会剥夺你目睹$n失败的机会。"
D.Strings[109913]="我们的战斗并未就此结束！"
D.Strings[109914]="多亏了你，我们的生命和灵魂安全多了。"
D.Strings[109915]="淹没在火海吧！"
D.Strings[109916]="没人能抵挡泰沙拉克！"
D.Strings[109917]="许多人都挑战过我，可都失败了。"
D.Strings[109918]="这个构造体应该有关于启迪印记的线索。我们得唤醒它。"
D.Strings[109919]="很好。我们马上就出发。"
D.Strings[109920]="这个罐子上符文说明里面装着某个强大的魔古缚灵者的遗体。许多符号似乎都带有警告的意味。"
D.Strings[109921]="我们会尽力的。"
D.Strings[109922]="裂隙塌缩了，英雄们！你们得快一点，入口就要永久关闭了！"
D.Strings[109923]="这个地方被诅咒了。让我们为这些可怜的灵魂带去圣光的慰藉吧。"
D.Strings[109924]="军团的势力遍及宇宙，听候我的调遣！"
D.Strings[109925]="见证这股灭世之力吧！"
D.Strings[109926]="军团会不惜一切摧毁我们的世界。他们会吸取这次的惨败的教训。"
D.Strings[109927]="一艘军团运兵舰和巡洋舰突然出现在了主入口上方。"
D.Strings[109928]="一艘军团巡洋舰突然出现在了圣殿入口上方。"
D.Strings[109929]="<拉下控制杆。>"
D.Strings[109930]="<推起控制杆。>"
D.Strings[109931]="控制台显示出了一个数字9。"
D.Strings[109932]="|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t神殿基座出现了一条虚空裂缝！"
D.Strings[109933]="|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t下层虚空之门出现了一条虚空裂缝！"
D.Strings[109934]="我有点糊涂了。你之前说了什么？"
D.Strings[109935]="|TInterface\\ICONS\\ABILITY_MAGE_FIRESTARTER.BLP:20|t你已成为了|cFFF00000|Hspell:244410|h[屠戮]|h|r的目标！"
D.Strings[109936]="哼。看来都结束了。"
D.Strings[109937]="<薇拉拉冷漠地俯视着你。>\n\n什么事？"
D.Strings[109938]="跟我说说其他人。"
D.Strings[109939]="我知道你要跟谁战斗。$b$b阿克蒙德给了他们每个人一个头衔以表彰他们在各自领域的丰富知识。$b$b遗憾的是，他们都加入了军团。这是一个难得的机会，能够让你看到他们曾经的样子。"
D.Strings[109940]="结束了。我的生命……属于……萨格拉斯了……"
D.Strings[109941]="$n赢得了比赛！"
D.Strings[109942]="你以为我傻吗？邪犬，过来！"
D.Strings[109943]="其他人，守住这里。"
D.Strings[109944]="我们要找到启迪印记。阿克蒙德可能把它留在学宫了。"
D.Strings[109945]="不！这战利品是我的！我要把它献给主人！"
D.Strings[109946]="上层甲板在这边。泽拉有很多话……要对我们所有人说。"
D.Strings[109947]="泽拉看到你冒险来救她，一定会重新信任你的——我敢肯定！"
D.Strings[109948]="准备登上维迪卡尔。拉尔加很快就能准备好了。"
D.Strings[109949]="谢谢你，罗姆尔。"
D.Strings[109950]="我准备好前往禁魔监狱了。"
D.Strings[109951]="<艾欧娜尔的精华在你面前盘旋。虽然她的美丽与纯洁显而易见，但你还能感觉到她的悲伤和恐惧。>"
D.Strings[109952]="混沌统治一切。"
D.Strings[109953]="我将带来你的末日。"
D.Strings[109954]="守住阵地！我们要用生命保护维迪卡尔！"
D.Strings[109955]="他们又包围了我们。可怜的蠢货。"
D.Strings[109956]="检测到敌方战士。威胁等级低。"
D.Strings[109957]="把道标放到我的位置。我们要回家了。"
D.Strings[109958]="你高估了他们的忠诚。如果有必要，那你就冒次险吧。我来整顿部队，迎接反击。"
D.Strings[109959]="其他人就没这么幸运了。他们还在坠毁现场坚守，为了活命而战斗。"
D.Strings[109960]="啊，你还活着！道标着陆了。"
D.Strings[109961]="拿着它，你离真正的命运又近了一步。"
D.Strings[109962]="我——我不能——我——啊！"
D.Strings[109963]="嘿，那是我们的！是我们先看见的！"
D.Strings[109964]="泽尼达尔不能白白牺牲！"
D.Strings[109965]="我接住你了。再试一次吧——我们暂时是安全的。"
D.Strings[109966]="我终于可以回去准备进攻了。你们可以留下来……等死！"
D.Strings[109967]="我会找到你的，入侵者。"
D.Strings[109968]="只要军团还在，我就不能死，大主教。跟我来。我们设置了一个结界。"
D.Strings[109969]="感觉到了吗？有东西在催我们回去……"
D.Strings[109970]="你休想拖住我，恶魔！"
D.Strings[109971]="谢谢你！谢谢你！"
D.Strings[109972]="等你抵达禁魔监狱，我再联络你。"
D.Strings[109973]="停下！不要听！"
D.Strings[109974]="<激活传送序列。>"
D.Strings[109975]="对，是阿坎恩发的……可他没想到……"
D.Strings[109976]="让我看看吧。"
D.Strings[109977]="这里有一个熟悉的气息。我听到它在召唤我。"
D.Strings[109978]="你们会的，愿圣光与你同行。"
D.Strings[109979]="谢谢你，酋长。我们很乐意接受一切可能的帮助。"
D.Strings[109980]="孩子，我们还有很多话要说，但泽尼达尔上的盟友正危在旦夕。"
D.Strings[109981]="维迪卡尔"
D.Strings[109982]="选择一个目的地。"
D.Strings[109983]="军团已经孤注一掷了。我们应该趁他们还在关注艾泽拉斯时果断出击。"
D.Strings[109984]="看来他们还是出现了。"
D.Strings[109985]="我相信维伦会理解的。"
D.Strings[109986]="那东西……它在……召唤我！"
D.Strings[109987]="那么，风行者？你怎么说？"
D.Strings[109988]="没人能抗拒暗影的意志。"
D.Strings[109989]="黑暗要你死。"
D.Strings[109990]="你的死亡将取悦黑暗之主！"
D.Strings[109991]="我说的不是信任。"
D.Strings[109992]="低语消失了。"
D.Strings[109993]="我们一直在等待！可圣光始终没有归来！"
D.Strings[109994]="快去刃拳海湾吧。我们的机会来了，去结束这场战争吧。"
D.Strings[109995]="能带领我们前往阿古斯的飞船终于建成了。"
D.Strings[109996]="我还没偏离那条道路。你知道我为何会抗拒。"
D.Strings[109997]="阿拉托尔！他也来了！"
D.Strings[109998]="这些东西是从哪儿来的？"
D.Strings[109999]="难道这些都是……"
D.Strings[110000]="能解释一下吗？简单点也行。"
D.Strings[110001]="我们不能放弃。"
D.Strings[110002]="看看头顶的天空。看看黑暗虚空中数百万的光辉吧。"
D.Strings[110003]="随着传送门的关闭，原本紧闭的大门打开了，通往禁魔监狱深处的道路开启了。"
D.Strings[110004]="现在，阿古斯的克罗库会响应飞行管理员的哨子。"
D.Strings[110005]="我准备好了，大主教。"
D.Strings[110006]="<将维迪卡尔与圣光裁决者相连。>"
D.Strings[110007]="又有血肉送上门了！"
D.Strings[110008]="我要饱餐你鲜嫩的血肉！"
D.Strings[110009]="快，大审判官！敌人冲过来了！"
D.Strings[110010]="你做好继续前进的准备了吗，我的朋友？"
D.Strings[110011]="如此……黑暗！"
D.Strings[110012]="别……放弃！"
D.Strings[110013]="这一天，我们已经等得太久了。"
D.Strings[110014]="你没事吧，图拉扬？"
D.Strings[110015]="准备好了就去克拉苏斯平台，艾泽拉斯的勇士都在等着你。"
D.Strings[110016]="你们的人民……你们的世界……终将崩溃。"
D.Strings[110017]="我跟你们战斗了一千年，恶魔。就算你大言不惭，也难逃一死！"
D.Strings[110018]="我们不能在这里滞留太久。"
D.Strings[110019]="她留了下来。我还能感应到她……但她的歌声变得苦涩而混乱。"
D.Strings[110020]="奥蕾莉亚呢？她还……"
D.Strings[110021]="今天不是我们的末日。我们将并肩战斗。"
D.Strings[110022]="通道开启了。你们熟悉、珍爱的一切，都将毁灭。"
D.Strings[110023]="我们在这里杀掉的恶魔是无法复活的，所以不要手下留情。"
D.Strings[110024]="乔娜，乔恩，去追侏儒轻啤！一群穴居人把它抢走了！"
D.Strings[110025]="不过没时间闲聊了。看来他有他的任务……我们也一样。该行动了，勇士。"
D.Strings[110026]="照顾好泰兰德，多听她的建议。她是我们中最出色的。"
D.Strings[110027]="你选择了塞纳里奥之道。而我……听从了另一个召唤。"
D.Strings[110028]="但最终，你也和我哥哥一样，开始认为我的选择已令我堕入黑暗的深渊。"
D.Strings[110029]="我们得继续并肩战斗，$n。不能让黑暗的时代拆散我们。"
D.Strings[110030]="|TInterface\\Icons\\SPELL_FIRE_FELIMMOLATION.BLP:20|t金加洛斯即将激活|cFFFF0000|Hspell:248061|h[净化协议]|h|r！快出去！"
D.Strings[110031]="现在，阿古斯的各位请注意。哈克穆德不想再搞特殊了。"
D.Strings[110032]="恶魔遮蔽了天空，即将发动进攻。做好战斗准备。"
D.Strings[110033]="北方的天空充满了混沌能量。"
D.Strings[110034]="天上很快就会挤满了恶魔。拿起你们的剑！"
D.Strings[110035]="军团来了！快找掩体！"
D.Strings[110036]="这真是……出人意料。没想到他的力量居然能摧毁她……"
D.Strings[110037]="如果我是你，就不会走那条路……"
D.Strings[110038]="不彻底摧毁燃烧军团，圣光军团就永远不会停息。"
D.Strings[110039]="<艾萨斯显得有些坐立不安。>"
D.Strings[110040]="我准备好了，罗姆尔。"
D.Strings[110041]="<他抓狂地翻着一本巨大的书籍。>\n\n我怎么可能把这些都记下来？"
D.Strings[110042]="<她抓狂地翻着一本巨大的书籍。>\n\n我怎么可能把这些都记下来？"
D.Strings[110043]="我的一个手下也参加了。他是个好战士！虽然不是勇士沃鲁斯克，但也是这次大赛中强有力的竞争者。"
D.Strings[110044]="今年的比赛很激烈。胜利者一定会很自豪的。"
D.Strings[110045]="我们发誓要击败军团。所有的战场都是相似的，哪怕它位于一个完全不同的世界。"
D.Strings[110046]="<希尔格林陷入了沉思，仿佛比平时更加沉默了。>"
D.Strings[110047]="强大的魔法保护着这些宝藏。只有用合适的能量包裹住自己的人才能得到它。"
D.Strings[110048]="尽你所能多给我带一些恶魔的眼睛来，异界人。我会给你丰厚的奖励。"
D.Strings[110049]="各个职业大厅会将他们的所有资源与你共享，你不需要继续研究神器知识了。通过共同的努力，我们已经将所有有关神器的知识都研究完毕了。"
D.Strings[110050]="我的东西！必须……警告……其他人……"
D.Strings[110051]="不……不！啊！回来！那是我的！"
D.Strings[110052]="那些废物进攻了！不朽者中队，攻击！"
D.Strings[110053]="<这孩子哭个不停，好象没人能安慰他。>"
D.Strings[110054]="真是无礼！快滚！"
D.Strings[110055]="基尔加丹会为所有艾瑞达带来繁荣的新时代。后人会记住他是多么伟大的领袖的！"
D.Strings[110056]="改变即将到来。这对我的人民是非常重要的时刻。"
D.Strings[110057]="还真是热闹，对吧？"
D.Strings[110058]="可能，也许。现在的气氛非常伤感。"
D.Strings[110059]="居然你也这么说了。我还以为只是我想象出来的，现在看可能不是。"
D.Strings[110060]="我感觉到出了什么大事，但根本解释不清楚！这讨厌的感觉是怎么回事？"
D.Strings[110061]="<听到你的问题，这个孩子对着你抽泣起来。>"
D.Strings[110062]="也许是只影豹！它们总是躲在阴影里……$b$b<孩子紧张地回头看了看。>"
D.Strings[110063]="嗯……不，我没注意到任何特别的情况。"
D.Strings[110064]="我准备好前往圣石了。"
D.Strings[110065]="毫无疑问，圣光必将赢得最终的胜利。"
D.Strings[110066]="即使在这荒芜的世界，我们仍为艾泽拉斯而战！"
D.Strings[110067]="我们在这场战争中收获了不少货物和古董。"
D.Strings[110068]="开始进攻安托鲁斯。"
D.Strings[110069]="|TINTERFACE\\ICONS\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|t这个区域已成为|cFFF00000|Hspell:250249|h[湮灭光束]|h|r的目标！"
D.Strings[110070]="虚空之光熔炉随时为你效劳，$n。"
D.Strings[110071]="这不是都明摆着吗？$b$b直接进攻安托鲁斯是犯蠢。军团的兵力远超我们，而且他们补充兵力的速度快得不可思议。有些蛮兵也很强大，能够拖慢我的推进速度……当然只是一点点。$b$b我们需要想其他办法来攻破他们的要塞。与此同时，那里还有如潮的恶魔等着我们去杀。$b$b回去告诉你的大主教，让他制订好战略。我还要上阵杀敌呢。"
D.Strings[110072]="终于到了。已经太久了……"
D.Strings[110073]="图拉扬想问问这里的局势。"
D.Strings[110074]="即使在这里，我也能听到它在召唤我。它很饥饿……"
D.Strings[110075]="我还以为死定了……谢谢你！"
D.Strings[110076]="|TInterface\\Icons\\ABILITY_MAGE_DEEPFREEZE.BLP:20|t快靠近火盆！|cFFFF0000|Hspell:251709|h[快速冻结]|h|r即将爆发！"
D.Strings[110077]="随便你们怎么处置这个凡人和她的盟友。他们无关紧要。"
D.Strings[110078]="%s的宠物科尔宾在你头上盘旋着。"
D.Strings[110079]="别担心我，我……迟早会找到出路的。"
D.Strings[110080]="回家吧，艾泽拉斯的孩子们。保护好最后的泰坦。"
D.Strings[110081]="泰坦能切断那种联系……但这里不行。他们得把阿古斯之魂带回他们的力量之地……万神之座。"
D.Strings[110082]="大法师伊米拉挥手让你跟上她。"
D.Strings[110083]="恶魔在用塑造者的烈焰对付你们！"
D.Strings[110084]="南方的天空充满了混沌能量。"
D.Strings[110085]="将一块海丝利安石放进空洞。"
D.Strings[110086]="阿塔玛水晶很快就让我看清了真相，接受那泰坦的提议只会带来可怕的后果。"
D.Strings[110087]="克乌雷！帮帮我们！"
D.Strings[110088]="塔尔加斯背叛了我们！"
D.Strings[110089]="我还记得……那些逃亡的日子。"
D.Strings[110090]="再一次宣泄我的怒火吧，阿格拉玛。终结这场圣光的入侵。"
D.Strings[110091]="我感觉那些恶魔在扭曲泰坦的灵魂！强迫他们用自己的力量为军团服务！"
D.Strings[110092]="我们终于要抵达终点了。朋友们，前进。"
D.Strings[110093]="多么令人感动的牺牲啊！"
D.Strings[110094]="一处新的侵入点里出现了一个军团指挥官。快去向他复仇！"
D.Strings[110095]="主人！我将为你夺取战利品！"
D.Strings[110096]="军团的恶犬在骚扰我们撤退的部队。快去多救几个士兵吧！"
D.Strings[110097]="你点燃了士兵心中的火焰。毫无疑问，我们会赢下这场战争！"
D.Strings[110098]="我的士兵逃过了一劫，他们都很感谢你。"
D.Strings[110099]="这些士兵的痛苦结束了……你赶到得很及时。"
D.Strings[110100]="随着燃烧的远征分崩离析，军团的计划也破产了。"
D.Strings[110101]="|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|t帕拉克希斯号开始为|cFFFF0000|Hspell:248861|h[末日之矛]|h|r充能！"
D.Strings[110102]="都……结束了？"
D.Strings[110103]="魔法燃烧我们的灵魂，死亡也无法结束痛苦。"
D.Strings[110104]="这个黑化的纳鲁散发着虚空能量。"
D.Strings[110105]="遵命，先知。我这就去。"
D.Strings[110106]="圣光会带我们找到他们。罗姆尔，开始最后的准备，别忘了带上部队，是时候了。"
D.Strings[110107]="圣光熄灭了。"
D.Strings[110108]="德莱尼们……艾泽拉斯的勇士们……反攻阿古斯的时机到了。"
D.Strings[110109]="远征……必须……"
D.Strings[110110]="我从未见过德莱尼集结起这样的大军。"
D.Strings[110111]="艾瑞达术士将这个世界的邪能之血扭曲成了对付我们的武器。你得解决他们。"
D.Strings[110112]="快开炮！为了阿古斯！为了人民！"
D.Strings[110113]="熔炉的功能齐全后，我们的武器就能像星辰一样闪耀！来，我演示给你看。"
D.Strings[110114]="熔炉中的圣光在熊熊燃烧，但它还不能运转！"
D.Strings[110115]="圣光仍然在我和你们的心中闪耀。我们必胜！"
D.Strings[110116]="我们得继续完成任务。一定要摧毁军团。"
D.Strings[110117]="一旦这座熔炉建成，就能将宇宙的基本力集中到你的武器上！它只是……还没完成。"
D.Strings[110118]="我已经为这些化石设想了许多实验。弄到它们可不容易。谢谢你。"
D.Strings[110119]="小心点，启动战争机甲可是需要大量能量的。你最好不要随意挥霍它的能量！"
D.Strings[110120]="是的。别搞错了，我们的道路并不好走，也在黑暗中挣扎过。但我们要一起面对经常背弃我们的世界。我们会携手找到力量。"
D.Strings[110121]="欢迎来到我的圣殿。"
D.Strings[110122]="这种敌人死有余辜。干得好。"
D.Strings[110123]="谁都不该坐等军团来夺取他们的灵魂。"
D.Strings[110124]="在黑暗神殿时，我手下曾有个恐惧领主。他现在投靠了军团。去让他后悔吧。"
D.Strings[110125]="成了！最后激活一次控制台就能完成传送了。剩下的交给我！"
D.Strings[110126]="有时，隐秘行动比正面强攻更有效。我相信这里正需要这样的战术。"
D.Strings[110127]="军团还抓了我们不少人。他们想要切断我们之间的血脉联系，让我们自相残杀。请去救救他们吧！"
D.Strings[110128]="我们就快一无所有了，恶魔却还偷窃我们的遗物，割裂我们的历史。请夺回它们，外来者。"
D.Strings[110129]="你来的正是时候。"
D.Strings[110130]="我知道，大法师。它有时……令人窒息，难以集中精神。"
D.Strings[110131]="一次令人信服的胜利。你证明了军团的存在毫无价值。"
D.Strings[110132]="现在他们该明白了……我们是不会心软的。他们的远征即将覆灭。"
D.Strings[110133]="只要跟这位新盟友合作，艾瑞达的光辉必将照耀整个宇宙！"
D.Strings[110134]="同胞们，我召集你们来此，聆听一个启示。"
D.Strings[110135]="小心。出现了一个渴望凡人鲜血的恶魔。"
D.Strings[110136]="恶魔渣滓正在破碎的大地上横行。打倒所有恶魔，一个不留！"
D.Strings[110137]="虽然以寡敌众，但圣光与我们同在。胜利必将属于我们！"
D.Strings[110138]="圣光刚在这里站稳脚跟，就有一艘邪恶的战舰来攻击我们了。你的力量又要派上用场了，勇士。"
D.Strings[110139]="当之无愧的胜利。军团必败！"
D.Strings[110140]="我没有信错人。你今天帮了圣光一个大忙，朋友。"
D.Strings[110141]="燃烧军团终于看清了真相……我们会将他们赶出阿古斯之心！"
D.Strings[110142]="得迫使恶魔后撤，否则我们输定了。拿起武器！"
D.Strings[110143]="圣光在上……不！"
D.Strings[110144]="这个世界中沉睡的能量能增强军团的力量。去将这些恶魔化为灰烬，别让他们得到它。"
D.Strings[110145]="我感觉附近有个盟友。"
D.Strings[110146]="尝尝我的剑吧，恶魔！"
D.Strings[110147]="这些沙子下埋藏着一口拥有无限力量的泉眼。将它从军团手里抢过来吧。"
D.Strings[110148]="你们击溃了他们。这些恶魔显然意识到了自己并非宇宙中最强大的力量。"
D.Strings[110149]="相信圣光。"
D.Strings[110150]="我是圣光的仆人。"
D.Strings[110151]="你的傲慢会毁了你。"
D.Strings[110152]="军团对鲜血的渴望永无止尽。将那些渣滓赶出这个世界。"
D.Strings[110153]="军团在抽取一头沉眠于地下的巨兽的鲜血。必须阻止它们！"
D.Strings[110154]="这些武器灌注了混沌的精华。很快，人们就会赞颂我们了！"
D.Strings[110155]="谢谢你。这些水晶可以为我们的防御工事供能。它们是宝贵的资源。"
D.Strings[110156]="我们都得拥抱不可避免的混沌。"
D.Strings[110157]="啊，故乡……我简直要思念它了。"
D.Strings[110158]="倒在我的剑下吧！"
D.Strings[110159]="能量核心……破裂……"
D.Strings[110160]="千里之堤，溃于蚁穴……"
D.Strings[110161]="就是这样，勇士。我们要进攻军团的心脏了。"
D.Strings[110162]="领主纳斯拉克斯就在塔里。打倒他！"
D.Strings[110163]="小心遭遇激烈抵抗。纳斯拉克斯不会束手就擒的。"
D.Strings[110164]="占据它，奥蕾莉亚。夺取它的混沌之力。"
D.Strings[110165]="我感到堕落纳鲁的力量……在召唤我。"
D.Strings[110166]="圣光生物怎么会变成暗影生物？"
D.Strings[110167]="你们来得正好，勇士们。影卫成员就在附近给本地生物灌注虚空能量。但我不清楚他们的目的。"
D.Strings[110168]="$n周围凝聚起了火焰能量。"
D.Strings[110169]="生命的缚誓者！她对萨格拉斯的计划很重要。"
D.Strings[110170]="仰望这完美的力量吧。这份礼物无法拒绝！"
D.Strings[110171]="姐妹们，或许那个纳斯雷兹姆太熟悉烈焰的痛苦了。"
D.Strings[110172]="囚犯变虚弱了，他就快投降了。"
D.Strings[110173]="看！那个可怜虫跟凡人入侵者打起来了。"
D.Strings[110174]="源于痛苦的礼物！"
D.Strings[110175]="看来她终于找到我了，还派了手下来做个了断。"
D.Strings[110176]="这么说，你们的联盟还在。这比我想像的还要久，但是，她已经种下了毁灭的种子。她可是很有耐心的。"
D.Strings[110177]="软弱的可怜虫！"
D.Strings[110178]="他在夸耀对暗影的蔑视。傲慢会毁了他的。"
D.Strings[110179]="$n附近的地面上有一颗火焰能量球。"
D.Strings[110180]="在摧毁军团的战争机器前，攻击核心毫无意义。恶魔大军很快就会击溃我们。"
D.Strings[110181]="救救他们，否则你们的抗争就毫无意义了。"
D.Strings[110182]="从接受交易的那一刻起，他们就背叛了我们所坚持的一切。他们已经无药可救……必须严惩。"
D.Strings[110183]="附近的一颗水晶爆发出了奥术能量。"
D.Strings[110184]="不过，你要是想看到现实被撕碎的话，就尽管问我的真名好了。"
D.Strings[110185]="小心点。我掌握着超出你想象的力量。"
D.Strings[110186]="机会来了，英雄。"
D.Strings[110187]="按照这个速度，我永远都当不上大执政官了。"
D.Strings[110188]="失败者都要吃苦头！决不能让先知跑了！"
D.Strings[110189]="我们也很担心你，卡德加。但我内心深处一直觉得，一个星球的爆炸肯定奈何不了你。"
D.Strings[110190]="别来烦我们！"
D.Strings[110191]="这是我们的家园！滚开！"
D.Strings[110192]="享受我冰冷的抚触，化为冰雕吧。"
D.Strings[110193]="我要看着你们被烤熟！"
D.Strings[110194]="你的尖叫将响彻安托鲁斯！"
D.Strings[110195]="<光铸勇士>"
D.Strings[110196]="你们无处可逃了。"
D.Strings[110197]="你错过了辅导课。快去启蒙大厅报到，参加考试吧。"
D.Strings[110198]="我对上一个试炼做了些改动。如果你能完成这个挑战，就能再次证明你的机智。"
D.Strings[110199]="但愿它们能从痛苦中恢复过来。干得好，但我们跟影卫的斗争还将继续。"
D.Strings[110200]="领取赏金不需要全尸，只要一些断肢就够了。"
D.Strings[110201]="现在，该进攻燃烧王座了。做好准备。安托鲁斯在等着我们！"
D.Strings[110202]="你们悬在天上的那个世界……完蛋了！"
D.Strings[110203]="在军团真正的力量面前颤抖吧！"
D.Strings[110204]="不要听那些低语。"
D.Strings[110205]="啊！噢。怎么了？"
D.Strings[110206]="一切都是角度问题。"
D.Strings[110207]="有趣，真有趣。"
D.Strings[110208]="祝你百发百中。"
D.Strings[110209]="我们决不能半途而废。"
D.Strings[110210]="信仰即吾盾。"
D.Strings[110211]="返回入口。"
D.Strings[110212]="太脆弱了。"
D.Strings[110213]="我总能领先一步！"
D.Strings[110214]="我们的工作不能被打断！"
D.Strings[110215]="黑暗赐予我力量！"
D.Strings[110216]="|TInterface\\Icons\\SPELL_FIRE_FELFLAMEBREATH.BLP:20|t金加洛斯强化了|cFFFF0000|Hspell:246840|h[毁灭者]|h|r！"
D.Strings[110217]="屈服吧，否则就死。"
D.Strings[110218]="点燃烈焰，对抗黑暗。"
D.Strings[110219]="在神殿中徘徊的黑暗……笼罩着整个玛凯雷的阴影……就是鲁拉。"
D.Strings[110220]="很高兴看到我们中间还有一个$c。我们需要一切可能的帮助。"
D.Strings[110221]="可悲的灵魂！你们即将失败。"
D.Strings[110222]="我牺牲了太多，决不能失败！"
D.Strings[110223]="今天就是你的死期。如果你还有一丝良心，就帮我们找到知识桂冠吧。"
D.Strings[110224]="经历过他带给我的痛苦……以及带给我人民的痛苦……我们终于走到了这一步。$b$b<维伦握紧了他的法杖。>$b$b你准备好之后，我们就一起了结这一切。"
D.Strings[110225]="但我欢迎你的这种改变。"
D.Strings[110226]="这真不像你，竟然一步不退。"
D.Strings[110227]="英雄们，纳鲁变虚弱了！"
D.Strings[110228]="等等！是这些风干扰了我们的感官，引起了野生动物的不安。"
D.Strings[110229]="你似乎是个假冒伪劣产品。"
D.Strings[110230]="你们以为会有其他结果吗？"
D.Strings[110231]="<圣光裁决者>"
D.Strings[110232]="过来受死吧！"
D.Strings[110233]="真是个废物。"
D.Strings[110234]="军团对自己人同样残酷。摧毁这个怪物，封印两个世界间的裂隙吧。"
D.Strings[110235]="每关闭一条裂隙，就能为我们的推进争取更多时间。愿圣光与你同在，勇士。"
D.Strings[110236]="哈！这将成为我教学时的最佳案例。"
D.Strings[110237]="我无法踏足裁判所。你早就知道了，对吧？"
D.Strings[110238]="伯特的机器人赢了！"
D.Strings[110239]="|TInterface\\Icons\\ABILITY_ROGUE_SHADOWSTEP:20|t萨普瑞什正准备使用|cFFFF0000|Hspell:247246|h[幽影侧击]|h|r攻击你！"
D.Strings[110240]="了不起。军团肯定没有想到你会这么强大。"
D.Strings[110241]="纳斯雷萨……它曾是魔法与知识的世界，现在却成了无法逃离的扭曲之地。"
D.Strings[110242]="军团将毁灭一切反抗者！"
D.Strings[110243]="一头恶魔对维迪卡尔发起了冲锋。去干掉它，证明它的主子错了。"
D.Strings[110244]="控制台显示出了一个数字5。"
D.Strings[110245]="|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t下层虚空裂口出现了一条虚空裂缝！"
D.Strings[110246]="现在，亲眼见证我们的劳动果实吧。看，晋升者祖拉尔，第一个完全拥抱虚空之人！"
D.Strings[110247]="我想你需要我送你回学宫入口。"
D.Strings[110248]="我们不会退缩！再从虚空里调些部队来，解决这些入侵者！"
D.Strings[110249]="为了对付我们，燃烧军团制造了大量的军火。引开他们的部队，给那些军火打上记号。然后……就快跑吧！"
D.Strings[110250]="我认为这是当之无愧的胜利。"
D.Strings[110251]="高阶启迪者阿尔贡。我该从何说起呢？\n\n在他的前任萨奇尔被放逐后，他才晋升到了这个位置。如果你不了解这段故事的话，我改天可以跟你说说。\n\n所以不用我说你也知道，他就是个……投机者。\n\n在他的影响下，我们深入研究了灵魂束缚的秘密。游荡在这些街道上的构造体就是他的手笔。而他们只反映了启迪者的一小部分力量。\n\n加入军团后，他就成了阿戈斯。\n\n圣光军团称他为斩魂者。有灵魂引擎的地方，就会有阿戈斯的身影。"
D.Strings[110252]="阿古斯火山正在喷发。"
D.Strings[110253]="我最后的力量……消失了。我无法……阻止他们了……"
D.Strings[110254]="击败他们，如果我被发现就完了。"
D.Strings[110255]="我将在阿古斯的烈焰中重生！我绝不……停止……战斗。"
D.Strings[110256]="做好准备。它上来了！"
D.Strings[110257]="Archenon poros，先知。圣光军团与你同在。"
D.Strings[110258]="我会尽力吸引它的攻击，但你必须在我们倒下前消灭它！"
D.Strings[110259]="噢，但我才刚开始呢。她会成为燃烧王座上的精美装饰！"
D.Strings[110260]="泽拉！别担心，你安全了。"
D.Strings[110261]="打得好。要是军团毁了维迪卡尔，我们就得葬身阿古斯了。"
D.Strings[110262]="如果军团比我们先找到那块石头会怎么样？"
D.Strings[110263]="|TInterface\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t%s正在为|cFFF00000|Hspell:244152|h[天启引擎]|h|r积蓄能量！"
D.Strings[110264]="艾泽拉斯将属于我们。"
D.Strings[110265]="你竟敢闯入我们的世界？"
D.Strings[110266]="圣光指引着我的箭。圣光的炽热足以令黑暗无所遁形。"
D.Strings[110267]="只要那些邪恶的恶魔还能喘气，就没有和平可言。$b$b只要那些无信的叛徒还活着，就不会有宽恕存在。"
D.Strings[110268]="系统重启，能量改道。武器装填完毕。"
D.Strings[110269]="目标已清除。"
D.Strings[110270]="正在激活传送阵列。"
D.Strings[110271]="下次轰炸恐怕会有重大伤亡——我们得先出击。"
D.Strings[110272]="它在抵抗我的法术，它不仅是攻城武器……"
D.Strings[110273]="这里所有的力量现在都属于燃烧军团了。"
D.Strings[110274]="你这是怎么搞的？"
D.Strings[110275]="搜查者，掩护大审判官离开。我来对付这些入侵者！"
D.Strings[110276]="这是我们的地盘，凡人。"
D.Strings[110277]="一个入侵者？"
D.Strings[110278]="我们要失去他了！"
D.Strings[110279]="别听他们的，阿坎恩！"
D.Strings[110280]="你们得看清真相！"
D.Strings[110281]="你留下的那张烧焦的羊皮纸能提醒军团，我们的抵抗不容忽视。谢谢你。"
D.Strings[110282]="阿坎恩，是你吗？你的人民怎么了？"
D.Strings[110283]="我即圣光，圣光即我。"
D.Strings[110284]="有声音！阿坎恩没听过的声音。"
D.Strings[110285]="别让漫长的黑夜压垮你们。接受它的恩赐。"
D.Strings[110286]="黑暗从四面八方向我们涌来。保持清醒。"
D.Strings[110287]="它变虚弱了。全力攻击！"
D.Strings[110288]="快点毁掉这玩意儿。军团需要大审判官！"
D.Strings[110289]="正在修复"
D.Strings[110290]="见识一下虚空吧！"
D.Strings[110291]="虚空欢迎你！"
D.Strings[110292]="没有光，就没有影，老师。"
D.Strings[110293]="当然是指你的配偶了。他对你的选择怎么看？"
D.Strings[110294]="等等。有一个……声音。"
D.Strings[110295]="都……结束了。"
D.Strings[110296]="燃烧军团只领先了我们一步。快用传送门回到这里，我来找出审判官的去向！"
D.Strings[110297]="可你行吗？就凭你那些……累赘？"
D.Strings[110298]="低语声……太……吵了！啊啊！"
D.Strings[110299]="让我满足你的好奇心吧。"
D.Strings[110300]="阿坎恩忘了。"
D.Strings[110301]="我得说，阿坎恩，这并不能让我安心。"
D.Strings[110302]="你们必须坚定。诱惑会削弱心智和精神。"
D.Strings[110303]="无论发生什么，我们都要团结。"
D.Strings[110304]="可怜虫！你竟敢踏入我们的巢穴？"
D.Strings[110305]="%s挣扎着，痛苦折磨着他们的身体。"
D.Strings[110306]="我——我看……不见……"
D.Strings[110307]="<痛苦地呻吟。>"
D.Strings[110308]="我们已经远离了屏障的保护。提高警惕，我的朋友。"
D.Strings[110309]="见证德莱尼的胜利吧——埃索达！"
D.Strings[110310]="我的人民一直在等着这一天的到来。"
D.Strings[110311]="圣光的选民们，敬礼！"
D.Strings[110312]="肌肉无力，骨骼脆弱的废物！"
D.Strings[110313]="拿起你的武器。"
D.Strings[110314]="我还能听到纳鲁的战歌。当时，她为我们打开了通道。"
D.Strings[110315]="<维伦盯着正前方，似乎没有发现你的到来。>"
D.Strings[110316]="数千年来，圣光军团一直在与燃烧军团征战不休，用尽了一切手段。"
D.Strings[110317]="我们必须团结起来，才有机会击败军团。"
D.Strings[110318]="小心，勇士。我们被包围了。"
D.Strings[110319]="你证明了你对艾泽拉斯的忠诚。你的奉献和牺牲都足以与我媲美。但你还得付出许多，更多。"
D.Strings[110320]="我弟弟做出了自私的决定，曾让许多人痛不欲生。他的罪行……很难被原谅。"
D.Strings[110321]="在我的命运揭晓之际，我想结束这场令我们分道扬镳的争执。"
D.Strings[110322]="照顾好他，泰兰德。虽然我常希望你的心能做出另一个选择，可最终……我知道你是正确的。"
D.Strings[110323]="但我的所作所为只有一个目的：拯救这世界。我不能半途而废，亦不能妥协。"
D.Strings[110324]="世界在对我们哭泣，$n。我们必须为拯救它而战。"
D.Strings[110325]="|TInterface\\Icons\\SPELL_FIRE_FELFIREWARD.BLP:20|t金加洛斯开始引导|cFFFF0000|Hspell:246516|h[天启协议]|h|r！"
D.Strings[110326]="|TINTERFACE\\ICONS\\INV_GIZMO_FELIRONBOMB.BLP:20|t你沾上了一枚|cFFFF0000|Hspell:244722|h[震荡手雷]|h|r！"
D.Strings[110327]="哈克穆德总是没有放松的时候。哪怕是在他自己的世界！"
D.Strings[110328]="<回忆阿古斯的事件>"
D.Strings[110329]="抹杀这些恶魔的存在！"
D.Strings[110330]="送这些恶魔上西天。"
D.Strings[110331]="恶魔来了。准备好你们的战刃。"
D.Strings[110332]="愿圣光指引我们……恶魔来了！"
D.Strings[110333]="恶魔来了！所有人都撤回维迪卡尔。快！"
D.Strings[110334]="<图拉扬狠狠地瞪着伊利丹。>"
D.Strings[110335]="我已经很久没有见过这个地方了。回忆……如潮水般淹没了我。"
D.Strings[110336]="噢，总算有值得一看的东西了！那就去吧，让我高兴一下。"
D.Strings[110337]="有些恶魔就喜欢站在火里……你有时间的话也应该试试。"
D.Strings[110338]="能够再次仰望天空中的艾泽拉斯，我的欣慰之情真是无以言表。故乡就近在眼前，仿佛触手可及一般。$b$b但它同样也在军团的掌握之中。我们必须在计划归乡之前阻止他们。"
D.Strings[110339]="能看到友善的新面孔真令人高兴。我已经很久没有看到来自艾泽拉斯的$G男人:女人;了！"
D.Strings[110340]="即使是对精灵来说，这段流逝的时光也已经足够长了。我们不在的时候，艾泽拉斯一定已经发生了巨大的变化。"
D.Strings[110341]="伊利丹打开通往阿古斯的道路后，我以为我们犯了一个大错。可现在，我相信还有希望。$b$b我必须相信我们还有希望。"
D.Strings[110342]="邪能魔法已经渗透了整个世界。它到底还有没有未被腐化的部分，这就很难说了。"
D.Strings[110343]="玛凯雷……它跟我记忆中一模一样。那些森林、山丘，还有塔布羊群……$b$b不知道我的老工坊是不是还在。如果你有时间的话，能不能……？$b$b抱歉。你还有更重要的事情要做。你准备好前往地表之后，就告诉我一声吧。"
D.Strings[110344]="阿古斯的大部分植物早已不可避免的灭绝了，但我在曾经到过的一个洞穴中发现了这种神奇的物种，可惜我已经记不清它的位置了。$B$B自从它到来之后，这种神秘植物就一直散发着亮度完全不亚于发光水晶的光芒。后者曾是阿古斯随处可见的一种装置，可现在已经成为了记忆中的历史。"
D.Strings[110345]="你说阿尔贡会同意我转去做执政官吗？我完全不擅长这个。但我至少可以应付一两个魔仆！"
D.Strings[110346]="我不怎么担心他们的脑袋。只有带上最厚重头盔的男性才会选择参赛，而这些就是玛凯雷最好的头盔了。"
D.Strings[110347]="你觉得谁会赢？"
D.Strings[110348]="打倒他！"
D.Strings[110349]="在伪装状态下无法进入！"
D.Strings[110350]="每一个恶魔的眼睛都看到过上千个世界。把它们带给我，我就能够看到一切了。"
D.Strings[110351]="<艾欧娜尔的灵魂在你面前浮现。你心中如释重负，充满了感激之情。但同时，紧迫的责任感冲淡了胜利的喜悦。>"
D.Strings[110352]="<瓦西里恩嘟囔了些什么，显然并不满意。>$b$b我认识一个叫这个名字的人，不过他的名声可不好。他曾经找我投资过一个项目，当时看上去似乎还有的赚，但我的投资一直没有得到回报。"
D.Strings[110353]="|TInterface\\Icons\\warrior_talent_icon_mastercleaver.blp:20|t索塔纳索尔的斧头释放出了|cFFFF0000|Hspell:181498|h[毁灭之力]|h|r!"
D.Strings[110354]="我会改造你，赋予你超乎想象的知识和难以估量的力量。"
D.Strings[110355]="<查看阿格拉玛的崛起。>"
D.Strings[110356]="呃……不！回来！回来！你滚开！"
D.Strings[110357]="嗷！嗷！嗷嗷嗷！！！"
D.Strings[110358]="我的骑兵在外面很辛苦。"
D.Strings[110359]="啊，被你抓到了。那就死吧！"
D.Strings[110360]="<塔尔加斯盯着阿克蒙德和维伦，只是偶尔会瞟一眼基尔加丹。>$b$b嗯。"
D.Strings[110361]="我不能肯定结果到底会是怎样，但我发自内心地相信，今天是个值得铭记的日子。"
D.Strings[110362]="<孩子显得非常不安。>$b$b我不知道……也许是吧？"
D.Strings[110363]="胡说！大家只是在庆祝！"
D.Strings[110364]="即使你已经说了一辈子的话，聆听他人也依然很重要。"
D.Strings[110365]="做好准备，勇士。附近潜伏着黑暗……"
D.Strings[110366]="我想传送到瓦里玛萨斯那里。"
D.Strings[110367]="我想传送到猎魂者伊墨纳尔那里。"
D.Strings[110368]="是谁唤醒了我？"
D.Strings[110369]="你好，感谢你帮助测试安托鲁斯，燃烧王座！\n\n我可以将你直接传送到目前开放测试的任意首领处。"
D.Strings[110370]="|TInterface\\Icons\\SPELL_FIRE_MOLTENBLOOD.BLP:20|t%s开始施放|cFFFF0000|Hspell:244057|h[燃烧腐蚀]|h|r。"
D.Strings[110371]="帕拉克希斯号就快回来了！圣光军团，起盾！"
D.Strings[110372]="我们必须继续战斗，直到消灭军团为止。"
D.Strings[110373]="我要在这个该死的地方摧毁燃烧军团。"
D.Strings[110374]="谢谢你，勇士……我还以为自己死定了。"
D.Strings[110375]="我以前听过这个故事……<跳过剧情，开始你在破碎海滩的旅程。>"
D.Strings[110376]="|TINTERFACE\\ICONS\\Inv_Elemental_Primal_Shadow.blp:20|t [将暗影精华放入虚空之光熔炉]。"
D.Strings[110377]="我们的任务就快完成了。阿古斯很快就会陷入黑暗！"
D.Strings[110378]="你在执政团之座遇到了什么事？"
D.Strings[110379]="科尔宾没有在%s找到任何亮晶晶的东西。"
D.Strings[110380]="%s的宠物科尔宾在你的头发里寻找着亮晶晶的小玩意儿。"
D.Strings[110381]="选择你想在阿古斯使用的维迪卡尔能力。每次只能激活一种能力。"
D.Strings[110382]="可你坐在这里。"
D.Strings[110383]="你以为自己是自由的？人人都有一个主人。"
D.Strings[110384]="我必须从无数方法中选一种来干掉你。"
D.Strings[110385]="我能让你永生。但是，你得先去死！"
D.Strings[110386]="我穿着鞋呢。"
D.Strings[110387]="有意思……你为什么不穿鞋？"
D.Strings[110388]="那座传送门在这里干什么？"
D.Strings[110389]="你好，$n。船上的人都很积极。你看起来也很忙！如果你需要休息的地方，尽管来这里找我。"
D.Strings[110390]="因为入侵者比我们想的要顽强，将军。"
D.Strings[110391]="维迪卡尔随时听候调遣。"
D.Strings[110392]="先知……外面出什么事了？"
D.Strings[110393]="萨格拉斯将摧毁我们奋斗的理由。"
D.Strings[110394]="阿古斯痛苦的灵魂已经安息了。"
D.Strings[110395]="那是造物的摇篮！"
D.Strings[110396]="那个女巫在用高戈奈斯的风暴攻击你们！"
D.Strings[110397]="小心！凡人是不能走织梦者的道路的！"
D.Strings[110398]="将一块圣光榍石放进空洞。"
D.Strings[110399]="将一块炫彩孔雀石放进空洞。"
D.Strings[110400]="这种力量……他没有骗我们。"
D.Strings[110401]="当新的万神殿崛起，宇宙中就没有力量能阻挡军团了！"
D.Strings[110402]="法阵就快完成了。别让那些凡人干扰重生。"
D.Strings[110403]="他们走到哪里，我们都要追过去，严惩他们的傲慢。"
D.Strings[110404]="军团肆意入侵阿古斯之外的世界，兵力过于分散。去找到他们的传送门，杀光那里的恶魔！"
D.Strings[110405]="仁慈的解脱！"
D.Strings[110406]="来吧……靠近点，小家伙们！"
D.Strings[110407]="这边！他们肯定就在附近。"
D.Strings[110408]="黑暗……会……笼罩你们……"
D.Strings[110409]="野蛮的艾瑞达从休眠中苏醒了。快去他们的巢穴大开杀戒吧！"
D.Strings[110410]="那些克罗库奴隶都逃到山下某个地方去了。他们本来不可能跑那么远的。"
D.Strings[110411]="军团的技师都很粗心。我发现他们的管理有漏洞。快去挑衅他们，毁掉他们的库存吧！"
D.Strings[110412]="我们的一个侦查小队失踪了。他们可能被军团抓住——甚至更糟。去找到他们……否则就迟了！"
D.Strings[110413]="一想到军团的士兵居然喝那种泔水……真是恶心！"
D.Strings[110414]="|TInterface\\Icons\\SPELL_FEL_INCINERATE.BLP:20|t帕拉克希斯号发射了一枚邪能火球，想要|cFFFF0000|Hspell:248925|h [歼灭]|h|r你！"
D.Strings[110415]="你们阻止不了他！也阻止不了我！"
D.Strings[110416]="大地在痛苦蠕动。邪能燃烧一切生命。"
D.Strings[110417]="无论你需要修理什么装备，我都可以帮你，$c。"
D.Strings[110418]="他们不可战胜。即使死亡，他们仍能归来！"
D.Strings[110419]="它成了一个道标……"
D.Strings[110420]="那些恶魔体内充斥着邪能。军团在远征期间，也没在这里浪费时间啊。"
D.Strings[110421]="在屏障消失前，维迪卡尔无法轰炸那些灭绝者。快！"
D.Strings[110422]="我们得趁那件武器还在充能时摧毁它！罗姆尔，放个道标下去！"
D.Strings[110423]="阿格拉玛！他成了萨格拉斯的帮凶。糟糕……真糟糕！"
D.Strings[110424]="你们残破的世界……将点缀……我们的天空……"
D.Strings[110425]="宽恕我……"
D.Strings[110426]="那头野兽被击败了。干得好，勇士们。"
D.Strings[110427]="我感觉这里涌动着虚空能量。找到源头并摧毁它。"
D.Strings[110428]="安托鲁斯在召唤我。"
D.Strings[110429]="我们的远征永不停歇！"
D.Strings[110430]="然后我的父母就能回家了。"
D.Strings[110431]="军团为了夺取纳斯拉克斯之塔，在附近开启了传送门。用战争机甲去阻止他们吧。"
D.Strings[110432]="你来得正好。这里的目标太多，我都射不过来了。"
D.Strings[110433]="一旦你摧毁发生器，我们就能用维迪卡尔瞄准防御工事了。我们就快成功了！"
D.Strings[110434]="她为圣光所付出的一切决不能白费！"
D.Strings[110435]="你说的对，先知。我们还有任务。"
D.Strings[110436]="你的身手真是惊人。但我相信我的箭矢能让那头恶魔死得更快。"
D.Strings[110437]="谢谢你，$n。愿他们安息。"
D.Strings[110438]="先是玛维，现在又是你。他在安托鲁斯肯定要吃苦头了。"
D.Strings[110439]="军团的进攻不会停歇。我们必须保持警惕。"
D.Strings[110440]="帮这些动物摆脱暗影的控制是种善行。看到城市变成这样，我很难过。"
D.Strings[110441]="我会完成狩猎的。"
D.Strings[110442]="邪恶临近了。"
D.Strings[110443]="我们还能攻破安托鲁斯，拆掉军团的复活引擎，但我们需要泽拉和圣光军团的帮助。"
D.Strings[110444]="力量就是力量。关键是我们怎么使用它。使用军团的资源来对付他们能帮我们占据上风。"
D.Strings[110445]="恶魔失败的哀嚎响彻了阿古斯。这种声音真是百听不厌。"
D.Strings[110446]="对……你让它们退缩了。打得好。"
D.Strings[110447]="一直以来，艾瑞达在宇宙中孤独地生活着。"
D.Strings[110448]="这头恶魔想靠阻止我们来飞黄腾达。去让它明白自己有多蠢吧。"
D.Strings[110449]="这世界上的每一个恶魔都是对阿古斯历史的否定。今天，你代表圣光重创了它们。"
D.Strings[110450]="我代表所有死于军团之手的高贵灵魂感谢你。"
D.Strings[110451]="黑暗泰坦的一名手下即将进攻。争取先发制人，一击毙命吧！"
D.Strings[110452]="多亏你迅速果断的行动，圣光军团的士兵安然无恙。非常感谢。"
D.Strings[110453]="军团以为这野蛮人能吓倒我们。去证明他们错了！"
D.Strings[110454]="我感觉附近有股强大的黑暗力量。小心！"
D.Strings[110455]="来自泽尼达尔的补给落入了军团之手。去夺回属于我们的东西吧，勇士！"
D.Strings[110456]="在大地的阴影中穿行吧。"
D.Strings[110457]="泽拉向你隐瞒了很多事情。"
D.Strings[110458]="军团想占有这个世界。快去破坏他们的统治。"
D.Strings[110459]="他们还没有在这里设防。"
D.Strings[110460]="那我们就别再浪费时间了。"
D.Strings[110461]="这片冰封废土之下藏着秘密力量。将它从军团那夺过来吧。"
D.Strings[110462]="军团在你的杀戮下退缩了。干掉他们！"
D.Strings[110463]="干得好，勇士们。这场胜利的消息会传遍黑暗虚空的。"
D.Strings[110464]="也许这世界的历史会有用。我要努力想想这里还剩下什么。"
D.Strings[110465]="好好战斗，旅行者。"
D.Strings[110466]="这些恶魔想给一头沉眠于地下的野兽放血。快去阻止他们的计划。"
D.Strings[110467]="没有机器，军团就不能抽取这头野兽的鲜血了。现在该轮到他们流血了。"
D.Strings[110468]="这种力量……不可思议！或许我们能让它效忠我们？"
D.Strings[110469]="这家伙一直是军团的肉中刺。我从没想过我们会成为盟友。"
D.Strings[110470]="这座城曾是阿古斯最伟大的奇迹。看看它现在！显赫一时的家族成了军团的走狗。很快，他们也将臣服于我们。"
D.Strings[110471]="你休想干扰重生。他们即将重获新生！"
D.Strings[110472]="你竟敢踏入圣池？哀嚎吧！"
D.Strings[110473]="诸界都将陨落。"
D.Strings[110474]="敌人已摧毁。"
D.Strings[110475]="我等着听你的痛苦哀嚎在殿堂中回荡。"
D.Strings[110476]="不出我所料。虚空腐蚀已经蔓延到了这里。"
D.Strings[110477]="说明书上不是这么写的……"
D.Strings[110478]="这比我想的更糟糕。我们能面对这样的敌人吗？"
D.Strings[110479]="你的傲慢会毁掉你。"
D.Strings[110480]="但愿现在还来得及。"
D.Strings[110481]="阿古斯之魂又召唤我了。他很疯狂……绝望……悲伤，非常悲伤。这真让我心碎！"
D.Strings[110482]="你们已经没用了！"
D.Strings[110483]="把下一个试验品送上来！"
D.Strings[110484]="许多人都为保卫这片土地献出了生命。为了他们，将恶魔赶回深渊去！"
D.Strings[110485]="燃烧王座"
D.Strings[110486]="你的存在毫无意义。"
D.Strings[110487]="据我估算，你们的生存几率为——零！"
D.Strings[110488]="恶魔们！冲锋！"
D.Strings[110489]="这太辛苦了！还是让我的机器来撕碎你们吧。"
D.Strings[110490]="军团的战争机器核心就在这些防爆门后面。解决这个威胁就能减弱恶魔的火力。"
D.Strings[110491]="我们要记住，他们是为这场战争牺牲的。"
D.Strings[110492]="我已经无能为力了，指挥官。他们已经回归圣光了。"
D.Strings[110493]="勇士们，听我说。军团攻破了我的圣殿，我的防线即将崩溃。帮帮我，别让萨格拉斯得逞。"
D.Strings[110494]="没有了传送门，燃烧军团就得不到援军了。现在，该我们大举进攻了！"
D.Strings[110495]="附近的一颗水晶感染了疫病能量。"
D.Strings[110496]="|TInterface\\Icons\\PRIEST_ICON_CHAKRA_BLUE.BLP:20|t你周围的奥术能量开始不断爆裂。"
D.Strings[110497]="|TInterface\\Icons\\PRIEST_ICON_CHAKRA.BLP:20|t疫病能量感染了你。"
D.Strings[110498]="勇士们，你们那边有情况。黑暗之门开启后，我就没感受过那么强大的力量。"
D.Strings[110499]="要是我大声说出来的话，就会撕开上千座虚空传送门，一些可怕的存在会跑来算旧账。"
D.Strings[110500]="我们不会让你失望的，先知。"
D.Strings[110501]="我失踪了那么多年，你就是这么对我的？"
D.Strings[110502]="Krono-ka lith'tor agnos……要么就是lith'nos agtor？呸！我就没念对过这句咒语！"
D.Strings[110503]="它马上就好，大主教。我保证。"
D.Strings[110504]="找到先知！杀光他的盟友！"
D.Strings[110505]="献给邪能的灵魂送上门了！"
D.Strings[110506]="老话说的好：受骗一次，他人可耻，受骗两次……"
D.Strings[110507]="这显然是种特殊战术。不能让军团利用这些无力自保的幽灵来施展阴谋诡计。"
D.Strings[110508]="激活的构造体能很好地吸引敌人。谢谢你！"
D.Strings[110509]="我需要一种特殊的水晶来维护维迪卡尔的防御系统。这里游荡的构造体也采用了这种技术。你只要想办法帮我拿到它们的核心就行。"
D.Strings[110510]="我待会儿再来对付你。"
D.Strings[110511]="废物。只有桂冠是没用的。"
D.Strings[110512]="这份轻视让我们有了找回印记的可能。要是他能预见到它的价值，肯定会毁掉它的。"
D.Strings[110513]="我的人民永远不会知道，我是多么难过……和后悔。"
D.Strings[110514]="这就是……他看到的幻象吗？"
D.Strings[110515]="不……我们付出了那么多……"
D.Strings[110516]="你没有看清……真相！"
D.Strings[110517]="阿坎恩在听。"
D.Strings[110518]="我忙着呢，$r。你需要什么？"
D.Strings[110519]="坚持下去。"
D.Strings[110520]="圣光救不了你，尤其是在这里！"
D.Strings[110521]="可控的阴影……能成为盟友。"
D.Strings[110522]="我离开家园太久了。还有我的儿子。"
D.Strings[110523]="很久以前，我和两个兄弟制造了一件为人民造福的圣物。"
D.Strings[110524]="我要把你送入黑暗！"
D.Strings[110525]="只是一次……战术失误……"
D.Strings[110526]="你抵挡不了我的利剑。"
D.Strings[110527]="你好，$n。跟军团的战斗怎么样了？"
D.Strings[110528]="你知道吗，我听说过一些谣言。人们说我嗜血成性，完全不像一个女祭司。"
D.Strings[110529]="屠杀恶魔有益身心健康。屠杀恶魔让你感到快乐。"
D.Strings[110530]="你每杀一个恶魔，我们就能少一个敌人。"
D.Strings[110531]="记得留意一切有用的东西。"
D.Strings[110532]="把受伤的敌人送来。一次简单的祈祷就能净化他们污秽的伤口！"
D.Strings[110533]="过来，英勇的战士们！"
D.Strings[110534]="你以为自己赢了？我是不朽的！"
D.Strings[110535]="那我们就改天再——"
D.Strings[110536]="闭嘴！你还敢提他们！"
D.Strings[110537]="我也没忘记你的背叛！"
D.Strings[110538]="那天，我也失去了一个兄弟。"
D.Strings[110539]="大守备官索沃斯向你点点头。"
D.Strings[110540]="他们的指挥官过来了！去让他后悔亵渎这个世界吧。"
D.Strings[110541]="快，英雄们！纳鲁昏迷了，但这只是暂时的！"
D.Strings[110542]="他们向平台跑了！我们正想让他们去那儿呢。"
D.Strings[110543]="圣光与我们同在。"
D.Strings[110544]="道路已经肃清了。圣光之母在等着我们。$b$b我们得快一点。现在没有东西能帮她阻挡燃烧军团了。"
D.Strings[110545]="带路吧，先知。"
D.Strings[110546]="死亡！死亡与痛苦！"
D.Strings[110547]="我没事。"
D.Strings[110548]="你怕黑是对的。"
D.Strings[110549]="基尔加丹留下的悲伤记忆可没法像你净化这片土地一样被轻松抹去。"
D.Strings[110550]="你们休想逃出阴影！"
D.Strings[110551]="我们……都有……一死。"
D.Strings[110552]="太容易崩溃了！"
D.Strings[110553]="大守备官索沃斯肯定地哼了一声。"
D.Strings[110554]="我在寻找一片高地，以便在军团蜂拥而至时帮维伦找一条出路。$b$b我一直在掩护他撤退，但跟其他人走散了。$b$b你有什么消息吗？"
D.Strings[110555]="耐心点，阿拉托尔。这需要时间，但你们会团聚的。相信我。"
D.Strings[110556]="又有恶魔需要你处置了。去找到它，结果它。"
D.Strings[110557]="我还没说完呢。我……我不知道该怎么说。也许应该换个时间，换个地点——"
D.Strings[110558]="有一天，我或许还会需要这把家传的武器。但起码现在，我有不同的路要走。"
D.Strings[110559]="我想跟你谈谈，狩猎大师。"
D.Strings[110560]="我们的部队已经在要塞中站稳脚跟了，大主教。"
D.Strings[110561]="旁观"
D.Strings[110562]="为了我们的人民！"
D.Strings[110563]="他……想让我们看些什么……"
D.Strings[110564]="艾泽拉斯之魂与我对话时，就像在歌唱。即使她的信息不够清晰，但依然美妙。"
D.Strings[110565]="我会指挥部队在军团的要塞外面建立一个据点，你去跟麦格尼谈谈吧。"
D.Strings[110566]="我们必须团结一致。"
D.Strings[110567]="你帮忙保护了我们人民的未来。"
D.Strings[110568]="非常感谢，$n。"
D.Strings[110569]="我……必须立刻回到我的人民身边。"
D.Strings[110570]="我需要你的帮助。打起精神，好吗？"
D.Strings[110571]="这种雕虫小技救不了你们。"
D.Strings[110572]="泰沙拉克的力量爆发了！"
D.Strings[110573]="我原本希望这能有用。那里有光，可没人在家。"
D.Strings[110574]="你以为自己够机灵。但我知道你会是什么下场。"
D.Strings[110575]="拉扎鲁恩，我的仆人。留下来，干掉这些蠢货。我还有事要做。"
D.Strings[110576]="我恐怕不能让你通过，$n。"
D.Strings[110577]="|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t妖女奥露拉黛儿开始施放|cFFFF0404|Hspell:247551|h[诱惑魅力]|h|r。快把目光转开！"
D.Strings[110578]="这段代码显然少了一个分号！"
D.Strings[110579]="我恢复了。"
D.Strings[110580]="如果我们回不来，就听洛萨克森指挥。保重，法瑞娅。"
D.Strings[110581]="我的余烬不会熄灭……"
D.Strings[110582]="噢……真想尝尝……你们……融化的血肉……"
D.Strings[110583]="你们的心智太容易被蒙蔽了！"
D.Strings[110584]="我们已经尽力了，但虚空还是不断从裂隙中渗透进来。去找到圣光军团，用他们的祝福再次放逐黑暗吧。"
D.Strings[110585]="<跳进裂隙。>"
D.Strings[110586]="你们的抗争结束了！"
D.Strings[110587]="你们的战争结束了。"
D.Strings[110588]="一艘军团运兵舰和巡洋舰突然出现在了下层入口上方。"
D.Strings[110589]="控制台显示出了一个数字8。"
D.Strings[110590]="时间才是关键。我们决不能让军团抓到先知。"
D.Strings[110591]="|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t破碎遗迹出现了一条虚空裂缝！"
D.Strings[110592]="看来这个讨厌鬼需要私下解决。我要亲手干掉你！"
D.Strings[110593]="抱歉，我没听清楚。你能倒回去再说一遍吗？"
D.Strings[110594]="这个挑战非常简单。走进去，然后一直跑到建筑的另一边。"
D.Strings[110595]="|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t一艘军团巡洋舰正准备进行|cFFFF0000|Hspell:244627|h[齐射]|h|r！"
D.Strings[110596]="多亏了你，军团的火炮都哑火了。"
D.Strings[110597]="我们开始吧，图拉扬。"
D.Strings[110598]="愚蠢的行为，但我会满足你的。"
D.Strings[110599]="跟我说说大执政官薇拉拉。"
D.Strings[110600]="我们没法再应付这些怪物新的攻击了，得立刻结束战斗。"
D.Strings[110601]="一旦我们阻止它开火，那个安塔恩肯定会转头攻击我们的。"
D.Strings[110602]="军团灭绝者正在猛攻我们的部队。破坏他们的防护屏障，让他们看看维迪卡尔的力量！"
D.Strings[110603]="明白了。我知道一个合适的人选：伊米拉。"
D.Strings[110604]="无论那是什么，我相信萨格拉斯都不会只有这一个。"
D.Strings[110605]="它是什么东西，罗姆尔？"
D.Strings[110606]="然后呢？我曾因为违背她的意愿研究虚空而被关进牢笼。她会再把我关起来吗？甚至更糟？"
D.Strings[110607]="万物都将臣服于毁灭者。"
D.Strings[110608]="天启引擎启动。"
D.Strings[110609]="我们的人民曾经很贪婪，非常渴望力量。而我信仰圣光，而且我拥有足够的力量让他们明白自己的道路是错误的。"
D.Strings[110610]="你是来帮我们摆脱连绵不绝的敌人的吗？"
D.Strings[110611]="你能够想象到的最严重的创伤就是我们自己的同胞居然会这样背叛我们。哪怕是过去了那么多年，这个伤口依然在溃烂化脓。$b$b这样的伤口必须被净化。在真正开始疗伤前，我们必须先切除腐肉。"
D.Strings[110612]="阿克蒙德和基尔加丹与黑暗泰坦达成交易时，我的人民没能全部逃离。"
D.Strings[110613]="我明白。谢谢你们俩。"
D.Strings[110614]="滚开，该死的黑暗。"
D.Strings[110615]="这真是个大发现。我们得把它弄走！"
D.Strings[110616]="你可真傲慢。"
D.Strings[110617]="哎呀……这是什么呀？"
D.Strings[110618]="唔……哈哈哈哈……"
D.Strings[110619]="灭绝者都完蛋了。冲过去！"
D.Strings[110620]="它归我们了，姐妹。"
D.Strings[110621]="他听不明白了！我们得结束他的痛苦。"
D.Strings[110622]="他们……为什么……不听？"
D.Strings[110623]="<捡起密码本。>"
D.Strings[110624]="堕落者在用邪能仪式折磨我的人民。用烈焰……净化那些黑暗咒语！"
D.Strings[110625]="阿拉托尔……我和你的母亲没有一天不——"
D.Strings[110626]="我要把我所看到的展示给你们看。"
D.Strings[110627]="这里流淌着超乎我们想象的力量。小心。"
D.Strings[110628]="没有知识桂冠，我们就无法获胜。"
D.Strings[110629]="影卫入侵营地"
D.Strings[110630]="城市里的最后一批动物也被虚空控制了。这颗水晶的力量能帮它们重获自由。"
D.Strings[110631]="我来了，黑暗之主。"
D.Strings[110632]="它如此黑暗。"
D.Strings[110633]="我将回归虚空！"
D.Strings[110634]="让它闭嘴！"
D.Strings[110635]="安静……安静！"
D.Strings[110636]="如此强大……看看吧！"
D.Strings[110637]="臣服吧！你只能如此！"
D.Strings[110638]="真没耐心。相信你会在另外一边找到你想要的答案。"
D.Strings[110639]="你的同胞在这里干嘛？"
D.Strings[110640]="走吧。我掩护你。"
D.Strings[110641]="他还在这里，但穿越了虚空。如果我们快点，或许还能救他。"
D.Strings[110642]="祈祷声还没有消散。安息吧，兄弟们。"
D.Strings[110643]="这边。阿坎恩有个计划。"
D.Strings[110644]="但圣光从未抛弃我们。它召唤你来此，又给了我们胜机。这机会该如何利用……就看我们的了。"
D.Strings[110645]="你的血肉将永远融入这片深渊！"
D.Strings[110646]="军团刺客已死亡。你……暂时安全了。"
D.Strings[110647]="如此可怕的黑暗！"
D.Strings[110648]="烈焰的仆从们！享用他们的血肉吧！"
D.Strings[110649]="%s上箭的速度令人眼花缭乱。"
D.Strings[110650]="别放松！我们今天就了结这头野兽！"
D.Strings[110651]="勇士，阿古斯远征队召唤你加入我们对军团大本营——阿古斯的进攻。"
D.Strings[110652]="一个进步的标志……却将宇宙中的邪恶吸引到了我们面前。"
D.Strings[110653]="对阿古斯发起总攻时，我们就知道自己可能无法生还。泽尼达尔坠毁时，我们似乎没有了希望。"
D.Strings[110654]="这些晶塔每次只能传送少量部队，不过现在也够用了。"
D.Strings[110655]="我上一次见到这个地方，似乎已经是上辈子的事了。往事历历在目……$b$b\n<维伦皱着眉头陷入了沉思。>"
D.Strings[110656]="你背叛了你的人民，先知。还有你的世界。这种背叛只能用死亡来偿还。"
D.Strings[110657]="跟紧我。有人在监视我们。"
D.Strings[110658]="这已经不是我记忆中的阿古斯了。"
D.Strings[110659]="我们可能踏入了陷阱。"
D.Strings[110660]="小心，勇士。军团很擅长欺骗。"
D.Strings[110661]="幸存者！我们来守住这里，你得抢在军团前面找到他们。"
D.Strings[110662]="那个恶棍开始行动了。"
D.Strings[110663]="他终于悔悟了。但我仍然怀疑这是不是真心话。"
D.Strings[110664]="有人听得到我说话吗？"
D.Strings[110665]="<回忆奥蕾莉亚与黑暗纳鲁的战斗>"
D.Strings[110666]="<回忆破碎群岛的事件>"
D.Strings[110667]="打倒这些恶魔！"
D.Strings[110668]="%s变换着色彩，逐渐融入了周围的环境。"
D.Strings[110669]="燃烧军团来了。做好准备。"
D.Strings[110670]="恶魔正在快速靠近！准备战斗！"
D.Strings[110671]="这个营地就要失守了。我们必须撤到安全地带去！"
D.Strings[110672]="感谢你能来。我对这里的幽灵有所怀疑，但我需要一些他们的精华才能了解真相。$b$b拿上这个调和水晶，并对附近那些看起来比较凝练的幽灵使用。$b$b不过小心点，调和的过程可能会激怒他们。"
D.Strings[110673]="刚才出什么事了？他……杀了她？"
D.Strings[110674]="一对新鲜的眼睛……这正是我需要的。"
D.Strings[110675]="何必要等你的朋友呢？你是个强大的凡人！"
D.Strings[110676]="集会上有什么奇怪的情况吗？"
D.Strings[110677]="基尔加丹为我们做了怎样的计划呢？我很好奇。"
D.Strings[110678]="执政团的智慧引领我们发展到了现在。希望他们知道自己在做什么，否则结局恐怕不会太好……"
D.Strings[110679]="阿古斯的一滴鲜血就有不可思议的力量，泰坦的力量。"
D.Strings[110680]="我不想用奇怪来形容这种感觉，但就像丢掉了什么东西一样，没错。"
D.Strings[110681]="没什么值得介意的，陌生人。"
D.Strings[110682]="<晶匠奈崔斯攥紧了他的铁锤。>$b$b说得没错。不管它是什么，绝不能允许它伤害基尔加丹。"
D.Strings[110683]="你也感觉到它在紧紧地抓着你的心脏了吗？不管是什么，拜托让它停下来吧。"
D.Strings[110684]="妈妈说不让我和陌生人说话。"
D.Strings[110685]="真是傲慢！你们是在挑战安托兰统帅议会！"
D.Strings[110686]="|TInterface\\Icons\\SPELL_SHADOW_GRIMWARD.BLP:20|t湿地蹒跚者摆脱了他们的腐蚀者；但在这个过程中被|cFFFF0000|Hspell:253552|h[吸取]|h|r了力量。"
D.Strings[110687]="我想传送到金加洛斯那里。"
D.Strings[110688]="我想传送到传送门守护者哈萨贝尔那里。"
D.Strings[110689]="|TInterface\\Icons\\ABILITY_WARLOCK_MOLTENCORE.BLP:20|t你受到了|cFFFF0000|Hspell:244768|h[荒芜凝视]|h|r！"
D.Strings[110690]="|TInterface\\Icons\\INV_OFFHAND_1H_ULDUARRAID_D_01:20|t女巫会施放了|cFFFF0000|Hspell:250095|h[阿曼苏尔的诡诈]|h|r！"
D.Strings[110691]="|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t%s开始施放|cFFFF0000|Hspell:244056|h[虹吸腐蚀]|h|r。"
D.Strings[110692]="他正在与痛苦抗争……想让我们看到……"
D.Strings[110693]="我听说总督终于解决了那个多管闲事的牧师。"
D.Strings[110694]="%s的宠物科尔宾咬住你耳朵，寻找着亮晶晶的小玩意儿。"
D.Strings[110695]="对，呃，你可难住我了。不过这样还是很舒服的。$B$B如果你不介意的话，我还有很多东西要读。"
D.Strings[110696]="很高兴见到你，伊沙娜。你还好吗？"
D.Strings[110697]="我侍奉万物的末日。"
D.Strings[110698]="黑暗中的……长剑……痛苦的……沙漠。"
D.Strings[110699]="牺牲在所难免。"
D.Strings[110700]="那没用的。我们失败了。看天上！"
D.Strings[110701]="我会尽力安抚泰坦之魂，你们快去结束他们的痛苦！"
D.Strings[110702]="将一块化合石放进空洞。"
D.Strings[110703]="你看到了一个空洞，刚好能放进一块海丝利安石。"
D.Strings[110704]="你看到了一个空洞，刚好能放进一块化合石。"
D.Strings[110705]="相比他的恩赐，这点要求不算多。"
D.Strings[110706]="我还记得团结的泰坦……可背叛毁了我们。"
D.Strings[110707]="有个泰坦仍然逍遥法外。她的精华能确保远征的胜利。"
D.Strings[110708]="不愿臣服者都将被毁灭。这是唯一的方法。"
D.Strings[110709]="艾泽拉斯！"
D.Strings[110710]="这个物体散发着微弱的光芒。"
D.Strings[110711]="安托鲁斯的核心就在前面。军团的无穷大军就源于它的力量。"
D.Strings[110712]="你留下，麦格尼。我们继续前进。"
D.Strings[110713]="别废话了。让这条萨格拉斯的走狗看看，他休想占领我们的世界！"
D.Strings[110714]="图雷，它终于摆脱了军团的魔爪？很高兴见到你，启蒙者。"
D.Strings[110715]="军团显然十分自负。追到被他们荼毒的世界去，让他们明白，他们逃不过我们的怒火。"
D.Strings[110716]="主人要你们死！"
D.Strings[110717]="我的守望……结束了。"
D.Strings[110718]="你的存在就是污染。污染必须被净化！"
D.Strings[110719]="我的眼睛骗了我……"
D.Strings[110720]="你打倒了那些蛮兵，再次夺走了军团的胜利。他们时日无多了。"
D.Strings[110721]="不仅成功打击了敌人，还将战争机甲完好地送了回来？这真是奇迹！"
D.Strings[110722]="一次辉煌的胜利！圣光的前进无人能挡！"
D.Strings[110723]="我们的斥候发现军团最出色的飞行员都聚到了一起。这是个一举歼灭他们的绝佳机会！"
D.Strings[110724]="哪怕是来到安托鲁斯的大门前，你救出的士兵们也会记住那些邪恶野兽垂死的哀嚎。"
D.Strings[110725]="前进的通道打开了。消灭军团的战役又能继续了！"
D.Strings[110726]="一群审判官从暗中涌出，绑架了我们的巡逻队。找到这些俘虏，帮他们逃出生天吧。"
D.Strings[110727]="军团的召唤师正在召唤巨型地狱火，想让它威胁我们的盟友。快去阻止仪式！"
D.Strings[110728]="这地方有点不对劲。地底深处有什么东西在召唤我。"
D.Strings[110729]="有问题。"
D.Strings[110730]="感谢圣光！我们还不算太迟。"
D.Strings[110731]="不听话的人都被送去了森林，一去不复返。"
D.Strings[110732]="罗姆尔，派我们的先锋去开辟一条战线吧。"
D.Strings[110733]="你准备好离开了就告诉我一声。"
D.Strings[110734]="跪下，否则就死。"
D.Strings[110735]="通道打开了。同胞们，盟友们，勇士们，维迪卡尔在等着我们！"
D.Strings[110736]="狩猎成功，英雄们。"
D.Strings[110737]="我们要拯救我们的世界，并且……彻底阻止燃烧军团。"
D.Strings[110738]="真强大！这下那些恶魔该明白了，我们不会轻易认输。"
D.Strings[110739]="军团的部队对你的到来毫无准备！去消灭他们！"
D.Strings[110740]="削弱他们的部队！我们会用维迪卡尔发出最后一击！"
D.Strings[110741]="圣光与暗影互相依存。如果我们能得到某个强大生物的暗影之力，熔炉或许就完整了！"
D.Strings[110742]="虽然形体破碎了，但是，她的圣光还未离去。"
D.Strings[110743]="一旦发送器与圣光裁决者连通，我们就能用它向你发送一台战争机甲。相信你知道该怎么做。"
D.Strings[110744]="你的观点很宝贵，女伯爵莉亚德琳。我会认真考虑的。"
D.Strings[110745]="对力量不受约束的渴望是最可怕的堕落。你们是怎么找到前进方向的？"
D.Strings[110746]="时光飞逝，敌人正在逼近。过来，做好准备，孩子们。决战即将开始。"
D.Strings[110747]="我恳求你们为我而战。我们将一起击退突袭，破坏萨格拉斯到手的胜利。"
D.Strings[110748]="必须打倒这头黑暗的野兽。不要手软，但你最好动作快点。"
D.Strings[110749]="我在纳斯拉克斯附近的集结点等你。维迪卡尔必须做好准备，随时帮我们守住阵地。"
D.Strings[110750]="她的灵魂会在安托鲁斯复活，但惩罚是免不了的。萨格拉斯可不会善待失败者。"
D.Strings[110751]="我已经在扭曲虚空中追杀恶魔一千年了。我想我可以把这个让给你。"
D.Strings[110752]="打击军团的方式可不止一种。干得好！"
D.Strings[110753]="圣光军团长存。"
D.Strings[110754]="我的狩猎不会结束。"
D.Strings[110755]="很高兴看到在我远离艾泽拉斯的漫长岁月里，有你们这样的英雄保护它。"
D.Strings[110756]="打得好。在与恶魔漫长的斗争中，我们得珍惜每一次胜利。"
D.Strings[110757]="那些货物属于圣光军团，而不是萨格拉斯的爪牙。干得好。"
D.Strings[110758]="有事吗，外来者？"
D.Strings[110759]="小心军团的怒火。"
D.Strings[110760]="军团只要控制了这里的力量就能所向披靡。快把他们赶走。"
D.Strings[110761]="让圣光打倒你！"
D.Strings[110762]="圣光唾弃你，恶魔！"
D.Strings[110763]="军团想占领这些岛屿。去赶走他们。"
D.Strings[110764]="军团想要控制森林。去碾碎他们。"
D.Strings[110765]="我们要看着军团覆灭。"
D.Strings[110766]="啊，很好。我已经很久没有教训过学徒了。来吧，面对我。"
D.Strings[110767]="很好，英雄们。你们将军团赶出了这里。"
D.Strings[110768]="我从未想过要杀死泰坦。这让我很难过，但我们必须这么做。"
D.Strings[110769]="见证伟大的造物者的命运吧。他们注定要湮灭。"
D.Strings[110770]="他真有潜力。可惜他拒绝为强者效劳。"
D.Strings[110771]="这家伙真可悲。看看吧，现在明白为什么你的意志必须强于你控制的力量了吧。"
D.Strings[110772]="艾瑞达召唤师想在破碎之野建一座新建筑。去打乱他们的计划，帮帮我们的士兵！"
D.Strings[110773]="我们的远征是唯一的救赎。一切都将在主人的烈焰中重生！"
D.Strings[110774]="战场上又挤满了魔蝠。快操作我们的炮台把它们从天上打下来吧！"
D.Strings[110775]="萨格拉斯会高兴的。"
D.Strings[110776]="已消灭。"
D.Strings[110777]="即将关闭……"
D.Strings[110778]="就算我死了，他也会来……"
D.Strings[110779]="这座要塞只是对安托鲁斯的拙劣模仿。"
D.Strings[110780]="它肯定有帮手。四处看看，如果发现有趣的东西，立刻叫我。"
D.Strings[110781]="该干活了。"
D.Strings[110782]="我们终于扭转了局面。让军团在我们的攻势下瑟瑟发抖吧！"
D.Strings[110783]="如果他们也被扭曲，这个宇宙就无力阻止萨格拉斯了。"
D.Strings[110784]="萨格拉斯留了几只心爱的宠物来陪我们玩。快把这些怪物赶出战场。"
D.Strings[110785]="附近的一颗水晶上燃烧着火焰能量。"
D.Strings[110786]="光铸者，后退！"
D.Strings[110787]="光铸者，守住这里！"
D.Strings[110788]="祝你早日击溃军团。"
D.Strings[110789]="要是我把核心矩阵改成放逐……等等，不对。那样会爆炸的。"
D.Strings[110790]="安托鲁斯需要回报！玛凯雷将属于我们！"
D.Strings[110791]="她们在用阿曼苏尔的时间之力对付你们！"
D.Strings[110792]="是的，不过我也不常见到他们。等这一切都结束后，洛萨之子们或许应该办一个团圆宴！"
D.Strings[110793]="你这是找死。那就去死吧。"
D.Strings[110794]="他们又少了一张底牌。或许我能想办法将这些水晶用于我们的事业。"
D.Strings[110795]="安托鲁斯的大军正打算用塔尔加斯剩余的传送门再次入侵玛凯雷。快去阻止他们，否则我们就输定了。"
D.Strings[110796]="那些构造体肯定还不算太陈旧，对吧？我想最终没有任何东西能够抵挡老化。"
D.Strings[110797]="有本事的话，就跟上吧！"
D.Strings[110798]="快点，朋友们。某个恐怖的存在蠢蠢欲动了……不是塔尔加斯。"
D.Strings[110799]="阿克蒙德对印记的力量不屑一顾。没有其他部件，它只能提供些许力量。而他最渴望的就是力量。"
D.Strings[110800]="渺小的……家伙……"
D.Strings[110801]="不！我们的……命运……"
D.Strings[110802]="你们可悲的抵抗结束了！"
D.Strings[110803]="规则就是规则。"
D.Strings[110804]="你说话了吗？"
D.Strings[110805]="你来得很及时，$n。我们刚把最后一点补给用掉。我还以为我们要等很久呢。多谢！"
D.Strings[110806]="肉身无常，唯有力量长存。"
D.Strings[110807]="我们是为了自己所爱的人而战。"
D.Strings[110808]="我们要为家园……和亲人而战。"
D.Strings[110809]="我们称它为执政团之冠。"
D.Strings[110810]="我知道，亲爱的。我也是这样。但只要见到他，我们自然就会知道该说什么了。"
D.Strings[110811]="我的死……也阻止不了它。虚空……将吞噬一切。"
D.Strings[110812]="我终于……看清了。虚空……很软弱。"
D.Strings[110813]="晨光乍现。"
D.Strings[110814]="羚羊挂角。"
D.Strings[110815]="自信地前进吧。"
D.Strings[110816]="拥抱宁静。"
D.Strings[110817]="来吧。此地不宜久留。"
D.Strings[110818]="受伤？哼！你还站着呢。继续战斗，我们稍后再聊。"
D.Strings[110819]="让圣光净化你。"
D.Strings[110820]="我的战刃杀你如割草芥。"
D.Strings[110821]="狩猎结束了！你归我了，先知！"
D.Strings[110822]="我都逃出了禁魔监狱，不能死在你手里！"
D.Strings[110823]="你们的前线抵挡不了我的攻击！"
D.Strings[110824]="你会让阿古斯骄傲的。接受奖励吧。"
D.Strings[110825]="愿圣光指引我们。"
D.Strings[110826]="我有义务告知你，主人就是为此才设计了这些试炼。"
D.Strings[110827]="够了！你们的入侵到此为止了，凡人！"
D.Strings[110828]="生灵俱灭！"
D.Strings[110829]="我和我的机器人是来清理诺莫瑞根的！\n\n但我还没有完全搞清楚它们的技术。目前，我可以让这些小家伙吸收毒气，但它们会产生更多的毒气。\n\n而且，一切都变绿了，看上去朦朦胧胧的。不过这其实也不错，可以让我集中精神干活。\n\n那么，我今天能为你做点什么呢，我亲爱的穴居人朋友？\n\n<伯特抬起头，看向你的左侧。>"
D.Strings[110830]="说出你的目的，否则就离开这里。"
D.Strings[110831]="流亡者伊米拉。你回来干什么？"
D.Strings[110832]="敌人想靠近我们的裂隙！拿起武器！"
D.Strings[110833]="<吸收骨灰。>"
D.Strings[110834]="艾泽拉斯将和你们一同倒下。"
D.Strings[110835]="我们经过的世界都陷落了。下一个就是你们。"
D.Strings[110836]="一艘军团运兵舰和巡洋舰突然出现在了圣殿入口上方。"
D.Strings[110837]="一艘军团巡洋舰突然出现在了下层入口上方。"
D.Strings[110838]="一艘军团运兵舰突然出现在了圣殿入口上方。"
D.Strings[110839]="控制台显示出了一个数字3。"
D.Strings[110840]="我们的人民被当成了邪恶仪式的炮灰。毁掉这些可怕的造物，帮我们妥善安置死者的遗体。"
D.Strings[110841]="把它带回来——快。我们在下面建立了安全区。"
D.Strings[110842]="你们的插手干扰不了我们的进展。万物都将臣服于虚空，否则就将倒在它的脚下。"
D.Strings[110843]="噢，你成功了。了不起。"
D.Strings[110844]="我们正在溃败！快去解决这场入侵！"
D.Strings[110845]="很好，这个试炼完成了。但这只是因为我没有足够的空间来考验你。"
D.Strings[110846]="摧毁他们每一处增援点！"
D.Strings[110847]="有了圣光之心，我们就能让泽拉恢复鼎盛状态了。$b$b这件事越快越好，这样我们的力量就能早日超过燃烧军团。"
D.Strings[110848]="你将面对学宫大宰相加拉苏姆！"
D.Strings[110849]="大执政官薇拉拉直接听命于阿克蒙德本人。\n\n在我的记忆中，她是个专注而安静的人。她领导着执政馆追寻创造的力量，与启迪者工会平级。\n\n在她的指导下，我们召唤奥术生物的能力快速提高。在此地游荡的魔仆身上还带有她的印记。此外，她主导开发的护盾技术我们至今还在使用。\n\n加入军团后，她改名为薇莉瑟拉，并接受了大魔导师的头衔。\n\n但愿你永远不会遇到她，$n。"
D.Strings[110850]="跟我说说大宰相加拉苏姆。"
D.Strings[110851]="|TInterface\\Icons\\SPELL_SHADOW_PAINSPIKE:20|t阿努苏开始施放|cFFFF0404|Hspell:245164|h[绝望碎片]|h|r！"
D.Strings[110852]="|TINTERFACE\\ICONS\\WARLOCK_CURSE_SHADOW_AURA.BLP:20|t虚空之剑泽达特开始施放|cFFFF0404|Hspell:246340|h[虚空喷发]|h|r！快跑！"
D.Strings[110853]="$n正在寻找对手！"
D.Strings[110854]="我能在它开火前用能量压制它，但需要一点时间。"
D.Strings[110855]="唔。守门人被关闭了。"
D.Strings[110856]="遵命，队长。"
D.Strings[110857]="那就让我们一起结束它吧。"
D.Strings[110858]="你们终将失败。姐妹们会……"
D.Strings[110859]="你能告诉我该去哪儿找吗？"
D.Strings[110860]="需要消灭目标。"
D.Strings[110861]="那些发现真相的人试图逃跑，结果却被困在这梦魇中。我都不知道他们是怎么活下来的。"
D.Strings[110862]="他们可以成为宝贵的盟友。"
D.Strings[110863]="它……好冷。"
D.Strings[110864]="夺取传送门力量，奥蕾莉亚！它能成为你的武器！"
D.Strings[110865]="我绝不会死在你的手里，怪物。我跟你的主子还有账要算呢。"
D.Strings[110866]="我还能做得更好。"
D.Strings[110867]="你的血肉背叛了你，入侵者。"
D.Strings[110868]="你躲不了的。"
D.Strings[110869]="你们休想再玷污这个世界！"
D.Strings[110870]="双界行者？"
D.Strings[110871]="不，不……不。"
D.Strings[110872]="我们的决定都是为了你的安全。离开你让我们的心都碎了。"
D.Strings[110873]="<圣光裁决者砸入了悬崖的一侧。它没有破损，但显然无法运转了。$b$b你应该可以激活它的应急装置，将它传送到维迪卡尔。>"
D.Strings[110874]="我在下面的废墟里等你，$n。我们从黑暗消失之地开始。"
D.Strings[110875]="出来吧。我们并不想伤害你。"
D.Strings[110876]="不能再等了，以免他们守住通往阿古斯的路。"
D.Strings[110877]="啊！你来的正好，凡人！"
D.Strings[110878]="听到了吗？那低语声在要你死。"
D.Strings[110879]="阿坎恩终于明白了……"
D.Strings[110880]="我和奥蕾莉亚会保护你的。"
D.Strings[110881]="赞美纳鲁。我自由了。"
D.Strings[110882]="原来如此……"
D.Strings[110883]="黑暗笼罩了我。"
D.Strings[110884]="求你了，别烦我！"
D.Strings[110885]="他不可能……知道……"
D.Strings[110886]="痛苦……终于结束了。"
D.Strings[110887]="我们必须找到圣光军团。在他们的协助下，军团必将覆灭。我们必须找到……"
D.Strings[110888]="吞下这愚蠢的苦果吧！"
D.Strings[110889]="来吧。我要亲眼看到它。"
D.Strings[110890]="我感觉你有点失望。我真是你最好的学生吗？"
D.Strings[110891]="我有东西要给你看，但我们不能被发现。跟我来。"
D.Strings[110892]="艾泽拉斯的飞船抵达时，我感觉到了他的存在。虽然分开了那么久，但是我不会搞错的。"
D.Strings[110893]="看来你已经见过总督了。"
D.Strings[110894]="让我们看看，求你了……"
D.Strings[110895]="至少他们摆脱了痛苦。"
D.Strings[110896]="我们应该继续前进。"
D.Strings[110897]="正在检查……"
D.Strings[110898]="也就是说，你想要了解关于阿古斯的一切，以用来一举彻底摧毁军团？"
D.Strings[110899]="你准备好之后，我们得谈谈。"
D.Strings[110900]="水晶发射器脉动着源自维迪卡尔深处的微妙能量。"
D.Strings[110901]="跪下，否则就死！"
D.Strings[110902]="我要啃食你的灵魂。"
D.Strings[110903]="傲慢的凡人！来吧……受死吧！"
D.Strings[110904]="我们的意志……不会破碎。"
D.Strings[110905]="抱歉，先知。等我有空时再解释吧。"
D.Strings[110906]="集中攻击。我来吸引他的注意。"
D.Strings[110907]="这里非常不对劲。我自己的力量恐怕还不够。"
D.Strings[110908]="<维伦大口喘着气。>"
D.Strings[110909]="<紧张地深呼吸。>"
D.Strings[110910]="愿圣光指引我的眼。Pheta vi acahachi。"
D.Strings[110911]="鲁拉……"
D.Strings[110912]="但我们和盟友间还隔着数以千计的恶魔。我们得削减军团的兵力，才有希望活着抵达泽尼达尔。"
D.Strings[110913]="图拉扬！很高兴看到你再次挫败了军团暗杀你的阴谋。"
D.Strings[110914]="我们还继续吗？"
D.Strings[110915]="住手！先知和他的盟友不是我们的敌人。"
D.Strings[110916]="伊利丹让我把这块水晶带给你。"
D.Strings[110917]="喂？是谁？我听到你了！"
D.Strings[110918]="妈妈？妈妈！怎么这么黑啊？这儿好吓人……"
D.Strings[110919]="你能带我返回现在吗？"
D.Strings[110920]="小心点，凡人。"
D.Strings[110921]="我们逐一击败了军团最强大的爪牙。可现在，我们必须面对它真正的力量了……"
D.Strings[110922]="多么壮观的飞船。它似乎是靠德莱尼最喜欢的水晶来保持浮空的。或许我们也能用这些水晶来储存奥术能量？"
D.Strings[110923]="这些传说常常回荡在小屋渗水的岩洞中。人们低声诉说着那些勇敢的克罗库斥候的故事——自从燃烧军团给这个世界打上他们的烙印，他们负起了寻找幸存者的重任。$B$B有一个传说提到，他们曾与黑暗之王手下一位刺有邪能纹身的恶魔领主大战一场。后者的体型巨大，但他的毁灭性力量更令人叹为观止。$B$B这个可怕的，长着犄角的颅骨头盔就是那场大战的唯一遗物。它提醒着克罗库人民，传说常常始于一次寻找希望的探索之旅，并在悲伤的绝望与痛苦中结束。但有时……它们也会以胜利告终。"
D.Strings[110924]="这把镰刀由一位古代克罗库铁匠锻造，上面的符文记录了燃烧军团与克罗库之间的一场激战。$B$B它黯淡的、石灰色刀刃已经出现了缺口，刀锋附近还站着黑色的、干涸的液体斑点。$B$B缠绕在刀柄上的塔布羊皮已经严重磨损，默默提醒着我们它的主人原本是怎么握着这件由工具演变来的强大武器踏上战场的。"
D.Strings[110925]="我回家了。我迷失了那么久，跟一群陌生人在一个陌生的世界游荡……此时此刻，我无言以对。"
D.Strings[110926]="我应该听我妈妈的，去当一名技师。"
D.Strings[110927]="我真该多带一些血骑士来。我们可以从这些战士身上学到很多东西。"
D.Strings[110928]="不知道留在苏拉玛的人怎么样。我相信他们肯定已经控制了局势。$b$b但我很怀念和维多利亚对练的日子。她是一个强大的对手。"
D.Strings[110929]="当奥术回响遮罩笼罩你时，保护宝藏的法术消散了。"
D.Strings[110930]="军团就是这么对待他们的“盟友”的……$b$b幸好我们拒绝了他们的提议。"
D.Strings[110931]="把恶魔的眼睛从他们的头上扯下来吧，异界人。我要看看他们都看到了什么。"
D.Strings[110932]="把我送回安托鲁斯。"
D.Strings[110933]="我们不会转化成睿智的领袖，而会是可憎的怪物。"
D.Strings[110934]="让我看看军团进攻前的晴日峰吧。"
D.Strings[110935]="<观看万神殿的破灭。>"
D.Strings[110936]="没有足够的能量，我只能做一些……临时发挥了。我这大技师的名字可不是白叫的！让矩阵核心过载，然后重构……$b$b这不重要。最重要的是火炮还可以用。我们会打碎安托鲁斯的大门，击败军团的。$b$b你准备好了吗，$n？"
D.Strings[110937]="不，你才是恶魔！"
D.Strings[110938]="基尔加丹已经很久没有对他的人民讲过话了。这一定是非常重要的时刻。"
D.Strings[110939]="对艾瑞达来说，这是值得欢庆的一天！我们很快就可以达到到应有的地位了！"
D.Strings[110940]="如果艾泽拉斯的鲜血也有这种力量……那些想统治这个世界的人一定会不惜一切去争夺它。"
D.Strings[110941]="你的建议只是在浪费我的时间。走开吧。"
D.Strings[110942]="我没发现有什么不同寻常的事，陌生人。"
D.Strings[110943]="感觉有点不对劲，但我不知道是什么。可能是我多心了。"
D.Strings[110944]="我很害怕。我想回家。"
D.Strings[110945]="看，是兹——执……是那三个人！"
D.Strings[110946]="跪下吧，我还能给你个痛快。"
D.Strings[110947]="我想前往安托鲁斯，燃烧王座（团队副本）。"
D.Strings[110948]="这是我们昔日的圣地，如今已经被军团亵渎了。把他们赶出去！"
D.Strings[110949]="我想传送到阿格拉玛那里。"
D.Strings[110950]="我想传送到艾欧娜尔那里。"
D.Strings[110951]="我想传送到萨格拉斯的恶犬那里。"
D.Strings[110952]="|TInterface\\Icons\\ABILITY_MONK_BREATHOFFIRE:20|t女巫会正准备施放|cFFFF0000|Hspell:245671|h[卡兹格罗斯之焰]|h|r！"
D.Strings[110953]="请原谅，我已经有几千年没有制作过这样的东西了。"
D.Strings[110954]="帕拉克希斯号来了！快用护盾！"
D.Strings[110955]="它在伊利丹大人手里。他的计划已经展开了，屠魔者。"
D.Strings[110956]="这里有大量可供采集的原料。一点都不要浪费了。"
D.Strings[110957]="那位纳鲁临死时，鲁拉的精华召唤了我。一位诞生于圣光中的生物转化了成暗影。\n\n那种感觉很熟悉。\n\n你目睹的那场转化完全在我的控制下，会在我觉得恰当时使用。我还是过去的那个我……只是有了新的能力。\n\n使用这种力量会引起一些……不安。但暗影是一种可以控制的力量，无需恐惧。\n\n和任何武器一样，你必须在使用时把它控制住。"
D.Strings[110958]="科尔宾从%s身上偷了一枚铜币！"
D.Strings[110959]="在邪能中重生！"
D.Strings[110960]="脚下冰冷的地面能帮助我保持专注。"
D.Strings[110961]="这里充满了魔法与秘密。"
D.Strings[110962]="萨卡尔，怎么这么慢！？"
D.Strings[110963]="他们又冲我们来了！给我带些烈焰来！"
D.Strings[110964]="他们最后的行动能压制阿古斯的力量，彻底囚禁……萨格拉斯。"
D.Strings[110965]="让他们明白傲慢的代价吧！"
D.Strings[110966]="恶魔还以为我们都在关注阿古斯，他们肯定毫无防备。"
D.Strings[110967]="用钥石穿过裂隙，去跟军团战斗吧！"
D.Strings[110968]="就在我们进军阿古斯核心的时候，军团还在其他世界继续远征。"
D.Strings[110969]="新玩具？真迷人！"
D.Strings[110970]="所有的世界都将在邪火中燃烧！"
D.Strings[110971]="军团越来越鲁莽了。他们开始绝望了！"
D.Strings[110972]="军团又损失了一件武器。"
D.Strings[110973]="胜利就在眼前，勇士们！解决残余的部队，我亲自去对付飞船。"
D.Strings[110974]="我有许多同胞的灵魂都在军团手中受苦。快去释放他们，让他们安息。"
D.Strings[110975]="这不仅仅是攻城武器……"
D.Strings[110976]="|TInterface\\Icons\\SPELL_FIRE_FELFLAMEBOLT.BLP:20|t帕拉克希斯号向你降下了|cFFFF0000|Hspell:248326|h [邪能之雨]|h|r！"
D.Strings[110977]="让我们抓紧机会摧毁这台邪恶的机器吧。"
D.Strings[110978]="别靠近。你也会死的。"
D.Strings[110979]="他们找不到我们，尤其在阴影中。"
D.Strings[110980]="苦役……结束了……"
D.Strings[110981]="死亡在等着你。"
D.Strings[110982]="我们用所有的时间和资源造了一艘新船。它将是我们重获新生的依仗。"
D.Strings[110983]="你的世界归我们了！"
D.Strings[110984]="阿古斯是我们世代的家园。不能让军团继续占有它。"
D.Strings[110985]="我们必须消灭军团，哪怕是撕裂阿古斯也在所不惜。"
D.Strings[110986]="啊，它的性能比我想象的还要好！太棒了。"
D.Strings[110987]="这样就行了！我这就把坐标加入道标矩阵。"
D.Strings[110988]="不能让她的圣光堕入黑暗。我们得尽量把她的遗体送进熔炉里去。"
D.Strings[110989]="圣光保佑你！享受它的力量吧！"
D.Strings[110990]="我的一生从来都没有离开过苏拉玛。看到这里，我才明白夜之子躲过了怎样的命运。"
D.Strings[110991]="我的灵魂在此徘徊了无数世纪，远离黑暗泰坦的魔爪。但他终于找到我，来夺取我的力量了。"
D.Strings[110992]="大主教，战争机甲全速运转起来了。快看！"
D.Strings[110993]="有个末日女武神想在我们眼皮底下组建起恶魔大军。不能让她得逞。"
D.Strings[110994]="城里的小动物特别容易受虚空能量的影响。使用这块水晶帮它们摆脱虚空的控制吧。"
D.Strings[110995]="为了阻碍军团进攻，我们得破坏他们的工事。为艾泽拉斯而战吧！"
D.Strings[110996]="军团休想摧毁我们的意志。你找回了这些纪念品，让我的人民有了坚持下去的信心。非常感谢。"
D.Strings[110997]="你真是固执得叫人惊讶。"
D.Strings[110998]="相比我的怒火，军团之怒苍白无力。"
D.Strings[110999]="这些敌人不配得到仁慈的对待……我们也不会手软。"
D.Strings[111000]="我们伟大的文明之光璀璨闪耀……但是，却无人欣赏。"
D.Strings[111001]="很高兴看到古老的传统受到尊重。谢谢你。"
D.Strings[111002]="前面出现了一头野蛮的恶魔。把它送回地狱老家去。"
D.Strings[111003]="你胜利的消息会传遍阿古斯。那些怀念欺诈者的人注定要失败！"
D.Strings[111004]="空气中充斥着邪能腐蚀。快打倒这个邪恶的怪物！"
D.Strings[111005]="圣光军团很荣幸能成为你的盟友，勇士。"
D.Strings[111006]="他们的每次进攻，我们都会强力回击。为了胜利！"
D.Strings[111007]="我们在阿古斯从不缺目标。又来了一个，勇士。"
D.Strings[111008]="圣光军团需要你，英雄。我知道你一定能完成任务。"
D.Strings[111009]="阿古斯永远属于我们。"
D.Strings[111010]="我听着呢，说吧。"
D.Strings[111011]="愿圣光庇佑我们。"
D.Strings[111012]="收起你的陈腔滥调。来吧！"
D.Strings[111013]="军团自以为控制着这个世界。去证明他们错了。"
D.Strings[111014]="我见过这种战术。但愿这不是我所想的那个敌人。"
D.Strings[111015]="那是巴拉特。"
D.Strings[111016]="你休想挡我的路。"
D.Strings[111017]="把我的人带回来，图拉扬。"
D.Strings[111018]="这些燃烧的砂砾掩埋着力量之泉。不要让军团占据它们。"
D.Strings[111019]="军团想控制这座岛屿。去阻止他们的行动。"
D.Strings[111020]="这些蠢货应该趁早逃跑的。一个不留。"
D.Strings[111021]="军团必须明白，不管在哪里，我们总能击败他们。"
D.Strings[111022]="你可以做得更好的。"
D.Strings[111023]="这样下去，你只能勉强保命了。"
D.Strings[111024]="这里有股力量……一股无法理解的力量！"
D.Strings[111025]="我来引开他们，你继续执行任务。他们或许能帮我热热身……"
D.Strings[111026]="军团入侵了你们的世界。现在，反击的时刻到了。"
D.Strings[111027]="无论如何，我们都得保持警惕。只有确保前往地表的道路畅通，我们才能继续进攻。"
D.Strings[111028]="敌人攻破了塔门。拿起武器！"
D.Strings[111029]="各位，该去占领中央塔楼了。准备战斗！"
D.Strings[111030]="你活下来了……有趣！感觉如何？"
D.Strings[111031]="你站在了命运的分岔口，奥蕾莉亚。你需要作出选择……并面对后果。"
D.Strings[111032]="纳鲁很少会以这种方式堕入虚空。我所知道的几个例子都有凡人参与。真是耐人寻味……"
D.Strings[111033]="去搞清他们的企图……阻止他们的行动。"
D.Strings[111034]="$n周围凝聚起了邪能能量。"
D.Strings[111035]="消灭他能为我们争取到进入神殿的机会。"
D.Strings[111036]="干扰他们对我们都有好处。同时，这里的指挥官还有一件对我有用的东西。"
D.Strings[111037]="我们的部队准备好进攻燃烧王座了，但找到艾欧娜尔之魂以前还不能行动。"
D.Strings[111038]="或许只有完成我多年前未尽的任务，才能结束他们的痛苦。"
D.Strings[111039]="够了，让阴影吞噬他们吧。"
D.Strings[111040]="那些凡人动摇了！"
D.Strings[111041]="那就让冰冷的绝望吸干他的意志！"
D.Strings[111042]="分享你的痛苦吧！"
D.Strings[111043]="告诉我，当她攫取那毛皮和白骨的王座时，你们是否都被迫臣服了？不……我敢说，你们都是自愿的……起码你们自以为如此。"
D.Strings[111044]="当叛徒用鲜血染红王座……当你们的圣地熊熊燃烧，当破碎的面具挂上你们的壁炉……你们就知道了。但那就太迟了。"
D.Strings[111045]="该结束这一切了！"
D.Strings[111046]="你们的痛苦……才……开始。"
D.Strings[111047]="费了这么多功夫和口水，就为了拖延强者取得注定的胜利。"
D.Strings[111048]="她很有潜力。低语声会引诱她走向宿命。"
D.Strings[111049]="破碎悬崖"
D.Strings[111050]="维迪卡尔随时待命，$n。我们接下来该去哪儿战斗？"
D.Strings[111051]="去死吧，堕落者！"
D.Strings[111052]="我抵挡不了战斗的召唤了！"
D.Strings[111053]="该让我的士兵来屠杀你们了！"
D.Strings[111054]="$n附近的地面上有一颗邪能能量球。"
D.Strings[111055]="这笔钱真好赚。"
D.Strings[111056]="我要留几样你们的零件作为纪念。"
D.Strings[111057]="干得好，勇士们。数千年来，燃烧王座的居民还是第一次受到攻击。"
D.Strings[111058]="战争议会终于为背叛付出了代价。没有他们的领导，军团很快就会陷入混乱。"
D.Strings[111059]="|TInterface\\Icons\\PRIEST_ICON_CHAKRA_RED.BLP:20|t火焰能量在你体内燃烧。"
D.Strings[111060]="|TInterface\\Icons\\ABILITY_CREATURE_CURSED_05.BLP:20|t帕拉克希斯号开始为武器充能，准备给艾欧娜尔带来|cFFFF0000|Hspell:249121|h[终极毁灭]|h|r！"
D.Strings[111061]="我们在冲击军团的高级指挥官。帮我们争取时间，奥蕾莉亚。"
D.Strings[111062]="我的虚空会吞噬你……如果你好言相求的话。"
D.Strings[111063]="他们将沦为我们的猎物！"
D.Strings[111064]="我是不是应该在稳定渗透物之前给投影充能？噢……"
D.Strings[111065]="没有战争机甲支援，我是不会让部队冒险攻塔的。"
D.Strings[111066]="都卖点力！这片土地已经闲置太久了。"
D.Strings[111067]="快回去干活儿……否则就挨鞭子！"
D.Strings[111068]="记住我的话！别让维伦跑了！"
D.Strings[111069]="你摆脱不了懦夫的印记。我们不会罢休的……"
D.Strings[111070]="阿古斯会让你痛不欲生！"
D.Strings[111071]="高戈奈斯……迷失在了痛苦的风暴中！"
D.Strings[111072]="艾瑞达……统治一切……"
D.Strings[111073]="你犯下了大错。"
D.Strings[111074]="你们休想活着离开！"
D.Strings[111075]="别担心，大主教。艾娜拉和索沃斯就在主营地里。其他人都走散了，但我确信他们俩还活着。"
D.Strings[111076]="<光铸战争机甲>"
D.Strings[111077]="我的兄弟们正在让这里加速陷入黑暗。快去干扰他们的活动。当然你不去也行。反正虚空迟早会胜利。"
D.Strings[111078]="太神奇了！它们的鳞片上布满了能感应魔力的微粒。这个情报肯定能派上用场。"
D.Strings[111079]="你争取了宝贵的时间，但我们得保持警惕。只要军团知道我们在玛凯雷，他们就不会罢休。"
D.Strings[111080]="我的同胞们既勤奋又聪明。登陆场恐怕又需要净化了。你知道该怎么做的。"
D.Strings[111081]="这下暂时应该够他们忙的了。"
D.Strings[111082]="我们在玛凯雷的活动恐怕已经唤醒了更多愤怒的幽灵。去让他们安息吧。"
D.Strings[111083]="该搞搞大屠杀了！"
D.Strings[111084]="你面对过军团造成的一切威胁。现在，就请你帮我安放桂冠吧。"
D.Strings[111085]="这玩意已经过时了。把它扔在圣殿里跟纳鲁一起腐烂好了。"
D.Strings[111086]="他到底想用试炼证明什么？也许印记本身就是种试炼？"
D.Strings[111087]="“那不是你的道路”，他们这么告诉我。这就是他们想要的吗？"
D.Strings[111088]="剩下的，你都知道了。"
D.Strings[111089]="我属于阿古斯！"
D.Strings[111090]="不可能！这不对！"
D.Strings[111091]="固执的家伙……我明白了。"
D.Strings[111092]="你休想……摆脱命运……"
D.Strings[111093]="陌生人说话很奇怪。"
D.Strings[111094]="你来得正是时候。我们的补给就快用完了。$b$b告诉维迪尔，让他的送货员勤快点。"
D.Strings[111095]="你竟敢踏上他的世界？去死吧！"
D.Strings[111096]="你要利用一切可能的武器。"
D.Strings[111097]="但为了艾泽拉斯和我们爱的人，一切都值得。"
D.Strings[111098]="圣光指引着我们。"
D.Strings[111099]="剩下的部件还在阿古斯。我们得前往玛凯雷，我和我的兄弟们统治过的地方。"
D.Strings[111100]="我认真思考了眼前的困境。按照安托鲁斯的情况，贸然挑战只会让我们万劫不复。"
D.Strings[111101]="一千年来，我每天都在想应该跟他说什么。可现在……我却什么都说不出来。"
D.Strings[111102]="我的宝贝有饲料了。"
D.Strings[111103]="我的宠物们饿了。"
D.Strings[111104]="凝视深渊，体会绝望吧！"
D.Strings[111105]="我将带来你的末日！"
D.Strings[111106]="虚空将吞噬弱者！"
D.Strings[111107]="你的失败早已注定。"
D.Strings[111108]="游荡在这片废土上的邪能兽身上的皮是我见过的最臭的皮革。$b$b但愿我们有一天能够离开这里，找到一个新家园，而且那里的动物不要那么臭。"
D.Strings[111109]="我在你的西北方向找到了一个安全的撤离点。"
D.Strings[111110]="泽尼达尔的损失是个悲剧。但这艘船也不错。或许我们还有与燃烧军团一战的机会。"
D.Strings[111111]="多杀恶魔，注意安全。"
D.Strings[111112]="你们已经无药可救了！"
D.Strings[111113]="你想怎么死，魔法还是剑？"
D.Strings[111114]="在你面前的，是残余的旧日回忆，是我们人民的回响。那时，黑暗泰坦尚未降临。$B$B每当我们有同胞摆脱军团的控制，他们就会时不时地带回一些纪念我们昔日生活的东西。$b$b这些遗物象征着我们失落的一切……也提醒着我们是为何而战。"
D.Strings[111115]="不。该结束了。"
D.Strings[111116]="如果他们跑了，你们的尖叫声将响彻安托鲁斯！"
D.Strings[111117]="这里的军团暂时完蛋了。我们在阿古斯的战争还得继续。"
D.Strings[111118]="你太迟了！我的力量在增长……你很快就将倒下！"
D.Strings[111119]="我们会赢得这场战斗的。"
D.Strings[111120]="通道开启了！快，英雄们！"
D.Strings[111121]="即使我们已经被敌人包围了，我还是很高兴能够再次与我的士兵们汇合。"
D.Strings[111122]="我的痛苦……结束了……"
D.Strings[111123]="所以他也来了。我就怕这样。"
D.Strings[111124]="我欢迎湮灭……"
D.Strings[111125]="你没事吧？"
D.Strings[111126]="维伦？"
D.Strings[111127]="打得好！那艘船报废之后，我们就能集中应对其他战线了。"
D.Strings[111128]="你们的尸体将冻结在永恒的痛苦中。"
D.Strings[111129]="我会让你们毛骨悚然。"
D.Strings[111130]="看来我得把残骸收集起来才能去领赏了。"
D.Strings[111131]="我这就把你送回制图板……但得先碾碎你！"
D.Strings[111132]="我的母亲肯定会问起希尔瓦娜斯的事。你打算怎么跟她说？"
D.Strings[111133]="那些孢子能让你们更加强壮，小崽子们！快回去干活儿，否则我就亲手杀了你们！"
D.Strings[111134]="“神射手”巴拉特向你致敬。"
D.Strings[111135]="你们的侧翼暴露了。"
D.Strings[111136]="很好。该去迎接我们的命运了。"
D.Strings[111137]="我们从阴影中出击。"
D.Strings[111138]="<伊米拉警惕地摆弄着印记。>$b$b拿着这样的圣物，我觉得很不安全。"
D.Strings[111139]="这个印记是学宫的最高荣誉。只有阿克蒙德选中的人能获此殊荣。"
D.Strings[111140]="快，别让深渊吞噬了你！"
D.Strings[111141]="这里不安全！"
D.Strings[111142]="那些塔布羊对于我们跟恶魔的战争至关重要。谢谢你保护了它们。"
D.Strings[111143]="他们终于能够安息了。"
D.Strings[111144]="让烈焰吞噬你们！"
D.Strings[111145]="你们毫无胜算。没人能阻止我们的远征！"
D.Strings[111146]="捡起枯竭的裂隙石。"
D.Strings[111147]="裂隙暂时全部关闭了，但他们肯定还会回来的！"
D.Strings[111148]="军团的舰队在集结。干扰他们的准备工作，封印裂隙，不要让他们抵达阿古斯！"
D.Strings[111149]="勇士们！这边！"
D.Strings[111150]="也许吧。"
D.Strings[111151]="我能感觉到空气中的力量。即使过了那么久，它依然在此徘徊。"
D.Strings[111152]="代码审查成功！"
D.Strings[111153]="伯特的机器人要打坏蛋！"
D.Strings[111154]="我是来找启迪印记的。"
D.Strings[111155]="哦不……我记得那个声音。"
D.Strings[111156]="警告：你即将吸收一个邪恶巫师的骨灰。这可能会导致不可预见的后果。你确定要这么做吗？"
D.Strings[111157]="军团打开了入侵禁魔监狱的传送门。去关闭它们……以免被军团迂回包抄。"
D.Strings[111158]="军团已经在艾泽拉斯肆虐太久了。该结束这一切了。"
D.Strings[111159]="|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t泰沙拉克的余烬过载，引发了|cFFFF0404|Hspell:244912|h[烈焰喷薄]|h|r!"
D.Strings[111160]="<接过水晶。>"
D.Strings[111161]="真脆弱。"
D.Strings[111162]="看，拉恩科纳，这片布满溃烂之池、死亡横行的地方！"
D.Strings[111163]="重现他们痛苦而疯狂的临终记忆，是个残酷的任务。但这是最好也是唯一的方法。谢谢你。"
D.Strings[111164]="一艘军团运兵舰突然出现在了下层入口上方。"
D.Strings[111165]="控制台显示出了一个数字6。"
D.Strings[111166]="随着军团不断蚕食影豹的猎场，那些饥饿的野兽变得更具攻击性了。去削减它们的数量吧，别让它们灭绝我们的塔布羊群。"
D.Strings[111167]="非常感谢你的帮助，法瑞娅。"
D.Strings[111168]="蠢货！我们会击退你们。我们的任务不能失败！"
D.Strings[111169]="见证维迪卡尔的力量吧！"
D.Strings[111170]="我就快成功了！你休想阻止我，蝼蚁！"
D.Strings[111171]="维迪卡尔这艘新飞船的修理工作很繁重。我能帮你什么忙吗？"
D.Strings[111172]="你得去帮他们，图拉扬。我到敌后去引开恶魔。我们很快就回来，阿拉托尔。"
D.Strings[111173]="来补充邪能吧。"
D.Strings[111174]="那边的波莫斯对于这个时代有一句名言：“给我一百个光铸者。否则，就给我一千常规部队。”"
D.Strings[111175]="这些叛徒休想打败我们，因为圣光与我们同在。"
D.Strings[111176]="是谁需要医生？太糟糕了，我们还在跟燃烧军团开战呢！"
D.Strings[111177]="许多人被萨格拉斯许诺的力量和荣耀所蒙骗，自愿加入了军团。"
D.Strings[111178]="没错。我在进攻时发现，军团的奴隶都跑了。"
D.Strings[111179]="别忘了战利品，凡人。我来照顾奥蕾莉亚。"
D.Strings[111180]="快，快！快去告诉军需官！"
D.Strings[111181]="如果我们能抓住这只恶魔，我就能吸干他的能量，把他困住。勇士们，我来提供陷阱，你们负责抓住他。"
D.Strings[111182]="吸引它的注意，伊利丹。我们不能功亏一篑！"
D.Strings[111183]="就快成功了！"
D.Strings[111184]="接受净化吧，恶魔！"
D.Strings[111185]="你哪儿都别想去，“勇士”。主人已经决定了你的下场！"
D.Strings[111186]="我到前面去开路。通向泽尼达尔的桥上似乎没有多少守卫。愿圣光保佑我们。"
D.Strings[111187]="阿坎恩会让你们明白的！"
D.Strings[111188]="那些反抗军团的烈士之魂鼓舞了所有人。"
D.Strings[111189]="<你能看到信函的一角被折进了信使的护腕里。>"
D.Strings[111190]="睁大眼睛，放轻脚步，$n。"
D.Strings[111191]="我们会去圣光穹顶找你的。"
D.Strings[111192]="我们不能让这世界陷入黑暗。"
D.Strings[111193]="我看到了你的灵魂，好黑暗呐……"
D.Strings[111194]="拥抱万物的末日吧！"
D.Strings[111195]="图拉扬相信我的决定，我对他也一样。"
D.Strings[111196]="闭嘴，闭嘴！阿坎恩在听……"
D.Strings[111197]="暗影消散了。"
D.Strings[111198]="一切都必须毁灭！"
D.Strings[111199]="一切都被……宽恕……"
D.Strings[111200]="是你把我们丢在这里等死！"
D.Strings[111201]="现在就看部落会不会响应维伦的号召了。那些野蛮人缺乏荣誉感，但是很擅长战斗。"
D.Strings[111202]="<前往禁魔监狱。>"
D.Strings[111203]="他们要找阿坎恩。他承诺会拯救他们。"
D.Strings[111204]="我的同胞。曾经是。"
D.Strings[111205]="比如你想达成什么目的……"
D.Strings[111206]="胜利总会到来。"
D.Strings[111207]="你能听到吗？他们在咀嚼，撕咬，哭号……$b$b<阿坎恩颤抖了一下。>$b$b埃索隆已经迷失了。"
D.Strings[111208]="审视内心，看看你们的警惕带来的力量吧。"
D.Strings[111209]="我们与燃烧军团的战斗还未结束。"
D.Strings[111210]="你们的入侵必将失败！大审判官拉尔加不会放过你们。"
D.Strings[111211]="我们的锁链渴望你的血肉！"
D.Strings[111212]="脆弱的骨头。松脆美味！"
D.Strings[111213]="你在这里不安全。我们得离开。快。"
D.Strings[111214]="Acheon phetar，赐我洞察之眼。告诉我它们在哪里！"
D.Strings[111215]="我不明白。我怎么感应不到它们？"
D.Strings[111216]="警告：发现敌人"
D.Strings[111217]="没事。多亏了我们的朋友。可，奥蕾莉亚……还有件事。"
D.Strings[111218]="老朋友，奥蕾莉亚肯定就在某个地方。其他幸存者也一样。"
D.Strings[111219]="大主教图拉扬……我们终于见面了。"
D.Strings[111220]="我们变了，就像阿古斯。除了忍耐，还能怎么办？"
D.Strings[111221]="维伦。你终于回到被你抛弃的故乡了。"
D.Strings[111222]="我准备好搜索幸存者了。"
D.Strings[111223]="你们的世界注定要沐浴在主人的烈焰中。"
D.Strings[111224]="他们抢走了酒桶！"
D.Strings[111225]="当我知道他还活着，而且带头与破碎群岛的军团战斗时……我也不想再跟他说话。"
D.Strings[111226]="前路漫漫。无论未来如何，让“怒风”之名因你而荣耀吧。"
D.Strings[111227]="你总是不信任我……但我想我的行为确实很难令你相信。"
D.Strings[111228]="你有最美好的品质，泰兰德。你的信念，你的忠诚。我对你的信念从未动摇，即使在是最黑暗的日子里。"
D.Strings[111229]="你也很伤心吧？你也跟我一样迷路了吗？"
D.Strings[111230]="在萨格拉斯攻击之前，希利苏斯是一片令人生厌的土地，可沙漠里至少曾有过生命。\n\n你在过去的任务完成了吗，勇士？"
D.Strings[111231]="我的兄弟们对我的恨意不比对你的少。这可真……方便。把他们的眼球给我带来，让我享用他们的幻象吧。"
D.Strings[111232]="你把哈克穆德带回了家，又抛弃了他。哈克穆德明白这是怎么回事！"
D.Strings[111233]="<回忆前往阿古斯的旅程>"
D.Strings[111234]="<回忆军团降临之前的事件>"
D.Strings[111235]="伊利达雷！守住阵地！这些恶魔死到临头了。"
D.Strings[111236]="燃烧军团来了。拿起你们的战刃。"
D.Strings[111237]="燃烧军团包围了我们的营地。做好准备。"
D.Strings[111238]="恶魔来了。举起你们的战刃！"
D.Strings[111239]="防守阵型！军团来了！"
D.Strings[111240]="圣光在上……恶魔又来了！我们必须撤退。"
D.Strings[111241]="<拿起调和水晶。>"
D.Strings[111242]="我们现在该怎么办？"
D.Strings[111243]="我简直不敢相信我的眼睛……"
D.Strings[111244]="你是故意的吗？"
D.Strings[111245]="别因为我而停下。我就在这里。"
D.Strings[111246]="是的，我想要通过阿古斯最艰难的试炼考验自己。"
D.Strings[111247]="你认识叫一个“双界行者”的人吗？"
D.Strings[111248]="这片土地过去曾经历了许多磨难，但这座宏伟寺院最终的结局仍然是未知的。$b$b如果你想重新体验过去的那些时光，我可以暂时让你回顾过去。"
D.Strings[111249]="多年以前，我的人民所居住的世界被虚空吞噬，在狂风中粉碎。我能感觉到一些老朋友的面孔就快在阿古斯上出现了。$b$b当然，我不是说他们的脸。"
D.Strings[111250]="非常聪明。谁会怀疑一个小孩子呢？"
D.Strings[111251]="执政团长久以来一直都在领导着我们。这个陌生人又能给予我们什么新东西呢？"
D.Strings[111252]="我并不太明白他们说的意思。"
D.Strings[111253]="未来的日子也许会很黑暗。现在……去希利苏斯吧，亲眼看看世界的创伤。"
D.Strings[111254]="毫无疑问。我们应该警惕些，陌生人。"
D.Strings[111255]="一切正常，陌生人。"
D.Strings[111256]="也吧，不过没什么是基尔加丹处理不了的。"
D.Strings[111257]="我没发现任何情况。"
D.Strings[111258]="我想传送到破坏魔女巫会那里。"
D.Strings[111259]="我想传送到安托兰统帅议会那里。"
D.Strings[111260]="啊，对，它们焊接得很好。"
D.Strings[111261]="皇帝之赐已出现在了竞技场内！"
D.Strings[111262]="|cFFFF0000|Hspell:252508|h[帕拉克希斯号]|h|r即将抵达！"
D.Strings[111263]="|TINTERFACE\\ICONS\\Item_HolySpark.blp:20|t [将圣光精华放入虚空之光熔炉]。"
D.Strings[111264]="可惜他也没能杀了那个精灵和她的盟友。"
D.Strings[111265]="|TINTERFACE\\ICONS\\SPELL_FIRE_FELFLAMERING.BLP:20|t安塔恩灭光者正在施放|cFFFF0000|Hspell:250880|h[邪震轰炸]|h|r！快躲进圣光之佑里！"
D.Strings[111266]="%s的宠物科尔宾在你的背包里翻来翻去。"
D.Strings[111267]="$n准备了一桌百鱼宴！"
D.Strings[111268]="我需要修理，杜拉尔。"
D.Strings[111269]="噢，看！又来一个宠物。"
D.Strings[111270]="机器爆炸时，地表下有什么东西动了起来。"
D.Strings[111271]="把凝固的烈焰之球带回来给我，那样我或许就能强化自己的战斗力了！"
D.Strings[111272]="伤口……在……灼痛……"
D.Strings[111273]="你们要为了阻止他而自我囚禁吗？"
D.Strings[111274]="英雄们，我能向泰坦发送信号。可仪式一旦开始……就不能回头了！"
D.Strings[111275]="那女巫对众神之父的折磨已经化为了实体！"
D.Strings[111276]="将一块阿古斯晶石放进空洞。"
D.Strings[111277]="你看到了一个空洞，刚好能放进一块圣光榍石。"
D.Strings[111278]="你看到了一个空洞，刚好能放进一块炫彩孔雀石。"
D.Strings[111279]="我曾指望别人能看出萨格拉斯的谎言背后的黑暗。"
D.Strings[111280]="我会横跨星海找到你，叛徒！哪怕要花上一千年！"
D.Strings[111281]="别放弃。带上其他人逃走吧，先知。我们为你争取时间。"
D.Strings[111282]="我还记得觉醒时……生命在我们周围绽放。"
D.Strings[111283]="那些同胞还在抗拒真理，主人。但他们即将崩溃。"
D.Strings[111284]="您有什么吩咐，主人？"
D.Strings[111285]="别理他，姐妹！专心完成你的任务。这些灵魂就快像阿格拉玛一样臣服了。"
D.Strings[111286]="啊啊啊！女巫！这就叫痛苦？我还经受过更可怕的呢！"
D.Strings[111287]="就快结束了……"
D.Strings[111288]="这可能是燃烧军团在宇宙中的圣地。恶魔宁可自毁双目也不敢看它一眼。"
D.Strings[111289]="|TInterface\\Icons\\Spell_Warlock_DemonicEmpowerment.blp:20|t金加洛斯开始施放|cFFFF0000|Hspell:249740|h[超载]|h|r！"
D.Strings[111290]="看来联盟也响应了号召。"
D.Strings[111291]="我们在一次突袭中在要塞东边的山上留下了不少武器。找回它们或许会有所帮助。"
D.Strings[111292]="军团的狂热远征动摇了。我们要去被亵渎的每一个世界驱散他们的臭气。"
D.Strings[111293]="消灭？呸！他们的兵力数不胜数。这是不可能的，是找死！"
D.Strings[111294]="我们想跟你们结盟。我们应圣光军团请求，来阿古斯消灭燃烧军团。再次跟我们并肩战斗吧！"
D.Strings[111295]="直视黑暗吧！"
D.Strings[111296]="主人……会毁灭……你们的。"
D.Strings[111297]="我看到了你灵魂中的弱点！"
D.Strings[111298]="来吧，小东西！死在我手里吧！"
D.Strings[111299]="一头地狱火从天而降，压死了召唤它的主人。去消灭这个怪物，别让它妨碍我们前进！"
D.Strings[111300]="为了将身体改造成更野蛮的形态，一些强大的艾瑞达陷入了休眠。快趁机干掉这些恶魔！"
D.Strings[111301]="你们的主子失败了，恶魔。滚回深渊去！"
D.Strings[111302]="我们找到了一个地方，对运输部队至关重要。可是，那里充斥着恶魔蜘蛛。赶快去烧掉那些蛛巢！"
D.Strings[111303]="感受生命之力吧！敬畏它！"
D.Strings[111304]="魔兽和陷阱拖慢了我们的速度。去解决这些障碍！"
D.Strings[111305]="但愿我的兄弟姐妹们能够得到一点安宁。"
D.Strings[111306]="我的士兵提到一种能融化护甲，损伤肌体的恶魔烈酒。去找到这种邪恶酒水的来源并毁掉它！"
D.Strings[111307]="我们得联手。为了艾泽拉斯！"
D.Strings[111308]="他们的武器附近没有守卫吗？"
D.Strings[111309]="这里找不到圣光，只有死亡。"
D.Strings[111310]="谢谢你，外来者。我们后会有期。"
D.Strings[111311]="救命……帮帮……我……"
D.Strings[111312]="他们中有些是最强大的艾瑞达战士。千万不要低估了他们。"
D.Strings[111313]="你们必将失败。"
D.Strings[111314]="埃索达一直没有从多年前的那次坠毁事故中恢复过来。"
D.Strings[111315]="圣光不会随着始祖纳鲁死去。它闪耀在我们心中！"
D.Strings[111316]="战争机甲启动！"
D.Strings[111317]="我们想出了一个打击军团的计划。但这次行动需要你的特殊才能，勇士。"
D.Strings[111318]="军团必将覆灭。"
D.Strings[111319]="这一刻终于到来了。"
D.Strings[111320]="军团的士气崩溃了……他们的暴政也一样。"
D.Strings[111321]="我会带领人民走出一切黑暗。"
D.Strings[111322]="三人执政团迎来了一位异世界的访客！"
D.Strings[111323]="必须打破军团对这片土地的控制。我们的机会到了！击退黑暗！"
D.Strings[111324]="每次胜利都令人心满意足，但打倒那样的敌人……我得承认，它令我更满意。"
D.Strings[111325]="多亏了你，我们的部队集结起来了，军团也溃逃了。"
D.Strings[111326]="前面潜伏着恶魔。以艾泽拉斯之名打倒它！"
D.Strings[111327]="前面……有强大的邪魔即将发动攻击。做好准备！"
D.Strings[111328]="前面有个重要目标。以圣光的名义打倒它吧！"
D.Strings[111329]="当心点。"
D.Strings[111330]="我们的时代已经来临。"
D.Strings[111331]="堕暗者决不放弃。"
D.Strings[111332]="如果知识桂冠真在这座神殿里……那我们就要跟虚空本身战斗了。"
D.Strings[111333]="塔尔加斯。我们没必要战斗。我给你一次机会，走吧。"
D.Strings[111334]="这世界有一种绝不容军团染指的力量。去阻止他们得到它。"
D.Strings[111335]="特拉蒙肯定就在附近。跟着尸体走。"
D.Strings[111336]="法瑞娅，报告情况。"
D.Strings[111337]="这些恶魔在掠夺森林的资源。不能让他们继续下去了。"
D.Strings[111338]="记住，我们三个都会考虑你的表现。"
D.Strings[111339]="有人说，力量来自出人意料的地方。"
D.Strings[111340]="你引起了军团指挥官的注意。去击败他们，剩下的恶魔就会逃跑了。"
D.Strings[111341]="武器，为了摧毁超乎想象的力量而建造的武器。可惜这种力量没投入更有价值的事业。"
D.Strings[111342]="这群姐妹的想法是对的，但她们缺乏实现意志的力量。"
D.Strings[111343]="她在摆弄自己不理解的力量。只要稍有不慎，她就会迷失其中。"
D.Strings[111344]="很好！这样就能防止敌人派来更多援军了。"
D.Strings[111345]="在激战中，人们常常会忘记后勤补给的问题，但它们对持久战至关重要。从战场上多收集点东西回来，以强化我们的防线。"
D.Strings[111346]="你缺乏……远见。"
D.Strings[111347]="泽尼达尔坠毁后，我们就失去了大部分空中支援。那些魔蝠给我们的地面部队造成了不少麻烦。"
D.Strings[111348]="为了萨格拉斯！"
D.Strings[111349]="未发现残余敌对目标。继续巡逻。"
D.Strings[111350]="压制系统上线。"
D.Strings[111351]="你跟德莱尼叛徒，还有他们的圣光结盟，这只会让你软弱。"
D.Strings[111352]="这次武器测试真是大获成功。"
D.Strings[111353]="我成了破……玩具……"
D.Strings[111354]="或许还有别的办法。但我需要一个帮手。"
D.Strings[111355]="等等，先知。我侦查过此地。盘踞在玛凯雷的阴影比你想的更加顽固。"
D.Strings[111356]="圣光啊……他们对我的世界做了什么？"
D.Strings[111357]="尽力帮助他们吧。奥蕾莉亚是那里的统帅，她能告诉你该怎么做。"
D.Strings[111358]="军团战舰来了！隐蔽！"
D.Strings[111359]="看来我的训练完成了。"
D.Strings[111360]="如此混乱……如此痛苦。我从未体验过这种感受。"
D.Strings[111361]="多亏了你，斥候们平安无事了。"
D.Strings[111362]="$n周围凝聚起了奥术能量。"
D.Strings[111363]="感谢你们清除我和这根法杖间的障碍，英雄们。"
D.Strings[111364]="现在，该我们以牙还牙了。"
D.Strings[111365]="这块灵魂碎片又在召唤我了，可这次有些不同。那不是阿古斯。是……另一个存在。"
D.Strings[111366]="这么多人都被抛弃了……他们徘徊着，重温着临死的那一刻。"
D.Strings[111367]="他的命运由我们决定。为你们的傲慢付出代价吧，凡人！"
D.Strings[111368]="一个泰坦……军团肯定是用它的灵魂力量在虚空中制造兵力！如果毁掉它，那他们的无穷大军……"
D.Strings[111369]="我们不能让这可怜虫尝到胜利的滋味。"
D.Strings[111370]="已经受不了了吗？"
D.Strings[111371]="这些冒牌货在呢喃着疯狂的低语。真外行！让我来示范一下正确的技术。"
D.Strings[111372]="看着软弱的心灵沉沦黑暗吧。"
D.Strings[111373]="好吧。我们会尽全力保护艾欧娜尔，不会让她堕落的。"
D.Strings[111374]="你准备好了就把手放在圣石上。"
D.Strings[111375]="看来还需要调整。"
D.Strings[111376]="但战斗远未结束。世界核心里有股强大的力量在痛苦翻滚。"
D.Strings[111377]="谁敢亵渎这副神圣的铠甲？"
D.Strings[111378]="我既然能亲手打发了你们，又何必用战舰呢？"
D.Strings[111379]="看来我的雇主高估了你们的威胁。但只要有钱赚就行。"
D.Strings[111380]="没错。我们必须得毁掉那些地狱火引擎。勇士们，用这个传送器登上维迪卡尔。去找下一个目标！"
D.Strings[111381]="你不是孤军奋战，图拉扬。恶魔每前进一步，都将付出血的代价。"
D.Strings[111382]="是生命的缚誓者艾欧娜尔！这座传送门就通向她的圣殿。快走，我掩护你们！"
D.Strings[111383]="勇士们！我听到了熟悉的召唤声，所以才会杀进这该死的地方。"
D.Strings[111384]="有两个恶魔倒下了，但还有更多在等着你去斩杀。"
D.Strings[111385]="附近的一颗水晶上流淌着邪能能量。"
D.Strings[111386]="一旦攻破那些尖塔，我们就能行动了。"
D.Strings[111387]="让他们吃点苦头。"
D.Strings[111388]="维迪卡尔随时待命。"
D.Strings[111389]="我会助你一臂之力的。"
D.Strings[111390]="恶魔闯入了我们的世界，一心想要毁灭所有的生灵。"
D.Strings[111391]="我该早点开始学习的。"
D.Strings[111392]="挖地三尺也要找到他！"
D.Strings[111393]="额，我怎么不知道……"
D.Strings[111394]="卡兹格罗斯的意志扭曲了。他控制不了自己的烈焰！"
D.Strings[111395]="圣光裁决者……她太壮观了。我马上就让它运转起来！"
D.Strings[111396]="你们越挣扎，赏金就越高！"
D.Strings[111397]="其他军官呢？但愿他们都安然无恙。"
D.Strings[111398]="<维迪卡尔传送道标>"
D.Strings[111399]="看来我得呼叫火力支援了。"
D.Strings[111400]="影豹在吞噬学宫的幽灵。给我带些它们的鳞片来，我或许能想出解决的办法。"
D.Strings[111401]="什么都阻止不了主人！"
D.Strings[111402]="嘘……你听到了吗？"
D.Strings[111403]="你的尸体将成为主人的战利品！"
D.Strings[111404]="陷入虚空吧！"
D.Strings[111405]="我没有……预见到。"
D.Strings[111406]="黑暗会吞噬你！"
D.Strings[111407]="虚空在召唤我！"
D.Strings[111408]="唯有攻无不克，才能战无不胜。"
D.Strings[111409]="那里有一个着陆的传送器。"
D.Strings[111410]="鲜血怎么啦？人人都需要它。但叛徒除外。所以我们要放干他们的血。"
D.Strings[111411]="等杀光他们，你就能休息了！继续战斗！"
D.Strings[111412]="不应该是这样的！我是不会死的！"
D.Strings[111413]="Sheet-sah，你还是只会躲在盟友身后。"
D.Strings[111414]="我只希望你的妻子和孩子能让你留下来。可你却冷酷地抛下了他们。"
D.Strings[111415]="你没有“失去”他。你是抛弃了他——抛弃了一切！同胞、故乡……和家人！"
D.Strings[111416]="噢，你真是伤透了基尔加丹的心！你知道你的离开让他多难过吗？"
D.Strings[111417]="剑圣特拉蒙向你致敬。"
D.Strings[111418]="生灵俱灭。"
D.Strings[111419]="明白了。勇士们，一旦大门开启，就去找鲁拉吧。我们掩护你们。"
D.Strings[111420]="原谅我，孩子。"
D.Strings[111421]="军团正在组装灭绝者，想用它轰击泽尼达尔！你得去攻占它。"
D.Strings[111422]="你们的血肉将滋滋作响。"
D.Strings[111423]="那就来吧。让我们以痛换痛吧！"
D.Strings[111424]="冷静点，那只是风而已。"
D.Strings[111425]="我竟然输了……"
D.Strings[111426]="看来你们需要一个惨痛的教训。让我来教你们吧。"
D.Strings[111427]="又一个敌人化为尘埃了。"
D.Strings[111428]="好黑……我还以为圣光……"
D.Strings[111429]="剑与魔法，都能为圣光服务。"
D.Strings[111430]="你！你不是恶魔。快来帮我们杀敌！"
D.Strings[111431]="我跟夸拉姆之间……有些旧怨。$b$b这么说吧，我离开学宫的过程不怎么愉快。"
D.Strings[111432]="我们得快点离开，否则就迟了！"
D.Strings[111433]="你们能抗拒烈焰，但休想抗拒我的怒火。"
D.Strings[111434]="让泰沙拉克的力量吞噬你们！"
D.Strings[111435]="在我的意志下，顽抗毫无意义。我会击溃你。"
D.Strings[111436]="我们还见过更糟的呢。我会守住这里的。"
D.Strings[111437]="圣光救不了你们……"
D.Strings[111438]="我们将一起见证军团走向末路。"
D.Strings[111439]="<地面上有一条裂隙，宽度勉强能够让你挤进去。里面非常黑暗，什么都看不见，但你能看出它很深。>"
D.Strings[111440]="坟场中又多了一具尸骨。"
D.Strings[111441]="|TInterface\\ICONS\\ABILITY_WARLOCK_BACKDRAFTGREEN.BLP:20|t站在|cFFF00000|Hspell:244761|h[歼灭]|h|r的影响范围内以躲避团队伤害！"
D.Strings[111442]="插入心灵幼虫"
D.Strings[111443]="要是能看到她返回安托鲁斯后的下场就好了。萨格拉斯可不会善待失败者。"
D.Strings[111444]="关于我的同胞为什么会在玛凯雷陷入疯狂，还有许多未解之谜。把你找到的记忆水晶都带回来给我，以便我继续研究。"
D.Strings[111445]="一艘军团巡洋舰突然出现在了主入口上方。"
D.Strings[111446]="控制台显示出了一个数字4。"
D.Strings[111447]="那些恶魔俘虏了我的人民，用可怕的仪式控制他们。我们不会再忍耐了。帮我们反抗军团吧！"
D.Strings[111448]="|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t废弃的瞭望台出现了一条虚空裂缝！"
D.Strings[111449]="我看到了，你既敏捷又顽强。但我在想，这是否能证明你也同样坚韧呢？$b$b<夸拉姆发出了一阵类似轻哼的噪声。>"
D.Strings[111450]="小心台阶。"
D.Strings[111451]="|TINTERFACE\\ICONS\\INV_ENCHANT_VOIDSPHERE.BLP:20|t杀掉虚空影像，不要让他们施放|cFFFF0404|Hspell:246483|h[湮灭裂隙]|h|r！"
D.Strings[111452]="我可不会留情的。我们开始吧。"
D.Strings[111453]="有话就说，陌生人。"
D.Strings[111454]="跟我说说高阶启迪者阿尔贡。"
D.Strings[111455]="|TINTERFACE\\ICONS\\ability_fixated_state_red.blp:20|t晋升者祖拉尔锁定了你！"
D.Strings[111456]="|TINTERFACE\\ICONS\\INV_KNIFE_1H_FIRELANDSRAID_D_01.BLP:20|t阿格拉玛开始施放|cFFFF0404|Hspell:244688|h[泰沙拉克剑技]|h|r！"
D.Strings[111457]="就……快要……成功了！"
D.Strings[111458]="然后呢？她因为我使用虚空之力而把我关进了牢笼。她会再把我关起来吗？甚至更糟？"
D.Strings[111459]="干得好。我和维伦在毁灭之冠等你，争取尽快阻止那个安塔恩。"
D.Strings[111460]="一群恶魔威胁到了维迪卡尔。去让它们腐臭的灵魂尖叫着滚回安托鲁斯的大厅。"
D.Strings[111461]="|TInterface\\ICONS\\ABILITY_HUNTER_SNIPERSHOT.BLP:20|t你成为了|cFFF00000|Hspell:244536|h[邪能轰炸]|h|r的目标！"
D.Strings[111462]="你准备好了就说一声。我们肯定很快就会有伴儿了。"
D.Strings[111463]="歼灭火炮装填完毕。"
D.Strings[111464]="我们依靠剑与魔法抗衡敌人。我们不能过于依赖其中一种。"
D.Strings[111465]="泽尼达尔坠毁时，哈顿的人救了我。"
D.Strings[111466]="虚空只会揭示部分真理。相信你的直觉。"
D.Strings[111467]="这是伪装？你想隐瞒什么？"
D.Strings[111468]="你以为你能逃跑吗？"
D.Strings[111469]="哈！可悲的凡人。"
D.Strings[111470]="他们的意志必将实现！意志必将实现！"
D.Strings[111471]="仆从们！过来！"
D.Strings[111472]="放弃吧，怪物！今日圣光必胜！"
D.Strings[111473]="虽然饱受折磨，我的人民仍在抵抗军团该死的远征。恶魔能摧毁他们的躯体，但不能击溃他们的意志。去释放他们的灵魂，让他们安息。"
D.Strings[111474]="但愿你能抢在军团前面找到这个拉尔加。维迪卡尔上有人能帮你。"
D.Strings[111475]="看，通道关闭了。我们该怎么去埃索隆？"
D.Strings[111476]="对，阿坎恩知道。"
D.Strings[111477]="|TInterface\\ICONS\\Spell_Deathknight_Necroticplague.blp:20|t你受到了|cFFF00000|Hspell:244093|h[冥魂之拥]|h|r的影响！"
D.Strings[111478]="我们是来帮你的，小家伙！"
D.Strings[111479]="离远点。那些玩意儿能伤人的！"
D.Strings[111480]="我……明白。愿圣光保佑你们。"
D.Strings[111481]="召唤"
D.Strings[111482]="逃亡地"
D.Strings[111483]="感谢你解放了那些动物。我还记得孩子们与它们玩耍的日子。如今的景象真让我心痛。"
D.Strings[111484]="黛文纽斯，我不在时，保护好我们的人民。我该去看看我们的故乡了。"
D.Strings[111485]="你们的世界完了。通向阿古斯的道路已开启。萨格拉斯的无穷大军来了！"
D.Strings[111486]="你该回维迪卡尔去报告我们的发现了。"
D.Strings[111487]="你感觉如何？"
D.Strings[111488]="带路吧。我已经准备好了。"
D.Strings[111489]="谁在呼唤阿坎恩？出来！"
D.Strings[111490]="圣光，帮帮我……"
D.Strings[111491]="它在召唤我们。听呐，听呐！"
D.Strings[111492]="伟大的黑暗无所不知！"
D.Strings[111493]="愿圣光诅咒你，先知！"
D.Strings[111494]="大审判官拉尔加被囚禁在禁魔监狱深处。军团已经到了，小心点！"
D.Strings[111495]="我就是来调查的。尽量跟上。"
D.Strings[111496]="这痛苦……只是暂时的。"
D.Strings[111497]="你已被发现，敌方派出了一名刺客。"
D.Strings[111498]="萨格拉斯降临时，我的兄弟们都抛弃了他们的部件。它们还在这里，在玛凯雷。"
D.Strings[111499]="机甲已经抵达"
D.Strings[111500]="在燃烧军团的强大压力下，我们怎么才能完好无损地抵达阿古斯？"
D.Strings[111501]="我们得赶快行动。既然恶魔已经知道我们来到地表，那军团很快就会全力围剿我们的"
D.Strings[111502]="我上一次见到她还是在泽尼达尔。她还在……接受监控。"
D.Strings[111503]="我不想跟你作对，哈顿。但我不能让你的怨恨妨碍我们与军团的战斗。"
D.Strings[111504]="没关系。它已经开始了。"
D.Strings[111505]="我们再也扛不住那些怪物的下一轮攻击了。得支援我们的部队。"
D.Strings[111506]="真的？"
D.Strings[111507]="今天我会给你一个汉堡作为星期二那天的报酬。"
D.Strings[111508]="好吧好吧……"
D.Strings[111509]="%s举杯祝酒！"
D.Strings[111510]="哇~~！！"
D.Strings[111511]="妈呀！"
D.Strings[111512]="拥抱你的末日吧！"
D.Strings[111513]="好了……"
D.Strings[111514]="暴风城最好的饮料！"
D.Strings[111515]="这里有暴风城最好的酒！"
D.Strings[111516]="%s发起了冲锋！"
D.Strings[111517]="救命啊！"
D.Strings[111518]="新鲜的肉！"
D.Strings[111519]="只需一小会儿，$n。"
D.Strings[111520]="这到底怎么回事？"
D.Strings[111521]="振作起来！"
D.Strings[111522]="%s捏着他的关节。"
D.Strings[111523]="$n，我有些话要和你说。"
D.Strings[111524]="你不能拿走我的蜡烛！"
D.Strings[111525]="注意你的脚步……"
D.Strings[111526]="我的想法很对。"
D.Strings[111527]="我要踩碎你的骨头，$R！"
D.Strings[111528]="%s清了清嗓子。"
D.Strings[111529]="这只需要花费一点时间，$n。"
D.Strings[111530]="还没到吗？"
D.Strings[111531]="你好。你是来寻找魔法导师的吗？"
D.Strings[111532]="我是一个卖布的，这是我默认的见面打招呼的话。"
D.Strings[111533]="我是一个卖布的，这是我常用的见面打招呼的话。"
D.Strings[111534]="关门，放狗！"
D.Strings[111535]="欢迎来到我的旅店，疲惫的旅行者。我能为您做点什么吗？"
D.Strings[111536]="将这座旅店设为你的家。"
D.Strings[111537]="法师"
D.Strings[111538]="潜行者"
D.Strings[111539]="德鲁伊"
D.Strings[111540]="牧师"
D.Strings[111541]="圣骑士"
D.Strings[111542]="猎人"
D.Strings[111543]="术士"
D.Strings[111544]="你在寻找哪种专业的训练师？"
D.Strings[111545]="工程学"
D.Strings[111546]="采矿"
D.Strings[111547]="烹饪"
D.Strings[111548]="制皮"
D.Strings[111549]="剥皮"
D.Strings[111550]="急救"
D.Strings[111551]="草药学"
D.Strings[111552]="裁缝"
D.Strings[111553]="钓鱼"
D.Strings[111554]="附魔"
D.Strings[111555]="我们代表的是黑暗。永恒而无形的黑暗。"
D.Strings[111556]="我能为你做什么？"
D.Strings[111557]="告诉我更多的信息。"
D.Strings[111558]="你听到那个声音了吗？"
D.Strings[111559]="你要找哪一类型的训练师？"
D.Strings[111560]="你为什么来这里？"
D.Strings[111561]="痛苦……终于结束了……"
D.Strings[111562]="我终于逃出来了！"
D.Strings[111563]="%s开心地欢呼了起来！"
D.Strings[111564]="这里什么都没有！"
D.Strings[111565]="就是这样。完成了。"
D.Strings[111566]="小心爆炸！"
D.Strings[111567]="你会为此付出代价的……"
D.Strings[111568]="我能在旅店里干些什么？"
D.Strings[111569]="我在这里！"
D.Strings[111570]="魔法只会使弱者堕落。继续你的训练吧，不然你的命运就跟那些家伙相差无几了。"
D.Strings[111571]="听你的！"
D.Strings[111572]="即使在和平时期仍然会有战争，而许多氏族仍在酋长的领导下奋勇作战。你是来为奥格瑞玛而战的吗？"
D.Strings[111573]="即使在和平时期仍然会有战争，而许多部落仍在酋长的领导下并肩奋战。你是来为奥格瑞玛而战的吗？"
D.Strings[111574]="你在这儿做什么？"
D.Strings[111575]="我不是个熟练的草药师，那么我还能帮上忙吗？"
D.Strings[111576]="但是……"
D.Strings[111577]="离开那儿！"
D.Strings[111578]="接下来发生了什么事？"
D.Strings[111579]="我在这儿！"
D.Strings[111580]="我对草药学没什么了解，那么我还能帮上忙吗？"
D.Strings[111581]="邮箱"
D.Strings[111582]="嘿！别碰那个！"
D.Strings[111583]="如果你不想死就跟我来。"
D.Strings[111584]="打开它。"
D.Strings[111585]="我能为你提供什么帮助吗？"
D.Strings[111586]="你需要有人指引你到达目的地吗？"
D.Strings[111587]="你要去哪里？"
D.Strings[111588]="%s昏倒在地。"
D.Strings[111589]="我……我在哪里？"
D.Strings[111590]="呃。"
D.Strings[111591]="有人吗？"
D.Strings[111592]="我们玩完了！"
D.Strings[111593]="%s转过来面对着你。"
D.Strings[111594]="呜喔！"
D.Strings[111595]="我们有闪光的钩子。这是基里安·哈根给我们的，他教我们如何剥皮。你有很好的兽皮。去盗贼区的内环找他吧。"
D.Strings[111596]="你什么意思？"
D.Strings[111597]="我将洗耳恭听。"
D.Strings[111598]="你，也必将臣服在我的脚下！"
D.Strings[111599]="哈！你们就这点本事吗？"
D.Strings[111600]="我们渴望复仇。"
D.Strings[111601]="愤怒的死者是永远不会安息的！"
D.Strings[111602]="更多的……更多的灵魂！"
D.Strings[111603]="毫无疑问。"
D.Strings[111604]="谢谢你，$n。我的痛苦结束了。"
D.Strings[111605]="猎人训练者名叫索塔尔。去剃刀岭西南部的洞穴中找他吧。"
D.Strings[111606]="%s醒来了！"
D.Strings[111607]="你需要什么？"
D.Strings[111608]="什么意思？"
D.Strings[111609]="医生来了！"
D.Strings[111610]="你想要找什么？"
D.Strings[111611]="你要找什么？"
D.Strings[111612]="你有事吗？"
D.Strings[111613]="不可能。"
D.Strings[111614]="你需要什么方面的指引？"
D.Strings[111615]="你需要指引吗？"
D.Strings[111616]="正在上课！"
D.Strings[111617]="愿圣光保佑你，$c。"
D.Strings[111618]="如果这就是你来此的目的，我们会尽一切可能训练你，帮助你成为真正的牧师。"
D.Strings[111619]="找我有事吗，$c？"
D.Strings[111620]="愿月神与你同在，$c。"
D.Strings[111621]="你怎么敢！"
D.Strings[111622]="真可怜。"
D.Strings[111623]="令人失望。"
D.Strings[111624]="这么黑暗……"
D.Strings[111625]="我们的导师玛法里奥已经从沉睡中回来了，$c。他是我们的指路明灯，我们必须竭尽全力保护他。"
D.Strings[111626]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B来自翡翠梦境的召唤将很快占据你的心灵。你将冬眠数年，在最纯净的环境中生活。你将在那儿接受最终的训练。"
D.Strings[111627]="我们代表的是黑暗，永恒而无形。"
D.Strings[111628]="你看起来像是那种手脚不干净的家伙。有什么我可以帮忙的吗？"
D.Strings[111629]="我跟你没什么好说的，你最好找个$c训练师来帮助你。"
D.Strings[111630]="看看野兽们的智慧和知识，你就会看到你自己。像猫头鹰一样地观察，从猎豹身上学习聪明机灵，并体现出狼的强大精神力量。"
D.Strings[111631]="死吧，你这卑鄙的家伙！"
D.Strings[111632]="愿灵魂与你同在。"
D.Strings[111633]="啊，$g牧师:女牧师;，你来的正是时候。谢谢你。"
D.Strings[111634]="你向我们发出挑战而我们来了。你所说的大师在哪里？"
D.Strings[111635]="啊，牧师，你来得正是时候。谢谢你。"
D.Strings[111636]="啊，$g牧师:女牧师;，你来得正是时候。谢谢你。"
D.Strings[111637]="%s喘息着。"
D.Strings[111638]="看看野兽的智慧和学识吧，这会帮助你你认清自己。你要学会像猫头鹰那样敏锐，像猎豹那样灵巧，像狼那样强韧。"
D.Strings[111639]="魔法只会使那些软弱的人堕落。继续你的训练吧，不然你的命运就跟那些人相差无几了。"
D.Strings[111640]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B来自翡翠梦境的召唤将很快占据你的心灵。你将休眠数年，在最纯净的环境中生活。你将在那儿接受最终的训练。"
D.Strings[111641]="这些都是大地之母走过的道路。愿你的祖先保佑你$c。"
D.Strings[111642]="我不会伤害你的。我在监视野猪人并记录他们的活动。我的人民注意到了某些奇怪的事情——黑暗的弥漫——从这个地区来的。我是来调查的，而我的发现很令人不安。$B$B似乎有一个很善于奥术的亡灵外交官。我不相信他也是被遗忘者……我认为事态更坏了。"
D.Strings[111643]="我想接受更多的德鲁伊训练，更好地理解大地之母的意愿。"
D.Strings[111644]="作为一个法师，你是极少数可以操纵传送门魔法来帮助你回到这里的$r之一。如果你准备好了，我现在就可以教你。"
D.Strings[111645]="作为一名法师，你是少数可以召唤传送门返回这个地方的$r。如果你已经准备就绪，我就可以教你这种法术。"
D.Strings[111646]="出现吧，我的奴仆！保卫你们的主人！"
D.Strings[111647]="我想你不愿意向我学习吧。你最好找个$c训练师帮助你。"
D.Strings[111648]="你看起来像是那种手脚不干净的人。有什么我可以帮忙的吗？"
D.Strings[111649]="我们的军队已经升级到老兵，但是我没有足够的军需升级到勇士。"
D.Strings[111650]="我有足够的军需将我们的军队升级到经验丰富的军队。"
D.Strings[111651]="那就是你的最好表现吗？"
D.Strings[111652]="为了酋长而战！"
D.Strings[111653]="为了国王而战！"
D.Strings[111654]="有什么事吗，$c？"
D.Strings[111655]="我们的军队已经升级到精练部队，但是我没有足够的军需升级到勇士。"
D.Strings[111656]="我有足够的军需将我们的军队升级到有经验的军队。"
D.Strings[111657]="西侧霜狼哨塔保护着霜狼村和霜狼要塞之间的大门。$B$B联盟控制着这片土地。"
D.Strings[111658]="西侧霜狼哨塔保护着霜狼村和霜狼要塞之间的大门。$B$B部落控制着这片土地。"
D.Strings[111659]="西侧霜狼哨塔保护着霜狼村和霜狼要塞之间的大门。$B$B联盟和部落还在争夺这片土地。"
D.Strings[111660]="西侧霜狼哨塔是霜狼村和城堡之间要塞。$B$B联盟控制着这片土地。"
D.Strings[111661]="西侧霜狼哨塔是霜狼村和城堡之间要塞。$B$B部落控制着这片土地。"
D.Strings[111662]="西侧霜狼哨塔是霜狼村和城堡之间要塞。$B$B联盟和部落还在争夺这片土地。"
D.Strings[111663]="我能帮忙吗？"
D.Strings[111664]="拉比恩，你要我做什么？"
D.Strings[111665]="难以忍受的痛苦！"
D.Strings[111666]="比赛现在开始！"
D.Strings[111667]="让战斗开始吧！"
D.Strings[111668]="你没看到我这儿正忙着呢！"
D.Strings[111669]="暗月马戏团已经来到本镇了！走过路过不要错过！"
D.Strings[111670]="一定要来看看暗月马戏团为你带来的各种千奇百怪的东西！"
D.Strings[111671]="暗月马戏团来了！不要错过啊！"
D.Strings[111672]="一定要来看看暗月马戏团带来的千奇百怪的东西！"
D.Strings[111673]="我们终于来了！暗月马戏团现在开始展出！一定要来看看艾泽拉斯大陆各种千奇百怪的东西！"
D.Strings[111674]="暗月马戏团已经来到本镇了！不要错过有史以来最华丽的表演！"
D.Strings[111675]="暗月马戏团只会逗留有限的时间。一定要在今天来看看啊！"
D.Strings[111676]="看这边！暗月马戏团开市啦！记得来看看艾泽拉斯最激动人心的集会！"
D.Strings[111677]="暗月马戏团已经来了！不要错过有史以来最华丽的表演！"
D.Strings[111678]="暗月马戏团只会停留一小段时间，别错过今天的大好机会！"
D.Strings[111679]="%s凝视着$n。"
D.Strings[111680]="回来！"
D.Strings[111681]="欢迎所有人参加艾泽拉斯最盛大的展览……暗月马戏团！快来体验精彩和刺激吧，别害羞！这儿出售各种新奇的货物，老少皆宜啦。记得跟教授谈谈关于暗月卡片的事儿。"
D.Strings[111682]="你好，朋友，欢迎来到艾泽拉斯大陆最伟大的展出！$B$B请你过来，看看我们呈现给你的东西。快来看看这些千奇百怪的东西吧！为暗月马戏团从这个神秘广阔世界收集到的东西而惊叹吧！我们不会收取你任何费用，我们会为所有的孩子带来快乐！"
D.Strings[111683]="你都卖些什么东西？"
D.Strings[111684]="整装待命！"
D.Strings[111685]="锵锵！"
D.Strings[111686]="啊……真冷……"
D.Strings[111687]="您好，$c，欢迎来到暗月马戏团。在马戏团可以做的事儿数不甚数，第一次来的客人可能会觉得有些不知所措。这就是我在这里帮忙的原因。您有什么问题吗？"
D.Strings[111688]="另外还有一些事情值得注意。我强烈推荐你去塞格那里预测一下你的财富在哪里。我知道，我知道……他是一个豺狼人。但是他是一个拥有特别力量的豺狼人，他可以预知你的财富在哪里！\n\n另外我们在不断扩展我们的马戏团。最近我们增加了一门大炮，你可以试图用它把自己发射到水晶湖！你可以和马戏团东面的玛克希玛谈谈，了解更多细节！"
D.Strings[111689]="你真好，$n——谢谢你陪我玩要糖果的恶作剧游戏！"
D.Strings[111690]="你是最棒的，$n——谢谢你陪我玩要糖果的恶作剧游戏！"
D.Strings[111691]="生命的希冀已被切断！梦游者要展开报复！"
D.Strings[111692]="让我吞噬你的灵魂吧！"
D.Strings[111693]="我能感受到你内心的阴影。邪恶的侵蚀永远不会停止！"
D.Strings[111694]="希望是灵魂染上的疾病！这片土地应该枯竭，从此死气腾腾！"
D.Strings[111695]="我在全神贯注地听你说呢。"
D.Strings[111696]="我会以牧师的方式来训练你，如果那是你到这里来的原因的话。"
D.Strings[111697]="我需要牧师训练。"
D.Strings[111698]="跟着我。"
D.Strings[111699]="联盟荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，与你想要提升声望的主城中的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找大元帅斯诺·落雪。"
D.Strings[111700]="联盟荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，跟你想要提升声望的主城的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找大元帅斯诺·落雪。"
D.Strings[111701]="焰火表演之后，他们会拿出高脚杯，我们就可以喝酒庆祝啦！"
D.Strings[111702]="很高兴见到你，$C。我想你是为安其拉之战而来的吧。我们急需帮助。$B$B联盟和部落需要同仇敌忾，共同对抗安其拉异种虫类和它们的首脑。我们在铁炉堡的军事区收集原料以制造各种战争物资，这些收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？"
D.Strings[111703]="很高兴见到你，$C。我想你是为安其拉一战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在铁炉堡的军事区，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？"
D.Strings[111704]="嗨，$C。我想你是为安其拉之战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在奥格瑞玛的精神谷，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？"
D.Strings[111705]="嗨，$C。我想你是为安其拉一战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在奥格瑞玛的精神谷，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？"
D.Strings[111706]="认命吧！"
D.Strings[111707]="艾露恩与你同在，$c。"
D.Strings[111708]="你会付出代价的……"
D.Strings[111709]="为卡利姆多而战！"
D.Strings[111710]="你们就这点能耐？"
D.Strings[111711]="为了卡利姆多而战！"
D.Strings[111712]="为酋长而战！"
D.Strings[111713]="愿你们的长者祝福你，$n，祝你明年万事顺意，心想事成。"
D.Strings[111714]="什么？你没有可以给我的纪念品？你不爱我了？"
D.Strings[111715]="我不能教你部族制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。"
D.Strings[111716]="我不能教你部落制皮，$n。你得前往塔纳利斯寻找纳瑞安的老巢。那本名叫“Soothsaying for Dummies”的书会对你有所帮助的。"
D.Strings[111717]="嗯……你想要什么，$r？你没看到我正忙着吗？"
D.Strings[111718]="真是美味！"
D.Strings[111719]="你看到了吗？那边有天灾士兵！"
D.Strings[111720]="你看到了吗？那边有天灾！"
D.Strings[111721]="你是说……"
D.Strings[111722]="你是怎么知道这些事的？"
D.Strings[111723]="%s点头表示赞同。"
D.Strings[111724]="你指的是……"
D.Strings[111725]="%s剧烈地喘息起来。"
D.Strings[111726]="休想从我面前逃掉！"
D.Strings[111727]="逃啊！有本事就逃啊！"
D.Strings[111728]="没有人能逃得掉！"
D.Strings[111729]="我要把你血脉里的血液全都冻住！"
D.Strings[111730]="任务完结！"
D.Strings[111731]="终止你的呼吸吧！"
D.Strings[111732]="谢……谢……你……"
D.Strings[111733]="别想逃过此劫！"
D.Strings[111734]="这是你的最高水平了吗？"
D.Strings[111735]="非常荣幸。"
D.Strings[111736]="谁啊？"
D.Strings[111737]="你好！你看起来很眼熟啊，我们以前见过么？$B$B如果我们曾见过的话，那你一定有那段神秘的数字！把你的神秘兑换码告诉我，我就给你一件礼物！"
D.Strings[111738]="你好，$C。"
D.Strings[111739]="%s清了清喉咙。"
D.Strings[111740]="回到寒冷的黑暗中去吧！"
D.Strings[111741]="我当然有工作要给你！我们一直在找寻$c，希望你能比那些我们送回埃索达去埋掉的德莱尼人好一点。$B$B艾克提恩大笑起来。$B$B我在开玩笑呢！你真该看看你刚才那表情。他们被送回埃索达是为了治疗些小伤，很快都会痊愈的……"
D.Strings[111742]="你好，$R。"
D.Strings[111743]="你胆敢召唤我？！"
D.Strings[111744]="我会报仇的！！"
D.Strings[111745]="需要什么东西吗？"
D.Strings[111746]="我们受到了攻击！"
D.Strings[111747]="我们对你的出席感到很荣幸，$n。"
D.Strings[111748]="发生了什么？"
D.Strings[111749]="滚开，懦夫！"
D.Strings[111750]="你无法阻止我们！"
D.Strings[111751]="回头吧，在你还有机会回头的时候……"
D.Strings[111752]="回头吧，在你还能回头的时候……"
D.Strings[111753]="圣光给了我们通往胜利和力量之路的魔法。"
D.Strings[111754]="你有什么烹饪材料吗？"
D.Strings[111755]="你有什么烹饪调料吗？"
D.Strings[111756]="嘿，赫米修斯，有什么新邮件给我吗？"
D.Strings[111757]="赫米修斯，快点过来！我有个非常紧急的邮件，必须交给联盟远征军的人类上将。"
D.Strings[111758]="嘿，赫米修斯，有我的新邮件吗？"
D.Strings[111759]="赫米修斯，快点过来！我有一封非常紧急的邮件必须交给联盟远征军的人类上将。"
D.Strings[111760]="你肯定是德莱尼人中最懒的信使了！"
D.Strings[111761]="你一定是德莱尼一族最懒惰的信使。"
D.Strings[111762]="请坐下，不要拘束。"
D.Strings[111763]="别想活捉我！"
D.Strings[111764]="%s咯咯地笑。"
D.Strings[111765]="那你随后做了什么？"
D.Strings[111766]="能和你在一起，我们感到很荣幸，$n。"
D.Strings[111767]="有埋伏！小心！"
D.Strings[111768]="蹲下！"
D.Strings[111769]="我们是不会被阻止的！"
D.Strings[111770]="你所做的努力……都是徒劳。"
D.Strings[111771]="又近了一步……"
D.Strings[111772]="珠宝加工"
D.Strings[111773]="你叫我吗？"
D.Strings[111774]="灵魂与你同在。"
D.Strings[111775]="我钓到了！"
D.Strings[111776]="哇，多棒的一场战斗啊！"
D.Strings[111777]="我怎么了？"
D.Strings[111778]="你要找哪位专业技能训练师？"
D.Strings[111779]="好吧，让我们离开这里。"
D.Strings[111780]="去铁炉堡的秘法区和那里的暗夜精灵德鲁伊谈谈吧，他们可以把你传送到月光林地去参加春节庆典。"
D.Strings[111781]="去铁炉堡的秘法区和暗夜精灵的德鲁伊谈谈。他们会把你传送到月光林地去参加春节庆典。"
D.Strings[111782]="我希望能有机会在冬幕节结束之前和冬天爷爷聊聊天。"
D.Strings[111783]="在春节期间，我们应该花时间来寻找我们的长者，思考他们的智慧。"
D.Strings[111784]="你看到烟火了吗？这是一年中购买烟火的最好时刻。"
D.Strings[111785]="永夜港的德鲁伊们正在月光林地举办一个隆重的春节庆祝活动。"
D.Strings[111786]="送我去地狱岩床！"
D.Strings[111787]="不许抢走我的蜡烛！"
D.Strings[111788]="快点工作！"
D.Strings[111789]="别高兴得太早！"
D.Strings[111790]="过来了。"
D.Strings[111791]="请坐吧，不要拘束。"
D.Strings[111792]="欢迎来到我的旅店，疲劳的旅者。有什么我可以帮你的吗？"
D.Strings[111793]="真迷人。"
D.Strings[111794]="拜托！让开！"
D.Strings[111795]="%s的感情崩溃了。"
D.Strings[111796]="你想要点什么，$r？"
