D.Strings[112358]="听我说，$n。你必须对抗巫妖王的掌控。他是个恶魔，想要让这个世界——我们的世界——毁灭。别让他利用你实现自己的阴谋。你曾经是个英雄，现在也一定能不辱使命。战斗吧！结束他的掌控！"
D.Strings[112359]="快动手，$n！结束我的痛苦！"
D.Strings[112360]="再一次问好。"
D.Strings[112361]="快来人救命！"
D.Strings[112362]="黑暗女王在注视着你。"
D.Strings[112363]="抱歉，女猎手。我们的新$c都还没准备好。他们还有许多东西要学。"
D.Strings[112364]="受苦吧！"
D.Strings[112365]="分散他的注意，别让他闲着！"
D.Strings[112366]="欢迎你，我的$g兄弟:姐妹;。如果你是来接受训练的，我将非常愿意将本领传授与你。$B$B在玛法里奥的注视下，我们现在和将来都会是平衡的保持者。永远牢记这一点。"
D.Strings[112367]="我们的主人玛法里奥已从梦境中返回，$c。他是指引我们前进方向的灯塔之光，我们必须竭尽全力保护这道光芒。"
D.Strings[112368]="愿先祖护佑着你，$n，让你在新的一年中与好运相伴。"
