D.Strings[112408]="首先，你要给我一个游戏代币。然后我就给你一个大锤。然后你就会看见有豺狼人从游戏场地上的桶里冒出来。$B$B你就要用锤子去打这些豺狼人，来获取积分。$b$B但比较复杂的是，这里一共有三种目标：普通豺狼人，霍格豺狼人和娃娃。$b$b普通豺狼人计一分，霍格豺狼人计三分。而娃娃呢？击打他们会导致你被击倒并昏迷……所以千万别打那些娃娃！$b$b如果你没能在规定时间内砸到足够的豺狼人，可以再花一个代币再试一次！你累积的分数也可以带入下一轮。"
