D.Strings[112553]="从古代王国的黑暗时期开始，我们熊猫人就开始依靠神秘的酿造工艺保持充沛的精力和体力。$B$B甚至在我们谈话的时候，我们的酒仙仍然在周游世界，寻找罕见和充满力量的成分来酿造最好的酒。$B$B找到这些行踪不定的酒仙并且帮助他们的人，可以得到香甜可口的美酒。至少，你能喝个够！"
D.Strings[112554]="从古王国的黑暗统治时期开始，我们熊猫人就开始钻研酿酒这门神秘艺术，来振作精神，强身健体。$B$B就在我们说话间，酒仙们还在世界各地奔走，寻觅稀有强劲的原料，以制出绝品佳酿。$B$B那些有幸找到这些隐秘大师，并向他们提供帮助的人，也许能获得风味十足的物品。至少能饱饮美酒！"
