D.Strings[113150]="四个至尊天神统治着这片土地。$B$B青龙玉珑，东方的生命赋予者。$B$B朱雀赤精，南方的希望。$B$B白虎雪怒，他的力量维护着北方的和平。$B$B玄牛砮皂，他屹立在西方的天际。$B$B最近，随着煞魔的蠢蠢欲动，杂念已经开始席卷各个寺院。他们需要我们的帮助，$r。"
