D.Strings[113366]="消遣时间！"
D.Strings[113367]="在我们踏上征途时，维迪卡尔甚至没有经过测试。但她还是把我们安全送回家了。\n\n我们对这艘船做的升级都是值得的，对吧？\n\n别回答，那只会让我心痛。\n\n飞船工程师的贡献总是被人忽视。"
D.Strings[113368]="我找到他们了！我终于找到他们了。\n\n<阿拉托尔的笑容中透露出一丝不确定。>\n\n给予我生命的那两个人……他们消失得太久了。我知道我们是为了我的安全而战，而且他们为此牺牲了许多。可是……\n\n我们不可能一下就变成幸福快乐的一家人。他们几乎对我一无所知，而我也只知道一些关于他们的传说。我们还需要好好彼此了解一下，还有很多创伤需要治愈。\n\n可我们至少能一起去完成这些事。"
D.Strings[113369]="奥蕾莉亚变了。我无法彻底理解她所掌握的力量。但她的心没有变，她还是我深爱的姐姐。我知道的。\n\n希尔瓦娜斯的消息让她的心情沉重。有些事……必须由她们面对面地解决。\n\n风行者家族的姐妹必须见一面，而见面的地点只有一个。"
D.Strings[113370]="反抗燃烧军团的战争旷日持久，让人精疲力尽。我们穿过一个个世界，跨越了扭曲虚空，才取得最终的胜利。\n\n我已经累了，$n。但我们还不能休息。\n\n麦格尼的末日预言让我深受震动。现在只剩下一个泰坦了，勇士，我们必须保护它。"
D.Strings[113371]="我曾在无数个夜里梦回阿古斯。一次又一次，我梦到故乡的模样，梦到我拯救了它。\n\n<维伦沉默了许久。>\n\n它已经没救了。但我们确实胜利了。\n\n我也不知道接下来会怎么样。但我不会等待预言的指引。我要尽我所能支持安度因国王，帮他做好准备，面对潜伏在黑暗中的威胁。"
D.Strings[113372]="我的心将随着阿拉托尔和图拉扬飞回艾泽拉斯，再看一眼故乡的森林。\n\n可是……\n\n温蕾萨告诉了我希尔瓦娜斯的遭遇。虽然心怀恐惧，可我必须亲眼看看她如今的模样。\n\n她还是我的妹妹吗？还是变成了一个被圣光抛弃的怪物？\n\n当然，我也变了。我拥有的力量可能招致一些人对我的忠诚的质疑。\n\n<奥蕾莉亚深吸了一口气。>\n\n我必须保持冷静和专注。我还有很多事情要考虑……"
D.Strings[113373]="漫长的战争终于结束了。\n\n我内心深处从未指望过能活着看到这一天。毕竟我经历了太多的战斗，太多的牺牲。\n\n<图拉扬叹了口气，激烈的情绪在他的眼中汹涌翻滚。>\n\n现在，我们该返回家园了。我已经有一千年没有踏上那个世界的土地了。\n\n昔日的生活早已离我远去。是时候创造新的生活，见见我们的儿子了。他代表了我为之奋斗的一切。"
D.Strings[113374]="来吧，勇士们！为拯救世界而战！"
D.Strings[113375]="还有希望，众神之父。这些凡人体内仍闪耀着生命之火。"
D.Strings[113376]="不！我们受了这么多苦……不能就这么结束！"
D.Strings[113377]="等他们听完之后，请把这块水晶留在海加尔山之巅，永恒之井的岸边。"
D.Strings[113378]="这块水晶里有两条口信。一条给我哥哥玛法里奥，另一条给泰兰德。请你帮我把水晶带给他们，勇士。"
D.Strings[113379]="无论如何，我都会直面自己的命运。但是……我还有些事要做……有些伤口需要愈合。"
D.Strings[113380]="通向阿古斯的道路开启时……当我第一眼看到军团的老巢……我就知道自己将一去不回。"
