D.Strings[113598]="我们终于得到了艾露恩之泪。愿它在我们对抗军团时带来胜利！"
D.Strings[113599]="今天，我们将欢庆胜利，但这是用至亲的鲜血换来的。"
D.Strings[113600]="准备好就告诉我一声。"
