D.Strings[113609]="让我们离开这里！"
D.Strings[113610]="那些双头怪在搭建篝火堆，准备烧烤我的族人！你得阻止他们！"
D.Strings[113611]="那些双头怪正在搭建一个巨大的篝火堆，准备用它来烧烤我的族人！你一定要阻止他们！"
D.Strings[113612]="这家伙是我的！"
D.Strings[113613]="感谢你。"
D.Strings[113614]="请……救救我……"
D.Strings[113615]="好的，我准备好了。我们快行动吧。我担心我们会被敌人发现。"
D.Strings[113616]="是的，我准备好了。我们快走吧。我担心敌人会发现我们。"
D.Strings[113617]="还有你。"
D.Strings[113618]="你以为你嬴了？"
D.Strings[113619]="你们的灵魂将会燃烧！"
D.Strings[113620]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\LFGFRAME\\LFGICON-SUNWELL.BLP:50:80|t$b化为灰烬吧！"
D.Strings[113621]="大家都没事吧？"
D.Strings[113622]="湮没！"
D.Strings[113623]="闪电战术！"
D.Strings[113624]="鲜血就是我们的力量！"
D.Strings[113625]="守夜人们，快！王子殿下需要我们！"
D.Strings[113626]="快，守夜人们！王子殿下需要我们！"
D.Strings[113627]="开始仪式吧。"
D.Strings[113628]="意志必将实现。"
D.Strings[113629]="真希望……能逃走……"
D.Strings[113630]="它何时才能结束？"
D.Strings[113631]="啊，迟到的英雄。我们的女主人现在应该已经放出了大审判官。"
D.Strings[113632]="啊，迟到的英雄。女主人现在应该已经放出了大审判官。"
D.Strings[113633]="快解决这个入侵者。拉扎鲁恩需要一点时间来将大审判官送去阿古斯！"
D.Strings[113634]="快解决入侵者。拉扎鲁恩需要一点时间将大审判官送去阿古斯！"
D.Strings[113635]="这太费时间了！我们还有更重要的事情要做，不能再跟这家伙玩了。"
D.Strings[113636]="这太费时间了！我们有更重要的事要做，别再跟它玩下去了。"
D.Strings[113637]="我们没必要跟这些哨兵死战。只要压制住它，等大审判官自由就行了！"
D.Strings[113638]="没必要跟这些哨兵死战。只要拖住它，等大审判官自由就行了！"
D.Strings[113639]="我们必须尽快毁掉这个哨兵。军团需要大审判官！"
D.Strings[113640]="我们得尽快毁掉这个哨兵。军团需要大审判官！"
D.Strings[113641]="他们的意志必将实现。"
D.Strings[113642]="心痛吧，你们的世界已经落入了萨格拉斯的掌心！"
D.Strings[113643]="你们世界将土崩瓦解，凡人。我们不可阻挡！"
D.Strings[113644]="还有很多事情要做。"
D.Strings[113645]="发……发生什么事了？"
D.Strings[113646]="明白。"
D.Strings[113647]="向我证明一下，你的经验和本能足以打倒任何猎物吧！"
D.Strings[113648]="向我证明一下，以你的经验和本能足以打倒任何猎物吧！"
D.Strings[113649]="我们从这边上！"
D.Strings[113650]="拿好了！"
D.Strings[113651]="你和你最信赖的宠物，就是战场上的主宰。召唤宠物可以将宠物召唤到你身边。"
D.Strings[113652]="你和你最信赖的宠物，是战场上的主宰。召唤宠物可以将宠物召唤到你身边。"
D.Strings[113653]="疯狂的彼岸在召唤我……"
D.Strings[113654]="尖叫吧！求救吧！"
D.Strings[113655]="我在想，那些暗夜精灵会为你哭泣吗？"
D.Strings[113656]="死亡也不能……阻止我们……"
D.Strings[113657]="疯狂的彼岸在召唤着我……"
D.Strings[113658]="这对我来说不过是杯水车薪……但我还是要谢谢你。"
D.Strings[113659]="没有暗夜井前我们怎么过的？"
D.Strings[113660]="作为一名平衡德鲁伊，太阳、月亮和星辰就是你的盟友。你可以将这些原始之力倾泻到你的敌人头上。"
D.Strings[113661]="作为平衡德鲁伊，太阳、月亮和星辰就是你的盟友。你可以将这些原始之力倾泻到敌人头上。"
D.Strings[113662]="下次再来。"
D.Strings[113663]="这是个远程技能，能造成伤害并产生星界能量。它可以用来施放更多强大的攻击技能。"
D.Strings[113664]="纠缠根须会使植物的根须从地下蹿出，将目标困在原地一小段时间。"
D.Strings[113665]="对目标假人用阳炎之怒，直到获得足够的星界能量来施放星涌术。"
D.Strings[113666]="用你的狂野和敏捷战斗给我看吧！"
D.Strings[113667]="野性德鲁伊的主要武器就是变形。在猎豹形态下，你的利爪和獠牙能撕裂对手，让他血流如注。"
D.Strings[113668]="撕碎本身就很强大，而对流血的目标会造成额外伤害，所以保持斜掠的效果。"
D.Strings[113669]="消灭一个敌人，激活乘胜追击并对下一个对手使用。"
D.Strings[113670]="让我看看你勇猛无畏的英姿吧！"
D.Strings[113671]="在激战中，你有时也需要迅速躲避危险……或者正面迎击它！"
D.Strings[113672]="你的第一个攻击技能叫痛楚，贴切的名字。"
D.Strings[113673]="生命分流能将你的生命力转化为法力值。别担心，你随时都能吸取对手的生命来治疗自己。"
D.Strings[113674]="施放闪电法术将是你克敌制胜的主要武器。"
D.Strings[113675]="在没有其他技能可用时，你可以使用闪电箭。"
D.Strings[113676]="潜行让多数敌人看不见你。依靠潜行，你能在敌人毫无防备的情况下悄悄接近。"
D.Strings[113677]="别忘了常使用锁喉，让你的敌人持续流血。"
D.Strings[113678]="在潜行中发起战斗会更有效率。"
D.Strings[113679]="真言术：盾帮你挡住了法师的第一次攻击，但第二次攻击还是打伤了你。"
D.Strings[113680]="在敌人靠近时，你可以用强大的中距离攻击，公正之剑。"
D.Strings[113681]="你可以用圣殿骑士的裁决来释放这种神圣力量，这个强大的近战攻击能为你的武器灌注圣光之力。"
D.Strings[113682]="圣盾术帮你挡住了法师的第一次攻击，但第二次攻击还是打伤了你。"
D.Strings[113683]="你的攻击会累积符文能量。符文能量可以用来施放凋零缠绕。这个法术能用邪恶能量冲击目标，并为你的食尸鬼恢复能量。"
D.Strings[113684]="它的黑暗力量能伤害敌人，并为你恢复些生命值。"
D.Strings[113685]="你的爪牙已死。施放亡者复生召唤一个新爪牙吧。"
D.Strings[113686]="能够召唤死亡的力量，意味着你不用担心敌人倚多为胜。"
D.Strings[113687]="亡者大军可以复活一群食尸鬼来攻击你周围的一切敌人。"
D.Strings[113688]="这个强大的技能无法频繁使用，把它留着应付紧急情况。"
