D.Strings[113726]="看看他们……他们甚至都不能算是人了。我绝不能变成他们那样。我们必须尽快找到阿斯托里尔。快点肃清道路！"
D.Strings[113727]="看呐……他们甚至都不能算是人了。我绝不能变成他们那样。我们必须尽快找到阿斯托里尔。快点肃清道路！"
D.Strings[113728]="我们是团结一致的高岭部族！"
D.Strings[113729]="你说得对！"
D.Strings[113730]="我这辈子所看过的……"
D.Strings[113731]="我这两辈子里所看过的……"
D.Strings[113732]="呸。在没有暗夜井之前，我们到底是怎么活下来的？"
D.Strings[113733]="这对于我的饥渴来说不过是杯水车薪……但无论如何还是要谢谢你。"
D.Strings[113734]="我们没能阻止他们……"
D.Strings[113735]="我们阻止不了他们……"
D.Strings[113736]="死了……都死了……他们突然从天而降……我们无处可逃……"
D.Strings[113737]="他们突然从天而降……我们无处可逃……"
D.Strings[113738]="那些暗夜精灵会为你哭泣吗？"
D.Strings[113739]="万灵都服从着我的意志！"
D.Strings[113740]="万灵，服从我的意志！"
D.Strings[113741]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\LFGFRAME\\LFGICON-SUNWELL.BLP:50:80|t$b末日降临了！"
D.Strings[113742]="主人能不断修复我的身躯。你还没赢呢。你赢不了的。我们是无穷无尽的！我们是燃烧军团！"
D.Strings[113743]="没想到我会把在玛凯雷的时间都花在这种事情上。"
D.Strings[113744]="没想到我在玛凯雷净干这些事了。"
D.Strings[113745]="开怪了！"
D.Strings[113746]="入侵者！你来自哪里？"
D.Strings[113747]="你是从哪儿来的？有入侵者！"
D.Strings[113748]="这个攻击技能要消耗更多资源但伤害也更高。幸好你的近战攻击有一定几率触发风暴使者，能降低消耗。"
D.Strings[113749]="这个攻击技能要消耗更多的资源，但伤害也更高。幸好你的近战攻击有一定几率触发风暴使者，能降低它的消耗。"
D.Strings[113750]="对敌人造成伤害可累积怒气，它能强化你的攻击。用猛击消耗怒气，对敌人造成伤害。"
D.Strings[113751]="作为圣光的信徒，你拥有许多防护和治疗手段。"
D.Strings[113752]="对目标假人使用寒冰箭，直到触发寒冰指效果。然后在效果期间使用冰枪术。"
D.Strings[113753]="你抵抗……不了的……"
D.Strings[113754]="这是我从一个巡逻的斥候身上弄来的。他管这个叫“自拍神器”。你知道这是什么吗？"
D.Strings[113755]="这是我从一个斥候身上弄来的。他管这个叫“自拍神器”。你知道这是什么吗？"
D.Strings[113756]="你确定你不是夜“之烦”吗？"
D.Strings[113757]="你确定你不是夜“之祸”吗？"
D.Strings[113758]="打得漂亮，英雄。"
D.Strings[113759]="圣光已经抛弃了你！"
D.Strings[113760]="作为圣光的信徒，你拥有许多防护以及治疗手段。"
D.Strings[113761]="造成伤害可累积怒气，能强化你的攻击。用猛击消耗怒气，对敌人造成伤害吧。"
D.Strings[113762]="梅鲁娜跪了下来，将一只银盆放在地上，然后到了少许晶莹透彻的井水进去。"
D.Strings[113763]="打得漂亮！"
D.Strings[113764]="这里发生了什么？"
D.Strings[113765]="那群邪教徒还会回来的，否则他也可能会在遥远的未来再次苏醒。我们必须吞噬他的力量。这样，他就彻底完蛋了。你知道这是必要的做法。"
D.Strings[113766]="对，我们已经等不及要享用那个堕落泰坦的爪牙了。但要先对付扎卡兹。"
D.Strings[113767]="而你就不同了，我们可以一起干出一番大事业。拿起我吧，我会帮助你的……但只是暂时的。"
D.Strings[113768]="软弱的可怜虫。暮光教父不用我，是因为他明白失败的代价。"
D.Strings[113769]="谢谢你，旅行者。"
D.Strings[113770]="滚出去，闯入者！"
D.Strings[113771]="和月光林地一样，这个村子和它的村民都是受我保护的。我只希望我能庇护更多的荒野以及荒野的守护者们。$B$B真希望我能足够强大到保护你们所有人。"
D.Strings[113772]="为你的懦弱付出代价！"
D.Strings[113773]="跟我走！"
D.Strings[113774]="我准备好了。我们走！"
D.Strings[113775]="使用野性狼魂召唤这些灵魂。"
D.Strings[113776]="现在，使用野性狼魂召唤这些灵魂。"
D.Strings[113777]="你这是螳臂当车。即使在你的梦里也一样。"
D.Strings[113778]="撕碎和斜掠都可以生成连击点数，从而强化强大的终结技。"
D.Strings[113779]="凶猛撕咬就是这样一个终结技，你的连击点数越多，伤害就越高。"
D.Strings[113780]="在你拥有5个连击点数时使用它吧。"
D.Strings[113781]="但你无法击败够不着的敌人。幸好，你有一个技能可以解决这个问题。"
