D.Strings[113784]="虽然无法长时间控制地狱火和末日守卫这样的大型恶魔，但你可以召唤它们为你战斗一小段时间。"
D.Strings[113785]="石化能用大地的力量强化你的武器，从而造成伤害。"
D.Strings[113786]="为什么不继续用火呢？对被点燃的敌人投掷熔岩吧。"
D.Strings[113787]="当你使用闪电链时，它会弹射到目标附近的其他敌人身上，对他们造成伤害。"
