D.Strings[113799]="这个远程法术能伤害和降低敌人的移动速度，并有几率强化其他攻击技能。"
D.Strings[113800]="今天，我们在此济济一堂，向我们高贵、优秀而且顽强的领袖表达崇高的敬意。"
D.Strings[113801]="今天我们在此济济一堂，向我们高贵、优秀而且顽强的领袖表达敬意。"
D.Strings[113802]="伊利达雷，听着。是时候了。我们付出的所有努力……所有牺牲都是为了现在这一刻。"
D.Strings[113803]="伊利达雷，听着。是时候了。我们所有的努力……所有的牺牲都是为了这一刻。"
D.Strings[113804]="作为增强萨满，你能将元素之力直接注入武器，将自己变成凶猛的近战大师，使用烈焰、大地和风暴的力量打倒敌人。"
D.Strings[113805]="撕碎和斜掠技能都可以生成连击点数，从而强化强大的终结技。"
D.Strings[113806]="你的宠物受伤了！快使用治疗宠物！"
D.Strings[113807]="练习使用英勇跳跃。"
D.Strings[113808]="用冲锋技能拉近你和目标假人之间的距离。"
D.Strings[113809]="你无法长时间控制地狱火和末日守卫这样的大型恶魔，但你可以召唤它们为你战斗一小段时间。"
D.Strings[113810]="为什么要停止使用火焰法术呢？对被点燃的敌人投掷熔岩吧。"
D.Strings[113811]="成交。"
D.Strings[113812]="我们发现了个入侵者！"
D.Strings[113813]="熔锤大人！我们发现了一个入侵者！"
D.Strings[113814]="%s赞同地点点头。"
D.Strings[113815]="黑暗……在召唤……"
D.Strings[113816]="主人会不断治疗我的。你还没赢呢。你赢不了的。我们无穷无尽！我们是燃烧军团！"
D.Strings[113817]="部落要为背叛付出代价！"
D.Strings[113818]="希尔瓦娜斯必须受到制裁！"
D.Strings[113819]="你这是螳臂当车。即使在梦里也一样。"
D.Strings[113820]="希尔瓦娜斯休想逃脱正义的制裁！"
D.Strings[113821]="部落要为他们的背叛付出代价！"
D.Strings[113822]="你面对的不仅仅是我玛克扎尔自己，还有我所号令的军团！"
D.Strings[113823]="来啊！来打我呀！"
D.Strings[113824]="你们无路可逃了！"
D.Strings[113825]="跑吧……还来得及。"
D.Strings[113826]="尝尝真正的痛苦！"
D.Strings[113827]="我代表着一千个沦陷世界的怒火。"
D.Strings[113828]="我代表一千个沦陷世界的怒火。"
D.Strings[113829]="太好了！"
D.Strings[113830]="闭嘴吧！"
D.Strings[113831]="我们的敌人注定失败！"
D.Strings[113832]="离我远点！"
D.Strings[113833]="我欠你的人情。"
D.Strings[113834]="别着急……"
D.Strings[113835]="到这里来，$n！"
D.Strings[113836]="对，对！"
D.Strings[113837]="阿苏纳"
D.Strings[113838]="现在不行！"
D.Strings[113839]="我已经准备好了！"
D.Strings[113840]="提高警惕，朋友。"
D.Strings[113841]="我会不惜一切阻止燃烧军团占领恐痕裂隙。"
D.Strings[113842]="出去小心点！"
D.Strings[113843]="别把它弄坏了！"
D.Strings[113844]="看好那东西！"
D.Strings[113845]="你的对手会试图靠人数来打败你，但他们低估了你真正的力量！"
D.Strings[113846]="我要把你的脑袋献给古尔丹。"
D.Strings[113847]="你的灵魂将沦为永恒的奴隶！"
D.Strings[113848]="这是什么？有人躲在这里？"
D.Strings[113849]="你的灵魂将永远臣服于我们！"
D.Strings[113850]="我要亲手把你的脑袋献给古尔丹。"
D.Strings[113851]="这是我们的时代。"
D.Strings[113852]="我们必须坚持。"
D.Strings[113853]="这是我们的时代了。"
D.Strings[113854]="我们的命运即将实现。"
D.Strings[113855]="命运就在我们手中。"
D.Strings[113856]="同德……"
D.Strings[113857]="我会让我的人去跟你的人谈谈。可以吧？"
D.Strings[113858]="我会让我的人去跟你的人谈谈。听起来不错吧？"
D.Strings[113859]="如何？"
D.Strings[113860]="在军团的力量面前颤抖吧！"
D.Strings[113861]="看看这是什么？有人躲在这里？"
D.Strings[113862]="妈妈说，我太小了，不能喝魔力酒。"
D.Strings[113863]="把它完整地带回来！"
D.Strings[113864]="照顾好它！"
D.Strings[113865]="就这样吧。"
D.Strings[113866]="这可真有趣。"
D.Strings[113867]="我们联手，就能变得更加强大。"
D.Strings[113868]="你的对手可能会试图靠人数来打败你，但他们低估了你真正的力量！"
D.Strings[113869]="我……输了……"
D.Strings[113870]="他竟然敢派人代他来？那个该死的卑鄙小人。"
D.Strings[113871]="他竟敢派人代他来？该死的卑鄙小人。"
D.Strings[113872]="干得漂亮！"
D.Strings[113873]="长官。"
D.Strings[113874]="没见过这样的……"
D.Strings[113875]="真漂亮。"
D.Strings[113876]="只要不让恐痕裂隙落入燃烧军团之手，我什么都愿意做。"
D.Strings[113877]="那些熊真暴躁！谢谢！"
D.Strings[113878]="那些熊真是太暴躁了！谢谢！"
D.Strings[113879]="我不会让军团再猖狂下去的。"
D.Strings[113880]="我不会让燃烧军团猖狂下去的。"
D.Strings[113881]="%s晕倒在了地上。"
D.Strings[113882]="我不明白。这不是城里。哪里——"
D.Strings[113883]="我不明白。这不是城里。这是——"
D.Strings[113884]="瑟维斯，我要你为最后一座传送门供能。"
D.Strings[113885]="瑟维斯，我要为你最后一座传送门供能。"
D.Strings[113886]="我们是团结的高岭部族！"
D.Strings[113887]="保护好你自己！"
D.Strings[113888]="为了陛下！"
D.Strings[113889]="我以为自己死定了……"
D.Strings[113890]="我以为自己已经死定了……"
D.Strings[113891]="我要谢谢你，旅行者。"
D.Strings[113892]="休息时间！"
D.Strings[113893]="你们的世界将被净化！"
D.Strings[113894]="想造几艘船玩玩吗？"
D.Strings[113895]="我要踩碎你的骨头，$r！"
D.Strings[113896]="想造几艘舰船吗？"
D.Strings[113897]="|TINTERFACE\\ICONS\\INV_MISC_HEAD_VRYKUL.BLP:40|t但它是你成功的第一步。到阿格拉玛的宝库附近来找我，我要考验一下你的力量。"
D.Strings[113898]="痛苦吧！"
D.Strings[113899]="让我看看你有些什么。"
D.Strings[113900]="好黑……我还以为……"
D.Strings[113901]="能逃走……就好了……"
D.Strings[113902]="这里还残留着瑟雷凯斯的虚空魔法。"
D.Strings[113903]="这里还留有瑟雷凯斯的虚空魔法。"
D.Strings[113904]="我还以为我要抓住它了。"
D.Strings[113905]="我还以为能抓住它了。"
D.Strings[113906]="死亡！"
D.Strings[113907]="是谁？！"
D.Strings[113908]="<用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力给一把三叉戟灌魔。>"
D.Strings[113909]="炸药！更多的炸药！我要更多的炸药！"
D.Strings[113910]="我们很乐意接受你的帮助，德拉丝。凝聚起来的圣光才最为耀眼。"
D.Strings[113911]="作为一名邪恶死亡骑士，你掌握着疾病和死亡的力量。"
D.Strings[113912]="我们很乐意接受你的帮助，德拉丝。凝聚的圣光才最强大。"
D.Strings[113913]="如果你能将敌人冻结，不让他们靠近你，那不是更好吗？"
D.Strings[113914]="如果你在战斗中受伤过重，灵界打击能扭转不利局面。"
D.Strings[113915]="如果你能将敌人冻结在原地，不让他们靠近你，那不是更好吗？"
D.Strings[113916]="如果你在战斗中受伤过重，灵界打击能帮你扭转局势。"
D.Strings[113917]="这家伙属于我了！"
D.Strings[113918]="这不可能..."
D.Strings[113919]="到此为止了！"
D.Strings[113920]="怎么不一样？"
D.Strings[113921]="古尔丹的力量时刻都在增长。但他已经彻底暴露——我们知道他在哪儿、他在干什么。现在，我们要主动出击！愿圣光怜悯我们的灵魂。"
D.Strings[113922]="古尔丹的力量时刻都在增长。但他已经彻底暴露了——我们知道他在哪儿，他在干什么。现在，我们要主动出击！愿圣光怜悯我们的灵魂。"
D.Strings[113923]="碾压！"
D.Strings[113924]="我先！我说了我先！"
D.Strings[113925]="你不懂——我非常需要它！"
D.Strings[113926]="你知道我等了多久吗？"
D.Strings[113927]="我不会再失败了！它归我了！"
D.Strings[113928]="就直接给我吧，好吗？"
D.Strings[113929]="我是你所能想象的最像精灵的精灵，如果那个精灵是我的话。"
D.Strings[113930]="我……必须把这匹马卖给你。"
D.Strings[113931]="哇，$G先生:女士;，你确定吗？这不会是什么恶作剧吧？"
D.Strings[113932]="很不幸，是的。"
D.Strings[113933]="很高兴跟你做生意。你让我飞黄腾达了，朋友！"
D.Strings[113934]="别让我久等了，庸人。赶快，赶快！"
D.Strings[113935]="这是什么？又是这种诅咒之石？！"
D.Strings[113936]="你会付出代价的，陌生人。我会找到你……然后毁灭你。"
D.Strings[113937]="我没法一直撑下去！快！"
D.Strings[113938]="我们到那儿见！"
D.Strings[113939]="天哪，听着很不妙。快回邮政长那儿去——我马上拆除这个传送门。"
D.Strings[113940]="别理会哈拉迈德。我知道在他内心深处还是喜欢这些免费的石头的。"
D.Strings[113941]="不管是刮风下雨还是大灾变，或者恶魔入侵，我们都不能放弃自己的职责。邮件必须送达。"
D.Strings[113942]="干得好。我们绝不能让不合适的邮件阻塞系统。"
D.Strings[113943]="不需要追踪寄信人。用这些邮筒就可以搞定！"
D.Strings[113944]="亡黯教派……我以为那些邪教徒早就被剿灭了。\n\n现在正是完成这个任务的好机会。我可以把我们送到奈萨里奥的宝库。"
D.Strings[113945]="我们可能晚了！真是噩耗。我听到附近有仪式的吟唱声。"
D.Strings[113946]="艾泽里特裂隙开始喷发了！"
D.Strings[113947]="你带来什么消息了吗，英雄？我感觉一股黑暗力量笼罩了雷霆崖。"
D.Strings[113948]="有位盟友遭到了上古之神的精神攻击。他还有救吗？"
D.Strings[113949]="有时我们必须走入梦境之地，寻找真相。"
D.Strings[113950]="我很希望能告诉你一些好消息。但根据我的经验，人一旦被上古之神控制，就没有希望了。"
D.Strings[113951]="灵体都很焦躁。有片阴影笼罩了这个地方。这里的泥土感觉……很不对劲。"
D.Strings[113952]="需要非常强大的结界才能挡住上古之神。\n\n或许一个结界重重，能够抵御虚空魔法的地方会有所帮助。"
D.Strings[113953]="$n收集到了艾泽里特！"
D.Strings[113954]="我感觉你带来了坏消息。"
D.Strings[113955]="如果圣光保佑，那你或许还有希望拯救你的朋友。$b$b可不要再耽搁了。如果不能尽快压制上古之神的影响，他的心智就会彻底陷入疯狂。"
D.Strings[113956]="这是谁要的小鸡？"
D.Strings[113957]="几乎没有任何预警的，库卡隆大举进攻了森金村。幸好有沃金帮助我们。"
D.Strings[113958]="他发表了一次鼓舞人心的演讲！"
D.Strings[113959]="我们赶到的时候，剃刀岭已经失守了。"
D.Strings[113960]="我们打了他们一个措手不及！"
D.Strings[113961]="我想念大酋长。我想我们都是。"
D.Strings[113962]="欢迎来到我的旅店！"
D.Strings[113963]="今晚很忙……不过挤一挤还是有位子的！"
D.Strings[113964]="姑娘小伙们，看看这是谁！"
D.Strings[113965]="快从壁炉旁拉一把椅子吧！"
D.Strings[113966]="欢迎回来！"
D.Strings[113967]="噢呵呵，很高兴再次见到你！"
D.Strings[113968]="哈，随便找个位子吧！"
D.Strings[113969]="看来我们在阿古斯的胜利都是徒劳的。萨格拉斯的最后一击不仅仅是将利剑插入了艾泽拉斯的心脏。"
D.Strings[113970]="随着艾泽拉斯的生命精华流出，联盟和部落的领袖都想争夺这种资源。利剑已经出鞘，战火又将重燃。"
D.Strings[113971]="我本希望在与军团的战争结束后，艾泽拉斯的人民能共建新的未来。可现在，我们的同盟被打破了。"
D.Strings[113972]="可我不会将武器对准任何一方。尤其是在我们并肩战斗过之后。"
D.Strings[113973]="相反，我要去卡拉赞咨询我的导师麦迪文。他收藏的古代文献里或许有治愈这个世界的方法。"
D.Strings[113974]="我该走了。后会有期……勇士。"
D.Strings[113975]="勇士……我有话说。"
D.Strings[113976]="这座山归我们了，凡人。你们很快就将承载真正的力量！"
D.Strings[113977]="这些英雄并非孤军奋战。"
D.Strings[113978]="我们会一起驱逐你的黑暗！"
D.Strings[113979]="你将臣服于我们，巨龙，就像奈萨里奥那样！蛊惑黑龙很容易。"
D.Strings[113980]="我都不知道自己邀请了一头巨龙来雷霆崖赴宴。早知道的话，我就会准备一张大桌子！"
D.Strings[113981]="以前只有梅拉和我们的勇士知道我的秘密。现在你也知道了，酋长。"
D.Strings[113982]="我觉得别人就不用知道了，灵魂行者。我们就把它当做……朋友间的小秘密吧。"
D.Strings[113983]="部落的领袖们，我召集你们——以及我们最伟大的勇士之一——来此，是因为我们的敌人正在调兵遣将。"
D.Strings[113984]="战争即将到来。部落需要新鲜的血液。你们有什么看法？"
D.Strings[113985]="大酋长，至高岭牛头人在对抗燃烧军团时曾与我们一起英勇奋战，就像多年前我们的祖先一样。"
D.Strings[113986]="我已经邀请他们的领袖来莫高雷参加盛宴。这是拉拢他们加入的好机会。"
D.Strings[113987]="他们很单纯，但也很强大。确实是战场上一大助力。"
D.Strings[113988]="我也有一个建议，大酋长。自从我们帮助苏拉玛从燃烧军团的手中获得解放后，辛多雷就一直与他们保持着外交关系。"
D.Strings[113989]="我和摄政王都认为两个王国有许多相似之处。我们相信夜之子会成为宝贵的盟友。"
D.Strings[113990]="就算没有暗夜井，苏拉玛的魔力资源依然丰富，足以成为我的一发利箭。"
D.Strings[113991]="你们俩的建议都非常棒。相信$n对这两个种族都很了解。你希望我们先寻求哪个潜在盟友呢？"
D.Strings[113992]="血蹄酋长，让我们的勇士跟你去雷霆崖赴宴吧。等甜点上桌时，我希望他们能发誓效忠部落。"
D.Strings[113993]="没问题，大酋长。"
D.Strings[113994]="联盟正在艾泽拉斯的每一个角落寻找战胜我们的机会。我们必须以牙还牙。"
D.Strings[113995]="附近的艾泽里特裂隙开始喷发了！"
D.Strings[113996]="感谢你能来，勇士。事态非常紧急。"
D.Strings[113997]="我们都知道，联盟在与军团的战争中损失惨重。直到现在，世界还在因为萨格拉斯的最后一击而流血。"
D.Strings[113998]="与此同时，部落正在为战争厉兵秣马。我们绝不能放纵他们的入侵行为。"
D.Strings[113999]="能否招募到更多志同道合的盟友决定了我们的未来，我召集你们来此就是为了听听你们的建议。"
D.Strings[114000]="多亏艾泽拉斯的英雄们与圣光军团并肩战斗，我们才能取得阿古斯的胜利。"
D.Strings[114001]="我们有许多勇士已经为大业牺牲。而剩下的人一定会为加入联盟而自豪。"
D.Strings[114002]="我们中也有许多勇敢的新人愿意排除万难，加入光铸者的队伍。"
D.Strings[114003]="谢谢你，大主教。光铸者战士的确能让我们如虎添翼。\n"
D.Strings[114004]="至高王陛下，我还记得我们两族联手对抗部落时的情谊。"
D.Strings[114005]="我与族人会面，希望让银月城重回联盟。但是我……失败了。"
D.Strings[114006]="但我得知有些辛多雷像我一样研究虚空，并被流放。如果我找到他们，我们的事业就能获得他们的帮助。"
D.Strings[114007]="暗影低语的追随者曾经使暴风城满目疮痍。但如果有人能掌握这种力量，那的确可以成为强大的盟友。"
D.Strings[114008]="感谢你们的建议。我还想听听我们的勇士的看法，我们应该先接触哪一支潜在的盟友。"
D.Strings[114009]="风行者女士，请去搜寻你流亡的同胞。也许这位勇士能助你一臂之力。"
D.Strings[114010]="我们会尽力搜寻的，陛下。"
D.Strings[114011]="这边走，勇士。"
D.Strings[114012]="我们花了数年时间来理解虚空可能提供的力量。现在，我们就快解开这个谜团了。"
D.Strings[114013]="我们是偶然发现这个地方的。我在我的法师塔里做实验时，身边突然出现了一条裂隙。"
D.Strings[114014]="自从血精灵社会将我们流放之后，其他人就加入了研究。"
D.Strings[114015]="这个盒子是最让人疑惑不解的……等等。你靠近时能量出现了波动。这真是……前所未见。"
D.Strings[114016]="我能看到虚空能量流正在成形。或许……对，就是它！"
D.Strings[114017]="你要知道，$r朋友。提帕托斯并不是因为你弱小才选择了$n。"
D.Strings[114018]="提帕托斯在战场上见过$n。你是提帕托斯见过的最勇敢的$c。"
D.Strings[114019]="其他孩子……对提帕托斯不太友善。"
D.Strings[114020]="提帕托斯记得这个地方……"
D.Strings[114021]="提帕托斯迷路了好几天。"
D.Strings[114022]="来吧。提帕托斯知道小提帕托斯会做什么。"
D.Strings[114023]="你怎么又矮又胖呀，提帕托斯？"
D.Strings[114024]="这个胖子可能听不懂你的问题，因为他太笨了！"
D.Strings[114025]="噢，矮胖子哭了！"
D.Strings[114026]="哈哈哈！真幼稚！"
D.Strings[114027]="我们要跟过去看看吗？"
D.Strings[114028]="不要，让这个胖冬瓜去跟青蛙玩吧。"
D.Strings[114029]="提帕托斯喜欢跟动物说话。动物们喜欢他，愿意听他说话。"
D.Strings[114030]="提帕托斯害怕时，就会找个地方躲起来。"
D.Strings[114031]="提帕托斯喜欢挖洞找东西。"
D.Strings[114032]="提帕托斯记得有个地方和这里很像。当时他挖得太深了。"
D.Strings[114033]="提帕托斯跑啊跑，迷路了好几天。"
D.Strings[114034]="就连影子，都能被提帕托斯看成怪物。"
D.Strings[114035]="最后，提帕托斯决定不再怕黑，并离开了洞穴。"
D.Strings[114036]="这里让提帕托斯想起了他曾去过一个不该去的地方。"
D.Strings[114037]="有些花不仅仅是花。"
D.Strings[114038]="但会动的花也不都是坏的！它们只是想吃虫子而已。"
D.Strings[114039]="真令人印象深刻。"
D.Strings[114040]="恭喜你了。"
D.Strings[114041]="攻击我的敌人！"
D.Strings[114042]="打击我的目标！"
D.Strings[114043]="我来带路。"
D.Strings[114044]="治疗我！"
D.Strings[114045]="虚空召唤着我们。"
D.Strings[114046]="通向力量的道路非常清晰。"
D.Strings[114047]="我们不惧怕未知。"
D.Strings[114048]="快退回暗影里去！"
D.Strings[114049]="帮帮我，拜托了！"
D.Strings[114050]="危险在靠近！"
D.Strings[114051]="我的法力所剩无几了。"
D.Strings[114052]="我需要更多的法力。"
D.Strings[114053]="不要有丝毫保留！"
D.Strings[114054]="向他们开火！"
D.Strings[114055]="人们都说虚空最饥渴。我们就先小小的咬上几口吧。"
D.Strings[114056]="靠近点。我就喜欢轻声低语。"
D.Strings[114057]="你想看看我的虚空形态吗？"
D.Strings[114058]="我的内心很空虚。你愿意来填补它吗？"
D.Strings[114059]="谁还需要圣光？有些事在黑暗中可有趣多了。"
D.Strings[114060]="你抵抗不了我的魅力。"
D.Strings[114061]="饥渴的可不只有虚空。"
D.Strings[114062]="保持专注。"
D.Strings[114063]="别听那些低语。"
D.Strings[114064]="行走在暗影中。"
D.Strings[114065]="记住奥蕾莉亚的教诲。"
D.Strings[114066]="我不同意。"
D.Strings[114067]="不，我们不吸血——那是萨莱因。我们完全是两种精灵。"
D.Strings[114068]="先是高等精灵，然后是血精灵，现在才是虚空精灵。别把顺序搞错了。"
D.Strings[114069]="我头发是谁做的？你可能听说过这位发型师。它的名字叫“虚空”。"
D.Strings[114070]="阴沉？我不是阴沉的人。这只是我的穿着风格……说话方式……还有行为模式。"
D.Strings[114071]="你觉得你有黑暗的一面？得了吧。"
D.Strings[114072]="呃，对，严格来说，虚空确实想要吞噬整个宇宙。不过我现在只要小小咬一口就够了。"
D.Strings[114073]="无论你怎么求我，我也不会长出触须或者变成一个大眼球。好吧，也许我会的。但那也不是因为你的要求。"
D.Strings[114074]="待在这儿。"
