D.Strings[114173]="当然不。"
D.Strings[114174]="想得美。"
D.Strings[114175]="有危险。"
D.Strings[114176]="快来帮我！"
D.Strings[114177]="暗影围绕着我们。"
D.Strings[114178]="你是来追寻力量的吗？"
D.Strings[114179]="我在黑暗中行动。"
D.Strings[114180]="我伤得很重！"
D.Strings[114181]="奥蕾莉亚会指引我们的道路。"
D.Strings[114182]="愿暗影掩护你。"
D.Strings[114183]="不要放弃你的意志。"
D.Strings[114184]="不要偏离你的道路。"
D.Strings[114185]="攻击这个目标！"
D.Strings[114186]="攻击我的目标！"
D.Strings[114187]="集火攻击！"
D.Strings[114188]="我求你了！"
D.Strings[114189]="行行好吧！"
D.Strings[114190]="从暗影中出击吧！"
D.Strings[114191]="打倒我们的敌人！"
D.Strings[114192]="我们的对手必败！"
D.Strings[114193]="真厉害。"
D.Strings[114194]="祝贺你。"
D.Strings[114195]="走这边。"
D.Strings[114196]="我知道你是怎么想的……“噢，真棒。又是一种精灵。”呃……我敢打赌，你肯定没想到还会有虚空精灵，对吧？"
D.Strings[114197]="如果你想找修长、黑暗又忧郁的家伙，那就是我。呃，至少我黑暗又忧郁。"
D.Strings[114198]="随便你们怎么说虚空的原则。起码它是一种精神！"
D.Strings[114199]="巧的是，我最喜欢的颜色就是紫色。我是说，在我融入虚空之前，我就喜欢了。"
D.Strings[114200]="奥蕾莉亚是我最喜欢的风行者家族成员。她比温蕾萨更雷厉风行，又不像她死掉的那个妹妹一样杀气腾腾。"
D.Strings[114201]="我能驾驭虚空能量并不意味着我就想吞噬所看到的一切。毕竟我还得保持身材呢。"
D.Strings[114202]="上古之神……我是说，真的吗？有些眼睛上长着嘴，有些嘴上长着眼睛。这还真是一团糟……"
D.Strings[114203]="我们必须撤退！"
D.Strings[114204]="我喜欢什么？这么说吧，我的偏好比较……黑暗。"
D.Strings[114205]="我在暗影中的表现更好。让我来为你演示一下吧。"
D.Strings[114206]="虚空教给我很多秘密。其中有一些绝对……包你满意。"
D.Strings[114207]="我一般不长触须。可如果是你的话，我可以破一次例。"
D.Strings[114208]="在研究暗影魔法时，人就会变得很柔韧。非常……柔韧。"
D.Strings[114209]="你满足了我的饥渴……我也会满足你的。"
D.Strings[114210]="提帕托斯喜欢小动物。青蛙、雷象、虫子……但蛇最讨厌了！"
D.Strings[114211]="唔……那边……"
D.Strings[114212]="提帕托斯！"
D.Strings[114213]="我们必须战斗！"
D.Strings[114214]="尝尝提帕托斯的拳头吧！"
D.Strings[114215]="你休想阻止提帕托斯！"
D.Strings[114216]="你是假的！"
D.Strings[114217]="提帕托斯一定要坚持下去！"
D.Strings[114218]="<从普通肤色变成紫色宇宙之力肤色。听起来像某种禁咒，引发黑暗力量的吟唱/低语。并不痛苦或紧张：总计3-5>"
D.Strings[114219]="我恐怕要完了……"
D.Strings[114220]="就这样。"
