D.Strings[114287]="我还没有学会这个技能。"
D.Strings[114288]="干得不赖。"
D.Strings[114289]="我欠你一个人情。"
D.Strings[114290]="我的战友们，你们经历的试炼证明了你们的内心闪耀着圣光。"
D.Strings[114291]="现在只剩最后一个考验了——但它也是最艰难的。"
D.Strings[114292]="它会迫使你们正视自己的真面目，以及你们对自己的认识。"
D.Strings[114293]="许多出色的德莱尼经历这个试炼后变成了破碎者……甚至更糟。"
D.Strings[114294]="如果你们有一点犹豫，请立刻退回去。这不是懦弱，而是明智。"
D.Strings[114295]="如果你们确实准备好了，就上前来迎接命运吧。"
D.Strings[114296]="提帕托斯……我们已经说过了，每个新兵都要带一个副手。你的副手呢？"
D.Strings[114297]="提帕托斯不需要帮手！"
D.Strings[114298]="上一个试图单独接受试炼的新兵最后粉身碎骨了。马上选个副手，否则就回兵营去。"
D.Strings[114299]="那好吧！提帕托斯就选……这个小家伙！"
D.Strings[114300]="开始试炼吧。愿圣光保佑你们俩。"
D.Strings[114301]="虚空。它的饥渴永无止尽。"
D.Strings[114302]="智士和学者畏惧虚空。"
D.Strings[114303]="但我们知道他们不了解真相。"
D.Strings[114304]="虚空造就和改变了我们。但你要成为它的主人。"
D.Strings[114305]="我们是士兵。"
D.Strings[114306]="经过数千年的斗争，圣光终于为我们指明了正途。"
D.Strings[114307]="我们的敌人终于倒下了。燃烧军团已不复存在。但我们的战争远未结束。新的威胁正在阴影中酝酿，等待发难的时机。"
D.Strings[114308]="你是光铸者。你必须成为对抗黑暗的希望灯塔。"
D.Strings[114309]="一万年来，苏拉玛就是我们的整个世界。"
D.Strings[114310]="几百年过去，艾泽拉斯已然变了……还落入了燃烧军团之手。"
D.Strings[114311]="我们的领袖背叛了我们，与恶魔达成了交易。可我们奋起反抗暴政……赶走了恶魔，夺回了苏拉玛。我们再也不会让它陷入黑暗。"
D.Strings[114312]="为了人民的未来，你必须帮我们在艾泽拉斯争取一席之地。"
D.Strings[114313]="首席奥术师塔莉萨，还有诸位贵宾。欢迎光临银月城。"
D.Strings[114314]="很荣幸能拜访这座优雅的城市。感谢您的邀请，摄政王阁下。"
D.Strings[114315]="叫我洛瑟玛就行。啊，差点忘了。请允许我向你们介绍：奥蕾莉亚·风行者女士，她曾是银月城的英雄。"
D.Strings[114316]="这真是意外之喜，风行者女士。希尔格林跟我提起过你在阿古斯之战中的英勇表现。"
D.Strings[114317]="我也很高兴见到你，首席奥术师。我无意打扰你的访问。也许我该稍后再来。"
D.Strings[114318]="无稽之谈。你有什么话都可以当着诸位客人的面说。"
D.Strings[114319]="那好吧。我带来了至高王安度因·乌瑞恩的——"
D.Strings[114320]="我还以为你是出于对银月城的热爱而来。可你却是奉联盟那个小鬼国王之命而来。这真叫人失望。"
D.Strings[114321]="出言不逊啊，洛瑟玛，这是真心话，还是从前那个忠于职守的游侠已经成了大酋长的喉舌？"
D.Strings[114322]="你质疑我，我们又何尝不怀疑你？你敢说虚空领主没有对你低语吗？你不是已经在阿古斯投入暗影的怀抱了吗？"
D.Strings[114323]="看来你对我的来意早有预料……而且一口回绝了。不过在离开之前，我有一个请求。"
D.Strings[114324]="我已经有一千年没有见过太阳之井了。我能再去看它一眼吗？"
D.Strings[114325]="我反对。我们不能信任她——"
D.Strings[114326]="无论奥蕾莉亚如何改变，她都是奎尔萨拉斯的女儿。我不会阻拦她前往我们的圣地朝圣。首席奥术师，我们也欢迎您和您的扈从。"
D.Strings[114327]="能看一眼太阳之井也是我的荣幸，洛瑟玛。还有，我喜欢朋友们叫我塔莉萨。"
D.Strings[114328]="罗曼斯，请帮我们打开通道吧。"
D.Strings[114329]="请跟我来。"
D.Strings[114330]="至高岭屹立不倒。"
D.Strings[114331]="这些话语提到了大地与岩石，还有我们人民的历史，我们排除万难团结到一起，抵抗我们共同的敌人。"
D.Strings[114332]="我们会分裂，也会迷失。但先祖之灵说，我们由大地、河流和天空联系在一起。我们是一家人，应该为家人而战。"
D.Strings[114333]="你该离开圣山冒险了。"
D.Strings[114334]="没想到你这么快就回来了，大主教。你跟国王的会见还顺利吧？"
D.Strings[114335]="苏拉玛已经解放，首席奥术师。"
D.Strings[114336]="我们都欠你一份情。你对我们的事业帮助巨大。"
D.Strings[114337]="能与你并肩对抗燃烧军团，部落也很自豪，女士。"
D.Strings[114338]="我必须承认，第一次听说部落时，我怀疑我们是否会有共同点。"
D.Strings[114339]="我本以为卡利姆多的远亲更适合结盟。但他们既傲慢，又多疑，我很失望。"
D.Strings[114340]="看来，“艾露恩的智慧”不想让她修复与我们的关系。那就这样吧。"
D.Strings[114341]="辛多雷也被泰兰德和她高傲的盟友嘲笑。他们多年来睡在山洞，躲在树巅，而我们则在为拯救这个世界奋战。"
D.Strings[114342]="联盟过于封闭……过于与世隔绝。我的人民再也无法忍受这种静滞。"
D.Strings[114343]="所以我很感谢您邀请我前往银月城。我想借此询问，夜之子在你们的部落里能不能有一席之地。"
D.Strings[114344]="我想摄政王听到你的话肯定很高兴。你准备好出发了吗？"
D.Strings[114345]="真是荣幸，女伯爵莉亚德琳。欧库勒斯有银月城的坐标，我会叫上希尔格林和瓦尔托伊。到那儿见。"
D.Strings[114346]="踏上胡恩多年前走过的道路，为至高岭之名带来……新的荣耀。"
D.Strings[114347]="作为回报，我们也重生为它的力量载体。"
D.Strings[114348]="然而对那些威胁这个世界……或攻击我们盟友的人……你将成为圣光之怒的化身。"
D.Strings[114349]="去跟新盟友一起冒险，让世界看看，夜之子的遗产高贵……而强大。"
D.Strings[114350]="它的低语能战胜巨龙的意志……甚至引诱泰坦之子陷入疯狂。"
D.Strings[114351]="虚空之力可以被掌握……只要有强大的意志，就能号令它。"
D.Strings[114352]="将暗影化为武器，拯救我们的世界……并且保卫联盟！"
D.Strings[114353]="情況不對勁。我感覺得到。"
D.Strings[114354]="務必制止他們。"
D.Strings[114355]="歐庫雷斯已經準備好了。很好，少一件要擔心的事。"
D.Strings[114356]="一定有人通報了大博學者，她們才會知道凡席爾也參與了這場反叛行動。如此殘暴的行為…\r\n\r\n艾莉珊德…為什麼？"
D.Strings[114357]="看來你有找到倖存者。很好，這讓我放心不少。"
D.Strings[114358]="你幫我拿回血石了嗎？"
D.Strings[114359]="你很有本事，我能理解瑞特辛為什麼喜歡派你辦事。"
D.Strings[114360]="看來血石滿足了。做得好！測試的時候到了…"
D.Strings[114361]="謝謝你趕過來，$n。"
D.Strings[114362]="一道魔法訊息，居然能夠從燃燒軍團的監視下傳出…非常聰明。"
D.Strings[114363]="是個外地人…\r\n\r\n你收到了我的信息？"
D.Strings[114364]="你很善戰。\r\n\r\n我想應該是時候正式的向你自我介紹。"
D.Strings[114365]="<薩莉瑟拉眼神渙散，身體不斷顫抖。>"
D.Strings[114366]="<薩莉瑟拉用顫抖的手拿著水晶。>"
D.Strings[114367]="等到我這裡的工作完成後，請你帶我去找薩莉瑟拉。"
D.Strings[114368]="<有人居住於此的痕跡。這份捲軸上書寫著奇異的文字，發出溫暖的光芒，使你忍不住伸出手觸摸。>"
D.Strings[114369]="我們得想辦法奪回蘇拉瑪爾城。"
D.Strings[114370]="我從沒想到，我居然會在被流放的時候，跑來研究凋萎者。透過他們，我又對我的族人有了更深刻的認識，也更加瞭解我們與夜井的關係。"
D.Strings[114371]="你的消息還沒傳來這裡，琪拉就先來了。她不久前剛來到這裡，但她顯然有意避開我的目光。\r\n\r\n你居然能夠得到她的信任，這是我辦不到的。有了她的幫忙，我們應該就可以召喚傳送門了。"
D.Strings[114372]="陌生人的花言巧語，雖然動聽，但無法動搖我的決心。快過來，依現在這種速度，在我們完成之前我大概都凋萎了。"
D.Strings[114373]="<泰德里斯盯著蘇拉瑪爾，似乎陷入沉思。>"
D.Strings[114374]="<你靠近的時候，泰德里斯才從沉思中回神。>\r\n\r\n這樣夠了，$r。\r\n\r\n峭壁荊棘是一種致命的毒藥，正好符合我的需要。"
D.Strings[114375]="這正是我們保存技術的證明。我本來不抱期望，經過洗劫和歲月的摧殘還會有東西留下。\r\n\r\n先祖們肯定會很高興的。"
D.Strings[114376]="你拿到書了嗎，$r？"
D.Strings[114377]="唉。既然你在幫我做事，我想必應該要問問你的名字。\r\n\r\n<泰德里斯把手伸進書中，拉出一株陌生的乾枯植物。>\r\n\r\n謝謝你幫我取得下一種材料。我對你的協助…感念在心，$n。"
D.Strings[114378]="$r，你拿到我的戰刃了嗎？"
D.Strings[114379]="謝謝你。既然我拿回戰刃了，我要夷平魔魂堡。\r\n\r\n我的怒火無人能擋，復仇之前不會停息。"
D.Strings[114380]="你帶了什麼來？"
D.Strings[114381]="這些聖物是曾經埋骨於此的生命的象徵與遺物，他們希望被後世所銘記，而這些祭禮使他們得以長眠。\r\n\r\n死者的魂魄如今能安息了，我得感謝你。"
D.Strings[114382]="你說得也有道理，$n。但我的決心不會動搖。"
D.Strings[114383]="什麼？我聽到熟悉的聲音…但不可能。"
D.Strings[114384]="你看見菈塔娜了？怎麼回事？\r\n\r\n…我知道了。對不起讓妳失望了，吾愛。"
D.Strings[114385]="我的族人安然無恙。現在我們來解決這些毒蛇！"
D.Strings[114386]="謝謝你，$n。你使我看清我的目標，給了我繼續活下去的理由。我們並肩作戰，就能夠拯救蘇拉瑪爾，並彌補我族人所犯下的罪。"
D.Strings[114387]="很好。來看看我們會有什麼發現。"
D.Strings[114388]="凋萎者…對夜井的迫切渴望使他們生不如死，同時他們本身的記憶也在折磨他們。\r\n\r\n確實是比死亡更悲慘的命運…"
D.Strings[114389]="<一個裝著許多頁技術筆記的袋子。快速翻閱後，你找到克達納茲的最後一篇記錄。>"
D.Strings[114390]="靈魂被摧毀是比死還可怕的下場。你拯救了那些靈魂，做得很好。"
D.Strings[114391]="我會一直配戴這條項鍊，紀念索隆迪爾！"
D.Strings[114392]="索隆迪爾不應該死得這麼慘。"
D.Strings[114393]="向索隆迪爾致敬。願你的靈魂在英靈殿中尋得一席之地。"
D.Strings[114394]="我會幫忙收集我們需要的東西。"
D.Strings[114395]="<布蘭道夫把配方混合。>\r\n\r\n好吧，我可沒說過這東西會好入口。乾杯。"
D.Strings[114396]="你辦到了，$n。你成功殺死了海潮祭司並從沙許塔爾納迦手中拯救了詹德維克。"
D.Strings[114397]="我們已經驅除了腐化，新生的水元素現在可以蓬勃成長了。"
D.Strings[114398]="動作快，$c！這些海巨人的食慾是無底洞！"
D.Strings[114399]="被消化這種死法實在很不光榮。"
D.Strings[114400]="記住，這些鱗片必須完整無缺，才能作為焦點。"
D.Strings[114401]="這些非常合用。"
D.Strings[114402]="完成了。我已能感到腐敗的存在逐漸被驅淨。\r\n\r\n感謝你，$n，你幫了這地方大忙。"
D.Strings[114403]="勇士，又見面了。看來大家都到了。"
D.Strings[114404]="為了你我著想，我希望你沒被跟蹤。我們動作要快，我就快要成功了。"
D.Strings[114405]="在阿佐朗死後，燃燒軍團的元氣大傷，一時之間難以復原。\r\n\r\n你贏得我的尊敬，$n。"
D.Strings[114406]="非常好。你在這裡的工作完成了。\r\n\r\n你幫了我很大的忙，請好好休息一下。\r\n\r\n拿去，這是你的報酬。聊表我的一點心意。"
D.Strings[114407]="你找到走私者了嗎？他們怎麼說？"
D.Strings[114408]="那是法力酒嗎？要給我的？\r\n\r\n<埃亞卓斯貪婪的把整瓶酒咽下。>\r\n\r\n我向你和這位艾斯托里致謝，沒有你們，我肯定就死在這了。"
D.Strings[114409]="這真是令人不安的故事。\r\n\r\n你做了一件好事，$n。他不能再折磨我們的人民了。"
D.Strings[114410]="我的選擇不多。我無法獨自面對黑騎士的另一次埋伏，而你的力量顯然相當強大。\r\n\r\n我會幫忙找你要的那把武器，但前提是你必須協助我，把他們搶走的其他東西物歸原主。\r\n\r\n就這樣說定了吧，術士？"
D.Strings[114411]="很高興看到你傷勢痊癒，$n。許多航向破碎海岸的精兵就沒這麼幸運了。"
D.Strings[114412]="一直以來，你對部落貢獻良多，$n。\r\n\r\n你的責任會變得越來越重…越來越重。"
D.Strings[114413]="它們所受的痛苦讓我感同身受。它們終將回歸，但現在它們將暫時獲得安息。"
D.Strings[114414]="奇怪，黑騎兵竟然沒跟過來。不過沒關係，這是一件好事。\r\n\r\n我相信找到黑騎兵的關鍵就在這附近。讓我們開始搜索吧。"
D.Strings[114415]="這本日記外表看似平凡，但當你接近時，卻發現其中散發著源源不絕的黑暗能量。\r\n\r\n你快速掃過內容後，發現這是埃瑞丁的日記，上面記載著他在逆風小徑的經歷。在日記的最後，不僅字跡產生變化，語氣也變得越來越陰沉。不斷提到「詛咒」，以及將偉大力量佔為己有的無盡慾望。\r\n\r\n而在你的瀏覽過程中，有條記錄吸引你的目光。"
D.Strings[114416]="啊，你就是那個鼎鼎大名的$c。很好。\r\n\r\n我們應該看看你是不是名副其實。"
D.Strings[114417]="就是那個嗎？"
D.Strings[114418]="這個羅盤絕對有問題。\r\n\r\n它似乎打算指向所有方向。"
D.Strings[114419]="看來惡魔獵人的擔憂絕非空穴來風。那些惡魔居然敢在國喪期間悄悄潛入我們的城鎮！\r\n\r\n這對部落而言可不是什麼好兆頭。"
D.Strings[114420]="看來這招有用，羅盤指著河流的方向。\r\n\r\n這表示…？"
D.Strings[114421]="你必須找到夜眼！"
D.Strings[114422]="謝謝你，$r。我會照料夜眼的傷勢。告訴我發生了什麼事！"
D.Strings[114423]="今天，黑騎兵嘗到有史以來最大的敗績，也是暮色森林人民的一大勝利。\r\n\r\n他們欠你一份恩情，我也是。"
D.Strings[114424]="真好，朋友選得真好！"
D.Strings[114425]="你做了正確的決定。\r\n\r\n希望你的本事就和名氣一樣響亮。"
D.Strings[114426]="德林能夠安全送出貨物了，謝謝你。"
D.Strings[114427]="卡萊德斯覺得很難過，我們沒有救出你的朋友。但如果我們的動作夠快，他們可能還活著。\r\n\r\n雖然賈岡諾斯會拷問他們，但是他會留下囚犯一條小命…通常來說。"
D.Strings[114428]="你有拿到足夠的酒嗎？"
D.Strings[114429]="我會負責將這個安全送回朋友手中。做得很好。"
D.Strings[114430]="殘忍的賈岡諾斯被擊倒了！\r\n\r\n朋友，你就是懼痕裂隙的新主宰！\r\n\r\n這裡就是朋友的新家。你控制了懼痕裂隙，你想來就來想走就走！"
D.Strings[114431]="$r，你有我需要的東西嗎？時間所剩不多了。"
D.Strings[114432]="這應該夠了。鷹爪粉很快就會失去效力，我們必須速戰速決。"
D.Strings[114433]="我以為…他們要…*哽咽*"
D.Strings[114434]="很高興你平安抵達了。這裡急需你的幫忙。"
D.Strings[114435]="如果要開一個傳送網路到薩莉瑟拉那邊，就非拿到這些器材不可。"
D.Strings[114436]="這些東西的狀況不太好，但是還算堪用。"
D.Strings[114437]="我們…成功了嗎？"
D.Strings[114438]="<艾萊莉說話時眉頭深鎖。>\r\n\r\n你該不會以為部落領袖可以齊聚一地，還不被燃燒軍團注意到吧？"
D.Strings[114439]="我才在懷疑為何突然間沒了她的消息。這對我的心情或許只是小有撫慰，但對於夜裔的部隊來說卻是極大的打擊。做得很好，$n。"
D.Strings[114440]="你可以幫我嗎？難道你也無能為力？"
D.Strings[114441]="<阿布撒隆立即吞噬上古法力，看來短時間內似乎說不出話。>"
D.Strings[114442]="<諾瑞莎懷疑地打量著你。>"
D.Strings[114443]="阿布撒隆…還活著？"
D.Strings[114444]="我幾乎不敢相信我看見的景象。以單一術士之力統領整支惡魔軍團，實在超乎我對議會能力的想像。\r\n\r\n我只希望這樣的力量足以逆轉戰局。"
D.Strings[114445]="計畫定下來了，開始著手進行吧。"
D.Strings[114446]="謝謝你救回歐庫雷斯。他對於我們的計劃是無可取代的戰力。"
D.Strings[114447]="你拿到我要的新鮮魔化肉塊了嗎？"
D.Strings[114448]="我看到你帶了剛切下來的魔火石化蜥蜴肉塊回來。\r\n\r\n仔細聽好。我會解釋這些東西的用途…"
D.Strings[114449]="我的對手消失以後，我就可以不受阻攔的取得領導權。"
D.Strings[114450]="<索隆迪爾氣若游絲勉強吐出幾個字。>\r\n\r\n毒藥…流遍我…全身。"
D.Strings[114451]="你拿到了軍團紋章嗎？"
D.Strings[114452]="我看到你帶著紋章回來。太棒了。\r\n\r\n讓我們看看這隻蟲舌魔看到自己同伴的下場，會有什麼反應。"
D.Strings[114453]="你成功了嗎？"
D.Strings[114454]="做得很好。我會細讀這些信件。"
D.Strings[114455]="<這看來是設置傳送裝置的好地點。>"
D.Strings[114456]="這場攻擊…和破碎海岸上的戰爭…都只不過是燃燒軍團的初步行動。\r\n\r\n如果我們不想辦法阻止燃燒軍團，我們就會失去我的父親，還有其他領導者所打造的一切。\r\n\r\n我們需要伊利達瑞的支援。"
D.Strings[114457]="我們或許終於能戰勝納迦了。"
D.Strings[114458]="我得承認你蠻厲害的，或許你真的能幫上我們的忙。"
D.Strings[114459]="海灣裡有海巨人！？\r\n\r\n你得立刻把這可怕的消息告訴托莉爾。"
D.Strings[114460]="<沃戈斯裂片在你手中發出脈動。>"
D.Strings[114461]="<沃戈斯裂片嵌入了傳送門旁的位置。漩渦般的魔化能量圍繞在裂片四周，整個房間充滿不祥的黑暗能量。>"
D.Strings[114462]="<寇札克裂片極力掙脫，似乎想飛向某個地方。>"
D.Strings[114463]="<寇札克裂片嵌入傳送門旁的定位。你可以感覺到無數魔化能量朝著傳送門聚集過來，在你身旁不斷翻滾擾動。>"
D.Strings[114464]="如果我是你，我會先洗手，再吃東西。"
D.Strings[114465]="非常好，這些夠我用了。"
D.Strings[114466]="你拿到了嗎？"
D.Strings[114467]="喔，感謝博學者！我曾怕永遠找不到它了。\r\n\r\n我知道這枚戒指有些…用途。我的確希望它不屬於任何重要人士。或是…會說話之人。"
D.Strings[114468]="我會再次找你的，我確定。"
D.Strings[114469]="你找到鑰匙了嗎？"
D.Strings[114470]="你找到鑰匙了！快點，看看合不合…\r\n\r\n沒錯，就是這支！你找到了！"
D.Strings[114471]="終於被人從這個可怕的牢籠中放出來了，太好了。作為回報，我會遵守對你和你古怪的多毛朋友所做的的承諾。"
D.Strings[114472]="莫咕莫嘎咕莫！莫咕莫嘎咕莫咕，莫咕哇啊莫咕嘎哩莫哩！莫咕莫嘎咕莫莫咕，莫咕哩咕…"
D.Strings[114473]="萊斯賓會為他的罪行付出代價！"
D.Strings[114474]="你是否讓他們免於折磨？"
D.Strings[114475]="你正在逐漸了解我們的現實世界。我能從你的表情中看出來。很好。"
D.Strings[114476]="<結界斷然張開，帶給你些微的痛感。克達納茲一定耗費了無數心力研發這個咒語，既可嚇跑凋萎者，又不會讓他們受傷。>"
D.Strings[114477]="牠們看起來很開心能回到家裡。做得非常好。"
D.Strings[114478]="<安格斯一邊擦眼淚一邊說。>\r\n\r\n布蘭伯利，你這傢伙…我保證會給你一場最盛大的葬禮！還有喝也喝不完的麥酒…"
D.Strings[114479]="做得非常好。他們不尊重狩獵，所以必須藉此提醒他們自己的定位。"
D.Strings[114480]="我從這裡就能聽見他們的哭喊，看到屠殺的慘況！總算能教訓那些任意奴役生物的夜裔精靈。躲在護盾下這麼多年來，他們竟然墮落到這種地步！"
D.Strings[114481]="這不是真的！\r\n\r\n布蘭伯利…我親愛的老朋友！你為什麼就這樣死了？"
D.Strings[114482]="$r，你拿到陷阱了嗎？"
D.Strings[114483]="這些裝置非常獨特。它們很像是我們獵人使用的陷阱，卻可以透過魔法吸引並困住附近的野獸。"
D.Strings[114484]="我在這裡看得一清二楚。那真是…慘不忍睹。"
D.Strings[114485]="戴格利爾太年輕、太愚蠢！"
D.Strings[114486]="我們港灣裡的法力鱒魚都已經釣捕殆盡。自從護盾升起後，我們現在只能在回憶中品嘗這滋味了。"
D.Strings[114487]="任何美食，就算是我煮的，也都比不上勝利的滋味。"
D.Strings[114488]="你能想像萊斯賓的真跡埋藏在一堆樹葉中嗎？真是糟蹋。"
D.Strings[114489]="太好了。我該把這些熔掉並鑄成錠，供下一批委託用。"
D.Strings[114490]="很高興看到友善的臉孔，我不知道靠自己一個人還能撐多久！"
D.Strings[114491]="你拿到我的項鍊了嗎？戴在那些…生物的脖子上，對我一點好處也沒有。"
D.Strings[114492]="那些可鄙的生物是我們美麗土地上的詛咒。至少牠們穿戴配件的品味還不錯。\r\n\r\n又或許牠們發亮的東西都喜歡吧。"
D.Strings[114493]="弗喬里克為詹德維克而死，我們不會忘了他的英勇行為。"
D.Strings[114494]="動作快，$n。"
D.Strings[114495]="<弗喬里克虛弱地看著你。>\r\n\r\n你及時趕回來了…"
D.Strings[114496]="沙許塔爾的部隊比我預料的還難對付。"
D.Strings[114497]="我必須為你今天拯救的維酷人表達感激之情。"
D.Strings[114498]="一切就緒。我們已幾乎要安置好了。"
D.Strings[114499]="這真是有趣的轉折。"
D.Strings[114500]="梅露娜派來的協助真是及時。我幾乎要放棄希望了。"
D.Strings[114501]="我感到欣慰，但還有我們必須做的事。"
D.Strings[114502]="那個蠢貨會讓多年的辛勞毀於一旦。跌落谷底比爬到高處容易許多…"
D.Strings[114503]="啊，快看！我就說它不會失去光采。現在沒有線索能從那傻瓜身上追查到我這了…\r\n\r\n你說什麼？弱化他地位的計謀？無論如何，傷害已經造成。安全總比遺憾好。"
D.Strings[114504]="他實在太熱情、太奔放。我看到他的幻想，完全按照他的規格製作作品。美麗的鑲鈿和瓷釉共同構成令人生畏的成品…"
D.Strings[114505]="以博學者之名啊，我已經忘記那個東西有多醜了。工藝技術絕對無懈可擊，只是…呃。我應該把那個東西整個熔掉。"
D.Strings[114506]="真是令人不安的故事！"
D.Strings[114507]="歡迎回來。很好，我們隨時可以開始。"
D.Strings[114508]="這位紳士正在告訴我他事多麼深愛他的森林。讓我們幫助他吧！"
D.Strings[114509]="牠們看起來吃得更飽了！"
D.Strings[114510]="最後，牠們都會蓬勃生長，而有了更多的闇角以後，狼群也能在之後幾年吃得更好。"
D.Strings[114511]="做得好，$r。"
D.Strings[114512]="真是貪吃的傢伙。"
D.Strings[114513]="我的心情好多了，$r。"
D.Strings[114514]="你的協助讓這一切得以實現。謝謝你。"
D.Strings[114515]="納迦不能再奪走我的親族了！"
D.Strings[114516]="我不認識你，但你不是海巨人，這樣就夠了。"
D.Strings[114517]="很高興知道他們還活著。他們的情報會在接下來的行動中派上很大的用場。"
D.Strings[114518]="我只希望我有機會早一步對付他。\r\n\r\n啊！他的屍體在這片水域裡腐爛了我也不在乎。"
D.Strings[114519]="<這個凋萎者似乎被法術石催眠，徹底平靜下來。>"
D.Strings[114520]="<他的袖子上有個小掛牌，上面寫著「16‧瑟倫」。>"
D.Strings[114521]="克達納茲最後還是變成了怪物…\r\n\r\n他的命運實在不該如此。感謝你結束他的生命。"
D.Strings[114522]="海潮祭司是危險的敵人。要擊敗她，我們得變得跟她一樣狡猾。"
D.Strings[114523]="你已拿到所有你需要的零件了…有些部位甚至還雙倍有餘。"
D.Strings[114524]="瑞特辛派你來的，是吧？看來我昔日的導師還是不肯親自動手做骯髒事。\r\n\r\n但當然，像他這樣地位的人，怎麼能讓人看到與疑似阿古斯覺醒者的成員在一起呢！其他人會怎麼想？\r\n\r\n雖然我很高興瑞特辛需要我的協助，但我不是在做慈善事業，$n。\r\n\r\n想要我幫忙，就要用力量與知識來交換。如果你有其中之一，那麼我們或許就能好好安排。"
D.Strings[114525]="真迷人。\r\n\r\n真希望這法術不會消散。"
D.Strings[114526]="我們應該可以在這安全地談一會話。"
D.Strings[114527]="馨菲不能毀在梅菲斯托手裡。如果驚懼領主可以利用她的力量和知識，就能對懼痕裂隙發動毀滅性的攻擊。\r\n\r\n使用召喚儀式可以把馨菲召喚到我們身邊，但我們需要先建立一個強大的定位點…"
D.Strings[114528]="我們雖然找回馨菲了，但她的心智還掌握在俘虜她的惡魔手中。\r\n\r\n他們到底在她身上下了什麼古代魔咒？我從來沒看過這種事情。"
D.Strings[114529]="很高興與你認識。"
D.Strings[114530]="這面具很適合你。\r\n\r\n在蘇拉瑪爾，能扮演他人一段時間是件深具益處的的事…。"
D.Strings[114531]="希望你是做好了準備才進入這座城市。時候到了。"
D.Strings[114532]="我們開始吧，怎麼樣？"
D.Strings[114533]="太好了，那個老糊塗總算得到報應了。\r\n\r\n看來漫步宏園現在需要一名新的珠寶匠，而我覺得我已經學會前任師傅的所有知識了。\r\n\r\n這是體恤你的辛勞的一點小心意。"
D.Strings[114534]="我們多了一份力量，敵人少了一個助力。這場仗我們一定會贏，$n！"
D.Strings[114535]="謝謝你，現在我們就能開始我們的工作了。"
D.Strings[114536]="我的小妹將宛若重生，不管她自己喜不喜歡。"
D.Strings[114537]="搜尋文獻之後，我們發現一部典籍，裡面詳細說明如何建立惡魔傳送門。只要我們知道位置，就能透過傳送門，出入任何惡魔世界。\r\n\r\n我們可以利用這種傳送門，找到並帶回剩下的議會成員。"
D.Strings[114538]="你找到靈魂了嗎？"
D.Strings[114539]="你從不讓人失望，$n。\r\n\r\n這個早已遭到遺忘的靈魂，現在可以更有貢獻。"
D.Strings[114540]="有了足夠的靈魂裂片，我們就應該有能力建立定位器了。"
D.Strings[114541]="你的部隊做得很好。我們擁有的靈魂裂片已經足以強化定位器。"
D.Strings[114542]="朋友拿到顱骨了嗎？\r\n\r\n啊，卡萊德斯感受到了！別讓它盯著卡萊德斯，朋友。我很樂意協助你，完全沒有不甘願。"
D.Strings[114543]="你拿到所有東西了嗎，朋友？"
D.Strings[114544]="非常好！現在，我們可以開始了。"
D.Strings[114545]="你有與支持我們的人聯絡上了嗎？"
D.Strings[114546]="路納斯特家族交遊廣闊，當時機來臨時，他們會是一大助益。"
D.Strings[114547]="沒錯，魔魂堡！卡萊德斯知道在哪裡！\r\n\r\n卡萊德斯可以建立一條路徑，連到那裡的傳送門！"
D.Strings[114548]="你來得正好，$r。"
D.Strings[114549]="<你從薩莉瑟拉的夢境中認出聖物。>"
D.Strings[114550]="<隨著魔法屏障逐漸消失，你聽見外頭傳來樹葉沙沙的聲響，以及昆蟲喀喀的聲音。>"
D.Strings[114551]="你知道你做了什麼嗎？"
D.Strings[114552]="<遠古種子散發能量脈動。>"
D.Strings[114553]="像這樣暫時的家就非常理想。"
D.Strings[114554]="<種子穩穩地落在高台上，卡嗒一聲沉了下去。>"
D.Strings[114555]="<菲恩抓住你的肩膀，高興地跳來跳去。>\r\n\r\n莫嚕咕！咕嚕莫嘎咕。"
D.Strings[114556]="喔，我親愛的小可琳！感謝你，感謝你！"
D.Strings[114557]="凡席爾是個非常風趣的人。"
D.Strings[114558]="我們非常幸運，居然可以取回它…謝謝你。"
D.Strings[114559]="你找到什麼？"
D.Strings[114560]="這真是讓我放了一百二十個心。"
D.Strings[114561]="謝謝你。我終於了結一件事了。"
D.Strings[114562]="太棒了！我會立刻研讀地圖。"
D.Strings[114563]="莫咕莫咕！啊咕莫咕。咕莫莫咕啊莫咕啊咕莫咕莫咕啊！莫咕啊莫咕啊咕。"
D.Strings[114564]="你讓他們離開了？我好高興。我也不喜歡被關在籠裡…"
D.Strings[114565]="莫莫咕莫…莫哩咕莫咕。莫哩咕哩咕咕莫哩！"
D.Strings[114566]="他們現在知道暮色百合不好惹，做得很好。"
D.Strings[114567]="嗯，沒錯。跟我猜的一樣。"
D.Strings[114568]="那麼就讓我帶你參觀一番。"
D.Strings[114569]="你或許會想先清滌一下味覺，我們釀的酒味道可都很濃郁！"
D.Strings[114570]="歡迎，遊覽還愉快嗎？"
D.Strings[114571]="很簡單，是不是？"
D.Strings[114572]="我一定會在你離開前為你準備一瓶秘能酒。"
D.Strings[114573]="好多了。十分感謝你。"
D.Strings[114574]="我會幫你把這些…呃…紀念品…裝好。"
D.Strings[114575]="瑪苟…不！"
D.Strings[114576]="狠下心腸，$n。\r\n\r\n瑪苟的死令人懊悔，但她不會是最後一個受虐而死的人。恐怕還有無數人跟她一樣的遭遇。"
D.Strings[114577]="很高興你了解我所提供服務的價值，夥伴。"
D.Strings[114578]="當你突然消失時，我們還以為你遭到了不測。\r\n\r\n我不知該對你的冒險歷程作何感想…我需要時間來整理心情。\r\n\r\n不論如何，很高興你安然無恙地回來了。"
D.Strings[114579]="這有點麻煩，但卡萊德斯有辦法！"
D.Strings[114580]="古爾丹說過，有力量的人都可以加入。如果朋友加入呢？然後靠近時把權杖搶走，然後跑！\r\n\r\n沒錯！這行得通，可是要讓他們信任。古爾丹需要眼睛。朋友可以幫忙拿眼睛，就可以有信任。"
D.Strings[114581]="沒錯，沒錯！找到眼睛！幫暗影議會！現在可以參加儀式了。權杖就在那裡。\r\n\r\n這件事有點麻煩，朋友，不過卡萊德斯對你很有信心！"
D.Strings[114582]="居然成功了，卡萊德斯不敢相信！儀式失敗，暗影議會全軍覆沒，而且我們沒死！\r\n\r\n喔，還有你拿到權杖！這是我們的大勝利！"
D.Strings[114583]="啊，$n。\r\n\r\n很高興能與你重逢。相信你已經準備好助我一臂之力。"
D.Strings[114584]="我像一位姐姐一樣關愛路納斯特女士，但我恐怕舉步維艱。"
D.Strings[114585]="非常好。讓我們討論一下對策。"
D.Strings[114586]="他沒有受到傷害！我欠你和黎利斯一份大人情。"
D.Strings[114587]="城市到處流傳著非常有趣的八卦，$n。勝利就在眼前了。"
D.Strings[114588]="<薩莉瑟拉用力握緊法術石，遲遲不肯放手。>\r\n\r\n這是他自找的。\r\n\r\n我不能一直困在過去。失去他，艾莉珊德就少了一大助力，我們離為夏多雷撥亂反正的目標也更近了一步。"
D.Strings[114589]="看來你已經控制住局面。我並不想…打擾你。\r\n\r\n又少了一個追求權力的貴族需要擔心。做得很好，$n。"
D.Strings[114590]="事情的結局可能沒我希望的這般明朗。"
D.Strings[114591]="我們今天大有斬獲，我絕不會忘記。"
D.Strings[114592]="你真是越來越令人信賴了。"
D.Strings[114593]="謝謝你。此處將永遠無法回復生氣，但至少不會再有人因為林精陷入瘋狂而受傷。"
D.Strings[114594]="你拿到樹皮了嗎？"
D.Strings[114595]="我會仔細研究這些東西。要是我們夠幸運，說不定可以找到答案。"
D.Strings[114596]="我不知道你怎麼拿到這東西，不過一定很不容易。我們面前困難重重，但你卻一一克服。來吧，讓我們復活奧肯多爾。"
D.Strings[114597]="我們的樹看來十分需要水份滋潤。"
D.Strings[114598]="我們必須採取非常手段。"
D.Strings[114599]="沒有裝甲的保護，電磁脈衝將在數秒內破壞自己。"
D.Strings[114600]="如果我的拱道地圖正確無誤，那些應該就是我們需要注意的所有出口。"
D.Strings[114601]="太好了。有了這個，把你們所有人傳送到海底的機率就會大大降低！"
D.Strings[114602]="看呀，夜落精靈的救贖。"
D.Strings[114603]="我們…終於自由了。"
D.Strings[114604]="我不再覺得飢渴了。我能夠思考——我會活下去！喔，亞魯因…"
D.Strings[114605]="真是令人嘆為觀止，$n。\r\n\r\n蘇艾許將是我們未來有力的盟友。我會暫時注意著它。"
D.Strings[114606]="<地脈饋流產生輕柔的脈衝。>"
D.Strings[114607]="<隨著你對饋流注入更多法力，構造體開始發揮作用。空氣中開始瀰漫著秘法能量，你的皮膚感到刺痛。>"
D.Strings[114608]="<隨著你將斷裂的部分放到柱子上，並開始注入法力，秘法能量開始修復斷裂處。地脈啟動後，它開始緩慢轉動。>"
D.Strings[114609]="<隨著狂暴的能量從圓柱的縫隙逸出，地脈饋流也開始劈啪作響。>"
D.Strings[114610]="<隨著你將碎片重新插入柱子中，秘法能量開始修復裂痕。你對地脈饋流注入上古法力，整個構造體開始復甦。>"
D.Strings[114611]="我所有後悔的念頭，都在那些人進入護罩底下的時候消失了。"
D.Strings[114612]="船隻即將從刃拳海岸的碼頭出航，\r\n\r\n在你出發前，先做好準備吧。我有預感這會是艱難的一仗。"
D.Strings[114613]="我可以幫你，但你必須先幫我一點小忙。"
D.Strings[114614]="讓我看看你找到的東西。"
D.Strings[114615]="真是太奇妙了！這絕對不是出自燃燒軍團之手。讓我仔細瞧瞧。"
D.Strings[114616]="我知道柯林恩。我們不會低估他的狠毒，我保證。\r\n\r\n謝謝你幫助歐蘿蕾，她是我非常要好的朋友。"
D.Strings[114617]="我聽說你打算離開這座城市…據說夜裔精靈還有其他地方可去，在那裡我們再也不用忍受艾莉珊德的瘋狂。\r\n\r\n我想跟你一起走。\r\n\r\n我可以為你彈豎琴，也可以當你的幫手，雖然這些在這裡都派不上用場。\r\n\r\n只要你開口，我就跟你一起透過傳送器離開，與另一端的知音分享我的音樂。"
D.Strings[114618]="總算可稍稍鬆一口氣。你做得很好，可以稍微休息一下。"
D.Strings[114619]="她確實是一名可敬的夥伴。"
D.Strings[114620]="<薩莉瑟拉有好一會兒說不出話來。>"
D.Strings[114621]="我必須想個辦法…"
D.Strings[114622]="你必須把聖光之心放在這裡。"
D.Strings[114623]="我們必須找到解決方案，我們沒有多少時間了。"
D.Strings[114624]="你看起來已經做好戰鬥的準備。到了那裡，別讓嗜血的慾望支配你。\r\n\r\n大酋長希望在你前往戰場之前，先贈與你這枚戒指，願你能帶著無數惡魔的頭顱凱旋。"
D.Strings[114625]="如果真的成功了，說不定圖拉揚和聖光軍團還有希望。"
D.Strings[114626]="死了？泰坦們死了？$B$B<卡德加沉思了一會。>$B$B這的確能解釋非常多事情，但我還是忍不住感到無比的哀傷。一直以來都只有我們獨自奮鬥，眾神在我們還沒出生之前就死了。$B$B至於聖光軍團和伊利丹，我感到不知所措，我從來沒感到如此無助過。$B$B伊利丹死了，而聖光軍團為了我們在群星間進行永無止盡的戰爭。$B$B我需要休息一會，$n。這消息對一個老人來說太難承受了。"
D.Strings[114627]="對一個悲慘的生命來說，是一個好的開始，也許是伊利丹的人生中屈指可數的幾個愉快記憶之一。雖然在那之後的數年，預言之子受到考驗，但依舊沒有使他挫敗。不論在往後在旅途中你會看到什麼，都不能忘記這點。$B$B還有許多的事情要玩成，不過時機還沒到。時機成熟時，我會呼喚你。"
D.Strings[114628]="失敗，拒絕。從那一天起，伊利丹就被這兩種心魔糾纏。但他依然無所畏懼，持續尋找自己的宿命，他找到了另一條道路。"
D.Strings[114629]="伊利丹追尋真相，眼前所見卻使他變得一意孤行。他開始認識到自己的命運，但他還必須做出最後一項犧牲。"
D.Strings[114630]="$n，看見你真讓人喜極而泣。謝謝你救了我。\r\n\r\n我不知道我被困住多久…但是我感覺到附近有數量龐大的惡魔。\r\n\r\n我在這裡還有很多事要做。要不要幫我一把？"
D.Strings[114631]="你帶了什麼關於『吞噬者』恐翼的消息來？"
D.Strings[114632]="恐翼是一隻非常可怕的惡魔…我不得不說，你的技術讓我印象深刻，$n。\r\n\r\n要殺的惡魔多到不行。很高興能夠再跟你並肩作戰。"
D.Strings[114633]="仔細聽好。"
D.Strings[114634]="你最好一次就聽懂，我很討厭同一件事要說兩遍。"
D.Strings[114635]="也許外來者還是值得期待。"
D.Strings[114636]="在季節嬗變之際，真相將會浮現。"
D.Strings[114637]="終於，我們失落已久的同胞總算能重回這個世界了。精靈的歸屬，是燦爛的星空，而非虛假的幻象。\r\n\r\n感謝你，$n。"
D.Strings[114638]="啊，$n，很高興看到你安然無恙！六法議會的成員正從施法後的虛弱逐漸恢復。\r\n\r\n高強度的傳送法術可能會使人頭暈目眩，你剛剛雖然暫時失去意識，但至少醒來的時候沒發現自己卡在牆壁裡！\r\n\r\n達拉然已經移動到破碎群島。從現在開始，我們會傾全力取得創世之柱，將燃燒軍團永遠逐出艾澤拉斯！"
D.Strings[114639]="隨時注意蘇拉瑪爾四處有沒有出現這類結晶。我們一定用得上。"
D.Strings[114640]="啊，這樣感覺好多了。謝謝你！\r\n\r\n開始上工吧。"
D.Strings[114641]="很高興你趕到了。"
D.Strings[114642]="希望會有更多人跟隨他們。\r\n\r\n感謝你讓他們知道，要為夜裔效力還有其他的選擇。"
D.Strings[114643]="你找到那些俘虜的下落了嗎？"
D.Strings[114644]="<西爾格臨一臉嚴肅地看著通訊器。>"
D.Strings[114645]="感謝你願意冒這個險。我們現在就來做個了結吧！"
D.Strings[114646]="做得好。在他們把援軍找來之前我們趕快離開吧。"
D.Strings[114647]="謝謝你。在你來之前，我們完全沒有獲救的希望。"
D.Strings[114648]="我們必須立刻採取行動！"
D.Strings[114649]="夜落精靈堅持要參與這場戰鬥。我們的人手應付不了所有的工作。"
D.Strings[114650]="現在只需要全神貫注在他的精華上，然後分析出他的所在位置。你做得很好。"
D.Strings[114651]="真是…不容易…但我很高興我們成功了。"
D.Strings[114652]="<凡席爾劇烈顫抖，眼神空洞地盯著前方。他似乎沒有察覺到你在這裡。>"
D.Strings[114653]="<凡席爾的雙手猛然伸出，從你的手裡搶走果實。>"
D.Strings[114654]="下次有雞會，我一定確保他得到妥善的照顧。我們今天大有斬獲，$n。\r\n\r\n艾莉珊德一定會記住，我們不會輕易丟下自己人。"
D.Strings[114655]="做得好。有時候一場簡單的勝利就能把軍隊團結起來。接下來，這些新兵就會開始訓練其他人，我們軍隊的規模就會越來越大。"
D.Strings[114656]="感謝你的勇氣，這些人的命都是你救的。他們不會忘記我們為此所冒的風險。"
D.Strings[114657]="你協助的受訓員一直在讚美你的戰鬥技巧。他們已經開始把自身所學教給其他人了。\r\n\r\n我很感激你在這方面的幫忙。"
D.Strings[114658]="這些武器應該會在接下來的戰鬥中派上很大的用場。做得好啊，英雄。"
D.Strings[114659]="你找得怎麼樣了？"
D.Strings[114660]="好極了。這些書籍裡的知識對我們之後的作戰應該大有幫助。"
D.Strings[114661]="很好。解決他之後，等我們部隊的主力抵達，就能建立更穩固的據點。"
D.Strings[114662]="我們差點在入侵行動開始之前就失敗了。做得好。"
D.Strings[114663]="謝謝你，$n。希望我們的部隊看到你完成這件事以後會恢復理智，並停止這種騷擾行為。"
D.Strings[114664]="暮衛部隊的每個成員都花了好幾百年磨練戰鬥技巧。我們可沒有這種時間訓練這些反抗軍。"
D.Strings[114665]="很高興看到你來。我正好需要幫手。"
D.Strings[114666]="我有點嚇到。有時候我覺得歐庫雷斯也不知道自己在做什麼。"
D.Strings[114667]="真是讓人生氣。好吧，至少她與生俱來的能力和我預估的差不多…"
D.Strings[114668]="完成了。沙亞蘭以後再也不缺法力了。"
D.Strings[114669]="真是一場精采的冒險。我們現在總算有足夠的法力提供給難民了。謝謝你，$n。"
D.Strings[114670]="就跟我所擔憂的一樣。希望他們現在不敢再派間諜出來了。"
D.Strings[114671]="她看起來不錯。奧肯多爾果實對我們的同胞來說確實是奇蹟。\r\n\r\n在接下來的戰鬥中，她會是不錯的盟友。西爾格臨會好好照顧她的。"
D.Strings[114672]="我實在無法表達對你的感激。我們會再度重逢的，我會確保我們再也不分開。"
D.Strings[114673]="那魯聽到我的呼喚了？有意思…$B$B很好，我們就開始著手進行吧。我們終於找到伊利丹的靈魂了，所在位置出人意料之外。"
D.Strings[114674]="伊利達瑞的靈魂稜石可以使用了。$B$B有人將伊利丹的靈魂從虛空之中抽離…或者是說竊取…然後帶往冥界了。在一個叫做黑爾海姆的地方。"
D.Strings[114675]="<聖光之心發出耀眼的光芒，似乎在吞噬靈魂稜石。>"
D.Strings[114676]="等有更多果實成熟時，我會再度請你幫忙。\r\n\r\n現在，我們需要討論令人不安的消息。"
D.Strings[114677]="嗯，現在我們可以專心解救還在城裡受苦的居民了。"
D.Strings[114678]="就在那裡。希望黎利斯給的是好消息…"
D.Strings[114679]="嗯，我們走吧。"
D.Strings[114680]="很好。我們現在就前往戰爭前線，了解情況。"
D.Strings[114681]="謝謝你，$n。我們每一天都朝解救蘇拉瑪爾更近一步。"
D.Strings[114682]="我好像聽到了什麼。"
D.Strings[114683]="你能不能施捨一些硬幣?"
D.Strings[114684]="今天的漢堡我會很樂意在星期二那天付錢給你。"
D.Strings[114685]="遵命，長官!"
D.Strings[114686]="馬上就去，長官。"
D.Strings[114687]="呃!"
D.Strings[114688]="不要再來了..."
D.Strings[114689]="我是一個賣布的，這是我原始設定的見面打招呼的話。"
D.Strings[114690]="你想找哪種專業技能訓練師?"
D.Strings[114691]="鍊金術"
D.Strings[114692]="我們代表的是黑暗與陰影。永恆。無形。"
D.Strings[114693]="請繼續。"
D.Strings[114694]="謝謝你。"
D.Strings[114695]="聽你的!"
D.Strings[114696]="嗨你，你是不是想要去詹迪亞的加迪植物園。我剛剛沒有說清楚嗎?哦，我肯定累了!只要沿著智慧谷裡的阿索蘭的市場後面的木製臺階到達暗巷區，你可以看到加迪就在那裡的上層。"
D.Strings[114697]="打開它。"
D.Strings[114698]="啊，現在我生氣了!"
D.Strings[114699]="%s昏倒在地上。"
D.Strings[114700]="地精因為體格矮小而很難擊中。不過，他們有時會手舞足蹈，擺臀扭胯。這時你就可以像這樣攻擊他們..."
D.Strings[114701]="嗚喔!"
D.Strings[114702]="貿易區上層的麥可·加勒特。"
D.Strings[114703]="吼..."
D.Strings[114704]="不要召喚這樣的東西。它如此脆弱，用棒敲擊就能使它粉身碎骨。"
D.Strings[114705]="%s嗚咽著。"
D.Strings[114706]="好!"
D.Strings[114707]="炸藥！更多炸藥！我還要更多炸藥！"
D.Strings[114708]="我們渴望復仇。"
D.Strings[114709]="關於磨損的憎惡體縫合線的資訊。"
D.Strings[114710]="嗯...我認為你體型過大，不能乘坐機械陸行鳥，$g先生:女士;。你很可能會壓碎這些精美的機器!"
D.Strings[114711]="你可能不會像白銀之手騎士團那樣追尋光之蹤跡，但是你總可以向我們尋求幫助。"
D.Strings[114712]="我們勝利了!阿莎利水晶已經修復!"
D.Strings[114713]="那位獵人訓練師名字叫索塔爾。去剃刀嶺西南部的洞穴中找他吧。"
D.Strings[114714]="讓我們展開新的戰役，對抗部落！"
D.Strings[114715]="(達納蘇斯語)安奴'多利尼·塔拉哈。奴·夏羅拉·伊奴多利。"
D.Strings[114716]="我聽到你的話了，巨熊之靈，而且我理解。我現在尋求你的賜福以深入地學習利爪的技能。"
D.Strings[114717]="我想接受訓練。"
D.Strings[114718]="%s死了。"
D.Strings[114719]="我想要遺忘我的天賦。"
D.Strings[114720]="這些都是大地之母走過的道路。願你的祖先保佑你們$c。"
D.Strings[114721]="%s看到他的主人死去，也隨即崩潰了!"
D.Strings[114722]="(達納蘇斯語)伊蘇奴... 歐夏蘭·薩拉·多米爾·... 安奴'多利尼..."
D.Strings[114723]="我們想要很多寵物。安雅·瑪爾雷能幫你照顧它們。去貿易區上層的旅館找她吧。"
D.Strings[114724]="%s的死亡哀嚎已經擾動了附近的異種巢穴!"
D.Strings[114725]="結束了，傑斯托。給我一盞信號燈。"
D.Strings[114726]="絕對是。給我一個火把，雷松。"
D.Strings[114727]="(達納蘇斯語)雪憂·麥利奈·伊蘇奴·朵多拉..."
D.Strings[114728]="單擊此處消除復活效果並修理所有裝備"
D.Strings[114729]="西部霜狼哨塔被部落佔領了！"
D.Strings[114730]="誰控制著丹巴達爾南部碉堡?"
D.Strings[114731]="西部霜狼哨塔保護著霜狼村和霜狼要塞之間的大門。$B$B聯盟控制著這片土地。"
D.Strings[114732]="西部霜狼哨塔保護著霜狼村和霜狼要塞之間的大門。$B$B部落控制著這片土地。"
D.Strings[114733]="西部霜狼哨塔保護著霜狼村及霜狼要塞之間的大門。$B$B聯盟和部落還在爭奪這片土地。"
D.Strings[114734]="有什麼我能幫忙的？"
D.Strings[114735]="這很有趣，但是這是你想要的嗎?"
D.Strings[114736]="讓賽事開始吧!"
D.Strings[114737]="死亡礦坑位於西部荒野南部的月溪鎮地下。"
D.Strings[114738]="暗月馬戲團只會停留有限的時間。一定要在今天來看啊！"
D.Strings[114739]="%s注視著$n。"
D.Strings[114740]="剛做好的...另一批的暗月特調。趕快來吧，它們很快會被搶光的!"
D.Strings[114741]="你好!朋友們，歡迎參觀艾澤拉斯大陸上最偉大的表演!$B$B請往前走並享受我們所提供的一切。讓暗月馬戲團在這個巨大而神秘的世界上所發現的奇特事物為你帶來前所未有的驚奇!我們會繼續不遺餘力地為各個年齡的小孩帶來雀躍不已的興奮感受!"
D.Strings[114742]="法希爾，我把墜飾弄丟了。我需要一個新的。"
D.Strings[114743]="我想要輸入驗證碼以領取我的魚人寵物。"
D.Strings[114744]="你是最棒的，$n - 謝謝你幫我去參加「不給糖就搗蛋」的活動!"
D.Strings[114745]="聯盟榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。聯盟不同陣營的表揚官分布在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找戰場元帥斯諾·落雪。"
D.Strings[114746]="部落榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。部落不同陣營的表揚官分布在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找督軍格爾庫克。"
D.Strings[114747]="卡林多的士兵們，防守基地!"
D.Strings[114748]="嗨，$c。你好眼熟...我們以前有見過面嗎?$B$B如果我們見過面，那麼...你一定有一組驗證碼吧。告訴我你的驗證碼，我就會給你一份禮物!"
D.Strings[114749]="如果你香香的我就跟你聊天。古龍水還不錯。"
D.Strings[114750]="什麼，你沒有硬幣要給我嗎?你不愛我喔?"
D.Strings[114751]="我不能教你部族的製皮技術，$n。你一定要去塔納利斯找到納里安·柔想的家。到了那裡，參照「新手的預言入門」這本書。"
D.Strings[114752]="你可以不用再插手了，$n!瓦薩拉克領主會採取他的復仇!"
D.Strings[114753]="什麼守護者?我完全不知道。"
D.Strings[114754]="喔不!你不能死!現在才剛開始! <PH>"
D.Strings[114755]="不留活口!"
D.Strings[114756]="天譴軍團就在附近!"
D.Strings[114757]="你有看到嗎?那裡有個天譴軍團的人!"
D.Strings[114758]="哦，雷利? <PH>"
D.Strings[114759]="是的，雷利! <PH>"
D.Strings[114760]="前進 3! <PH>"
D.Strings[114761]="你是說..."
D.Strings[114762]="嗨，我是個新生者。"
D.Strings[114763]="我看到你當時的褲子是捲下的而你的錘子在你手中。"
D.Strings[114764]="你有什麼樣的未來資訊?"
D.Strings[114765]="你看起來就是我需要的術士!一定要打敗邪惡的哥布林首領斯納爾。"
D.Strings[114766]="節日 - 天譴軍團入侵，神秘事件 - 入侵行動持續時間，第0階段"
D.Strings[114767]="節日 - 天譴軍團入侵，神秘事件 - 入侵行動持續時間，第1階段"
D.Strings[114768]="節日 - 天譴軍團入侵，神秘事件 - 入侵行動持續時間，第2階段"
D.Strings[114769]="死亡是唯一的解脫！"
D.Strings[114770]="謝…謝…你…"
D.Strings[114771]="如你所願。"
D.Strings[114772]="你好，$n。我是強尼·麥克威醬。我被開發者用來實行特殊的功能做為測試。在這段測試期間，我的工作有兩件事:$B$B(1) 將你標示為完成納克薩瑪斯協調任務，這樣你才能從指揮官艾利格·黎明使者那裡接下一個「戰爭的回響」任務。你必須先完成該任務才能進行第3階段甲套裝的任務。$B$B(2) 將你傳送至納克薩瑪斯。$B$B你想要哪一個?"
D.Strings[114773]="我需要被標示。"
D.Strings[114774]="你好，$n。我看到你已完成進入納克薩瑪斯的任務。記得到東瘟疫之地的聖光之願禮拜堂和指揮官艾利格·黎明使者談談，取得任務「戰爭的回響」。你必須先完成那個任務才能進行第3階段護甲套裝的任務。$B$B我可以將你直接傳送至納克薩瑪斯或者你可以使用病木林裡的傳送門，就在西邊。"
D.Strings[114775]="%s說了一些難以理解的悄悄話。"
D.Strings[114776]="%s啜泣著。"
D.Strings[114777]="啊，活著真好。"
D.Strings[114778]="再來一杯!"
D.Strings[114779]="走開...我想在這裡睡覺。"
D.Strings[114780]="奪旗點爭奪中1"
D.Strings[114781]="奪旗點爭奪中2"
D.Strings[114782]="奪旗點勝1"
D.Strings[114783]="奪旗點勝2"
D.Strings[114784]="奪旗點進度1"
D.Strings[114785]="奪旗點進度2"
D.Strings[114786]="這是怎麼回事？"
D.Strings[114787]="你不該來這裡!"
D.Strings[114788]="你們阻止不了我們全部!"
D.Strings[114789]="趁你還來的及的時候回頭。"
D.Strings[114790]="進入階段3<PH>"
D.Strings[114791]="火盆激發了無助的獸人![PH]"
D.Strings[114792]="進入階段2<PH>"
D.Strings[114793]="你有任何烹飪補給嗎?"
D.Strings[114794]="嘿赫米瑟斯，我有新信嗎?"
D.Strings[114795]="赫米瑟斯快來!我有一封緊急信件一定要送到聯盟遠征隊的人類上將手上。"
D.Strings[114796]="你一定是德萊尼史上最懶的信差。"
D.Strings[114797]="抱歉，你輸了!<PH>"
D.Strings[114798]="嗨，$n。點擊下列的選項來完成任務9711 - 殘忍的馬帝斯。$B$B請注意雖然我正嘗試施展一個法術但並沒有任何事發生。"
D.Strings[114799]="你讓我變的完整。"
D.Strings[114800]="對我施展另一個法術，對同樣的目標作用但為不同的效果 - 就像死亡之觸。"
D.Strings[114801]="我的王，事情將會完成。"
D.Strings[114802]="抱歉，你贏了!<PH>"
D.Strings[114803]="[PH]衝突完成!"
D.Strings[114804]="開始事件<PH>"
D.Strings[114805]="放逐<PH>"
D.Strings[114806]="[PH]英國人來了!清理路面!"
D.Strings[114807]="如你所願!"
D.Strings[114808]="看來你做了錯誤的選擇，$c。"
D.Strings[114809]="帶我到那去<PH>"
D.Strings[114810]="競賽祝福者，請給我獎賞。"
D.Strings[114811]="沒有可用的交通工具了!應該很快就會有一個了...<PH>"
D.Strings[114812]="就要結束了!"
D.Strings[114813]="就差一步..."
D.Strings[114814]="沒有時間了!"
D.Strings[114815]="[PH]玩家!快去樹那裡阻止阿克蒙德，我們會守住這裡的不死族!"
D.Strings[114816]="給我一面戰旗。我會去佔領雙塔廢墟。"
D.Strings[114817]="我有個夢想...一個製作舒服鞋子的夢想，它們是世界無敵的!"
D.Strings[114818]="我知道如何製作有史以來最舒適的鞋子...前提是要有夠軟的皮革來製作它們!"
D.Strings[114819]="我們出發吧!"
D.Strings[114820]="你是誰?你和巫師在一起嗎?[PH]"
D.Strings[114821]="不，我現在不是最重要的。你必須幫助索爾脫逃。我會放火來分散注意力，不過我被關在這個有法力的監牢裡，所以你得代替我才行。[PH]"
D.Strings[114822]="冬天爺爺在冬幕節日的盛宴期間，會在鐵爐堡的樹下為每個人留下玩具!"
D.Strings[114823]="傳說年獸沉睡在月光林地的月神湖水裡，一年只出現一次。但是那只是一個傳說。"
D.Strings[114824]="在新年慶典期間，我們應該花時間尋找我們的長輩並且聽取他們的智慧。"
D.Strings[114825]="你有看過煙火嗎?現在可是一年之中購買它們的最佳時機。"
D.Strings[114826]="藥劑師學會著手研究尋求出巫妖王瘟疫的解藥。"
D.Strings[114827]="米歐瑞德護士真的很好，她在我爸爸受傷的時候照顧他。"
D.Strings[114828]="那些男孩們總是到這裡來製造麻煩和嚇唬窮人、小老鼠們。"
D.Strings[114829]="薩克-沙拉瑞斯-尼拉克!"
D.Strings[114830]="啊喀-哈!"
D.Strings[114831]="凱文·喬丹和強納森·樂卡夫特!"
D.Strings[114832]="我們絕不能讓主人失望。"
D.Strings[114833]="Ba'anthalso-dorei! (殺死陸地人！)"
D.Strings[114834]="你的等級還不足以參加暴風之眼的戰鬥。等你獲得更多經驗的時候再回來。"
D.Strings[114835]="敵人將無法通過這裡!"
D.Strings[114836]="範圍效果成功了。"
D.Strings[114837]="祝你好夢。"
D.Strings[114838]="(惡魔語)再來一次!"
D.Strings[114839]="那就是我所說的!"
D.Strings[114840]="Andu-falah-dor!  (願自然恢復平衡！)"
D.Strings[114841]="(達納蘇斯語)滾回虛空去吧，惡魔!"
D.Strings[114842]="看我的! [PH]"
D.Strings[114843]="我贏了嗎? [PH]"
D.Strings[114844]="沒人可以打那個東西! [PH]"
D.Strings[114845]="這個南瓜看起來肯定香甜多汁!沒人會注意到要是我咬了一小口... [PH]"
D.Strings[114846]="誰正在偷我的南瓜?!你不會跑不掉的，你這個無賴! [PH]"
D.Strings[114847]="一切都照著進度在進行。"
D.Strings[114848]="遺忘部族製皮不是件容易的事。如果你選擇遺忘它，你將會遺忘所有需要部族製皮的所有方法!"
D.Strings[114849]="他們能奪走我們的土地，但是他們不能奪走我們的自由!攻擊![PH]"
D.Strings[114850]="啊...哈!找到他們了!把他們全都殺了! [PH]"
D.Strings[114851]="替我將我們敵人的頭顱帶來!現在就去殺光他們![PH]"
D.Strings[114852]="嘖嘖! [PH]"
D.Strings[114853]="Belore... (陽光…)"
D.Strings[114854]="控制獸人蠻兵"
D.Strings[114855]="所有附近的阿拉卡都面對東方，並吹出長而低沉的祈禱。[PH]"
D.Strings[114856]="嘎!是誰膽敢殺死我的信奉者並且召喚我，高階祭司A，向前![PH]"
D.Strings[114857]="我們有一些不速之客... [PH]"
D.Strings[114858]="喔，這會很有趣![PH]"
D.Strings[114859]="測試02"
D.Strings[114860]="絕不留情!"
D.Strings[114861]="%s衝向前，仔細地觀察它的敵人。"
D.Strings[114862]="司凱堤斯風行者把一捆芳香藥草投入火裡。[PH]"
D.Strings[114863]="你認為你贏了?"
D.Strings[114864]="但你們是龍!獸人怎能對你做這些事?"
D.Strings[114865]="地獄火半島 - 莫爾迪巴原始設定問候語"
D.Strings[114866]="Band'or shorel'aran! (準備道別吧！)"
D.Strings[114867]="Endorel anuminor! (聽從我的命令吧！)"
D.Strings[114868]="Endala finel endal! (嚥下你最後一口氣吧！)"
D.Strings[114869]="Anar'endal dracon! (以龍息之名！)"
D.Strings[114870]="Anu... bala belore...alon. (溫暖的…陽光…等待著我。)"
D.Strings[114871]="Alana be'lendor! (你的末日到了！)"
D.Strings[114872]="Be'lemer an-delei! (你徹底失敗了！)"
D.Strings[114873]="結束了。"
D.Strings[114874]="Anar'anel belore! (以太陽之名)！"
D.Strings[114875]="注意!"
D.Strings[114876]="駐紮!"
D.Strings[114877]="如果你喜歡的話你可以親吻我，不過動作要快。"
D.Strings[114878]="確定你有為了下一場煙火秀到處張貼佈告!晚下6點開始，每個小時整點一次!"
D.Strings[114879]="朋友自己找點喝的吧。只要記得在喝的時候離暗礁遠一點就好了。"
D.Strings[114880]="煙火後，將會推出高腳杯。我們接著將會對我們的同伴舉杯!"
D.Strings[114881]="下午6點開使，城裡每個小時整點都會有一場異常盛大的煙火表演。"
D.Strings[114882]="那是什麼?"
D.Strings[114883]="Tal anu'men no sin'dorei! (與血精靈為敵者死！)"
D.Strings[114884]="Be'lanen dalorai!(你該死了！)"
D.Strings[114885]="司凱堤斯獲勝!"
D.Strings[114886]="可惡!"
D.Strings[114887]="(惡魔語)阿克拉·拉赫西·米希斯拉!"
D.Strings[114888]="[DEBUG]在我身上施法[DEBUG]"
D.Strings[114889]="[DEBUG]那麼我們走吧!"
D.Strings[114890]="嘎!"
D.Strings[114891]="我們最近專注在測試海加爾山戰役。你一定要達到紫羅蘭之眼至少尊敬的聲望才可參加。$B$B就是當你在進行卡拉贊時你可以獲得的聲望。"
D.Strings[114892]="吉米，你能夠幫我標示海加爾山的進入權嗎?"
D.Strings[114893]="吉米，我想要買東西。"
D.Strings[114894]="現在你已經海加爾山同步了，我可以將你傳送至時光之穴了。當你準備好了就讓我知道吧。"
D.Strings[114895]="我準備好進入海加爾山了，吉米。傳送我!"
D.Strings[114896]="我們最近專注在測試黑暗神廟。你一定要達到紫羅蘭之眼至少尊敬的聲望才可參加。$B$B就是當你在進行卡拉贊時你可以獲得的聲望。"
D.Strings[114897]="我想要購買黑暗神廟的鑰匙還有一些優良裝備。"
D.Strings[114898]="現在你已經有了黑暗神廟的鑰匙(卡拉伯爾勳章)，我可以直接傳送你到黑暗神廟。當你準備好就跟我說吧。"
D.Strings[114899]="Belesa menoor!(幹得好！)"
D.Strings[114900]="Diel ma'ahn... orindel'o.(低等…生物。)"
D.Strings[114901]="Diel fin'al.(送你上路。)"
D.Strings[114902]="Sha'amoor ara mashal?(準備放棄了嗎？)"
D.Strings[114903]="Shal'mor sinabanal!(為了你的生命而戰吧！)"
D.Strings[114904]="Selama am'oronor!(奉行正義！)"
D.Strings[114905]="把肉從你骨頭上扯下來！"
D.Strings[114906]="瞧，是$n!"
D.Strings[114907]="有你在這，我們就安全了，$n。"
D.Strings[114908]="但願有更多像你這樣的$g英雄:英雌;，$n。"
D.Strings[114909]="$n，我希望你可以在這裡待一陣子。要是你有時間的話，稍後停留一下。"
D.Strings[114910]="現在你將會看到真正高超的騎術!"
D.Strings[114911]="那將會留下紀錄...我只要在這休息一下。"
D.Strings[114912]="喝酒最棒的事就是裝酒醉...我只素在假裝。"
D.Strings[114913]="最後能跟朋有對飲真素好...平常我組能坐在家裡自己喝而已。"
D.Strings[114914]="美好時光!<嗝!>"
D.Strings[114915]="前往奧格瑪的飛艇剛剛抵達!要到杜洛塔的乘客請上船!"
D.Strings[114916]="前往幽暗城的飛艇剛剛抵達!要到提里斯法林地的乘客請上船!"
D.Strings[114917]="雷!雷!雷!雷酒，嘿!"
D.Strings[114918]="喂，就是你!喝巨魔酒!讓你又大又壯!"
D.Strings[114919]="你試過最好的了，現在試試其它的!巨魔酒!!"
D.Strings[114920]="你在艾澤拉斯找不到更好的啤酒啦。"
D.Strings[114921]="噢，再走過一次，小可愛!你背部的肌肉線條真美!"
D.Strings[114922]="你!可愛的人!你想要到我的地方去看看我的工具收集嗎?"
D.Strings[114923]="呦喔喔喔喔吼，你這個勻稱有魅力的人，就是你!"
D.Strings[114924]="別擋路!"
D.Strings[114925]="看來好像我得從別處拿點喝的了。"
D.Strings[114926]="我要回去孤兒院!"
D.Strings[114927]="喝下這桶免費的酒，然後把你的酒桶拿來丟暴飲者們!"
D.Strings[114928]="要是我爸還活著，他就會熄滅那些火焰!"
