D.Strings[114995]="薩魯法爾來了，沙蓋!是薩魯法爾!布洛克斯的兄弟本人來幫助我們了!"
D.Strings[114996]="我可以嗅到你的恐懼。"
D.Strings[114997]="喲，叮噹。叮噹啊老兄。叮噹，喲！"
