D.Strings[115002]="加入我們..."
D.Strings[115003]="你沒聽說過「每月啤酒」俱樂部?那裡的女孩們真的很愛開派對。她們的興趣只要持續下去，啤酒節就永遠不會結束!去年就有些時候，感覺啤酒節好像還沒結束。$b$b如今，她們發現，讓啤酒節的精神繼續下去的最好方法，就是讓大家加入她們的俱樂部。$b$b只要花一點點錢，幾個獎品章，你就能加入了!你每個月都可以從信箱裡收到啤酒，要是你喜歡的話，你可以額外買啤酒。這真是劃時代的東西，還可以確保啤酒節的精神永遠不會消失。"
D.Strings[115004]="自毀程序已展開。"
