D.Strings[115009]="喔不，另一面啟動了![PH]"
D.Strings[115010]="最後一面啟動了，當心!我快要完成了，別讓他們靠近![PH]"
D.Strings[115011]="成功了!應該解決了! [PH]"
D.Strings[115012]="哺咕嚕哺咕哺呣!"
D.Strings[115013]="欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。到上面把他找出來。"
D.Strings[115014]="欸，欸!只有召喚我的人可以看。"
