D.Strings[115051]="在大藥劑師普崔司身旁工作是我的榮幸。他的工作從巫妖王的瘟疫中拯救了這個世界，給了我們新的希望。"
D.Strings[115052]="風暴之心國王派我來接受霜誕矮人應有的考驗。我已經準備好接受試煉了，弗尤林。"
