D.Strings[115071]="冰川瀑布的東邊，老兄。去那邊把你能找到最好的護甲給帶回來。那些聯盟根本不會知道誰在攻擊他們。"
D.Strings[115072]="你準備好要面對觀察者了嗎?[PH]"
D.Strings[115073]="沒錯，冰結者，搖一搖，烤一烤! [PH]"
D.Strings[115074]="清理火星塞!$B$B\n|TInterface\\Icons\\INV_Misc_EngGizmos_12.blp:64|t"
D.Strings[115075]="你確定你想在對抗尤格薩倫的戰鬥中要我幫忙?"
D.Strings[115076]="嗯...你們其中一個蠻兵可以去解決那邊那些人嗎？！"
D.Strings[115077]="(古神語)他會學會...沒有君王能夠永遠統治;只有死亡才是永恆不變!"
D.Strings[115078]="我被打敗了。打得漂亮!"
D.Strings[115079]="雙天賦專精讓你可以保留兩套職業專精、天賦和雕紋模組。你可以輕易地切換這兩套天賦。\n\n當你切換天賦模組時，你會同時切換第二套雕紋模組和第二套快捷列。\n\n你無法在戰鬥中切換，並會消耗你的可用資源。"
D.Strings[115080]="傳送至凜冬之廳。"
D.Strings[115081]="(泰坦語)我會碾碎你!"
D.Strings[115082]="我不知道我到底能不能參賽!每個人都好大!"
D.Strings[115083]="古柯什！"
D.Strings[115084]="部落雜碎！"
D.Strings[115085]="謝謝。"
D.Strings[115086]="把他們擊退！"
D.Strings[115087]="$n$G先生:女士;，火山出了什麼事？"
D.Strings[115088]="(蟲族語)脆弱的肉體!"
D.Strings[115089]="那些法師們發生了什麼事？"
D.Strings[115090]="啊啊啊!"
D.Strings[115091]="死王八！"
D.Strings[115092]="神奇魔咒！"
D.Strings[115093]="蘇依納米朱朱，哥布！"
D.Strings[115094]="它倫脫播須！"
D.Strings[115095]="米課，迷逆它烏兒！"
D.Strings[115096]="時間就是金錢，朋友！"
D.Strings[115097]="散開！"
D.Strings[115098]="這是個測試"
D.Strings[115099]="遇見了某人？我以為這裡已經沒有其他的龍族了。"
D.Strings[115100]="我從元素界域而來！"
D.Strings[115101]="你現在站在天譴軍團的聖地。聖光在這裡沒辦法保護你，聖騎士。沒有東西能保護你..."
D.Strings[115102]="但這樣的殊榮已經不再屬於你了。很快，我將會擁有一位新的勇士。"
D.Strings[115103]="超載中"
D.Strings[115104]="%s瞪著你好一陣子，顯然無法相信你居然是真的。"
D.Strings[115105]="鮮血與雷霆，吾兒。"
D.Strings[115106]="嗯嗯"
D.Strings[115107]="火箭中有一種化學藥劑。那是什麼?"
D.Strings[115108]="元素裂隙已經出現於城鎮的各地。我們必須馬上將它們關閉!疏散所有非戰鬥人員，確保他們到安全的場所!"
D.Strings[115109]="等你準備好的時候，我會護送你進入太陽之井。"
D.Strings[115110]="別在那邊窺探，朋友。$B$B如果你想買王冠公司節日商品，你可以去找城裡的可愛商品商人。"
D.Strings[115111]="啊啊啊啊!"
D.Strings[115112]="它正在瘋狂地閃爍和嗶嗶叫。挖這！"
D.Strings[115113]="你別想干擾。"
D.Strings[115114]="瑪勾納吉！吉！毫金，安發，達比！"
D.Strings[115115]="[ph]雷霆崖的居民們!我們的族母瑪加薩要求你們在存取貴重物品時付點小小的費用。"
D.Strings[115116]="[ph]花這筆錢能讓你在一定時間內使用銀行服務。"
D.Strings[115117]="[ph]拒絕支付這筆費用的居民，不得在雷霆崖使用銀行服務。"
D.Strings[115118]="[ph]從我這裡買一張准許證明，你就能存取你的寶庫。"
D.Strings[115119]="[ph]各位雷霆崖的居民注意這邊!"
D.Strings[115120]="[ph]只要一小筆金額，你們就能取得使用任何一位恐怖圖騰拍賣師服務的全境許可。"
D.Strings[115121]="[ph]這筆錢會全數用在部落的改善措施上。"
D.Strings[115122]="[ph]不願意付錢的居民不得使用拍賣服務。"
D.Strings[115123]="[ph]克蕾兒死了?難以想像會發生這樣的事情。"
D.Strings[115124]="[ph]我們還是相當幸運。瑪加薩帶得不錯。她知道會有這麼一天的。"
D.Strings[115125]="[ph]居然這麼快?我想連她都沒料到這次的入侵會順利到這種程度。"
D.Strings[115126]="[ph]在想事情?你能有什麼事情好想的?"
D.Strings[115127]="[ph]在凱恩死掉後這麼短的時間內又站上「我們的」雷霆崖...這不是好運。"
D.Strings[115128]="沃金，你可以跟我說暗矛部族是什麼時候離開奧格瑪的嗎？我必須親眼看到卡爾洛斯的所做所為。"
D.Strings[115129]="[ph]這讓我想到...完全沒有人料到這一點。"
D.Strings[115130]="[ph]她八成盤算很久了。"
D.Strings[115131]="[ph]對雷霆崖發動攻擊比原先預期的要來得容易。"
D.Strings[115132]="[ph]沒有了凱恩，雷霆崖的居民們已經沒什麼鬥志。"
D.Strings[115133]="[ph]現在這邊為我們所控制，這附近將會變得不一樣。"
D.Strings[115134]="[ph]我只是希望風暴之歌當時能解決那偽善者。貝恩一死，我們就能再搞定更多的巡邏衛兵。"
D.Strings[115135]="[ph]還沒。我最後一次和塔拉寇說話的時候，就應該已經開始了。"
D.Strings[115136]="[ph]保持警戒。看到血蹄的徽記就代表我們即將要面臨一場硬仗。"
D.Strings[115137]="[ph]看起來恐怖圖騰部族現在有地方能建造家園了。"
D.Strings[115138]="[ph]我不會這麼快就下定論。"
D.Strings[115139]="[ph]如果那個篡位者來到這裡，我們跟他沒什麼好說的。"
D.Strings[115140]="[ph]貝恩?要他來這的話他會抓狂的。我們這邊人數至少是他的兩倍。那個需要擔心的對象是他才對。"
D.Strings[115141]="[ph]別低估了血蹄那邊的人數。你有沒有看過凱恩平常帶著的那根圖騰?"
D.Strings[115142]="[ph]我只聽過故事。有些人說這得要用兩手才能拿得起來，可是凱恩用單手就能輕鬆揮舞。"
D.Strings[115143]="[ph]的確是。讓我們祈禱貝恩的力量不及他父親的一半...不然我們需要的是更多的衛兵。"
D.Strings[115144]="喂，我不過是想拿我應得的。"
D.Strings[115145]="[PH]我們不會失敗或畏縮。"
D.Strings[115146]="[PH]我們不會虛弱或疲累。"
D.Strings[115147]="[PH]不論是受到突發戰鬥的驚嚇，還是長時間執行警戒任務，都無法削弱我們。"
D.Strings[115148]="[PH]把工具交給我們..."
D.Strings[115149]="[PH]..我們將會完成任務!"
D.Strings[115150]="[PH]為了諾姆瑞根!"
D.Strings[115151]="火焰將會吞噬這個世界。風暴將會捲走所有希望。最後元素將會統治一切!"
D.Strings[115152]="拋開充滿戰爭和苦工勞役的生活，在元素之中重獲新生，然後在新世界中取得你應有的正當地位!"
D.Strings[115153]="冷靜點，朋友。有很多時間可以慢慢回答你的問題。"
D.Strings[115154]="牠碰到了兩隻正在爭鬥的科多獸。$b狼很聰明的決定等一隻擊敗另一隻。"
D.Strings[115155]="為了部落，$c。"
D.Strings[115156]="搞什麼...?"
D.Strings[115157]="哇呀呀呀呀呀呀呀呀呀呀"
D.Strings[115158]="水晶賦予你新的能力!運用這些能力擊敗那些召喚出來的元素。"
D.Strings[115159]="這些事件…組織中彼此的怨恨和勾心鬥角。這些是懦弱和醜陋的，沒錯。但是！這些也是必要的！"
D.Strings[115160]="*打呵欠*"
D.Strings[115161]="哇呀嗚！！！"
D.Strings[115162]="喀喀喀…啊啊啊…！"
D.Strings[115163]="了不起！"
D.Strings[115164]="我應該待在凱贊跟那些火山混在一起就好了。"
D.Strings[115165]="以我獨子的屍體起誓，你這隻該死的豬雜種。"
D.Strings[115166]="看，崖行者，看這場戰爭是如何光榮地劃下句號。"
D.Strings[115167]="繼續攻擊，$n!"
D.Strings[115168]="夠了!陶土議會可以暫時的阻止這次的入侵。但是你必須知道，元素們會再回來的!"
D.Strings[115169]="嘿..."
D.Strings[115170]="為了部落, $n!"
D.Strings[115171]="別擔心，二副。我們還會有機會的。我們會做好充足的準備。"
D.Strings[115172]="我們正在靠近洞穴，船長。"
D.Strings[115173]="波動動動動動動動動…"
D.Strings[115174]="…拳！！"
D.Strings[115175]="破壞！"
D.Strings[115176]="別讓那些納迦靠近坑洞!"
D.Strings[115177]="校準導火線..."
D.Strings[115178]="我不該問的..."
D.Strings[115179]="又見面了。"
D.Strings[115180]="喳喳！"
D.Strings[115181]="咕嚕咕嚕咕。"
D.Strings[115182]="咕嚕咕嚕咕！"
D.Strings[115183]="嚕嚕咕嚕咕咕嚕咕嚕咕嚕！！"
D.Strings[115184]="暴風城兩家最受歡迎的旅店分別坐落在貿易區和矮人區:鑲金玫瑰和黃金酒桶。"
D.Strings[115185]="暴風城的花園已經被毀，許多夜精靈也因此不幸喪生。現在最有可能找到老瑟萊斯丁的地方就在矮人區外頭。$B$B城北廣場有道往下的樓梯…你可以在那邊看到她的小屋。"
D.Strings[115186]="告訴我更多關於地深之源和世界之柱的事情。"
D.Strings[115187]="呃啊！"
D.Strings[115188]="死亡只是個開始。"
D.Strings[115189]="DEBUG事件送出 - 北 - 部落進展"
D.Strings[115190]="DEBUG事件送出 - 北 - 聯盟進展"
D.Strings[115191]="DEBUG事件送出 - 北 - 部落受阻"
D.Strings[115192]="DEBUG事件送出 - 北 - 聯盟受阻"
D.Strings[115193]="DEBUG事件送出 - 北 - 部落中立"
D.Strings[115194]="DEBUG事件送出 - 北 - 聯盟中立"
D.Strings[115195]="DEBUG事件送出 - 北 - 聯盟獲勝"
D.Strings[115196]="DEBUG事件送出 - 北 - 部落獲勝"
D.Strings[115197]="我想要回去再看一遍其中某個影像。那把魔法刃還在你身上嗎？"
D.Strings[115198]="那隻怪物正在從恐怖圖騰的先祖們那裡吸收力量！我們一定要讓他們安息，才有辦法擊敗這隻怪獸！"
D.Strings[115199]="呣嚕咕嚕咕嚕？"
D.Strings[115200]="呣嚕咕，呣嚕咕嚕咕嚕咕咕！"
D.Strings[115201]="呃啊啊啊啊啊！"
D.Strings[115202]="還不錯。"
D.Strings[115203]="戰鬥吧！"
D.Strings[115204]="我要在那頭龍的臉上狠狠揍一拳！"
D.Strings[115205]="市民們，請有點耐性。對著我們大吼大叫是無法改變現狀的。"
D.Strings[115206]="檢查完畢，你可以走了。"
D.Strings[115207]="那是教徒的衣服。守衛!"
D.Strings[115208]="這看起來有點可疑，我不能放你進去。"
D.Strings[115209]="風與水之先祖啊，我已經為你們鋪好了道路，前來將暴風城夷為平地吧!"
D.Strings[115210]="看守銀行和部落的財寶遠比躲在鐵籠裡收發錢幣和物品來得有意義多了。$B$B我一點也不想跟那些成天拿筆算錢記帳的哥布林交換工作。"
D.Strings[115211]="他要你幫他做什麼？"
D.Strings[115212]="(聽不懂的胡言亂語)"
D.Strings[115213]="嘿，你有沒有看到格羅—格羅？獸人，大概這麼高。沒看到？$B$B嗯。大家好像都一陣子沒看到他了。八成是私自跑走了。"
D.Strings[115214]="我們可以就這樣繼續一直打下去。但是你究竟想要什麼？"
D.Strings[115215]="嚇噢！"
D.Strings[115216]="我猜你現在已經聽說過那個洞了，$r。如果還沒有，你很快就會聽到一大堆關於它的事情。"
D.Strings[115217]="淤泥農場 - 首領表情"
D.Strings[115218]="翻找中"
D.Strings[115219]="謝謝你救了我，$g小伙子:小姑娘;。我預見了一個恐怖的景象。我被困在一個充滿火焰的山洞，被迫要插圖騰，治療怒氣衝天的戰士，最後還看不到半件薩滿用的裝備。"
D.Strings[115220]="噢噢!!!"
D.Strings[115221]="伊拿斯庫里格姆嘎哈格姆拉。"
D.Strings[115222]="你已經輸了。"
D.Strings[115223]="有聽說戈特·哄誘是怎麼把他上個助理炒魷魚的嗎...直接推下山谷!所以最好別激起他的黑暗面。"
D.Strings[115224]="你干擾了古拉巴什的計畫，小傢伙。來不及了。你們全都來不及了!"
D.Strings[115225]="聖光與你同在。"
D.Strings[115226]="姆嗚啊啊啊啊!"
D.Strings[115227]="姆嗚啊啊啊啊啊!"
D.Strings[115228]="呣呣咈呣咈咈咈。咈呣。"
D.Strings[115229]="檢視這件物品。"
D.Strings[115230]="你抓不到我!"
D.Strings[115231]="聰明的決定。我自己也會這樣選。"
D.Strings[115232]="嘎啊啊啊!"
D.Strings[115233]="看看他的力量!"
D.Strings[115234]="火之國度將吞噬你們!"
D.Strings[115235]="<拿起寶珠並用力搖晃。>"
D.Strings[115236]="誰有修理機器人?"
D.Strings[115237]="呃..."
D.Strings[115238]="歡迎來到暗月馬戲團，$c！"
D.Strings[115239]="精靈貴族已然歸來，並且帶回了失傳百千年之久的魔法技藝。$B$B你有東西要我查驗嗎?"
D.Strings[115240]="唉，真沒意思。"
D.Strings[115241]="首先，你先給我一個遊戲代幣。然後，我會給你一把錘子。你會看到豺狼人從遊戲區的桶子裡冒出來。$B$B用錘子打中豺狼人，你就會獲得分數。$b$b要特別注意的是，桶子會出現三種目標：普通豺狼人、大豺狼人，還有寶寶。$b$b普通豺狼人能獲得一分，大豺狼人算三分。至於寶寶？打中寶寶會害你摔跤暈倒…所以千萬不要動手打寶寶！$b$b如果你時間內無法打到夠多的豺狼人，只要多花個代幣就好了！因為你累積的點數是可以沿用到下一場遊戲的。"
D.Strings[115242]="讓我聽聽剩下的部份，吉爾妮探員。"
D.Strings[115243]="測試P1。開始第一波!"
D.Strings[115244]="測試P1。開始第二波!"
D.Strings[115245]="測試P1。猴人開始逃命了!"
D.Strings[115246]="測試P2。第三波來了!"
D.Strings[115247]="測試P2。錦魚人來了!"
D.Strings[115248]="[暫用]救救我兄弟"
D.Strings[115249]="[暫用]你成功了伙計"
D.Strings[115250]="你聽見了嗎？他們在某處，平安無事！"
D.Strings[115251]="如你所願，指揮官。"
D.Strings[115252]="未使用"
D.Strings[115253]="暗影披風消失!PH"
D.Strings[115254]="他們對我們開火了，長官!"
D.Strings[115255]="什麼?那是...陸地?"
D.Strings[115256]="盡可能用力打我！"
D.Strings[115257]="掰掰。"
D.Strings[115258]="我們可以走了嗎?你啤酒喝夠了沒?"
D.Strings[115259]="快了。"
D.Strings[115260]="(這裡要放進超棒的完成事件，霍重新開始燃燒，然後使用某種非文字的方式來表達感謝 。)"
D.Strings[115261]="(寺廟火盆重新點燃並取得成就時的精采完成事件。)"
D.Strings[115262]="(完成事件:牛車試著翻滾烏果，繩子斷裂，烏果繼續打鼾沒有醒來。)"
D.Strings[115263]="(事件:舒把一顆大水球砸到烏果頭上，烏果醒過來，開始滿鎮追著舒跑。)"
D.Strings[115264]="(事件:尚羲大師向你講述神真子和與他談話的方法，然後插下他的手杖撒手塵寰。)"
D.Strings[115265]="接住！"
D.Strings[115266]="看看這個!"
D.Strings[115267]="又來了?!"
D.Strings[115268]="[這條線已被切斷]"
D.Strings[115269]="我會盡我所能淨化腐化的力量，我的火焰不會傷害到你。"
D.Strings[115270]="[動畫待確認]艾莎衝向船，卻只看到紀正往船外跑，逃離即將到來的爆炸。"
D.Strings[115271]="[動畫待確認]紀擁著艾莎往後跑，以免她受爆炸傷害。她掙扎著喊叫，惟恐神真子受到無法治癒的傷害，並憤怒於紀沒有詢問她便做出如此倉促的決定。"
D.Strings[115272]="[動畫待確認]船劇烈地炸開了。紀和艾莎被爆風吹飛到遠處的地面，但並沒有受傷。"
D.Strings[115273]="[動畫待確認]兩人站起身來看著原本插著船骸的空洞。一條血河從神真子的身上噴發出來。"
D.Strings[115274]="沒用!"
D.Strings[115275]="滾吧。"
D.Strings[115276]="幫幫忙!我的蛋掉了!"
D.Strings[115277]="魔古選了最糟的時機來攻擊。螳螂人們行動了，即使是巨大的長城也無法使他們停下來。"
D.Strings[115278]="歐克!"
D.Strings[115279]="弓箭手，放箭!"
D.Strings[115280]="老丘爪的得獎名雞，咯雞媽媽!"
D.Strings[115281]="用力搖晃你的屁屁!"
D.Strings[115282]="誰膽敢打擾我?現出你懦弱的面孔，跪在我的面前!"
D.Strings[115283]="啊哈哈哈!真是個可憐的東西!"
D.Strings[115284]="該死的怪怪人!給我回來!"
D.Strings[115285]="咕嚕摩有好鼻子。可以用氣味分辨幸運星和倒楣運。你聞起來是幸運星。"
D.Strings[115286]="恐懼於你自身的毀滅吧!"
D.Strings[115287]="乘坐熱氣球離開神真子前往暴風城的影片。"
D.Strings[115288]="乘坐熱氣球離開神真子前往奧格瑪的影片。"
D.Strings[115289]="[PH]這只是幻覺，別煩我。"
D.Strings[115290]="圖洛，馮，庫洛斯!"
D.Strings[115291]="卡利馬斯!"
D.Strings[115292]="苟庫拉!"
D.Strings[115293]="洛庫。"
D.Strings[115294]="準備好...開打!"
D.Strings[115295]="我要開始做炸彈!PH"
D.Strings[115296]="你那把武器是跟誰拿的，你姊姊嗎?"
D.Strings[115297]="畏懼我吧!"
D.Strings[115298]="你準備好了嗎?"
D.Strings[115299]="我們必須找出原因。沒有影潘，潘達利亞一定會被黑暗吞沒..."
D.Strings[115300]="再見。"
D.Strings[115301]="看起來我得親自動手。那就來吧！"
D.Strings[115302]="你能在寵物對戰中贏過我嗎?來戰鬥吧!"
D.Strings[115303]="綠隊達成一個擊殺。"
D.Strings[115304]="黃隊達成一個擊殺。"
D.Strings[115305]="時間到。競技場的戰鬥結束了!"
D.Strings[115306]="暴風之眼的戰鬥即將開始。"
D.Strings[115307]="怎麼說?"
D.Strings[115308]="有四尊聖獸天尊統治著這片土地。$B$B『玉蛟』玉龍，東方的生命賜予者。$B$B『紅鶴』赤吉，南方的希望。$B$B『白虎』雪怒，以其力量鎮守著北方。$B$B『玄牛』怒兆，屹立於西方。$B$B最近隨著煞的進逼，祂們的神殿都被捲入了混亂之中。祂們需要我們的幫助，$r。"
D.Strings[115309]="自從舊王國的黑暗時代開始，我們熊貓人就藉助於釀酒的神秘技巧來保持我們高昂的精神和力量。$B$B就算在我們交談的同時，釀酒大師們也正在世界各地遊蕩，尋覓稀有且強力的材料來釀造最好的酒。$B$B那些能找出這些難以捉摸的釀酒大師並給予他們幫助之人，可以獲得充滿風味的物品。最少最少，你會喝到很多的酒!"
D.Strings[115310]="我們就知道你做得到!"
D.Strings[115311]="我不知道，$r。這株大蔬菜看起來不對勁。他們怎麼能若無其事地只吃菜?他們的肉都到哪去了?"
D.Strings[115312]="哇啊嘎吧!!!"
D.Strings[115313]="從仰加印古的邪惡猴人海盜手中取回叢林啤酒。"
D.Strings[115314]="赤吉照管著南方的紅鶴寺。$B$B她正試著要從煞爆發後導致的混亂中重整秩序。$B$B如果你想要幫助她，前往位於喀撒朗蠻荒的赤吉搖籃。"
D.Strings[115315]="影潘是個古老的組織，只接受與訓練最好的菁英。$B$B如果你能設法讓自己派上用場，你會發現自己有資格取得許多強大的物品。"
D.Strings[115316]="博學行者在這世界中旅行，尋找新的傳說並傳承舊有的歷史。$B$B我們探訪潘達利亞中各地人文的豐富歷史。$B$B如果你想要聽這些故事，前往位在恆春谷，魔古山宮入口之上的知識之座和博學行者阿洲談談。"
D.Strings[115317]="我不知道，$r。$B$B我們對卡拉西所知是少之又少。他們似乎相當殘忍，所以或許你的唯一獎賞會是痛快地死去。$B$B但話又說回來，他們的文明相當龐大且先進。如果你能成功和他們協商，或許他們會給予你未知的力量。$B$B只有一個方法可以查明。"
D.Strings[115318]="鐵匠們全都在工匠大廳裡做事，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。"
D.Strings[115319]="[%s]坦承:我沒有公平對待我的所有坐騎。"
D.Strings[115320]="愚蠢的小孩。"
D.Strings[115321]="最好不要玩弄還沒徹底理解的秘密。也許你應該關閉那個抑制裝置。我的同伴和我可以照顧好自己，我們會沒事的。"
D.Strings[115322]="堅持住，殺光剩下的活口!"
D.Strings[115323]="在翠玉林的綠石採石場有採礦大師。他們應該能幫你增進技能。我會替你在地圖上標記出來。"
D.Strings[115324]="桑·紅鱗是雲蛟衛的軍需官。$B$B你可以在翠玉林的落英園找到他。$B$B我會替你在地圖上標記出位置。"
D.Strings[115325]="顫抖吧！"
D.Strings[115326]="<蛟寶寶對你微笑。>"
D.Strings[115327]="我想要挑戰你。"
D.Strings[115328]="喀-喀-喀-喀-喀啦！"
D.Strings[115329]="放輕鬆點，好嗎?"
D.Strings[115330]="就是那樣！"
D.Strings[115331]="很好。我們戰鬥吧。"
D.Strings[115332]="主人會很高興的。"
D.Strings[115333]="土歸土。"
