D.Strings[115335]="現在進入競技場的，你們都認識$g他:她;，你們都愛$g他:她;。掌聲歡迎第8階的鬥士$N!!"
D.Strings[115336]="[PH]那些薩烏洛克在守護洞穴。我們來對付它們。"
D.Strings[115337]="潘達利亞是我們的！"
D.Strings[115338]="發生什麼事？它醒過來了！"
D.Strings[115339]="你已經證明自己是個超卓非凡的英雄。掌握命運的勇士。"
D.Strings[115340]="我聽到好多吼叫聲 - 發生了什麼事情?"
D.Strings[115341]="帶我去帝王谷。"
D.Strings[115342]="我會掩護你。"
D.Strings[115343]="在熊貓人工地使用不該出現的酒桶以永久加快該處的進展速度！$B$B|TInterface\\Icons\\INV_CASK_04.blp:64|t"
D.Strings[115344]="別忘了設定你的世界狀態地區!"
D.Strings[115345]="這就是雷王的副本!"
D.Strings[115346]="我喜歡你的風格，英雄。"
D.Strings[115347]="動作要快啊！"
D.Strings[115348]="遊俠們!守好熔爐。攻破大門，讓它再也關不了!"
D.Strings[115349]="做得好!我們可以通過了。大家不要走散。保住我們的優勢!"
D.Strings[115350]="我連怎樣釣魚都不會！可以教教我嗎？"
D.Strings[115351]="聯盟的傢伙也在這兒！"
D.Strings[115352]="向敵人進攻！"
D.Strings[115353]="哈托克，鐵狼之子！我來取你的人頭了。"
D.Strings[115354]="去找倫妲。\n\n她通常就在軍營入口的北邊。"
D.Strings[115355]="當你靠近水晶時，你能感覺到它強大的能量。附近的一些精魂狐疑地朝你的方向看來。"
D.Strings[115356]="走這邊。"
D.Strings[115357]="點燃引信…"
D.Strings[115358]="我的部隊全聽您號令，吾王。"
D.Strings[115359]="磨折盡受會你！"
D.Strings[115360]="沒有人會來救你。"
D.Strings[115361]="卡德加，我們來看看迦羅娜攻擊的時候究竟發生了什麼事吧。"
D.Strings[115362]="我為火焰而活！"
D.Strings[115363]="波瑞拉米爾。"
D.Strings[115364]="貝拉許。"
D.Strings[115365]="艾弗拉許。"
D.Strings[115366]="阿列那米爾。"
D.Strings[115367]="Anu'dora! (為了真理！)"
D.Strings[115368]="你看到了嗎？他差點把我的頭給砍了！"
D.Strings[115369]="你該去找沙沙比，伙計。$B$B她在精神谷，通常在漁夫老昂貝托旁邊的樹下睡覺，像一隻大老虎。"
D.Strings[115370]="|TInterface\\Icons\\inv_boots_cloth_31v3.blp:32|t\n卡拉給予你祝福。加速和奔跑速度提高。"
D.Strings[115371]="你看起來好像迷路了，外地人！你來這裡做什麼？"
D.Strings[115372]="帶領商隊前往[管道營地]。"
D.Strings[115373]="被大地粉碎！"
D.Strings[115374]="在找杜格魯‧血怒嗎？他在兵營後面練習法術。"
D.Strings[115375]="倫妲就是你要找的人。\n\n她就在兵營入口的北方。"
D.Strings[115376]="鋼鐵部落的人跟著我們到這裡來了！我們該怎麼辦？"
D.Strings[115377]="開心果莎璐，你的歡笑會在神殿中迴蕩，繞梁不息。現在，就為眾靈帶去歡笑吧。"
D.Strings[115378]="雷克納使錘的功夫和他拿畫筆的技巧一樣厲害。願你的靈魂得到安息。"
D.Strings[115379]="這是…？"
D.Strings[115380]="為了霜狼！"
D.Strings[115381]="怒靈掙脫束縛了！"
D.Strings[115382]="你做了錯誤的選擇！"
D.Strings[115383]="大家都沒事吧？"
D.Strings[115384]="有沒有搞錯啊？！"
D.Strings[115385]="快去接！"
D.Strings[115386]="要是這棟建築被燒了，你也逃不了！快點！"
D.Strings[115387]="|TINTERFACE\\ICONS\\ability_socererking_arcanewrath.blp:20|t你被|cFFF00000|Hspell:156238|h[秘法懲戒]|h|r烙印了！"
D.Strings[115388]="話語和事物"
D.Strings[115389]="你為什麼要褻瀆我們的神聖魔法？"
D.Strings[115390]="聽候您的差遣，指揮官。"
D.Strings[115391]="一切榮耀歸於戰歌氏族。一切榮耀歸於新的領袖，卡爾洛斯·地獄吼！"
D.Strings[115392]="夠了。遊戲時間結束，我來親自對付你。"
D.Strings[115393]="我是你臨時的追隨者。開戰了，$N！"
D.Strings[115394]="我是你假裝的追隨者。走吧，我會跟著你。"
D.Strings[115395]="黑手酋長"
D.Strings[115396]="外面那裡一團亂！"
D.Strings[115397]="那個混蛋逃脫了！"
D.Strings[115398]="主人！我來找你了！"
D.Strings[115399]="滾出去！"
D.Strings[115400]="再敲幾下就好了。"
D.Strings[115401]="我們得先解決那隻怪物才能接近卡爾洛斯。"
