D.Strings[115403]="我的刀刃渴望復仇！"
D.Strings[115404]="歐古姆‧卓爾‧昂德羅‧杜卡爾。"
D.Strings[115405]="莫勾克‧杜姆‧阿格爾！"
D.Strings[115406]="遵命，船長！這是我的榮幸。"
