D.Strings[115409]="祝你下次好運。"
D.Strings[115410]="嘗嘗烈日的怒火！"
D.Strings[115411]="Anu belore dela'na. (願永恆的太陽指引我們。)"
D.Strings[115412]="(達納蘇斯語) Andu fallah。"
D.Strings[115413]="真是好險！"
D.Strings[115414]="我會讓你死得俐落一點。"
D.Strings[115415]="我會回來的…"
D.Strings[115416]="(獸人語) Throm-Ka，$n。"
D.Strings[115417]="Dioniss aca. (一路平安。)"
D.Strings[115418]="乾淨俐落。"
D.Strings[115419]="你會知道什麼叫痛苦。"
D.Strings[115420]="部落的間諜趁亂闖進了要塞！"
D.Strings[115421]="勝利在望。"
D.Strings[115422]="我是巴希歐克。"
D.Strings[115423]="拯救中"
