D.Strings[115442]="(惡魔語)你就受盡折磨而死吧！"
D.Strings[115443]="(惡魔語)愛管閒事的鼠輩！"
D.Strings[115444]="休息時間！"
D.Strings[115445]="加里維克斯的修理廠是哥布林區最大的建築物，那裡擁有相當齊全的工程學設備。\n\n到那裡找漢恩‧躍箭接受工程學訓練。"
