D.Strings[115450]="難以置信…"
D.Strings[115451]="(惡魔語)可悲的小蟲！"
D.Strings[115452]="Akim-kurai! (你逃不掉的！)"
D.Strings[115453]="里克阿馬納拉，苟拉米旬，阿密爾胥！"
D.Strings[115454]="淹沒！"
D.Strings[115455]="想建造船艦嗎？"
D.Strings[115456]="你死期到了！"
D.Strings[115457]="古爾丹的力量每分每秒都在壯大。不過他再也躲不了了。我們已經知道他人在哪裡，知道他在弄什麼把戲。進攻的時機到了！願聖光護佑我們的靈魂。"
D.Strings[115458]="他們來了。快！古爾丹命令我們一定要完成…"
D.Strings[115459]="Sul'dren il nathas! (納薩拉斯不滅！)"
D.Strings[115460]="惡魔答應給我們無窮的力量。"
D.Strings[115461]="瑟雅娜和一個叫寇達娜的看守者往西南邊去了。"
D.Strings[115462]="Ish valah, wynn talos... (封鎖此地的印記，聽我指示…)"
D.Strings[115463]="Sarim! (開！)"
D.Strings[115464]="我會讓你陷入永恆的長眠。"
D.Strings[115465]="守夜者，注意！親王需要我們的協助！"
D.Strings[115466]="拜託…幫幫我…"
