D.Strings[115480]="貝藍…"
D.Strings[115481]="魯卡達瑞…"
D.Strings[115482]="提卡拉彌…"
D.Strings[115483]="費尼…"
D.Strings[115484]="馬耶茲！"
D.Strings[115485]="帕努斯…"
D.Strings[115486]="瑪拉達斯！"
D.Strings[115487]="喀嘎！"
D.Strings[115488]="村莊…是我們的…"
D.Strings[115489]="死亡無法…阻止我們…"
D.Strings[115490]="你的世界…注定毀滅…"
D.Strings[115491]="我在想，夜精靈會不會為你哀悼呢？"
D.Strings[115492]="你無法阻止將到來的黑暗。連在夢中也不行。"
D.Strings[115493]="來點樂子…大聲呼救吧！"
D.Strings[115494]="瘋狂在呼喚我…"
D.Strings[115495]="幹嘛認真打啊…？"
D.Strings[115496]="黑暗…逼近…"
D.Strings[115497]="提里奧在哪？"
D.Strings[115498]="我們無法阻止他們…"
D.Strings[115499]="你的靈魂是我們的。"
D.Strings[115500]="這只夠稍微緩和我的渴望…但我還是很感謝你。"
D.Strings[115501]="戰鬥！為我報仇！"
D.Strings[115502]="她應該跑到這裡了。繼續找！"
D.Strings[115503]="最讓人吃驚、最空前絕後的…"
D.Strings[115504]="呣嚕咕嚕咕嚕！"
D.Strings[115505]="Erath-omnas! (堅守陣地！)"
D.Strings[115506]="呣嚕嚕嚕咕！咕嚕咕！"
D.Strings[115507]="呣呣咕？呣咕咕咕。"
D.Strings[115508]="呣嚕咕嚕咕嚕咕嚕！"
D.Strings[115509]="呣咕？呣嚕咕嚕咕嚕！呣嚕！"
D.Strings[115510]="呣嚕咕嚕咕嚕。呣嚕咕嚕？呣咕！"
D.Strings[115511]="每吸收一個靈魂，我的力量就更加強大。我會征服這個世界…所有世界！"
D.Strings[115512]="你的死期到了！"
D.Strings[115513]="Anath'ashar! (為榮耀而戰！)"
D.Strings[115514]="Lok'tar... ogar... (不勝…即亡…)"
D.Strings[115515]="團結一心，高嶺永存！"
D.Strings[115516]="呣嚕，咕嚕咕嚕。嗝嚕咕嚕咕嚕咕！呣嚕。"
D.Strings[115517]="呣嚕咕嚕咕嚕。呣呣呣嚕！"
D.Strings[115518]="咕呣嚕呣嚕？呣嚕。嚕！"
D.Strings[115519]="呣嚕咕嚕！咕呣。呣咕呣咕。"
D.Strings[115520]="莫咕嚕。呣嚕咕嚕咕嚕，哺勒咕啊咕，啊嗚嚕咕嚕！呣，呣嚕咕嚕。啊咕嚕咕嚕，嗝哺嚕。\n\n呣嚕咕嚕，咕呣嚕。呣嚕？咯莫呣嚕！"
D.Strings[115521]="Alar il raka Azoran il zennrakkan oth kamilgolad! Morgul... morgul! (我會告訴你阿佐朗大人在哪裡！饒了我吧…手下留情！)"
D.Strings[115522]="賽維斯，我需要犧牲你來為傳送門充能。"
D.Strings[115523]="%s點頭贊同。"
D.Strings[115524]="我想再看看我們能取得哪些武器。"
D.Strings[115525]="是，我準備好了。趕快加緊腳步吧，我很擔心敵人會發現我們。"
D.Strings[115526]="我不懂。這不是城裡。這裡是…"
D.Strings[115527]="Arash-falas... (平復傷痛…)"
D.Strings[115528]="Tor'theras falar！(讓敵人畏懼吧！)"
D.Strings[115529]="咕嗯…嗯嗯嗯…"
D.Strings[115530]="嚕嗚嗯嗯！"
D.Strings[115531]="姆嗯姆嗯。"
D.Strings[115532]="嗚嚕嚕嗯。"
D.Strings[115533]="看來我…低估你們了。"
D.Strings[115534]="我被…擊敗了…"
D.Strings[115535]="拉卡尼休！"
D.Strings[115536]="伊克尼卡！"
D.Strings[115537]="拉比塔卡！"
D.Strings[115538]="(吼叫聲)"
D.Strings[115539]="可惜你們辛苦來到這裡，就為了死在薩維斯手上！"
D.Strings[115540]="黑騎兵在側翼！準備！"
D.Strings[115541]="Sia'la yemil! (骯髒的東西！)"
D.Strings[115542]="阿奇斯，諾曼諾斯！"
D.Strings[115543]="加，諾塔萊許，達，伐…"
D.Strings[115544]="基瑞斯 - 阿拉克，約索，諾魯許…"
D.Strings[115545]="N'eth ana! (解除！)"
D.Strings[115546]="An'ratha... an'tal-thandros! (月井的榮耀不滅！)"
D.Strings[115547]="看看他們…他們根本不能算是人。我不要變成那個樣子。我們要趕快找到艾斯托里。快清出一條路！"
D.Strings[115548]="Irlik raka glab markzan! (我會逮住你！)"
D.Strings[115549]="莫咕嚕咕咕咕嚕！"
D.Strings[115550]="呣嚕咕嚕咕嚕！呣嚕咕嚕咕嚕！"
D.Strings[115551]="我們必須擋住他們！"
D.Strings[115552]="沒人能阻止我！"
D.Strings[115553]="莫咕嘎嚕嘎咕！"
D.Strings[115554]="莫嘎咕莫嘎莫咕！"
D.Strings[115555]="誰在那裡？"
D.Strings[115556]="Sk'shuul agth vorzz N'Zoth naggwa'fssh! (你們的死象徵著恩若司無盡的榮耀！)"
D.Strings[115557]="Sk'yahf agth huqth N'Zoth qornaus... (你們的靈魂將平息恩若司無盡的饑渴…)"
D.Strings[115558]="魚人的訓練非常順利！"
D.Strings[115559]="謝謝你！那些熊真的很不聽話！"
D.Strings[115560]="她說你有關於遠古武器的消息。"
D.Strings[115561]="燒盡一切！"
D.Strings[115562]="已移除。"
D.Strings[115563]="咕哺咯嚕，哇嗚咕哺咯。"
D.Strings[115564]="哺嘞。"
D.Strings[115565]="哇咕！咧咕！"
D.Strings[115566]="Reesh Archim, galar. (煉獄將吞噬你，廢物。)"
D.Strings[115567]="Kirel volosh！(受死吧！)"
D.Strings[115568]="Ered'achor, shudas'urzul... kurai. (惡魔語咒語。)"
D.Strings[115569]="Azhir manari kirel. Akim manari galar! (惡魔咒語)"
D.Strings[115570]="痛苦這個名字很適合你的第一招攻擊技能。"
D.Strings[115571]="我不會再聽信你的詭計！你會破壞父親的心血！"
D.Strings[115572]="我不會失敗的，主人！力量…再給我更多力量…"
D.Strings[115573]="從手中發射閃電，是你對付敵人的主要武器。"
D.Strings[115574]="An'anora! (為了族人！)"
D.Strings[115575]="你的世界將被燒毀！"
D.Strings[115576]="你的虛無行者死了。使用召喚虛無行者把它叫回來。"
D.Strings[115577]="痛苦動盪會持續造成傷害，而且每次施展都會讓它變強！所以你應該盡可能使用這個法術攻擊！"
D.Strings[115578]="雖然無法長時間控制煉獄火跟末日守衛之類的強大惡魔，但你可以召喚一隻在短時間內為你作戰。"
D.Strings[115579]="使用召喚末日守衛，把這隻惡魔叫出來。"
D.Strings[115580]="使用你的衝鋒技能，縮短你與假人的距離。"
D.Strings[115581]="解決一個敵人，你就能對下一個敵人使用勝利衝擊。"
D.Strings[115582]="你的對手可能會想以多欺少包圍你，但是他們低估了你真正的實力！"
D.Strings[115583]="在激烈的戰鬥中，你有時必須迅速遠離危險…或是立即貼近敵人！"
D.Strings[115584]="練習使用英勇躍擊。"
D.Strings[115585]="布勒格！"
D.Strings[115586]="布勒格？"
D.Strings[115587]="真言術：盾使你不受法師第一次攻擊的傷害，但第二次讓你受傷了。"
D.Strings[115588]="以虎掌開戰，可以讓你有足夠的真氣使用強大的翔陽腳。這個技能會消耗2點真氣，並造成可觀的傷害。"
D.Strings[115589]="召喚你的寵物！"
D.Strings[115590]="你的寵物受傷了！使用治療寵物！"
D.Strings[115591]="對假人施展閃電箭，直到你的元能全滿，然後施展大地震擊。"
D.Strings[115592]="承受傷害是戰鬥的一部分，但身為武僧，你可以運用迷霧來治療自己或是盟友。使用流洩技能來治療你的傷口。"
D.Strings[115593]="使用流洩來完全恢復你的生命力。"
D.Strings[115594]="使用流洩來治療自己！"
D.Strings[115595]="展現你的靈巧與殘暴吧！"
D.Strings[115596]="身為野性德魯伊，變形就是你的優勢。在獵豹形態下，你的獸牙與利爪會讓對手流血不止。"
D.Strings[115597]="你的撕碎和掃擊技能會產生連擊點數，連擊點數可以提高終結技的威力。"
D.Strings[115598]="盡量先讓目標受到膿瘡傷口影響，然後才使用天譴打擊。"
D.Strings[115599]="死亡之握可以在相當遠的距離外使用。試著遠離目標使用看看。"
D.Strings[115600]="掌控了召喚死亡的力量，你就不用怕敵人以多欺少了。"
D.Strings[115601]="使用亡靈大軍，召喚你的手下。"
D.Strings[115602]="如果在戰鬥中受到過多的傷害，可以用死亡打擊來扳回劣勢。"
D.Strings[115603]="對目標使用死亡打擊能恢復你的生命力。"
D.Strings[115604]="你的僕從死了。施展死者復生來召喚一個新的僕從。"
D.Strings[115605]="對假人使用寒冰箭直到觸發冰霜之指，在冰霜之指效果存在時使用冰霜長矛。"
D.Strings[115606]="如果能把敵人定住，讓他們無法靠近你，那該有多棒啊？"
D.Strings[115607]="使用寒冰護體來降低受到的傷害。"
D.Strings[115608]="你的武器燃起烈焰後，就可以專注在主要攻擊上了。"
D.Strings[115609]="身為平衡德魯伊，太陽、月亮跟星星都是你的盟友，幫助你對敵人釋放原始的力量。"
D.Strings[115610]="使用梟獸形態，變成梟獸。"
D.Strings[115611]="團結力量大。"
D.Strings[115612]="呃啊啊…"
D.Strings[115613]="不要吃我！"
D.Strings[115614]="艾莉珊德在想什麼，居然放他們進來？"
D.Strings[115615]="Anaria shola. (有話快說)"
D.Strings[115616]="Al diel shala. (旅途平安。)"
D.Strings[115617]="任務還沒完成。"
D.Strings[115618]="小心點，別弄壞！"
D.Strings[115619]="開回來的時候要完好如初！"
D.Strings[115620]="外面的人小心啦！"
D.Strings[115621]="真是脆弱的生物。你們的末日就在眼前！"
D.Strings[115622]="讓我來見識見識你強大的力量！"
D.Strings[115623]="對你的武器使用致命毒藥。"
D.Strings[115624]="記得使用絞喉，讓你的敵人不斷流血。"
D.Strings[115625]="城市裡的居民…"
D.Strings[115626]="心裡充滿憐憫…"
D.Strings[115627]="天啟就要來臨。"
D.Strings[115628]="不公平，我都沒當過大博學者！"
D.Strings[115629]="爸媽說我太小了，不可以喝秘能酒。"
D.Strings[115630]="這是什麼？有人躲在這裡嗎？"
D.Strings[115631]="別來煩我！"
D.Strings[115632]="Ered'nash ila mornu nakuun. Ered'nash ban man'ari! (惡魔咒語。)"
D.Strings[115633]="打得好，英雄。"
D.Strings[115634]="咕莫咕咕！莫莫咕莫莫咕啊。莫咕咕莫啊？"
D.Strings[115635]="莫咕莫咕莫莫。咕啊莫咕莫莫咕莫咕！莫莫啊咕莫咕咕莫莫咕。莫咕莫莫咕莫咕咕啊莫咕咕？"
D.Strings[115636]="莫咕，啊莫咕莫莫咕…"
D.Strings[115637]="咕呣咕呣！咕嚕咕嚕莫咕啊。"
D.Strings[115638]="呣咕啊。莫嚕咕咕莫嚕啊呣咕咕？"
D.Strings[115639]="莫嚕咕呣啊！咕咕嚕咕莫莫！呣咕嚕莫咕莫莫啊！呣咕莫咕！"
D.Strings[115640]="莫莫咕！莫啊莫咕莫咕…"
D.Strings[115641]="咕莫啊！莫莫咕…莫咕莫咕咕！莫咕咕莫咕咕！"
D.Strings[115642]="莫咕。莫啊咕。"
D.Strings[115643]="莫咕！莫咕莫，莫咕啊莫咕莫啊咕莫咕。"
D.Strings[115644]="莫莫啊咕！咕啊莫，咕莫啊莫咕啊莫咕咕啊咕。"
D.Strings[115645]="咕莫莫咕呣？咕莫嚕莫啊呣咕！"
D.Strings[115646]="呣咕。呣咕莫嚕咕咕！"
D.Strings[115647]="咕呣嚕呣…呣古嚕莫，呣古嚕咯，呣呣咕。呣古嚕…"
D.Strings[115648]="咕呣咕嚕！咕莫莫咕呣咕啊？呣咕嚕？咕莫莫？！"
D.Strings[115649]="莫咕呣咕。呣咕莫啊咕莫咕咕嚕？莫咕咕呣咕嚕莫莫咕咕。"
D.Strings[115650]="莫咕莫咕啊！咕莫咕莫咕啊啊咕啊莫莫！"
D.Strings[115651]="咕咕莫莫！咕莫莫咕莫莫啊！"
D.Strings[115652]="莫咕莫莫咕莫咕。莫莫啊咕莫！"
D.Strings[115653]="呣咕呣嚕，莫咕嚕咕咕莫莫嚕莫咕？"
D.Strings[115654]="呣嚕嚕！咕莫咕莫呣莫咕嚕莫莫啊。嚕莫咕？"
D.Strings[115655]="你這滿屁股藤壺的懶鬼，我希望你拿到船長的黑紙條！"
D.Strings[115656]="莫咕莫咕莫咕咕莫啊咕咕？！"
D.Strings[115657]="莫莫咕莫咕莫莫咕莫咕咕啊莫咕！"
D.Strings[115658]="你聽到甲殼腳爪在黑暗中悉窣的聲音…"
D.Strings[115659]="提洛斯，傳送回馬爾頓。"
D.Strings[115660]="敬宗師一杯！"
D.Strings[115661]="Ash'thoras denil. (克服困難。)"
D.Strings[115662]="Ishnu-alah! (祝你好運！)"
D.Strings[115663]="Tenu'balah. (你好。)"
D.Strings[115664]="你不是夜裔，你是怪異。"
D.Strings[115665]="Kal'theros maldin. (我們是受選者之子。)"
D.Strings[115666]="Nor'bethos Suramar. (為了蘇拉瑪爾的未來。)"
D.Strings[115667]="我們永不屈服。"
D.Strings[115668]="我們的命運即將揭曉。"
D.Strings[115669]="你想做什麼？"
D.Strings[115670]="我們的時代來臨了。"
D.Strings[115671]="嘿，我們之中至少要有一個成熟的人。"
D.Strings[115672]="看來我比你還要成熟！"
D.Strings[115673]="換句話說，再煩我，我隨時可以把你烤焦。"
D.Strings[115674]="Andu Falah'dor！(願自然恢復平衡！)"
D.Strings[115675]="我從巡邏隊員那邊買到了這個。他說這叫「自拍相機」。你知道怎麼用嗎？"
D.Strings[115676]="你無法…抵抗…"
D.Strings[115677]="我會把你的頭親自獻給古爾丹。"
D.Strings[115678]="你的靈魂會永遠服侍我們！"
D.Strings[115679]="有了你為我們收集到的資源，我們終於能喚醒這對古代戰刃全部的力量了！"
D.Strings[115680]="亡靈大軍會召喚出一群食屍鬼，攻擊你周圍的所有敵人。"
D.Strings[115681]="面對冰凍的目標，冰霜長矛才能發揮真正潛力，讓傷害大幅提升。"
D.Strings[115682]="糾纏根鬚會讓植物根部從地面鑽出，將目標固定在原地一段時間。"
D.Strings[115683]="兇猛撕咬是終結技，當你有越多連擊點數，就能造成越高的傷害。"
D.Strings[115684]="有5點連擊點數之後，再用這招。"
D.Strings[115685]="有忠實的寵物在身邊，你就能克服任何環境阻礙。召喚寵物可以把寵物呼喚到你身邊。"
D.Strings[115686]="當你快打輸時，可以用假死來欺騙敵人，讓他們以為你不會再造成威脅。"
D.Strings[115687]="如果你已經用過割裂，那消耗5個連擊點數使用毒化，可以造成不錯的傷害，還可以強化毒藥的效果。"
D.Strings[115688]="有時候，你要懂得看情況撤退。留得青山在，不怕沒柴燒。"
D.Strings[115689]="懺悟是個強大的法術，可以對敵人造成傷害。你要盡可能地使用它。"
D.Strings[115690]="生命分流會用你自己的生命力來補充法力。別擔心，你可以從敵人身上把生命力再吸回來。"
D.Strings[115691]="不過你沒辦法攻擊遠方的敵人。還好有個技能可以解決這問題。"
D.Strings[115692]="Rath, anu'telar! (這，是為了生存！)"
D.Strings[115693]="Aran'arcana. (讚美秘法。)"
D.Strings[115694]="An'ratha adore. (守護者與你同在。)"
D.Strings[115695]="Tel vallath. (永夜之城。)"
D.Strings[115696]="Shal'assan torah. (專心致志。)"
D.Strings[115697]="我們樂意接受你的協助，德菈絲。聖光齊心照耀時最明亮。"
D.Strings[115698]="Ishnu-talah Kaldorei! (願卡多雷平安永存！)"
D.Strings[115699]="Ishnu-talah Kaldorei. (願卡多雷平安永存。)"
D.Strings[115700]="Anar'endal dracon belora. (以巨龍吐息之炎。)"
D.Strings[115701]="Elun'orin torel! (以伊露恩之力！)"
D.Strings[115702]="Athu'gag magg'naggwa. (這個世界將面臨無盡的痛苦。)\n\nQor'naus'agth lwhuk. (永恆的飢餓將吞噬一切。)\n\nLilth gag'huqth'hoq. (你能減緩我的飢渴。)"
D.Strings[115703]="咕嚕呣咕嚕！"
D.Strings[115704]="有什麼能為你效勞的嗎？"
D.Strings[115705]="Achal hecta. (你好。)"
D.Strings[115706]="Roma Hekt corta. (珍重再見。)"
D.Strings[115707]="為什麼要騷擾我？"
D.Strings[115708]="好吧，這是你逼的，我只能無視你的存在。"
D.Strings[115709]="要打架再叫我。"
D.Strings[115710]="哇咕！嗄啦哺嘎呃！噗勒嗄錘子！"
D.Strings[115711]="嗚嗄！噗呃啊嗄噗。姆嗄嘞呃噗呃海潮！"
D.Strings[115712]="你會受到制裁，伊利丹！"
D.Strings[115713]="<為其中一把三叉戟注入25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t上古法力。>"
D.Strings[115714]="開始召喚吧。"
D.Strings[115715]="呣咕！呣咕咕咕呣咕咕嚕！"
D.Strings[115716]="呣咕咕！呣咕咕咕！"
D.Strings[115717]="競技場又有骨頭鋪地板了！"
D.Strings[115718]="使用野性之魂召喚出幽靈狼！"
D.Strings[115719]="刪了我吧"
D.Strings[115720]="薩莉瑟拉秘法師，我還記得先祖之戰時，你們站在哪一方。我們要怎麼相信你不會背叛，變成下一個艾莉珊德…或者是艾薩拉？"
D.Strings[115721]="莫咕嚕莫咕。"
D.Strings[115722]="一定會有…我們的容身之處…"
D.Strings[115723]="看來...今天晚上…我得…先告退了…"
D.Strings[115724]="敵人一旦進入你的視線，他們就別想逃走。"
D.Strings[115725]="你的魚叉技能可以定住敵人，然後迅速把你拉過去。"
D.Strings[115726]="咕嚕莫咕莫莫咕！"
D.Strings[115727]="莫咕莫咕嚕咕嚕姆。"
D.Strings[115728]="莫咕嚕咕嚕莫咕嚕莫咕嚕咕嘎。"
D.Strings[115729]="莫咕嚕莫咕嚕。"
D.Strings[115730]="咕嚕莫咕莫嚕咕嚕莫嚕。"
D.Strings[115731]="莫咕嚕咕嚕嘎咕。"
D.Strings[115732]="elekkamomen otunbuntu rotu kelaramen! (召喚咒語。)"
D.Strings[115733]="咕咕莫咯姆爾姆？"
D.Strings[115734]="請你解釋一下，以你對時尚的理解，為什麼會穿這麼無趣的長袍出門？"
D.Strings[115735]="要前往北裂境的話，就去找莉夏‧坦稜拜，她是海怪號的碼頭管理員。在暴風港的北端碼頭搭乘海怪號可以前往北風凍原的驍勇要塞。"
D.Strings[115736]="有種就來啊！"
D.Strings[115737]="你為何而來？"
D.Strings[115738]="我差點就沒命了…宗師，我永遠感激你！"
D.Strings[115739]="咕嚕嘎嗚咯咕！！"
D.Strings[115740]="咕嚕嘎莫咯咕！"
D.Strings[115741]="莫咕嚕嘎！"
D.Strings[115742]="咕嚕嘎咕莫咕嚕嘎卜！？"
D.Strings[115743]="咕嚕嘎咕嘎！"
D.Strings[115744]="莫嚕咕嚕咕嚕莫嚕咕嚕！"
D.Strings[115745]="咕嚕莫嚕咕嚕！？"
D.Strings[115746]="目標，克索諾斯！"
D.Strings[115747]="Throm-Ka! (你好！)"
D.Strings[115748]="Lok-tar Ogar!(不勝即亡！)"
D.Strings[115749]="提里斯護法的敵人去死！"
D.Strings[115750]="低等生物。"
D.Strings[115751]="Diel fin'al! (送你上路！)"
D.Strings[115752]="嘎古嚕咕嚕古！"
D.Strings[115753]="莫咕嚕…咕嚕咕厄咕咕嚕嚕嗚嗚！"
D.Strings[115754]="姆咕嚕咕嚕！咕嚕莫咕嚕咕！"
D.Strings[115755]="嘎古咕嚕！"
D.Strings[115756]="姆咕嚕咕嚕！咕嚕莫咕嚕咕魯姆咕咕咕嚕！"
D.Strings[115757]="波嚕喀"
D.Strings[115758]="波喀"
D.Strings[115759]="啪喀"
D.Strings[115760]="咕哇"
D.Strings[115761]="啪"
D.Strings[115762]="喀啦啊啊"
D.Strings[115763]="喀啦"
D.Strings[115764]="嘎"
D.Strings[115765]="咕"
D.Strings[115766]="兜"
D.Strings[115767]="嘟嘟嚕"
D.Strings[115768]="咕嘟嚕"
D.Strings[115769]="嘰喳"
D.Strings[115770]="嘰"
D.Strings[115771]="喳"
D.Strings[115772]="喀叩"
D.Strings[115773]="喀"
D.Strings[115774]="啪喀喀…"
D.Strings[115775]="咖喀…唧恰…"
D.Strings[115776]="咕哆…唧喀…"
D.Strings[115777]="啪喀…唧恰唧恰…"
D.Strings[115778]="Pheta voros. (聖光與你同在。)"
D.Strings[115779]="你會為你的懦弱付出代價！"
D.Strings[115780]="我就這樣…死了嗎？"
D.Strings[115781]="什麼時候才會結束？"
D.Strings[115782]="Pheta thones gamera. (聖光指引我們。)"
D.Strings[115783]="Pheta vi hylas (聖光會照看我們)。"
D.Strings[115784]="遵從主人的意志。"
D.Strings[115785]="Golad niton acalah. (願祖靈長存。)"
D.Strings[115786]="就不能放過我們嗎？"
D.Strings[115787]="Arkonos vi acahachi! (秘法賜我力量！)"
D.Strings[115788]="誰都擋不住我們的遠征！"
D.Strings[115789]="讓你嘗嘗真正的痛苦！"
D.Strings[115790]="希瑞奇斯的虛無魔法還殘留在這裡。"
D.Strings[115791]="痛苦慘叫吧，讓大家知道挑戰燃燒軍團不會有好下場。"
D.Strings[115792]="我是吞噬千百個世界的怒火。"
D.Strings[115793]="真想不到我得在麥克艾瑞做這種事。"
D.Strings[115794]="時間拖太久了！比起跟這個東西鬥，我們還有更重要的事。"
D.Strings[115795]="快點消滅這個哨兵。燃燒軍團需要高階審判官！"
D.Strings[115796]="都過了這麼久，這些哨兵還在巡邏，真是不簡單。"
D.Strings[115797]="好黑暗…我原本希望…"
D.Strings[115798]="真希望我已經…逃…"
D.Strings[115799]="為你的愚蠢付出代價！"
D.Strings[115800]="啊，英雄你來晚了。我們應該已經救出高階審判官了。"
D.Strings[115801]="Aardon'sha, kir kah'los! (聖光帶我們迎向勝利！)"
D.Strings[115802]="Pheta vi acahachi! (聖光賜我力量！)"
D.Strings[115803]="不使用"
D.Strings[115804]="Der'ek... manul... (我的火焰…熄滅了…)"
D.Strings[115805]="趕快解決這傢伙，菈薩路姆把高階審判官帶去阿古斯需要時間！"
