D.Strings[116068]="「亞魯涅斯法杖位在一處封閉的魔法空間中，只有最強大的秘法師才能開啟。大法師雷塔瑞克是第一個召喚出它的人，最後一個則是我。」$b$b- 尊者艾格文"
