D.Strings[116071]="把你的力量借給我。我們一起打開通道。"
D.Strings[116072]="勝利屬於我們！我們去外面等你。"
D.Strings[116073]="你受傷了嗎？"
D.Strings[116074]="我們會跟你一起對付它。"
D.Strings[116075]="請助我一臂之力，我們一起了結這件事！"
D.Strings[116076]="如你所願，去吧。我感覺他們離這裡不遠了。"
D.Strings[116077]="它們來了。做好準備。"
D.Strings[116078]="撐下去，怪物就快要倒下了！"
D.Strings[116079]="你們的努力全都白費了！"
D.Strings[116080]="過來這裡。不要被發現了。"
D.Strings[116081]="時間到了。出發前往阿古斯。"
D.Strings[116082]="勇士，我派了烏鴉協助你登上指揮艦。"
D.Strings[116083]="祝你好運，先知。相信你不會讓我失望。"
D.Strings[116084]="啊，勇士！原來你在這裡。我還擔心是不是太早引爆炸彈了。"
D.Strings[116085]="做好準備。我要救你們出來，然後引爆炸彈！"
D.Strings[116086]="歡迎你，勇士。我們可以開始進攻了。"
D.Strings[116087]="我跟賽倫的其他學徒一起合作，尋找他的所在位置。我相信他就在永恆之眼！"
D.Strings[116088]="感謝你的協助，先知。相信你一定很快就能解決這個問題。"
D.Strings[116089]="斬魔者，看來你已經完全馴服牠了。我要恭喜你！"
D.Strings[116090]="戰鬥領主，等你準備好面對最後的挑戰者，就站到符文上。"
D.Strings[116091]="第一場由勇猛的戰鬥領主對上惡名昭彰的卓格巴，『強者』丹魯爾！"
D.Strings[116092]="歡迎，大領主。我正在為護具的淨化儀式做準備。但我們一直到現在都無法取得聖水。"
D.Strings[116093]="我跟安東尼達斯不熟，但我相信他會為你今天所做的一切為榮，大法師。"
D.Strings[116094]="大法師，別分心！只剩一個稜碟要處理了。記住，我的學徒可以幫你的忙。"
D.Strings[116095]="大法師，做得好！淨化以後，這個稜碟就算靠近其他的，也不會產生劇烈的反應。其他兩個稜碟應該可以比照處理。"
D.Strings[116096]="大法師，歡迎你。希望你已經準備好了。"
D.Strings[116097]="等等…那個笨蛋酒鬼忘了，是吧？你給我想辦法點燃火藥。我不許這個任務失敗！"
D.Strings[116098]="瑪克西米利安，你好呀。"
D.Strings[116099]="注意背後！"
D.Strings[116100]="我好像抓到感覺了。"
D.Strings[116101]="勇士，找你找好久！喔，你說為什麼把頭裝在水晶球裡嗎？我在嘗試新東西。"
D.Strings[116102]="下一張勇士武裝的訂單。"
D.Strings[116103]="你對自己做了什麼，$n？比起$r你現在更接近惡魔。"
D.Strings[116104]="你的武器不錯。想幫忙，就去找捷斯和艾萊莉。"
D.Strings[116105]="這個傳送門會把你帶往艾克索達。勇士，祝你好運。"
D.Strings[116106]="太好了！你得盡快回達拉然，然後到守護者之廳和我碰面。路上小心，朋友。"
D.Strings[116107]="Krona ki cristorr! (燃燒軍團必敗！)"
D.Strings[116108]="已經沒有你能做的事了，勇士。"
D.Strings[116109]="只有瑟拉親生的那魯才有能力打開核心。這就是你被派來這裡的原因。"
D.Strings[116110]="勇士，我們得立刻出發！"
D.Strings[116111]="該你上場了。釋放隱藏其中的力量吧！"
D.Strings[116112]="你幫了月之守衛一個大忙。我們該怎麼回報你？"
D.Strings[116113]="我撬不開這鎖。交給你了。"
D.Strings[116114]="他就在樓下。動作快！"
D.Strings[116115]="希望這個祝福可以照亮通往勝利之路，宗師！"
D.Strings[116116]="所以，英雄們，讓我們一起為聯盟的煞星歡呼吧！"
D.Strings[116117]="轉身面對你的同袍，勇士。讓他們見識你的狡詐和冷酷。"
D.Strings[116118]="很好！你現在了解平衡德魯伊的作戰方式了。"
D.Strings[116119]="很好！你現在了解野性戰鬥德魯伊的作戰方式了。"
D.Strings[116120]="很好！你現在了解武器戰士的作戰方式了。"
D.Strings[116121]="很好！你現在了解痛苦術士的作戰方式了。"
D.Strings[116122]="許多法術需要耗費大量法力，但你有個聰明的解決辦法。"
D.Strings[116123]="很好！你現在了解增強薩滿的作戰方式了。"
D.Strings[116124]="釋放元素力量獲得勝利！"
D.Strings[116125]="很好！你現在了解元素薩滿的作戰方式了。"
D.Strings[116126]="嘿，讓我看看你的本事！"
D.Strings[116127]="很好！你現在了解刺殺盜賊的作戰方式了。"
D.Strings[116128]="很好！你現在了解戒律牧師的作戰方式了。"
D.Strings[116129]="很好！你現在了解懲戒聖騎士的作戰方式了。"
D.Strings[116130]="很好！你現在了解武僧的作戰方式了。"
D.Strings[116131]="很好！你現在了解冰霜法師的作戰方式了。"
D.Strings[116132]="很好！你現在了解野獸控制獵人的作戰方式了。"
D.Strings[116133]="很好！你現在了解穢邪死亡騎士的作戰方式了。"
D.Strings[116134]="來吧，朋友們！一起歡呼吧！和我一起獻上對勇士的敬意！"
D.Strings[116135]="大領主！你以白銀之手之名所舉起的神兵武器，是正義與懲戒的最佳象徵！"
D.Strings[116136]="為神獵手歡呼吧！願你箭無虛發，招招致命！"
D.Strings[116137]="歡迎你，大祭司，在你協助牧道會的時候，我們發現你和手上這件遠古神兵的連結加深了。"
D.Strings[116138]="先知，這些靈魂看著你和遠古武器之間的羈絆逐漸加深。"
D.Strings[116139]="死亡領主，我們看著你揮舞神兵武器，輕鬆奪取敵人的性命。"
D.Strings[116140]="宗師！振虎會的大家一直看著你和遠古武器之間的羈絆越來越強。"
D.Strings[116141]="呃啊啊！"
D.Strings[116142]="迪維尼斯，這位勇士擊敗了入侵的敵人。現在，帶著受選者去清理大廳裡面殘存的惡魔吧。我們要為人民再次守護艾克索達！"
D.Strings[116143]="成功了！由你出手就是不一樣。"
D.Strings[116144]="你會喜歡這裡的景觀。走吧！"
D.Strings[116145]="沒人可以對抗燃燒軍團！"
D.Strings[116146]="很抱歉我必須如此堅持，我們一定要先談談。"
D.Strings[116147]="殺了那個雜種！不…等等。我有更好的主意。"
D.Strings[116148]="就連在這裡，我都聽過你的名聲。但我並不怕你。"
D.Strings[116149]="請見諒，這可能會有點痛。"
D.Strings[116150]="等等…有辦法了！如果你用自己的靈魂和哈提連結，就能把力量導回泰坦之擊！你可以拯救哈提，同時修復這把槍！"
D.Strings[116151]="我知道你因為哈提的事在難過，獵人，我也一樣難過。你和野生動物的靈魂連結如此密切，我從來沒見過像你這樣的人。"
D.Strings[116152]="完成了。動作快，把聖錘拿起來！這樣就可以確保提爾的遺體永遠不會再受到騷擾了！"
D.Strings[116153]="今天，這位潛影拿到了傳說中的弒君之刃，這樣一來，我們就能正面迎戰燃燒軍團了。"
D.Strings[116154]="今天，這位潛影拿到了傳說中的吞噬者之牙，這樣一來，我們就能正面迎戰燃燒軍團了。"
D.Strings[116155]="謝謝你。我是斯黛拉苟莎。"
D.Strings[116156]="…這不是你這種小蟲子該出現的地方。"
D.Strings[116157]="因此，我在此將我的職責傳給這位英雄。他是真正的生命保護者…真正的夢境守護者！"
D.Strings[116158]="要不是有這位英雄幫忙，我們早就全都死在海加爾山上了。"
D.Strings[116159]="你必須拯救傷患。我會準備淨化儀式。"
D.Strings[116160]="我們必須幫巴珊娜淨化剩下的夢魘。格哈尼爾的命運就交給萊耶莎和這位英雄了。"
D.Strings[116161]="謝謝你。現在我要去殺掉困住我的看守者。"
D.Strings[116162]="保護潮石！"
D.Strings[116163]="快讓開，蠢貨！最好放尊重點！"
D.Strings[116164]="我們願意跟隨勇士共赴沙場，把燃燒軍團徹底摧毀。"
D.Strings[116165]="什麼？！你難道沒有一點幫助騎士同伴的責任感嗎？"
D.Strings[116166]="好久不見。真的好久不見！"
D.Strings[116167]="你還活著！"
D.Strings[116168]="范克里夫，你對無冕者還有利用價值。你可以選擇…成為新的潛影密探，或是死在這裡。"
D.Strings[116169]="那就這樣吧。恭喜你。范克里夫是我們的箇中好手，你已經見識過了。"
D.Strings[116170]="今天，這位潛影拿到了傳說中的驚懼雙刀，這樣一來，我們就能正面迎戰燃燒軍團了。"
D.Strings[116171]="我們幫你留了個座位。坐下，我們就會回答你的問題。坐下就對了。"
D.Strings[116172]="我們請求你立刻前往潛影之廳。"
D.Strings[116173]="做得好。在你對付瓦瑞迪斯的時候，我們已經掃蕩過空中了。"
D.Strings[116174]="要是不管它，惡魔就會再開一道傳送門。準備戰鬥！"
D.Strings[116175]="聖光啊…"
D.Strings[116176]="你能加入真是太好了。"
D.Strings[116177]="亞榭洛的死亡騎士們，我親自派遣這位勇士去貫徹我的意志。聽從他的命令，就像服從我一樣。"
D.Strings[116178]="是你嗎？總算有好事發生了！"
D.Strings[116179]="請你盡可能把還活著的人送到寺廟去。小莊說到鶴之洞穴，就從那裡開始！快，我們要在失守之前離開這裡！"
D.Strings[116180]="勇士，我認為這位勇戰者…應該是好人。快跟上去，這或許是你在山上爭取盟友的最佳機會。"
D.Strings[116181]="他們撤退了。"
D.Strings[116182]="動手！把它打下來！"
D.Strings[116183]="血騎士與你同在，大領主。艾澤拉斯絕不會淪陷！"
D.Strings[116184]="提高警覺。瓦瑞迪斯是個狡詐的對手。"
D.Strings[116185]="如果需要協助，儘管說一聲。"
D.Strings[116186]="你先請。"
D.Strings[116187]="我會到卡薩斯平臺跟你會合，並準備好魔蝠帶你到蘇拉瑪爾。狩獵開始了！"
D.Strings[116188]="你死了那麼多族人竟然還敢在我面前出現？馬上放了我，我還可以饒你一命。"
D.Strings[116189]="奪回…灰燼使者…"
D.Strings[116190]="暗愁與黑羽將獲得伴隨你進入蘇拉瑪爾的殊榮。小編制的隊伍最有機會飛入要塞而不被察覺。"
D.Strings[116191]="爸爸，爸爸，我回來了！這位英雄救了我！"
D.Strings[116192]="你們都知道我旁邊這位勇士的高貴事蹟。聖光已經選擇了他來繼承提里奧的大領主身分。在新領袖的帶領之下，我們會成為一把對抗燃燒軍團的利劍！"
D.Strings[116193]="這些優秀的男女需要一位領袖。你的豐功偉業證明了你適合承擔這個重責大任。來吧，我會為你向眾人發表談話。"
D.Strings[116194]="我們是燃燒軍團！"
D.Strings[116195]="感謝聖光，我找到你了。我有急事要跟你說。"
D.Strings[116196]="我們…開始吧。"
D.Strings[116197]="你得盡快過來。提里奧指名要找你。我擔心他的時間不多了。快點！"
D.Strings[116198]="趁敵人還沒反擊，趕快離開吧。"
D.Strings[116199]="我們恭候多時了。卡德加近來可好？"
D.Strings[116200]="請別走遠。"
D.Strings[116201]="英雄？你要去哪裡？"
D.Strings[116202]="快點，我們必須找到那道鎖的鑰匙。我敢說鑰匙就在東邊那個獄卒身上。"
D.Strings[116203]="Krona ki cristorr (燃燒軍團必敗)！"
D.Strings[116204]="大法師卡德加？真是稀客。"
D.Strings[116205]="就快到了。"
D.Strings[116206]="謹遵命令。"
D.Strings[116207]="可敬的對手！"
D.Strings[116208]="我們開始釀酒吧！"
D.Strings[116209]="我們團結一心！"
D.Strings[116210]="不勝即亡。"
D.Strings[116211]="下面出了什麼事？"
D.Strings[116212]="「亞魯涅斯會反抗意圖駕馭它的人，必須先讓這把法杖強大的意志屈服。」$b$b- 尊者艾格文"
D.Strings[116213]="見識真正的力量吧！"
D.Strings[116214]="快逃…快啊。"
D.Strings[116215]="表現不錯！"
D.Strings[116216]="不能再浪費時間了。"
D.Strings[116217]="走這裡。"
D.Strings[116218]="你好，斬魔者。在對抗燃燒軍團的戰役中，我們看見你跟武器之間的連結越來越強大。"
D.Strings[116219]="你好，斬魔者。在對抗燃燒軍團的戰役中，我們看見你和武器之間的連結越來越強大。"
D.Strings[116220]="可悲。"
D.Strings[116221]="就等你了，親愛的。"
D.Strings[116222]="練習結束了。該來測試一下你的能耐了。綜合你所學過的所有內容，在戰鬥中擊敗我的手下。"
D.Strings[116223]="辛尼‧斯麥瑟低下頭，無聲地表達謝意。"
D.Strings[116224]="這是我的榮幸。"
D.Strings[116225]="<在上面堆放20堆星輝玫瑰塵。>"
D.Strings[116226]="你以為你贏了嗎？"
D.Strings[116227]="「亞魯涅斯令人捉摸不定。召喚者必須盡快與法杖連結，以免因為它的變幻無常而前功盡棄。」$b$b- 尊者艾格文"
D.Strings[116228]="我詛咒你！"
D.Strings[116229]="快點！"
D.Strings[116230]="但至少是個開始。到阿格拉瑪寶庫附近找我，我來測試你的力量。"
D.Strings[116231]="懼怕黑夜吧！"
D.Strings[116232]="Archenon poros. (祝你好運。)"
D.Strings[116233]="說吧。"
D.Strings[116234]="有話快說。"
D.Strings[116235]="願大地之母守護你。"
D.Strings[116236]="沒錯，我們很期待吞噬墮落泰坦的爪牙。但首先是…扎卡茲。"
D.Strings[116237]="如同月光林地，這裡的村莊及居民也受我保護。但願我能守護更廣大的林野與更多大自然的朋友。$B$B多麼希望我有足夠的力量保護所有人。"
D.Strings[116238]="我的職責…結束了。"
D.Strings[116239]="黑暗會吞噬你們！"
D.Strings[116240]="測試"
D.Strings[116241]="黑暗會吞噬你！"
D.Strings[116242]="有什麼事嗎？"
D.Strings[116243]="戰鬥領主！這裡！"
D.Strings[116244]="我們也不想肩負這個重擔，預言者，但命運已經注定。"
D.Strings[116245]="聽你號令。"
D.Strings[116246]="這傢伙是我的！"
D.Strings[116247]="要來嗎？"
D.Strings[116248]="沙許塔爾納迦會消滅詹德維克人！"
D.Strings[116249]="我的星辰遭遇危險！快去保護她！！"
D.Strings[116250]="到東南方協助法隆迪斯親王。"
D.Strings[116251]="我們得盡快行動，$n。伊利達瑞需要我們協助擊退燃燒軍團。\n\n先迎擊燃燒軍團，我們才能繼續尋找艾蘇納的創世之柱。"
D.Strings[116252]="身為增強薩滿，你能在武器中灌注元素之力，化身狂熱的近戰鬥士，用火焰、大地和風暴的力量擊敗敵人。"
D.Strings[116253]="使用冰霜新星凍結我的士兵。"
D.Strings[116254]="很高興見到你。"
D.Strings[116255]="那…那是什麼？"
D.Strings[116256]="我們出發了！"
D.Strings[116257]="(惡魔語)獻祭典禮開始！"
D.Strings[116258]="(惡魔語)可憐的凡人！"
D.Strings[116259]="我還沒學會那個技能。"
D.Strings[116260]="我的技能等級不夠高，不能裝備這件物品。"
D.Strings[116261]="這類物品太多了。"
D.Strings[116262]="還要再等一下。"
D.Strings[116263]="拜託你！"
D.Strings[116264]="做得漂亮。"
D.Strings[116265]="攻擊我的敵人！"
D.Strings[116266]="多謝。"
D.Strings[116267]="待在這裡。"
D.Strings[116268]="我很樂意。"
D.Strings[116269]="我還沒準備好。"
D.Strings[116270]="你好，摩根。$B$B闪金镇的交易非常繁忙，所以我根本抽不出时间来帮你送货！$B$B我已委托帮我送这封信的人给你带去一包大蜡烛（你知道，可笑的狗头人总喜欢把这些东西戴在头上）。$B$B请向这位送货的人表示我们的感谢，并给予他合理的报酬。"
D.Strings[116271]="致尊敬的克雷利安校长，$B$B 我以前的主人，我写这封信是为了让您了解到您的学生最近都做了些什么。我听从您的建议离开了我深爱的暴风城，在世界各地到处游历，以此来历练我的知识与智慧。我去过许多地方，最后决定在月溪镇这个可爱的小镇定居。随着收获季节的到来，西部荒野的农田景色是如此的美丽。"
D.Strings[116272]="刚到这里没几天，我就开始为附近农场中的孩子们上课了。我的课程进行得很顺利，镇长便委任我设立了一所学校，而且现在已经开始动工修建一所全新的校舍了!我从银松森林到暴风城，现在又来到月溪镇——谁能想到我会在艾泽拉斯经历那么多的事情!$B$B 向您致意，$B$B 斯塔文·密斯特曼托"
D.Strings[116273]="尊贵的大人，$B$B 我听说您需要为您的孩子找个老师。现在我暂时住在闪金镇的狮王之傲旅店里，由于目前月溪镇糟糕的状况，我被迫放弃了学校校长一职。我愿做您孩子的老师，希望您能接受我的申请。如果有必要，克雷利安校长可以向您证明我的能力。"
D.Strings[116274]="当冬天的雨季过后，道路适合旅行的时候，我会亲自前去找您。$B$B届时再见，$B$B斯塔文·密斯特曼托写于银松森林"
D.Strings[116275]="……那个叫基尔斯的男孩似乎很难管教，对我来说也许是个挑战。他的姐姐蒂罗亚则是个非常聪明的孩子，她的美貌也格外引人注目，蒂罗亚浑身都散发着女人独有的气质，而他们家可能已经安排她在明年结婚了。我有点跑题了。这个星期我会陪他们一家人到他们那座艾尔文森林东谷伐木场附近的夏季别墅去度假，那里离赤脊山很近。我希望能在那儿再给您写信。"
D.Strings[116276]="……奇特，无法自控，今天我感受到了这种以前从未有过的感觉。在我辅导基尔斯学习历史的时候，蒂罗亚正在外面照料着她的花园。过了一会，她走了进来，把鲜红的秋海棠放在我的手心上，对我嫣然一笑，我感到自己的心在猛烈地跳动……"
D.Strings[116277]="……我敢肯定，她和我有着相同的感觉。今天早晨，她甚至把手放在了我的手掌中。当她微笑的时候，她的眼眸像钻石一样闪亮。我们进行着无言的交流，她已经占据了我的心，她让我的全身热血沸腾。"
D.Strings[116278]="……我从未想过自己会这么愤怒!她怎么敢这样对我!我教基尔斯数学的时候，蒂罗拉来了，还带着她的一个求婚者，他们竟公然手拉着手!真是个没教养的年轻人。蒂罗亚也没怎么介绍我，只是轻描淡写地说了句，“哦，这是我的家庭教师，斯塔文叔叔。他是个不错的老人。”老人!一听到这个词，我的脸就涨得通红。我不过比她大了几岁而已，而她竟背叛了我……"
D.Strings[116279]="……我的心仿佛随着绝望而跌入了无底的深渊。她欺骗了我的感情，现在竟然还订了婚。这个可恶的骗子，她假装自己陷入了爱河，其实她一直以来只是想要伤害我而已。我的心里只有黑压压的一片，每过一分钟，这种感觉就更加强烈一分。我要让她付出血的代价，但是与我流过的眼泪相比，那是多么的苍白无力……"
D.Strings[116280]="汤米·乔 ：$B$B 随着时间不断流逝，我的心因为没有你的存在而越发的失落。啊，只愿我们的家人能够超越他们之间愚蠢的仇恨，并且能认识到真正的罪恶其实就是这种仇恨。仇恨吞噬了我们的幸福，而且我担心受难的并非只有我们两个家族而已。$B$B 如果他们能够明白这些，那么也许有一天我们可以走到一起。我希望能等到那一天，我将为此而活着。$B$B 深爱你的梅贝尔"
D.Strings[116281]="阿古斯，$B$B 正如你所知，我一直因为提供军队的补给需求而焦头烂额。我不应该对自己的工作有所抱怨，但是我们储备的铁即将用完。$B$B 我已经没有足够的铁来制造马蹄铁了。我知道你有大量的储备，因此我想在下一批铁运到之前先向你借50双马蹄铁。$B$B 对你表示万分感激，$B ——弗纳"
D.Strings[116282]="板条箱上附着一张纸条。上面写着：$B$B “弗纳——听说赤脊山遇到这样的麻烦，我感到甚是遗憾。这里是你所需要的马蹄铁。如果方便的话，请你尽快付给我100银币。”$B$B “如果你愿意的话，也可以用黑色雏龙的下腹部鳞片来支付报酬（我听说黑色雏龙在赤脊山十分常见）。既然我们是朋友……4块鳞片就够了。谢谢你。——阿古斯"
D.Strings[116283]="尊敬的大人，$B$B 战争已经降临到我们的头上了。厄运正在一步步地向我们走来。$B$B 作为湖畔镇的镇长，我有责任向您汇报最近在王国最东部地区所发生的军事活动。$B$B 从我的信中，您可以了解到赤脊山地区和湖畔镇的现状。"
D.Strings[116284]="石堡的失守是一件非常严重的事。在以前的报告中，我已经向您详细说明了黑石氏族的兽人与名为莫甘斯的术士勾结的情况。黑石兽人作战时凶猛残暴，此次显然又得到了莫甘斯的邪恶法术的帮助。陛下的许多勇士都为了保卫要塞不惜牺牲自己的性命，但最后还是没能守住。"
D.Strings[116285]="奇怪的是，在获得了这场卑鄙的胜利之后，莫甘斯很快就开始转而攻击兽人军团。这个术士在东北方建造了一座神秘的塔楼，并组建了一支小型的暗皮豺狼人军队来调遣。兽人和人类都成了这些野蛮而肮脏的怪物的受害者。关于莫甘斯和黑石氏族首领加塞尔佐格之间到底发生了什么事情，我们也只能推测到以上这样的程度了。"
D.Strings[116286]="野蛮的兽人似乎非常倾向于屠杀国王陛下的子民，在过去的两个星期里，黑石氏族向湖畔镇发动了多次进攻，许多勇士都付出了生命。兽人军队推进的速度惊人，而且攻势猛烈，他们甚至将横跨止水湖的大桥都毁了。我们的补给十分缺乏，连给伤患包扎伤口的绷带都告罄了。"
D.Strings[116287]="我请求国王陛下在这个危难的时刻能给予湖畔镇的人民足够的支援。我们需要更多的战士来保卫领土，需要更多的武器装备来武装部队，也需要更多的食品和建筑物资。大人，请您帮助我们在构筑人类抵御野蛮兽人的最后一道堡垒。我们决不能让敌人进入暴风王国的领土。"
D.Strings[116288]="北方的土地已经变成了邪恶力量的温床，我担心还会有更强大更黑暗的敌人接踵而来。暴风王国必须采取行动，以免让我们的城镇沦陷，人民沦为奴役。$B$B 此致，$B$B 所罗门镇长$B 湖畔镇$B 暴风王国"
D.Strings[116289]="尊敬的所罗门镇长：$B$B 我和您一样为死去的人而哀悼。我会确保让国王陛下了解到目前的状况，同时我也衷心希望能为湖畔镇增派援军。不过奇怪的是，陛下最近没有什么举动，这件事我只能私下对您说说。$B$B 请多加保重，$B$B 马库斯·乔纳森将军$B 暴风王国"
D.Strings[116290]="斯托曼：$B$B某些胆大的家伙竟然找了个陌生人来跟我谈关于迪菲亚盗贼的事。你曾经救过我一命，而现在你又让我处于极度的危险中。$B$B不过我还是欠你的人情。迪菲亚兄弟会的势力远比你想像中的要大。从西部荒野到艾尔文森林，每座矿坑都在他们的控制之下。他们还征召了狗头人和豺狼人执行命令，还有哥布林为他们铸造金属怪物，用于在西部荒野农场上劫掠当地的居民。"
D.Strings[116291]="斯托曼大人——$B$B 石匠公会由技术最为熟练的建筑师组成，其领导者是艾德温·范克里夫。在第一次兽人战争中，暴风城被兽人夷为平地，这些石工参与了暴风城的重建工作。范克里夫和他的工匠都是出类拔萃的建筑师，他们在建筑方面的造诣和艺术性从光明大教堂和暴风要塞这两座建筑中就可见一斑。"
D.Strings[116292]="然而，暴风城的军事力量从艾尔文森林一直扩张到荆棘谷，这使得暴风城的贵族们背上了沉重的债务。高额债务削弱了整个王国的经济实力，使他们无法兑现之前对范克里夫和他的石匠所承诺的酬劳。为了重建这座光辉的城市而辛勤工作了数年之后，这些石工却心碎地离开了，被城市腐败的官员们彻底地遗忘。"
D.Strings[116293]="我个人和艾德温·范克里夫相处了很久，根据我对他的了解，这么说吧，与他为敌不是那么容易的。要知道，他是我儿时的伙伴，是我亲自训练他的，因为我以为有一天他会和我并肩工作。如果范克里夫就是迪菲亚兄弟会的首脑，那么只能希望圣光怜悯我们的灵魂了。$B$B 马迪亚斯·肖尔$B 暴风城刺客公会"
D.Strings[116294]="干得好，朋友!现在你需要朝东方前进，沿着悬崖一直向东走。找到路边废弃的烟囱，那里有一只旧木桶，它可以为你提供下一步行动的线索。"
D.Strings[116295]="现在，从这只桶所在的地方向北方行进。笔直地向前走，当你看到海边悬崖上的那座风车时，找到风车旁边的一只空壶。四处看一下，也许你就能找到你要的东西。"
D.Strings[116296]="找到了这只威士忌酒瓶，你离宝藏就不远了!从酒瓶的位置向西前进，走到海岸边，然后下水继续前进!一直向西边游，你就可以看到藏有宝箱的岛屿!"
D.Strings[116297]="黑爪：$B$B 海洋在等待着我们，而我们需要你从北方运来的补给。尽力收集所有物资，一根铁轨一只水桶都不要放过，我们需要足够的金属。藏宝海湾那边本应有货物运来，但迟迟未到。黑爪，帮帮我，这次把你的补给直接运到“谷仓”去。我们不能再浪费时间了。$B$B - 范克里夫"
D.Strings[116298]="斯托曼大人：$B$B 湖畔镇请求您的民兵的援助。在我写这封信的时候，我们正受到黑石氏族兽人和莫甘斯率领的暗皮豺狼人的夹击。如果形势不是如此严峻的话，我也不会向您求助。我们也在等待暴风城的援助，不过在他们的援军到来之前，我恳求您能对我们施以援手。暴风王国一旦腹背受敌，整个人类都将面临着危险。$B$B 所罗门镇长"
D.Strings[116299]="尊敬的阁下：$B$B 西部荒野为您的失利而哀悼，但是我们这里也饱受战争的困扰，农夫都被盗贼和收割傀儡赶走了，暴风城也撤走了他们的驻军，留下毫无防御的我们。在暴风城遗弃了我们之后，我召集组建了西部荒野人民军，试图夺回曾经属于我们的领土。如果我将人民军调往赤脊山的话，西部荒野必将遭受毁灭。$B$B 我表示万分的遗憾和歉意。$B 格里安·斯托曼"
D.Strings[116300]="埃伯洛克公爵大人：$B$B 湖畔镇请求守夜人的援助。我们正受到黑石氏族兽人和莫甘斯率领的暗皮豺狼人的夹击。如果形势不是如此严峻的话，我也不会向您求助。我们也在等待暴风城的援助，不过在他们的援军到来之前，我恳求您能对我们施以援手。暴风王国一旦腹背受敌，整个人类都将面临着危险。$B$B 所罗门镇长"
D.Strings[116301]="尊敬的阁下：$B$B 我只能非常遗憾地告知您，守夜人部队现在不能离开夜色镇。也许您还没有注意到，暴风城已经不再为我们这个地区提供军事支援了。守夜人是完全由镇中的人民自发组建和训练的，他们的职责是在没有暴风城帮助的情况下保卫夜色镇。没有守夜人，夜色镇一定会沦陷。但愿您在困境中能有好运。$B$B - 艾尔罗·埃伯洛克公爵"
D.Strings[116302]="这封信上的字仿佛在不断地跳动和扭曲，你根本无法看清它们……"
D.Strings[116303]="这是一张西部荒野地产的契约。它赋予在契约上签名的拥有一块土地的所有权，以及该土地上面所有农作物和建筑物的所有权。$B$B 在这份文件上签字的人是：$B$B     瑟多尔·法布隆$B     弗娜·法布隆"
D.Strings[116304]="[契约的背后潦草地写着以下文字]$B$B 我们从法布隆那里弄到了他的契约，如果你想为自己伪造一份契约的话也很容易，法布隆不会给我们带来任何麻烦的。我上一次看到他们的时候，他们一家人正在离开西部荒野，不过因为四轮货车坏掉而不得不停了下来。"
D.Strings[116305]="月亮照耀着山谷$B 月光洒满了丛林$B 骄傲的战士响应号召$B 保卫我们的国家和神圣的大地$B$B 月亮照耀山谷$B 远离战争的哭泣$B 这里流淌着$B 敌人和我们的鲜血。"
D.Strings[116306]="当我们的同胞永远离去$B 走进未知的土地$B 在山谷的深处$B 灵魂与精神变得坚强。$B 当我们的同胞永远离去$B 来到山上的圣殿$B 我们将保卫他们永恒的精神$B 将它镶入神圣的蓝水晶。$B 当我们的同胞永远离去$B 月亮照耀着山谷。"
D.Strings[116307]="月光和火光，$B 肉体和骨头，$B 在鲜血中书写，$B 在石头上雕刻。$B$B 要么远离这片土地$B 要么遭遇厄运$B 死亡守卫着$B 国王的陵墓。"
D.Strings[116308]="卡尔文大人：$B$B 这位信差以证明自己信仰正义与圣光之道，并有能力与侵扰暮色森林的不死生物和恶魔战斗，$g他:她;也愿意加入卡尔文家族的伟大事业。$B$B 我建议您给这位圣光的战士派遣更多工——有些镇民可能在暗中帮助与圣光为敌的势力，不如让这位$c去调查一下。$B$B 您忠诚的卡洛尔"
D.Strings[116309]="摩根·拉迪莫尔曾经是一个伟大而高尚的骑士，他为了保卫无辜、贫穷和饱受痛苦的人而战斗。多年来，他几乎跑遍了艾泽拉斯的所有边远地区，为受苦的人民带来安慰，惩戒那些作恶多端的人。$B$B 在他十八岁那年的夏天，摩根与一位名叫莉丝的年轻女孩结婚了。他们彼此相爱，后来生了一个儿子和两个女儿。$B$B 在摩根三十二岁那年，洛丹伦的战争爆发了。"
D.Strings[116310]="摩根被召入圣骑士光明使者乌瑟尔的部队，与兽人和不死生物作战。因为战争，他离开了妻子和儿女，离开了安宁的家园。$B$B 数年过去了，战争依然没有结束，摩根亲眼目睹了许多可怕的事，他目睹了白银之手骑士团的解散，目睹了乌瑟尔的死，也目睹了瘟疫的蔓延。只有一件事可以让他远离疯狂和崩溃的边缘，那就是他相信自己总有一天可以和妻子儿女团聚。"
D.Strings[116311]="摩根最终回到了家乡，但那里已经不再是他熟悉的景象了。曾经青翠的树林变得枯萎凋零，散发着堕落的气息，不死生物和其他黑暗的势力到处横行。遍地都是已被损毁的房屋与农场，乌鸦岭附近的墓地占据了大片的土地。摩根怀着震惊和迷惑，艰难地回到家中，却只发现那里已成废墟。"
D.Strings[116312]="摩根不知道自己的家遭遇了什么样的灾难，他赶去村庄里寻找答案，寻找他的妻子和孩子们的消息。$B$B 摩根询问了许多人，但是没有找到任何线索。就在现在被称为夜色镇的这个地方，有一位牧师告诉他应该到乌鸦岭的墓地去搜索一下是否有他妻儿的墓碑。摩根不愿相信他的家人会死去，他走遍了暮色森林的每一片农场和每一所房子，但还是一无所获。$B$B 他相信自己的家人已经出去逃难了，于是骑马从夜色镇赶往毗邻的湖畔镇。"
D.Strings[116313]="就在去湖畔镇的路上，他最终决定到乌鸦岭的墓地去一次。摩根在墓碑之间穿行了数个小时，看到了许多熟悉的人名被刻在墓碑上，这让他变得几近发狂。最后他看到了众多的墓碑中间有一小片由三块墓碑组成的墓地，看起来已经很久无人打理了。当他靠近那片墓地的时候，他全身充满了恐惧。摩根擦去了墓碑上的灰尘，显出了上面的名字。墓碑上简单地雕刻着几行字母，那是他最不愿看到的名字："
D.Strings[116314]="莉丝·拉迪莫尔$B$B 我们深爱着的妻子与母亲$B$B 摩根的忧虑立刻变成了沮丧，进而变成了无比的悲痛，他不禁瘫在地上开始哭泣。摩根一连几个小时望着墓碑，一边哭泣，一边对着墓碑请求原谅和宽恕。又过了几个小时，他突然情绪大变，开始发狂，他拔出佩剑，一边怒吼一边用剑如狂风暴雨一般砍向墓碑。愤怒让他变得盲目，他疯狂地挥舞着剑，不断地攻击着。"
D.Strings[116315]="他的举动引起了三个墓地值班人的注意，他们试图阻止他。摩根注意到了他们，于是他把自己的愤怒和对罪恶的谴责统统倾泻这些无辜的人身上，最后杀害了他们。$B$B 杀人之后，摩根的愤怒逐渐散去，他的脑子也恢复了正常的意识。在看到自己的剑血淋淋地插在一个值班人的胸膛里时，激烈的情绪将他推向了崩溃的边缘，他抽出匕首猛然刺入了自己的心脏。$B$B 第二天，有人发现了摩根·拉迪莫尔和另外三个无辜者的尸体。"
D.Strings[116316]="他被埋葬在墓地旁边一个匆匆挖掘的墓穴里，没有举行任何葬礼。摩根杀了无辜的人，这完全违背了他的信仰与天性，再加上他因为不能挽救家人而感到了巨大的悲痛，这些使得摩根死后也无法得到安宁。$B$B 只过了几天，人们便发现他的墓穴被破坏，他的尸体也不知所踪。"
D.Strings[116317]="如今，摩根·拉迪莫尔被失去妻儿的痛苦和对自己的仇恨煎熬着，每日都在暮色森林中游荡。现在他称自己为摩拉迪姆，满怀仇恨在暮色森林中徘徊，毫无理智地肆意进行屠杀。"
D.Strings[116318]="在过去的几个星期里所遭遇到的恐怖令我几乎要崩溃了，然而写下我所看见的这些事也许会让我感到舒服一点。所以我就这么做了，这也是在现在这段阴冷的日子里我所能得到的唯一安慰。"
D.Strings[116319]="第一天$B$B今天我和学徒来到了寒脊山谷，平安无事地穿过了洞穴之后，我们在食人妖巢穴外面的安全地带扎了营。$B$B 第二天$B$B 该死的狼嚎声让我整晚都没睡着。$B$B 明天我就要去弄一套狼皮做的衣服。$B$B 今天那个年轻的学徒与石腭怪作战相当英勇,也成功地战胜了那些丑陋的东西，不过他的胳膊受伤了，得好好休养一下。看来这阵子得由我来打理了。"
D.Strings[116320]="这个护甲标志十分适于缀在皮甲或布甲上，东谷伐木场中的迪博雷恩家族的人可以对它进行加工。"
D.Strings[116321]="以下是迪菲亚盗贼从艾尔文森林的矿坑中开采金矿并送往西部荒野总部的日程表。$B$B 征收日程：$B$B 周日：中午12:30$B 周二：中午12:30$B$B 在指定的日子里，从艾尔文森林的矿坑中开采出来的金矿将被集中在布莱克威尔南瓜田中。负责收取这些货物的“收货人”会佩戴一枚我交给他的特殊戒指。"
D.Strings[116322]="格瑞林：$B$B我的时间很紧张，很多事情堆积在一起，让我抽不出身来，希望你对食人妖的调查不会让我更加繁忙。我授权你对付食人妖，你可以使用任何你认为必要的手段——只要你能找出一个有利的解决方案来。$B$B $B 麦格尼·铜须"
D.Strings[116323]="第三天$B$B 天气很冷。中午下了点雪。$B$B 第四天$B$B 小伙子终于恢复了一些，今天他的精神看来不错，所以我们出去对食人妖进行了第一次侦查。根据它们皮肤上涂抹的标记和所戴的装饰品，我可以确定他们是霜鬃食人妖。"
D.Strings[116324]="第五天$B$B 年轻的学徒守着营地，而我则潜入洞穴观察了一番。食人妖的数量很多，这是个大麻烦，我们得召集大批巡山人才能把他们从洞穴里清除掉。$B$B 最近我似乎没有提到过穴居人，他们在这一带的数量也越来越多了，不过穴居人是个非常原始的种族，不足为患。也许时间可以证明我的看法是对还是错。另外我一个星期都没喝过一滴啤酒了。"
D.Strings[116325]="第六天$B$B 又是寒冷的一天。有雪，有食人妖，没有酒。$B$B 第七天$B$B 地上的雪很白，$B$B 天很蓝，$B$B 狼群又会在夜晚嚎叫，$B$B 一滴酒也没有。"
D.Strings[116326]="第八天$B$B 巨魔的麻烦可能不像我们之前所想的那么严重。他们虽然数量众多，不过没有很好的装备和组织。只要组织小股力量就足以解决他们带来的威胁。"
D.Strings[116327]="我的日记$B$B 过去几个星期所遭遇的恐怖让我几乎崩溃；为什么在书里写下这些文字能让我免于陷入疯狂？也许这样就好像是在对一个沉默的同伴忏悔我的罪行，又像是将那些折磨我的思想从脑中清除，把它们都推到纸上去。$B$B 在此之前，我还写过一次日记，不过那本日记被我放在一个"
D.Strings[116328]="关于寒脊山谷地区霜鬃食人妖活动状况的报告$B$B 由参议院外交特使格瑞林·白须提交$B$B 根据我对寒脊山谷地区霜鬃食人妖的观察结果来看，我认为他们对这个地区的矮人没有太大的威胁。只要军队施以一点援助就可以消除他们的威胁。有了驻扎在寒脊山谷的巡山人"
D.Strings[116329]="和我们的雇佣兵（由参议院拨给我的行动基金来支付必需的费用），我相信我们在短时间内就能解决这个问题。$B$B 铜须陛下已经授权由我来指挥这次行动。"
D.Strings[116330]="关于丹莫洛地区霜鬃食人妖活动状况的报告$B$B 丹莫洛的食人妖大部分聚集在霜鬃食人妖要塞，那是本地区西部的一座巨大的山洞。他们的数量众多，这必须引起我们的注意，但是食人妖们似乎更乐意待在洞内。毫无疑问，这是因为他们不想冒着被灭绝的风险去招惹矮人。即使他们有所行动，那也应该是基于保卫自己领地的原因。"
D.Strings[116331]="我认为只要我们不要去侵犯他们的领地，食人妖对我们就不会构成实际的威胁。一般的矮人平民对这种情形可能并不感兴趣，不过考虑到军事资源的分散，为了谨慎行事，我们应该将消灭食人妖的问题放在一个较为次要的位置去考虑，对我们来说，主要的威胁仍然来自穴居怪和黑铁矮人。$B$B 这里还一并附上了我兄弟格瑞林关于安威玛情况报告的副本。$B$B 森内尔·白须"
D.Strings[116332]="亲爱的塔雷尔：$B$B 请原谅，这封信我写得很匆忙，但时间对于我们来说真的很宝贵。$B$B 挖掘队对泰坦史前古器物的挖掘工作进展迅速。不过我们还发现了其他的史前遗物——一些巨大的骨头。"
D.Strings[116333]="在挖出巨骨后不久，我们遭到了迅猛龙的攻击。来自丹莫德军团的部队英勇作战，但最后他们还是被打败了，几乎全军覆没。我们只有三个人幸存了下来。一个名叫奥莫尔·铁衣的工人非常英勇，是他保护了我和勘察员维尔加的安全。"
D.Strings[116334]="我们在一处隐蔽的洞穴避难，这里目前似乎挺安全。不过在有军队控制住迅猛龙之前，我们还是只能被困在这里。维尔加还在想办法继续工作，但我知道他可能还心有余悸。塔雷尔，这就是我们的处境。请布莱德·长须立刻派一只军队来营救我们。$B$B 即使在这艰难的时刻，我也希望你一切都好。$B$B - 麦琳"
D.Strings[116335]="荆棘谷的青山$B$B 第一天和我们预想中的完全一样。我们大部分时间都忙于为建立营地做一些必要的准备。我在一条淡水河的入口处找到了理想的驻扎点。根据旁边被废弃的古老码头判断，这个地方曾经有人住过，不过只有时间才能说明这里究竟住过些什么人。"
D.Strings[116336]="接下来的几年，在暴风城背叛了石匠公会后，艾尔加丁爵士开始厌恶他的贵族身份。他不愿因继承了他父亲的高贵血统而在贵族中获得崇高的地位。不过我跑题了。这个故事的主题不是政治文章或者人物传记，而是要叙述我在荆棘谷的青山中猎捕的经历。"
D.Strings[116337]="我们在黎明时动身向南出发，一路穿过了伽什废墟。巴尼尔说他担心会遇到血顶部族的食人妖。我告诉巴尼尔，比起生吃我们这些冒险者来，血顶部族更关心的是如何摧毁他们的敌人，劈颅部族。不过巴尼尔显然没有因此而感到一丝的宽慰。但是，我有一把上好膛的火枪、满袋的黑火药，还有三个本领高强的猎人做伴，所以我一点也不担心会遭遇敌人的埋伏。"
D.Strings[116338]="我们匆忙射出的子弹为巴尼尔赢得了足够的逃跑时间。他大声叫嚷着跑下山丘，重新回到队伍之中。我们急忙离开了丛林，因为有一群凶残的鞭尾迅猛龙正在追寻着我们的足迹。$B$B 现在攻守易位，猎手变成了猎物。"
D.Strings[116339]="我为这次探险召集了艾耶克·罗欧克、艾尔加丁爵士和我忠实的仆人巴尼尔·石罐。我曾经在保卫联盟的战斗中与艾耶克的父亲并肩作战，看着艾耶克成长起来让我有种很特别的感觉，她父亲对她进行了严格的武器技能训练。看到她熟练地使用弓箭，我不禁怀疑她的血管里是否流淌着精灵的血。"
D.Strings[116340]="天一亮我们就起来了，巴尼尔开始准备早饭。我注意到艾耶克有点心烦意乱。今天的旅途将会漫长而危险，我们的狩猎行动也许会把我们带向危险。注意力不集中就很容易导致错误，甚至是灾难。艾耶克一直都在盯着在河边清洗餐具的巴尼尔。"
D.Strings[116341]="我们向西部进发，在繁茂的枝叶之间穿行。我们小心翼翼地走在厚厚的落叶上寻找猎物。整个早上都在令人沮丧的沉默中度过，山谷里没有任何激动人心的东西，连一阵微风都没有。到了下午，探险队开始变得不安，巴尼尔的脚步不再像一个追踪猎物的猎手那样谨慎，而是笨拙地踏着步，在枯叶或落枝上踩出响亮的声音来。"
D.Strings[116342]="我们一路狂奔回到了营地，丝毫不敢放慢速度。深夜，我们围着篝火静静地坐在一起，大家心里都明白，我们是被奇异的命运所拯救，这就是狩猎高手活动所带来的风险：我们在和命运玩游戏。然而，我们之中的每一个人都可能会在未来的某一时刻面对命运严峻的考验。我这个老矮人感到高兴的是，这一时刻并非发生在荆棘谷的青山中。"
D.Strings[116343]="尊贵的同僚和求知者们：$B$B挖掘工作仍在继续中，但是由于我最近报告中提到过的穴居人所带来的麻烦，挖掘进度变慢了。虽然一些穴居人比其它的同类更具有攻击性，我依然有信心解决他们。$B$B最近我们发现了很多神器，除了其中一件以外（这件我会在下面进行说明），其它的都和以前发现的区别不大――很有趣，但是没什么启发性"
D.Strings[116344]="有一件东西很特殊――那就是我们最近发现的一个十分特别的神像（我在上次报告中对它作过简单的描述），这个神像似乎对这里的穴居人有某种影响力。他们都受到它的吸引，有些甚至变得极度疯狂！$B$B我们还需要进行更深入的研究才能了解这些神像的真正作用。不过我相信，我们可以从中找到穴居人和泰坦之间的联系"
D.Strings[116345]="最后，我必须再次强调我对炸药粉的迫切需求。我这里的存货已经非常少了，这会严重地阻碍挖掘行动的进展。我听说新的炸药粉补给会很快送来，但是我一直都没有收到。$B$B能否告诉我到底是什么原因导致这批货还没有运达我这里？$B$B此致，$B勘察员基恩萨?铁环"
D.Strings[116346]="所有的事情都是从我找到罗兰之墓里那把被诅咒的镰刀时开始的。对，就是从那时开始……在找到它之前，这个地区看起来与北郡山谷一样平静。$B$B 但是当我发现了露在碎石堆外的那把镰刀的柄之后，一切都变了，该死的，当时我居然把它拔了出来，从此之后，罗兰之墓就变成了恐怖滋生之地!~"
D.Strings[116347]="如果我早知道会发生这样的事，我当初就算把自己的手砍了也决不会去抓那块雕着符文的木柄。我真是追悔莫及啊!后悔，我一直以为这是老人的特权，但现在我明白了，其实让人被后悔所缠绕的不是年岁，而是绝望，它让你再也无法摆脱后悔，只能饱受痛苦的煎熬。$B$B 不过我已经像个诗人般喋喋不休好半天了。现在，我得继续我的日记……"
D.Strings[116348]="自从拔出那把镰刀之后，矿坑里就开始发生变化。火把的光焰总是向一边倾斜，而我们对自己的声音也失去了控制。有时一个人的细声低语会突然变成吼叫声，传遍整个隧道，让人不得不掩住耳朵；而有时即使我们放声大喊，那声音却传不了多远就变得极其微弱，直至消失在风中。$B$B 这让我们十分紧张，不过我们很快就不再担心这件事情了。因为有另一种力量将我们从矿坑里赶了出去——那就是狼人。"
D.Strings[116349]="狼人从四面八方向我们袭来，从洞里冒出来抓向我们，或是从树上跳下来扑向我们。我们中的半数人在惊恐中被瞬间干掉，剩下的人都开始没命地逃跑。我看到自己的兄弟一个个丧身在狼人的尖牙或利爪之下，惨叫声不断划破寂静的森林。$B$B 据我所知，我是唯一一个逃出那个地方的人。"
D.Strings[116350]="我不知道那个晚上为什么独有我能生还。我一直都很小心，灵敏地避开狼人的袭击，每一次闪躲都准确无误。我的绰号“胆小鬼”就来自于我的这个特点。也许正是我的谨慎小心救了我……$B$B 也许是我从碎石堆里挖出来的镰刀救了我。不过，这不可能是镰刀本身的作用，因为我在逃跑途中把它给弄丢了。但如果是我把狼人引到暮色森林的话，那么也许它们是因为这一点而放了我一条生路。这些该死的狼人！"
D.Strings[116351]="也许我命中注定应该活下来亲眼看着我给暮色森林带来的巨变，亲眼看着狼人撕裂这片土地，以邪恶将这里玷污。$B$B 如果这就是我的命运，那我的命运远不止这么糟糕。将魔爪伸向暮色森林的不仅仅是狼人——还有来自逆风小径的恶魔。$B$B 我的下一谷?日记就要记述这些，我希望那也是最后一章……"
D.Strings[116352]="从罗兰之墓侥幸逃出来后，我躲在一个斯温家的谷仓里。我在那里面过了好几个星期，一直都被恐惧所笼罩，也不敢让斯温和他的家人知道我的存在。虽然从我对他们的观察来看，这些农夫都是些很本分的平民，而且如果我从藏身的地方走出去，他们也一定会接纳我住在他们家里，不过对我而言，要信任别人是十分困难的——尤其是经历了矿坑里那恐怖的一幕之后。$B$B 因此我躲在那儿，一直没有现身。"
D.Strings[116353]="在我来到这座农场几天后，斯温准备去一次夜色镇。他吻了吻他的妻子，然后微笑着和孩子们告别，并保证会很快带着玩具和糖果回来。可怜的人，那是他和全家人最后一次在一起……$B$B 至少他们是快乐地分别的，至少他的妻子第一个死去，没有亲眼看到她的孩子们被屠杀。但这对我来说没有用。我看到了所有的惨剧，而这一切从此一直不断在我的梦里出现。"
D.Strings[116354]="现在回忆起当晚的细节，我的手还禁不住颤抖。斯温离开之后，他的家人不得不独自面对可怕的黑骑士。悔恨的感觉一直缠绕着我，当时我就在那里，我本应该跳出来与那些从逆风小径来的恶魔战斗。也许这是一种虚假的悔恨，对于每一个逃过悲剧的幸存者来说，情形也许都是一样的。我知道，如果我从藏身的地方走出来，我也会和他们一样被杀戮，我的身体也会被撕得粉碎。"
D.Strings[116355]="不过，虽然我很清楚自己无法阻止那场残酷的杀戮，我的心中还是怀着深深的悔恨：是我将黑骑士引到了斯温的农场。我发现的镰刀不仅将狼人引到了暮色森林，它还引来了逆风小径的黑骑士。$B$B 那时，斯温的妻子紧紧搂着孩子们，想给他们一些安慰，但是她知道死亡必将来临。黑骑士杀害他们之前还问了斯温的妻子一个问题，这让我知道了所有的一切。"
D.Strings[116356]="“月神的镰刀。”一个骑士用凄厉刺耳的声音叫道，就像在石头上磨斧头的那种声音。当喊出“镰刀”这个词的时候，这个声音变得嘶哑起来，好像窒息了一样。$B$B 我一听到那个声音，立刻就被恐惧笼罩了，一方面是因为那个声音非常可怕，另一方面……我知道那个骑士所说的镰刀是什么。那一定就是几天前我在罗兰之墓的碎石中拔出的那件该死的东西，那就是黑骑士们所要寻找的东西!$B$B 它就是给斯温一家人带来灭顶之灾的罪魁祸首。"
D.Strings[116357]="我一直以来都不知道她的名字，因为她的丈夫和孩子总是叫她“亲爱的”，“宝贝”和“妈妈”。但是我很希望知道她的名字，我是唯一一个见证她当时的英勇行为的人。虽然她只是一个农夫的妻子，但是我从来没看到过有人能像她这么勇敢。$B $B 她当然不知道那把镰刀是什么东西，但是当她知道黑骑士在寻找镰刀时，就突然想到了一个计划。$B $B 那是个大胆而聪明的计划，如果她能成功的话，那该有多好！"
D.Strings[116358]="“镰刀?”她平静地问道。“我当然知道。这儿谁不知道?”她的双眼坚定地望着骑士，如果不是因为我知道实情的话，我一定也会相信她所说的话——虽然她根本不知道关于镰刀的事情。$B$B 她的这一招奏效了。那个提出问题的骑士轻微地低下头凑向她，然后尖声说道：“在哪里?”$B$B “我可以带你去，带你们一起去。”她回答道。我看到她的眼中闪过一丝希望。"
D.Strings[116359]="“不过路很远，带着孩子会拖累我们，必须得把他们留下。”$B$B 她的计划很简单，不过简单的计划成功的可能性最大。如果她成功了，就能让那些强盗远离农场。她可能会因此而死，可是孩子们就安全了。如果强盗相信了她那崇高的谎言，这个计划就能成功。$B$B 虽然我从未信仰过圣光之道，但是当斯温的妻子勇敢地站在那帮可怕的强盗面前时，我仍然虔诚地为她祈祷。$B$B “让他们相信吧。”我祈祷着。"
D.Strings[116360]="他们站在那儿一动不动，而她也平静地面对着他们的凝视。这时一个骑士抬起眼，仿佛在聆听远方的召唤。他从衣服里拿出一块宝石，向它望去。他用宝石在斯温妻子的面前晃动。一股光芒从骑士的身上缓缓冒出，随即变成了一只恐怖的白色的手，伸向那个女人。她毫无畏惧地望着这股光芒，不过我已经看出她自信背后的一丝不安。那只手伸向她，用手指罩住了她的脸庞。"
D.Strings[116361]="斯温的妻子像一尊雕像一样直直地站在那里，眼睛睁得大大的。虽然她的嘴唇张开着，似乎是在尖叫，但是她却始终无法发出声音。过了一会儿，那只折磨着她的手终于松了下来，把她丢在地上。拿着宝石的那个骑士巍然正坐在马鞍上，一个声音从他口中传出。$B$B “这个女人在撒谎，”那个可怕的声音时常在我梦里出现，“她没有见过镰刀。”"
D.Strings[116362]="然后，骑士的肩膀瘫软了下去，好像躯壳中的灵魂突然离它而去。随后，那个苍老而尖厉的嗓音又响了起来，他说的最后一句话是：$B$B “大人下令了，杀掉他们。”"
D.Strings[116363]="我无法描述接下来所发生的事情。它深深地刻在我的脑海里，但是我脆弱的灵魂无法把它写下来，那是短暂而又无比恐怖的时刻。$B$B 我只能写下事情的结局：斯温的一家都被杀害了。没过多久，斯温回来了，他看到了这一片死亡的惨景，悲痛欲绝，这使我不敢现身。我不敢让他找到我，于是我就从农场里逃走了。我也不知道斯温现在在哪里，但是我希望有一天他能平静下来。"
D.Strings[116364]="镰刀被拔出之后，狼人从四面八方向我们袭来，从洞里伸出爪子抓向我们的腿，或是突然从树上跳下来扑向我们。我们中有一半人在惊恐中被杀掉，包括我在内的幸存者都在没命地逃跑。在逃跑时，我看到自己的兄弟一个个丧身在狼人的尖牙或利爪之下，尖叫声不断划破寂静的森林。$B$B 据我所知，我是唯一一个逃出那个地方的人。"
D.Strings[116365]="<书中剩余的部分是空白的>"
D.Strings[116366]="报告：关于狗头人$B$B 北郡山谷中狗头人的活动日益增加。他们在修道院的北面和回音山矿坑里建立了营地，而且数量众多。我已经召集了一些圣骑士、战士以及当地居民去帮助我们对付这帮歹徒。$B$B 现在一切进行得很顺利。我会及时向您汇报最新进展的。"
D.Strings[116367]="报告：关于盗贼$B$B 比狗头人更令人担忧的是，一群人类的盗贼出现在山谷里。他们带着红色的面罩，自称为兄弟会的成员。这种组织会给本地和整个艾尔文森林带来威胁。$B$B 我们已经查到了他们的一个首领——加瑞克·帕德弗特，希望能够很快对他进行审判。"
D.Strings[116368]="报告：关于狼群$B$B 关于狼群袭击北郡的报告最近有所增加。伊根认为狼群数量的增加主要是由于许多狼都从暮色森林来到了山谷中。$B$B 虽然狼群很少袭击人类，但是它们数量的激增给农夫增加了很多麻烦。这段时间来已经发生多宗家畜失踪事件了。"
D.Strings[116369]="嘉奖：$B$B 传递此公文者将会被授予暴风城军队代表的头衔，以证明他/她曾全力帮助过北郡。我相信您将会发现这个人也可以帮助艾尔文森林。$B$B 署名：$B - 治安官杜格拉斯·玛克布莱德，$B 暴风城防卫军，北郡"
D.Strings[116370]="杂味炖肉$B$B3份秃鹫肉条$B3个血牙野猪的头$B3颗鱼人人的眼球$B3根秋葵$B$B把以上各种材料都混在一起烹煮至少两小时后方可食用。"
D.Strings[116371]="亲爱的伊维特：$B$B 我将委托我们这里最迅捷的信差将这封信交给你，希望他能设法穿越我们之间茂密的森林。我希望你能读到这个，因为这将是你最后一次收到我的消息了。$B$B 在这黑暗的日子里，只有当我知道了你不会再经受我所经受的厄运，我才能感到些许的安慰。"
D.Strings[116372]="我担心斯通菲尔德和马科伦家族之间的勾心斗角会毁掉汤米·乔和梅贝尔之间的爱情，在现在这个时代中，即使面对再多黑暗的威胁和战争的阴影，我们也应该努力去呵护爱情和年轻的生命。$B$B 所以，我希望你能帮忙制作一些隐身药水，让这两个年轻人能够相聚。$B$B 谢谢你，威廉。还有，当你空闲的时候别忘了多来我这里玩玩。我们已经有好久没见过面了，我十分怀念以前与你一起度过的快乐时光。$B$B - 米莱德"
D.Strings[116373]="由暴风城建筑官员巴洛斯·艾力克斯顿亲自提交$B$B 陛下：$B$B 我之所以写这样一份报告，是因为我觉得应该对迪菲亚兄弟会这个组织最近的动向及其在王国领地内的所有活动向您做一汇报。$B$B 为了把他们的情况解释清楚，请允许我我首先介绍一下这个组织的一些背景。或许您并不知道，我以前曾是暴风城石匠公会的会员。经过多年的辛勤工作，我们完成了暴风城的重建，而石匠公会却没有收到分毫的报酬，甚至根本没有人提及。"
D.Strings[116374]="当时任石匠公会会长的艾德温·范克里夫多次索要暴风城拖欠的报酬，而暴风城贵族议会的回应却是命令石匠公会解散，这当然激怒了范克里夫。他发起了一场暴乱，带领石匠公会的人离开了暴风城。$B$B 在我继续讲述之前，还有一些发生在那时的其他事情应该让你了解一下。"
D.Strings[116375]="首先，正是在那个时候，暴风城的贵族向我许诺说，如果我能脱离范克里夫的组织，他们就可以让我担任城市建筑师的职位。由于和他的一些思想有分歧，我便选择了留在暴风城。$B$B 暴乱期间，范克里夫最信任的助手巴基尔·斯瑞德被俘，一直关在监狱里等待审判和盘问，现在几乎已经被人遗忘了。"
D.Strings[116376]="话题还是回到范克里夫吧。在他带领石匠公会的残部逃出了暴风城，当时西部荒野几乎没有驻扎任何暴风城的军队，他就利用这种情况驱逐了那里的农夫，并且控制了当地的金矿。$B$B 利用他所掌握的资源，范克里夫计划对暴风城政府进行复仇。$B$B 这些情报是由送交这份档案的人收集到的，这个人也及时帮助我们揭露了这个大阴谋。"
D.Strings[116377]="可根据情况决定是否公布以下消息。$B$B 提瑞斯法林地区命令$B 麦罗斯队长$B 瓦松队长$B 派瑞恩队长$B$B 由总指挥官下达的命令。$B$B 派瑞恩队长，进一步加强西南城堡的防御（按计划行事）。更多的补给将在稍晚些时候送达。同时，在附近的农场征收必需的物资，并对布瑞尔地区的亡灵进行必要的侦察和情报搜集工作。"
D.Strings[116378]="瓦松队长，北部城堡一带的不死生物活动日益增加，必须快速果断地消灭这种活动。$B$B 麦罗斯队长，瘟疫之地边界地区的不死生物正在不断集结。增援部队将在接下来的几周内到达你的辖区。$B$B 为圣光的荣耀而战！"
D.Strings[116379]="第1天$B$B 我的坦克坏了，但是我知道我们要找的那种矿石就在山中的某个地方，我让塞克·锤足留在这里看着坦克。$B$B 我要继续独自寻找。如果我不能回来的话，这将成为我最后的遗嘱。$B$B 驾驶员莫里·铁钻$B 铁炉堡攻城坦克旅"
D.Strings[116380]="第2天$B$B 我继续寻找，但没有找到矿石。我不知道这是不是石轮那家伙跟我们开的玩笑，如果是这样的话，等我回到钢架补给站，他可就惨了!$B$B 今夜，在我搭建营地的时候，我听见有一声咆哮在山谷中回荡。$B$B 那听起来不像是狼，似乎更像是一只熊。"
D.Strings[116381]="第3天$B$B 那个咆哮声持续了一夜，今天白天还一直跟着我，让我没法专心寻找矿石。我想确实是有一头熊跟着我!$B$B 我希望它能靠近点，那样我就可以把手里的锄头插在它的脑袋上了。"
D.Strings[116382]="第4天$B$B 我的补给越来越少了。我有足够的食物，不过我从没想到会离开我的坦克在野外待这么久的时间，而且还只带了两小桶酒。$B$B 前两个晚上我都没有睡觉，一直在听着那该死的咆哮声，我的酒都差不多喝光了!$B$B 我明天得回到我们的坦克那儿去，我可不想在没有酒喝的情况下在这里迷路。"
D.Strings[116383]="第5天$B$B 我碰到了那头该死的熊!它在光天化日之下向我发起攻击，咆哮着从我身后袭来。$B$B 要不是风向不对的话，我肯定可以闻到它的气味。它那身臭毛皮和腐烂的气味就足以让我发晕了!$B$B 我和它打斗了一番，但它咬住了我的腿。现在我不能动了，我的酒也没了，而且更糟糕的是我还没有找到那块矿石。该死!"
D.Strings[116384]="第6天$B$B 那头熊没有回来——我一定是把它打成重伤了!不过我还能听到它的咆哮，它大概是在等着我死掉!$B$B 不管是谁发现这本书，我都要托付给你一个任务。杀了那头肮脏的熊!杀了它，再把这本书交给我的朋友塞克·锤足，让他知道发生了什么事。$B$B 拿着我的护甲，你会用得到它的!"
D.Strings[116385]="通过对各种生物化石的研究，我已经推测出在很久很久以前曾有一场大瘟疫横扫了整个洛丹米尔湖。是什么导致了这次瘟疫?我们也许永远都不会知道。但是根据散布在湖床里的残留物可以知道，当时污染的程度是非常高的。"
D.Strings[116386]="为了揭开这个秘密，我已经开始对现存的生物进行研究，以此来寻找线索。湖岸潜藏者和湖岸爬行者都是居住在洛丹米尔湖中央的古老动物，它们身上长着一种苔藓，和某些化石的痕迹有些相似。我还需要进行更多研究才能推测出其中的联系。"
D.Strings[116387]="比索·埃斯沙德大人：$B$B 遵照您的指令，我派遣这个$c来为您效力。$B$B $g他:她;非常可靠，而且听从指挥，在对付天灾军队的过程中证明了自己的实力，所以我选择$g他:她;来协助您完成任务。$B$B 祝您安好，$B - 执政官塞弗伦"
D.Strings[116388]="失踪：基沙恩下士    他在石堡要塞的血腥战役中失踪，据说已被黑石兽人俘虏。    基沙恩下士应该是被关押在湖畔镇北面的黑石营地中，也就是通往燃烧平原隘口的西边。    根据所罗门镇长的命令，任何救回基沙恩下士的勇士都将受到治安官马瑞斯的嘉奖。"
D.Strings[116389]="您好，主人。$B$B 请原谅我用这种方式给您写信。奥特兰克的暗影法师正在忙于他们的计划，我不得不使用外面的——从我们新的“盟友”中招募的——信差给您送信。但我用了我们最深奥的密码来撰写这封信的具体内容，所以由这些乡巴佬送信是非常安全的。"
D.Strings[116390]="瓦里克：$B 管好那些奴隶，等我们回来。继续在这里保存它是很危险的。我们将到北方去，到一个不可能被发现的地方去。$B$B 它们只不过是动物，不过是凶残的动物——只要它们有了一定的数量，我们就有大麻烦了。绝对不能让它们集结起来，这是我最不想看到的事情。"
D.Strings[116391]="迪菲亚总部来的一队人会与收货人联系，后者会将他收到的黄金进行转交。$B$B 一定要确保这个过程谨慎无误地完成。负责转移黄金的是收货人，不过迪菲亚兄弟会的每个成员都有责任帮助他完成任务。"
D.Strings[116392]="我的兄弟们，记住，我们曾经是值得骄傲的工匠。我们要用工匠惯有的缜密和谨慎来完成现在的任务。"
D.Strings[116393]="恐怕当初我父亲决定留下来守卫家园是个严重的错误。亡灵的部队已经席卷了提瑞斯法林地，虽然我们做好了防御的准备，而且补给也很充足，但是由于我兄弟代弗林的背叛行为，现在我们缺少足够的人手来抵抗亡灵的不断袭击。$B$B 伊维特，如果你接到了这封信，那么你一定要明白，代弗林是叛徒。"
D.Strings[116394]="代弗林因为感到绝望而临阵逃脱，他与亡灵签订了一份协议。我不知道他的背叛行为到底给他带来了多少好处，但是我知道其中必定有诈。$B$B 如果你看到我的兄弟，那就快点逃跑吧，因为他已经变成了一个恶魔。几天前的一个夜晚，他杀死了两个看守，趁我们都在睡觉时把一小队亡灵带了进来。"
D.Strings[116395]="他们发起了凌厉的攻势。在我们干掉这些偷袭者之前，他们又杀了一个人。现在我们没有足够人来守卫边界。要不了多久，我们就会筋疲力尽，而亡灵又会发起攻击。$B$B 虽然那天晚上我在那些拼死作战的人和面色憔悴的亡灵中看到了代弗林的脸，但是在我抓到他之前，这个懦夫就溜走了。也许他已经死了，也许他还活着，给亡灵当间谍。$B$B 不管怎样，他都是个怪物。"
D.Strings[116396]="代弗林警告过我们，与亡灵为敌必死无疑。早在我们被包围之前——大概就是亡灵刚刚进入提瑞斯法林地的时候，他就说过这话。也许他是想恳求我们离开，也许他是在幸灾乐祸。$B$B 我总是很难理解代弗林的动机，他从小就是那么神秘。"
D.Strings[116397]="不过他是对的，我们的确失败了，阿加曼德家族将会从此消亡。虽然我现在还活着，但我知道自己的死期也不远了。$B$B 我并不害怕，也不后悔留下来和家人待在一起，不过我最后牵挂的还是你。$B$B 你要好好活下去，我亲爱的伊维特，那样我才能安息，$B - 萨尔曼"
D.Strings[116398]="我们的计划进行得很顺利，正如以前提到过的一样，我们与一队自称辛迪加组织的人类结了盟。他们的首领以前曾是奥特兰克的贵族，他们希望能再次控制这里。$B$B 因此，这些愚蠢的人类与我们达成了一个协议，他们将会为此而后悔。"
D.Strings[116399]="现在辛迪加组织在这边的势力还很小，不过他们对这一带非常了解，并且有充足的人力。我相信只需加以适当的引导，辛迪加就能再次统治奥特兰克。$B$B 而且，我们已经督促辛迪加向附近阿拉希高地的激流堡城进军。我们的军队、巨魔，还有激流堡的人类在那里展开了一场旷日持久的战斗，不过我认为，只要有正确的策略，我们就能占据那座曾经伟大的城市。"
D.Strings[116400]="希尔斯布莱德城镇文档$B$B 希尔斯布莱德的人民发誓将永远效忠于伟大的铁炉堡国王麦格尼·铜须和暴风城国王安度因·乌瑞恩所建立的联盟。$B$B 此档是为管理奥特兰克地区的城市而建立，并为国王和联盟的纳税人服务。"
D.Strings[116401]="教师卢瑟福·博塞德$B 债务已还清。$B$B 铁匠埃沃里·维林塔$B 债务已还清。$B$B 书记员霍拉斯·怀特斯蒂$B 债务已还清。$B$B 议员吉利斯$B 债务已还清。$B$B 议员胡克斯$B 债务已还清。$B$B 农夫盖斯$B 债务已还清。$B$B 农夫雷恩$B 欠款，收获时以农作物偿还。$B$B 农夫莱恩$B 欠款。租地被收回。"
D.Strings[116402]="农夫卡拉巴$B 欠款，收获时以农作物偿还。$B$B 平民维尔克斯$B 债务已还清。$B$B 平民博诺安$B 债务已还清。$B$B 矿工威尔迪$B 欠款，碧玉矿坑送来下批矿石时偿还。$B$B 矿工西尼$B 欠款，碧玉矿坑送来下批矿石时偿还。$B$B 矿工哈克特$B 欠款，碧玉矿坑送来下批矿石时偿还。 'row2'>矿工奥维尔$B 欠款，碧玉矿坑送来下批矿石时偿还。$B$B 矿工菲格拉德$B 欠款，碧玉矿坑送来下批矿石时偿还。$B$B 平民奈杉德$B 债务已还清。$B$B 平民梅恩$B 债务已还清。$B$B 工头邦德斯$B 欠款，碧玉矿坑送来下批矿石时偿还。"
D.Strings[116403]="一支不死族小队毫不顾忌人类和不死族之间的对立关系，到我们这里来寻找他们的“同胞”。克甘达玛是这支小队的队长，他的皮肤已经腐烂，他的血液早已停止了流淌，但他却显得彬彬有礼，他对同伴安全的关心甚至胜于关心他自己。$B$B 实际上，我甚至觉得他拥有我周围的人已经丧失许久的人性。"
D.Strings[116404]="但是我为什么要提到这个?我之所以这样做是为了表明我将要写下的东西是可信的，因为这些话来自克甘之口，我希望我的同胞看到这本日记，知道我为什么要相信他的话：$B$B “还有一些上古之神在世界的深渊中游荡，新的势力在寻找支配这些古老力量的方法，谁成功了，谁就将得到一件可怕的武器去对付他的敌人。”"
D.Strings[116405]="这就是克甘达玛将他的血石坠饰递给我时所说的话，那时他的眼里还带着某种恐惧或是敬畏。他的手接触到我的手时犹豫了片刻，好像不愿放弃那个坠饰。一股反感的力量传遍了我的全身，而至今我还不清楚当时是我自己排斥他那已死亡的肉体，还是坠饰本身让我毛骨悚然。$B$B 因为我感到了坠饰中隐藏的力量，那是一股深沉、隐蔽、饥渴的力量，它似乎极度希望被释放出来。"
D.Strings[116406]="我在达拉然的同事对研究克甘带来的血石不太感兴趣，而是很快隔离了那四个流亡者，并把血石继续留在他们身上。但是克甘的真诚促使我开始着手研究他的血石坠饰。"
D.Strings[116407]="我希望能够和我的同事通过研究证明那种石头确实具有某种魔法特性，如果达拉然的巫师不希望发掘血石的能量，那么我们至少应该了解它的特性，因为我们的敌人也许会利用血石对付我们。$B$B 所以我的研究开始了。"
D.Strings[116408]="在实验的第一阶段，我假定血石是一种岩石，比如石英石或黑曜石之类的。于是我做了一系列实验以确定血石所含的矿物成分，以及与其颜色、硬度等特性有关的成分。令我沮丧的是，这块血石和一般的矿石不一样，我的实验毫无结果。"
D.Strings[116409]="事实上，血石常常出现和我的预期完全相反的反应!它好像在故意和我的实验作对。$B$B 它似乎是具有生命的，而且还会思考。$B$B 虽然很恼怒，但我并不气馁，我决定不再把它当作一块没有生命的岩石来研究。$B$B 然而我又一次失败了。"
D.Strings[116410]="我的所有新实验都无法揭示这块血石的来历。我那时所解开的唯一一个谜就是：血石既不是活的，也不是死的!$B$B 不过正是在失败的边缘，我迎来了一个大突破。我最近的实验里使用了一只玻璃杯，杯口边有个小小的锯齿状的缺口，在实验又一次以失败告终之后，我去打扫工作台，结果一不小心被那个杯子割伤了手。"
D.Strings[116411]="伤口不深，但是血流不止。在我开始用绷带包扎受伤的手指时，已经有很多血流到了工作台上。$B$B 此时我发现了一件很奇怪的事情……"
D.Strings[116412]="溅在血石坠饰周围的血似乎受到了某种引力的作用，全部都被吸向那块宝石。血液一碰到坠饰就消失了，而在吸收了我的血之后，石头的红色变得更深了。"
D.Strings[116413]="看到这个，我的头脑一下子清醒了不少，也许是因为我的新伤口（虽然我不敢相信自己居然流了那么多血），也许是因为在屡遭挫折之后终于发现了血石的秘密。我坐下来开始思考，脑中不断涌现各种想法和问题，这让我头晕目眩、摇摇欲坠。$B$B 血石会吸收鲜血?它渴望鲜血吗?它还会吸引鲜血?"
D.Strings[116414]="或许血石是用血制成的?如果是这样的话，那它所用的是谁的血呢?我的?任何人类的血?或是随便什么动物的血?$B$B 也许血石是用某种未知事物的血制成的，就是克甘将坠饰交给我时又惧怕又崇敬的那个东西。$B$B 我一定要找到这个问题的答案，它是一切的关键。"
D.Strings[116415]="这重新激起了我的热情，我又投入到研究之中。这次我没有做假设，而是系统地完成了各项试验。这需要我更加努力地工作，当然也意味着会有更大的发现。$B$B 另外，尽管我的实验室很小，而且没有助手的帮助，但是我终于发现了血石的另一个有趣的特点。"
D.Strings[116416]="除了血，还有一些自然力量附在这块石头上。火，水，雷，石，它们与血混合在一起（但这个问题仍然存在：到底是谁的血?），虽然这种混合物外表上看起来很平静，但是各种力量在它内部相互争斗着。这让我对这个奇怪的不祥之物有了更多的疑惑。"
D.Strings[116417]="不过要回答这些问题，还需要对坠饰进行更多的研究和实验，洛丹米尔收容所恐怕无法提供相应的人力和设备。因此我派了一个信差把血石坠饰送到达拉然去，并给他们提供了关于如何进行实验的具体说明，以免他们重复我曾经犯过的错误。"
D.Strings[116418]="在等待那里的实验结果的日子里，我又去找克甘谈了谈。尽管我不断逼问他关于血石的事，他却没有再多说一句。他也很少提及在他所属的不死生物群体——他称之为“被遗忘者”——那边度过的日子。"
D.Strings[116419]="但是克甘看起来更喜欢谈点别的东西，特别是在洛丹伦沦陷之前他在那里成长的时光。$B$B 他依然深深地爱着那个现在已经变成一片废墟的王国。$B$B 克甘越来越吸引我，这使我不再那么焦急地等待实验结果了。"
D.Strings[116420]="可是过了几个星期还是没有收到消息，我的耐心开始动摇了。向达拉然询问之后，我才得知血石居然根本没有送到我同僚的手上。我的信差在半路失踪，血石也和他一起消失了!$B$B 这是个沉重的消息。虽然克甘和他的人还有血石样本可以供我实验，不过我担心这枚坠饰会落在邪恶势力的手中。"
D.Strings[116421]="我已经派了另一个信差去达拉然，并且听说他们现在已经开始在我们的保护范围之外的废墟中搜索那枚坠饰了。$B$B 我只希望我们行动得不是太晚。"
D.Strings[116422]="游荡者格里雷克的故事$B$B [……碑文的头几行已经被磨损得无法看清了，不过最后几行还可以辨识……]$B$B 格里雷克跺着脚穿越丛林。因为愤怒，他的双眼冒着火，嘴里发出低沉的声音。$B$B 他高举左手朝天怒吼着。经过长期的狩猎，他的左臂显得异常强壮。$B$B 格里雷克很久之前就永远地失去了他的右臂。"
D.Strings[116423]="食人妖传说，第三卷$B 海潮之石$B$B 作者：大法师安斯雷姆·鲁因维沃尔$B 达拉然$B$B 序言$B$B 古老的古拉巴什帝国是许多令人着迷的传说的发源地，这些传说毫无疑问和他们周围的环境有关，因为通过对他们的信仰和社会习惯的研究，我发现他们对于自然表现出了极度的尊崇。$B$B 在上一卷中，我已经详细描述了食人妖对于蛇的崇拜，在这一卷中我要谈的是他们与大海的有趣而独特的关系。"
D.Strings[116424]="库德兰·蛮锤    着名的巨龙战士，鹰巢山的狮鹫飞行员，进攻德拉诺兽人世界的联盟远征军狮鹫分队的指挥官。可能已阵亡。    “我们将听到风中传来狮鹫的召唤，我们将听到战锤敲击的声音回响在山间。勇敢地面对困境吧，我的兄弟。祖先的圣堂在召唤着你。”    - 弗斯塔德·蛮锤，鹰巢山国王"
D.Strings[116425]="游侠队长奥蕾莉亚·风行者    奎尔萨拉斯着名的游侠，令巨魔闻风丧胆的猎人。进攻德拉诺兽人世界的联盟远征军侦查队长兼情报特派员。可能已阵亡。    “你的心如利箭，在风中笔直地飞翔，我的姐妹。你是我们军队中最聪慧的勇士，也是我们族人中最受敬爱的领袖。”     - 希尔瓦娜斯·风行者，奎尔萨拉斯游侠将军"
D.Strings[116426]="\"肯瑞托的卡德加大法师    麦迪文的学徒，进攻德拉诺兽人世界的联盟远征军最高指挥官。可能已阵亡。    “没有人能够如此无私地深入最黑暗而危险的战场。不管你在哪里，我们都希望你一路顺风，勇敢的流浪者。”        - 安东尼达斯，达拉然大法师"
D.Strings[116427]="图拉扬将军    安杜因·洛萨公爵的将官，白银之手骑士团的圣骑士，进攻德拉诺兽人世界的联盟远征军的高级将领。可能已阵亡。    “Esarus thar no'Darador' - 我们以鲜血扞卫荣誉。  我的朋友，你是公正与美德的化身。你的名字将是我们永远的荣耀。”    - 光明使者乌瑟尔，白银之手骑士团"
D.Strings[116428]="达纳斯·托尔贝恩    激流堡的民兵指挥官，进攻德拉诺兽人世界的联盟远征军总指挥官图拉扬将军的战略顾问。可能已阵亡。    “孩子，你的经历和牺牲将永远被我们铭记。自我们的光辉帝国建立之日起，英雄的鲜血便浸透了整个帝国的历史。”  - 索拉斯·托尔贝恩，激流堡公爵"
D.Strings[116429]="光明使者乌瑟尔在此安息$B$B 第一圣骑士 - 白银之手骑士团的奠基人$B$B 乌瑟尔誓死保卫洛丹伦王国，尽管他最心爱的学生背叛了他，但我们相信他的灵魂永生。即使厄运降临于我们的故土，他依然在关注着我们。他的光芒将照亮所有人类前行的路途 - 只要我们依然以他为榜样，它就永远不会消失。$B$B          - 无名氏"
D.Strings[116430]="无尽之海$B$B 古拉巴什帝国三面环海，因而水就自然成为了食人妖部落元素信仰中的一个重要组成部分。虽然食人妖能够在他们丛林帝国的广袤土地上肆意妄为，可是大海却丝毫不受他们的影响。大海是如此浩瀚而又神秘莫测，即使对强大的食人妖来说，它也是个令人不安的邻居。"
D.Strings[116431]="值得注意的是，最近的发现表明，食人妖对跨越无尽之海的兴趣似乎非常小。虽然在整个艾泽拉斯、洛丹伦和卡兹莫丹地区都有食人妖出没，但是在新大陆卡利姆多及南海的岛屿上却没有食人妖文明的迹象。"
D.Strings[116432]="这是否证明食人妖不愿冒险离开他们的领土，或是他们缺乏长途旅行所必需的相应技术？这一点还有待进一步研究分析，但它已经不是本文要探讨的了。$B$B 不过有一样东西会引起所有人的注意，最近在荆棘谷的大片食人妖废墟中找到的线索显示了食人妖和大海相关的一面，这一面以前从未为人所知，也没有相关的史料记载。$B$B 海潮之石$B$B 最近在荆棘谷食人妖废墟中的发现涉及到了一件叫做“海潮之石”的东西。"
D.Strings[116433]="将食人妖传说中的许多片段结合在一起，我们便可以得到关于这块石头的完整描绘、以及它对古老的古拉巴什帝国的重要意义。$B$B 海潮之石似乎可以将支配各种形式的水的力量赋予其拥有者，包括对河流、雨水和潮汐等形式的支配。根据这些和海潮之石的用途有关的故事，我猜测它实际上是水之领主的力量的物质表现形式。"
D.Strings[116434]="这件东西如何乃至何时摆脱水之领主的控制而落入食人妖的手中，这则是另外一个问题，对我来说也还是个谜。$B$B 控潮者$B$B 和潮汐的涨落一样，海潮之石进入了食人妖的世界，然后又消失，每一次在食人妖手中停留??时间决不会超过一代。"
D.Strings[116435]="根据食人妖的传说，海潮之石第一次来到古拉巴什帝国，是被一个食人妖战士在荆棘谷海岸边闲逛时发现的。他看到了这块神奇的蓝色石头，石中还浮动着乳白色的线条。战士带着这块有趣的石头继续旅程。$B$B 过了一段时间，战士发现这块石头能给他带来控制水的能力。"
D.Strings[116436]="他可以借此召唤完全由水组成的生物：水元素——原本只有肯瑞托的大法师才具有这种能力。$B$B 这个战士来到了帝国的核心地带祖尔格拉布，向国王展示他的能力。显然，他迅速成为了全帝国关注的焦点。古拉巴什的国王也被他的能力折服，立刻给他封了一个荣誉职位：“控潮者”，而他原来的名字则逐渐被遗忘了。"
D.Strings[116437]="接下来的很多年里，控潮者都在为古拉巴什帝国效力，他在战斗中召唤水元素助阵，为了帝国改变荆棘谷的水流。不过时间久了，控潮者开始喜欢隐居独处，他离开皇宫的时间也越来越久。$B$B 控潮者对古拉巴什帝国隐瞒了一个秘密——海潮之石在赋予他强大能力的同时还对他施加了一个诅咒。"
D.Strings[116438]="随着时间的流逝，控潮者的身体开始渐渐消失。随着潮汐的每次涨落，他都会失落一部分肉身——身体一会儿出现一会儿消失——直到临死时，他来到了最初找到石头的那片海滩，步入大海，从此消失。$B$B 又经历了好几代的时间之后，海潮之石再一次被冲到荆棘谷的海岸上，又被另一个控潮者拾得，然后这个食人妖又将它带到祖尔格拉布去。"
D.Strings[116439]="这样的过程一代接一代地不断发生，石头随着潮汐出现，控潮者随着潮汐离开。$B$B 今天，到处都有关于潮汐之石的故事，但是依然有一个疑问，为什么这个具有如此强大能量的东西会出现得这么有规律?这一切究竟是由谁掌控的?"
D.Strings[116440]="我让尼哈鲁船长把斩浪号从东南方向开到岸边去。等信号发出后，我们就让他的船员冲出来。$B$B 加尔·盐蹄那个壮汉可以打前锋，我们要让里维加兹和卡拉·海角措手不及，把他们送到海底喂鱼去。$B$B 你们几个负责把一切对范克里夫的计划有价值的东西都抢走。"
D.Strings[116441]="我会命令艾隆帕开火，防止任何黑水海盗的船只进出港口。$B$B 红雾号的弹药打光之后，我会将她开到斩浪号旁边对她进行补给。$B$B 等盐蹄和他的人在镇子上放了火之后，所有人都回到船上去，我们就立刻开船，还可以在野人海岸给藏宝海湾再来一次炮击。$B$B - 舰队指挥官菲尔拉伦"
D.Strings[116442]="坐着那条破船从赞吉尔身边逃跑似乎是很明智的，但是现在我开始觉得死亡也许是个更好的选择。$B$B 我想是我祖先的恩赐让我逃脱了他们的惩罚。但是现在我又觉得，如果我能经受住监狱生活的考验，没准我能获得无比珍贵的智慧。"
D.Strings[116443]="统治这座小岛的野兽……它的力量实在是太强大了。其他的生灵都在它面前退缩，就连凶猛的黑豹也一样。现在我似乎还是可以听到它的吼叫声，这声音总是让我魂飞魄散。$B$B 那些生物会阻止任何想要到这座小岛上来的人，我必须对我的祖先充满信心。"
D.Strings[116444]="我想念我的部族，还有我的家人。我会愉快地迎接空旷平原上吹过的风，或是雷霆崖的日落，而不是这座湿热的丛林。$B$B 我能看见不远处清澈的海水，但那并不能使我平静下来，它只能勾起我对被关押的那段日子的记忆。"
D.Strings[116445]="第1天：$B 早上6点到11点 - 收拾营地$B 上午11点到11点半 - 休息，吃午饭$B 上午11点半到下午4点 - 经过一条峡谷$B$B 第2天：$B 与第一天的安排一样$B$B 第3天：$B 同样的安排$B$B 第4天：$B 同样的安排，但有一个例外。日落前，在托尔森经过峡谷时，他要我掩护他一下。我猜他要去见我们的人。$B$B 让我感到意外的是，他一小时之后就回来了。我原本希望他见过我们的人之后能够和库尔森重新会合，但看来事情并不是这样。"
D.Strings[116446]="第5天:$B 托尔森今天显得十分不安。一定是他昨天值勤途中遇到的什么人或什么东西让他感到恐惧。$B$B 我以为我们的人已经和他谈过了，不过当我询问托尔森在我掩护他时去了哪里的时候，他却默不作声。他把我当作朋友，所以他认为不告诉我这个危险的秘密可以保护我。$B$B 他的忠诚用错了地方，但是这种忠诚却十分强大。他和我们重新汇合之后一定会成为库尔森军队有力的增援。"
D.Strings[116447]="第6天：$B 一大早，托尔森与尤瓦中士进行了一次长谈。我不得不假装睡觉，因此不敢移动身体去偷听他们的谈话。但是我猜他们正在谈论托尔森前几天的那次值勤。$B$B 我在午餐时近距离地观察尤瓦，发现他也在观察我。不久，多伦又叫上了托尔森。多伦和尤瓦肯定知道托尔森正在与你的人会面。$B$B 他在为叛军做间谍。"
D.Strings[116448]="我们不能再给托尔森提供更多情报了，必须除掉他。他对我们已经不再有用。$B$B 如果有机会的话，我会杀了托尔森，但是如果你收到了这封信，那就表示我还没找到机会。$B$B 在这种情况下，我建议在托尔森与我们的人下一次见面时给他致命的一击。$B$B -M"
D.Strings[116449]="议会将任用您来统御人类和矮人领地的部队，这是个明智的决定。我很荣幸可以在奥特兰克担任您的助手。$B$B 以萨格拉斯的名义，$B  $B 纳伽兹，$B 阿格斯祭师"
D.Strings[116450]="蠢货！$B$B 我的计划是同时摧毁那两座桥。你们这些头脑简单的蠢货都干了些什么？你们只完成了一半的任务，还让整个联盟都对我们产生了警惕。你们全都是蠢货！$B$B 你们只有一次弥补错误的机会。我们在离桥不远处的阿拉希高地还有个秘密据点，那里还藏有一些炸药。$B$B 如果你们还想继续活下去，就得给我完成任务！$B$B - 卡姆·深怒"
D.Strings[116451]="我亲爱的萨拉：$B$B 我想我们这几天要去看守萨多尔桥。也许我从此就无法再给你写信了，所以现在我很想给你写点东西，让你知道我在生命中最后的日子里都在想念着你。"
D.Strings[116452]="我们的任务可能要持续好几天，并且充满了乐趣，但是对我而言，它也许意味着残酷的战斗和死亡。如果我必须在战场上为联盟而牺牲的话，那么我随时都作好了这种准备。$B$B 对于我所从事的事业，我充满了信心，勇气永远与我同在。"
D.Strings[116453]="我知道铁炉堡王国非常需要联盟的胜利，而我们欠那些在恶魔战争中浴血奋战的牺牲者很多东西，我多么希望能放弃此生所有的快乐去维系这个联盟，并还清欠那些牺牲者的债。"
D.Strings[116454]="萨拉，我对你的爱是永远不灭的，它如同无形的绳索束缚着我，没有东西能够解开它。而我对王国的热爱则像强风一样袭来，让我在战场上也无法不想念着你和我们的家园。"
D.Strings[116455]="我不断想起和你一起度过的美好时光。我感激圣光，也感激你。我和你度过了那么多美妙的日子，而现在我却不得不放弃这一切。我们本来还可以生活在一起，相亲相爱，看着我们的儿子在身边慢慢成长，然而现在我不得不放弃这些希望，这对我来说是多么困难的一件事啊。"
D.Strings[116456]="我对于我神圣的使命没有什么抱怨，不过我总是听到有人在对我轻声低语——也许是风吹来了我的小爱德格的祈祷，它告诉我一定要安然回到我所爱的人身边。我亲爱的萨拉，如果我不能回去，请你不要忘记我对你的爱有多深。即使我在战场上永远停止了呼吸，我也会在那之前轻轻呼喊你的名字。$B$B 请原谅我以前所犯的错和我给你带来的那些痛苦，我那时总是那么愚蠢，那么自私。"
D.Strings[116457]="如果我能用眼泪清洗影响你快乐的那些污点，如果我能和这个世界上的所有灾祸斗争，保护你和我心爱的孩子免受伤害，那对我该是多么快乐的事啊。$B$B 但是我做不到。$B$B 当你带着我们的孩子与残酷的命运斗争时，我会在扭曲虚空中看着你，在你身边徘徊，悲伤而又耐心地等待着我们再也不用分开的那一天。"
D.Strings[116458]="但是，萨拉，如果一个死去的亡魂能够重新回到艾泽拉斯并环绕在他们挚爱的人周围，我会一直陪伴在你的身边。无论是你高兴还是失落的时候，如果有微风吹拂你的脸颊，那就是我的气息，当你的鬓角感到清凉的微风，那就是我的灵魂轻拂而过。$B$B 萨拉，请不要为我的死亡感到悲伤，我只是暂时离开了，我会在那个世界等着你，等着我们重逢的那一天。$B$B - 苏利"
D.Strings[116459]="章鱼咆哮着，发出了雷霆般的响声：$B$B “我们来了。”$B$B 米洛斯毫不动摇地矗立着，不断地施展他的魔法力量。海浪分成两股向伊拉莱袭去，淹没了它们前面的丛林。米洛斯命令他的手下开始施展法术，喧闹声瞬间变成无数食人妖的齐声吟唱。$B$B 这时在所有声音中有一个声音显得尤其突出。"
D.Strings[116460]="米洛斯怒吼着，他手下的力量都被汇集起来向章鱼释放过去。$B$B 大海被一劈为二，米洛斯的法术以光的速度投向奈普图洛斯的奴仆。闪电撕破了天空，这股力量正中大章鱼，瞬间雷霆万钧，海水也被蒸发得一干二净，大地上留下的只有一个燃烧的巨坑。$B$B 米洛斯相信他的法术可以击垮这些巨大的章鱼，于是他大叫着庆祝胜利。"
D.Strings[116461]="但是这些章鱼都非常古老，它们看着大陆从海洋中升起。$B$B 它们看着上古之神统治世界，又看着陌生的旅者将它们击败，它们看着魔法时代的兴起。$B$B 它们经历了岁月蹉跎，它们掌握着许多秘密。虽然米洛斯的法术十分强大，但是他和食人妖一样终究只是肉身。$B$B 于是他的法术失败了。"
D.Strings[116462]="法术没有制服章鱼，反而激怒了它们。千万年来，没有任何凡人能够带给它们痛苦，而食人妖的法术却令它们如此痛苦。$B$B 因此它们摆脱了米洛斯的法术束缚，咆哮着展开了复仇。$B$B 隆隆声从海底传来，那是滔天海浪来袭的预兆。在它们到达伊拉莱时，阴影笼罩了整座城市。$B$B 然而在海浪摧毁城市之前，章鱼泰然自若地停下了。"
D.Strings[116463]="食人妖巫医开始颤抖，充满恐惧地呼唤他们的主人。米洛斯凝视着重重海浪，虽注定失败却仍面露藐视。他又开始施展自己擅长的那一套，默念着咒语，食人妖将他最后的话语蚀刻成石。然后米洛斯泰然面对来袭的章鱼。$B$B 他面部扭曲，奋力投出所有的力量，这是他的最后一击。$B$B 章鱼将它们的愤怒都倾泻在米洛斯身上，接着整个大海都向伊拉莱扑了过去。$B$B 一切都结束了。"
D.Strings[116464]="水淹没了丛林，冲走了所有的东西。食人妖和野兽尖叫着被大水冲过、淹没。$B$B 许多古拉巴什的居民还没搞清楚大海为什么吞没他们，就已经葬身海底了。$B$B 最终海水冲到山前停了下来，然后撤回到它们原本所在的地方，留下的只有死一般的寂静。$B$B 海水退去了，但是它们依然在伊拉莱四周涌动，时刻准备着将它永远淹没。"
D.Strings[116465]="瓦加祖尔安全地躲在山后的祖尔格拉布，当他走入丛林时，他发现自己的人民已经全部被海浪卷走了。$B$B 他绝望了，因为他征服的梦想已经破碎。$B$B 从此之后，也没有人再看见过圣蛇米洛斯。"
D.Strings[116466]="尊敬的陛下：$B$B 作为一个普通战士的妻子，我明白自己是不能向您这样伟大的领导者的行为提出疑问的。从洛克莫丹的湖畔到丹莫洛的雪峰，我们的国土上正在发生的战争是为了保护我们的朋友与爱人的生命而进行的。"
D.Strings[116467]="但是我们以保卫生命的名义所发动的战争需要付出多大的代价?要牺牲多少战士才能让我们认识到，我们拼命想要保护的生命正在从战场上离开我们?$B$B 我们还要在刀光剑影下撕碎多少未来的希望?究竟需要多少被鲜血浸湿的土地才能让我们把过去的恩怨埋葬?"
D.Strings[116468]="这不是一个普通战士的妻子应该提的问题。$B$B 然而我现在是作为一个普通战士的遗孀给您写这些的。我的丈夫只是您成千上万个士兵中的一员，而对于我来说，他就是伟大的苏利·巴鲁，是我孩子的父亲，是我心爱的丈夫，是要和厮守终生的伴侣。$B$B 伟大的陛下，如果我的问题对您不敬，请原谅我。但是逝者已经不能亲自来问这些问题了……$B$B 您忠诚的臣民，$B 萨拉·巴鲁"
D.Strings[116469]="施涅德：$B$B 你好。我相信运河地区的生意很兴隆，我们这儿的贸易区一直都很热闹。$B$B 我们的存货几乎都用光了，现在急需布匹。请你尽快为我们供货。$B$B 祝你好运，另外，希望你的孩子萨尔曼学业进步。$B$B - 哈兰·巴格雷"
D.Strings[116470]="给库尔提拉斯舰队的正式命令$B$B 我，普劳德摩尔将军，将率领第一批部队登陆卡林多海岸。$B$B 我离开时，本尼迪克上尉负责全权指挥，并负责库尔提拉斯军队的所有内部事务。如果12个月内我还没有从提拉加德城堡传回消息，本尼迪克上尉将发动第二轮攻击。"
D.Strings[116471]="<HTML><BR/> <BODY><BR/> <H1>部落征兵通知</H1><BR/> <BR></BR><BR/> <P>持此通知者已被证明具备出众的力量和战斗技巧。我建议将其分派到十字路口去执行任务。</P><BR/> <BR></BR><BR/> <BR></BR><BR/> <P>此致</P><BR/> <BR></BR>- 卡加尔·战痕<BR/> <BR></BR><BR/> <BR></BR><BR/> <BR></BR><BR/> <P>批准。<BR></BR><BR/> - 塔克林·寻路者</P><BR/> </BODY><BR/> </HTML>"
D.Strings[116472]="<HTML><BR/> <BODY><BR/> <H1>部落征兵通知</H1><BR/> <BR></BR>/BR> <P>持此通知者已被证明具备出众的力量和战斗技巧。我建议将其分派到十字路口去执行任务。</P><BR/> <BR></BR>/BR> <BR></BR>/BR> <P>此致</P><BR/> <BR></BR>- 卡加尔·战痕/BR> <BR></BR>/BR> <BR></BR>/BR> <BR></BR>/BR> <P>批准。<BR></BR>/BR> - 塔克林·寻路者</P><BR/> </BODY><BR/> </HTML>"
D.Strings[116473]="巴尔莫丹的挖掘$B$B 我们探险者协会派出的勘探员所发现的东西看来很有价值，这一带埋藏着的文物对我们来说是无价之宝。无疑，我们可以在巴尔莫丹的沙土之下找到一些关键的线索。$B$B 这个地区的地质情况使得我们不得不采取一些极端措施，因为许多沙地都因为长期处于荒芜的环境和多变的天气下而变得十分坚硬了。"
D.Strings[116474]="解决的方法非常简单。我们制作了强力的爆炸物，它的威力足以炸破最坚硬的物质。$B$B 这项爆破工作开展起来必定会非常吵闹，但是我们的工作显然要比当地居民的生活安定更加重要。事实上，我们已经把一群牛头人赶出了这个地区，而且这些牛头人也确实是一群祸害。"
D.Strings[116475]="由于在这里碰到了种种问题，我认为我们需要后方军队的支援。不仅仅是因为挖掘场需要军队的保护，另外巴尔莫丹的所在地对于联盟来说也具有很大的战略价值，因此，国王应该派兵驻守这里。$B$B 啊，我扯得太远了。还有很多挖掘工作等着我去做呢。我已经花了太多时间来写这个东西，没时间去进行挖掘了……"
D.Strings[116476]="主动式负载平衡器控制台可以自动调节燃料、燃气、液体的流动及相关的机器设备。在完成了初始化设置之后，只需简单维护即可进行日常的运行。$B$B 控制台的主要部件（从左到右）依次是：$B$B 主动力杆$B$B 处于连接位置时，启动主动式负载平衡器。将动力杆调至“关闭”位置时，机械装置也不会自动松开，它只会"
D.Strings[116477]="菲兹普罗克主管，你提交的设备申请表已经拉兹杜克总裁批准。$B$B 他让我提醒你注意风险投资公司在整个卡利姆多大陆的既得利益。我们在贫瘠之地的钻井和采矿业是有利可途的，而且效益卓着，但是你所管辖的莫高雷地区还是需要为我们提供足够的生产量。"
D.Strings[116478]="菲兹普罗克主管，你提交的设备申请表已经拉兹杜克总裁批准。$B$B 他让我提醒你注意风险投资公司在整个卡林多大陆的既得利益。我们在贫瘠之地的钻井和采矿业是有利可途的，而且效益卓着，但是你所管辖的莫高雷地区还是需要为我们提供足够的生产量。"
D.Strings[116479]="顾问委员会可以理解在如此靠近牛头人领地的地方进行大规模的商业活动非常困难，但他们不会阻碍我们在该地区的总体计划。$B$B 我们很高兴听说你们已经开始在矿物储量丰富的莫高雷平原上采矿了。正因为这样，委员会才批准了你的物资申请。"
D.Strings[116480]="除了采矿，我们还希望莫高雷分公司能够提供木材，另外还为你提供了原材料和几台新型粉碎机，用以建立一座伐木场。"
D.Strings[116481]="进入冷却过程，要等一到两分钟才会完全关闭（视实际情况而定）。$B$B 特别注意：只有当机器上的三个控制阀都松开的时候才能操作主动力杆。这些控制阀可以按照任意顺序关闭。$B$B 第一个是主控制阀，在垂直的巨大烟窗底部。接下来是燃料控制阀，在燃料箱（应有三个）和烟窗之间的管道上。"
D.Strings[116482]="最后是调节阀，在通往烟窗的两个圆柱形油箱中的较低的那个上面。$B$B II.燃料指示计$B$B 显示主燃料箱、第二燃料箱和第三燃料箱的当前压力。$B$B III.流量计$B$B 显示当前系统内的流量。"
D.Strings[116483]="IV.流量控制器$B$B 升高或降低流量。由主动式负载平衡器自动控制。$B$B V. 温度指使计$B$B 显示系统的操作温度。"
D.Strings[116484]="星辰的孩子已经在永恒之井闪光的湖水边定居了很久。众所周知，象征永恒曙光的艾露恩在就在这水中休憩。岸边住着星辰的孩子们，艾露恩眷顾着他们，给他们安家，而他们也总在夜晚虔诚地凝望月空。"
D.Strings[116485]="当森林中的古树被连根拔起的时候，由塞纳留斯的儿女们看守的树林，还有星辰之子们的石塔，整个世界都在颤抖。我们的女王即使在绝望和混乱的战争期间仍保持着她的优雅。在魔法的作用下，天空都变了颜色，爆炸好像要将世界撕成碎片。"
D.Strings[116486]="德尔葛兰大人：$B$B 事情正像您所担忧的那样。您关于奥萨拉克斯之塔的猜测是正确的。有一群邪恶的信徒聚集在奥萨拉克斯之塔一带，他们当中有许多术士，甚至还有一个凶残的萨特。我不清楚是何种邪恶的力量将他们聚集在一起，但是我对此感到十分忧虑。$B$B 他们自称是暗滩教派的信徒。$B$B 请原谅我这封信写得很简短，但是危险正潜藏在森林中，我只能简单地描述一下这里的情景。"
D.Strings[116487]="虽然在湖岸周围有许多城镇，但其中最重要的就是亚米萨兰和巴莎兰，艾萨拉——卡多雷敬爱的女王——也赐福于这两座城镇。她将自己的仆人和贵族们安排到这两座城镇中居住，并派遣埃瑟里克斯·纳拉辛统治他们，不过埃瑟里克斯一般都住在远离城镇的奥萨拉克斯之塔。    他的助手是法师阿斯特利安，他以自己强大的战斗力以及对于魔法的熟练掌握而着称。"
D.Strings[116488]="阿斯特利安和巴莎兰的居民住在一起，另外他还多次造访亚米萨兰，他关心那里人民的需要。    就这样，这两座永恒之井岸边的小镇不断发展繁荣，而星空下的其它地方却渐渐陷入了疯狂。"
D.Strings[116489]="兄弟相残，同族征战。并不是所有上层精灵都参与了战斗，有些人呆呆地站着，由于这极度的疯狂而不能动弹，他们的城市和乡村在他们身边土崩瓦解。    亚米萨兰化作了一片废墟，它的居民们紧紧依附着大地，仿佛大地可以让他们幸免于难。直到这时，艾萨拉赐福的埃瑟里克斯·纳拉辛出现了，他要保护同胞们的安全。    他告诉那些惊慌失措的同胞，只需施展一个简单的法术，他就能保护他们。"
D.Strings[116490]="当他们周围的兄弟姐妹、父亲母亲一个个倒下的时候，他们将获得永恒的生命，不必畏惧即将来临的大灾变……"
D.Strings[116491]="希尔耶之星$B$B 这颗星在守财奴格雷尔伯格的手上，这个贪婪的巨魔总是在奥特兰克城的废墟中搜索各种珍奇的玩意。他的大部分收藏品都与垃圾无异，只有希尔耶之星例外，它有着非常珍贵的特殊能力。"
D.Strings[116492]="达古恩之手$B$B 古书上说达古恩的爪子会分泌一种毒液，这种毒液不会毒死它的猎物，不而会令它突变成另一种东西——上古种族中的一员。毫无疑问，这种毒液对我们很有价值。$B$B 达古恩住在深海中，不过他经常被尘泥沼泽的鱼人召唤到水面上来，它们的先知会使用一种附有魔法的海藻召唤达古恩。只要你杀掉足够多的鱼人智者，就应该可以找到这种海藻。把海藻放在鱼人的祭坛上，然后达古恩就会被你召唤来了。"
D.Strings[116493]="遗产之心$B$B 死灵莫格是荆棘谷的一个食人妖法师，遗产之心就在他的手上。据说解开遗产之心中包含的谜团就可以摆脱死亡的威胁。你可以在祖玛维废墟里找到莫格。如果你能打败他的话，把遗产之心带来给我。"
D.Strings[116494]="把这三样东西——希尔耶之星、达古恩之手和遗产之心——交给我，然后你就将得到雅格因的笔记。"
D.Strings[116495]="希尔耶之星$B$B 守财奴格雷尔伯格是奥特兰克的一个巨魔，这块宝石就在他的手上，宝石的主人可以拥有与其他世界沟通的能力。情报显示，格雷尔伯格在奥特兰克城的废墟里徘徊，不断地搜寻更多的遗迹。"
D.Strings[116496]="达古恩之手$B$B 达古恩是深海中的一种巨兽，它为尘泥沼泽的鱼人所崇拜。它们的萨满对一种特殊的海藻施了魔法，然后用这种海藻把达古恩引到水面上来。去猎杀那些鱼人，从它们身上找到附有魔法的海藻，然后把它放在鱼人的祭坛上，然后等待达古恩出现。$B$B 我需要他的手。"
D.Strings[116497]="遗产之心$B$B 古书上说拥有遗产之心的人就会长生不老，它的拥有者是死灵莫格。莫格是劈颅部族的巫师，他住在荆棘谷的祖玛维废墟里。"
D.Strings[116498]="亡灵哨兵任务报告$B$B 侦察员：兰妮·尤瑞克, 奎恩·尤瑞克, 埃兰德·玛科雷$B$B 主要任务：完成对银松森林北部的侦查工作，并且判断天灾军团和野生动物的威胁程度。"
D.Strings[116499]="侦察员发现了大量狼人的存在。建议派出捕猎小队扫除这个威胁。$B$B 在亡者旷野的农场上发现了不死生物豺狼人。虽然我们还不知道它们在农场聚集的目的，但是根据其动向和准备程度来看，它们很快就有可能开始军事行动。在我们观察豺狼人的这段时间里，并未发现它们当中有明显的首领。也许它们是在等待指挥官或是增援的到来。"
D.Strings[116500]="我们的侦察员继续搜索时，在伊瓦的农场遭遇了阻击。伊瓦和他的家人，还有他的工人们，都成了天灾军团的爪牙。$B$B 我们的侦察员遭到他们的袭击，虽然最后成功地击退了伏兵，但是均身负重伤，尤其是奎恩。"
D.Strings[116501]="他们在伊瓦的旧房子里设置了一处防守点，兰妮负责警戒工作，埃兰德则继续侦查任务。$B$B 埃兰德在北边的一座果园中被狼人困住，后来在一个$R$C的帮助下才得以逃脱——也就是向您递交这份报告的信差。"
D.Strings[116502]="另外，这位信差不仅协助我们完成了任务，而且帮助我们击败了邪恶的伊瓦、营救了埃兰德，并且负责递送了这份报告。$B$B 我们对$g他:她;充满感激之情，希望上层能对其卓越表现给予相应的嘉奖。$B$B - 亡灵哨兵兰妮·尤瑞克$B 行动负责人"
D.Strings[116503]="一个邪恶的力量造成了这一切$B 他的元素生物永不停歇$B 他悠闲地坐在鬼雾峰$B 对着你露出轻蔑的笑容$B$B 你很快就要面对这个法师$B 只有他的死亡才能终结这件疯狂的事"
D.Strings[116504]="迈萨迪斯神殿$B$B “愿伊露恩的光芒如远古时那样永远照耀着山谷，照亮森林中的道路。”"
D.Strings[116505]="月神满足了我的愿望。我的同伴不应白白牺牲，我将用月神镰刀为他们复仇。这是一件古老的物品，一根粗糙的螺旋状的木头，可能比卡多雷还要古老。$B$B 我花了很长时间来研究神赐给我的这件东西。它不是一件普通的武器，也不是一个简单的法器。有了它……仿佛时空的障碍都变得微弱了许多。"
D.Strings[116506]="我手中握着镰刀，看到了一片混乱的景象。狼人……对抗着一个不可思议的敌人。狼人以他们一贯的狂暴发动攻击，但他们面对的是一个毫无畏惧的对手：碧火之王。$B$B 这时我才意识到了镰刀的真实力量，注视着它，我就能和狼人交流。不过我所用的交流工具并非语言，而是一种不同的方式……一种难以描述的方式。$B$B 重要的是，狼人能听见我、理解我。"
D.Strings[116507]="我将能量引入镰刀，时空的障碍越发减弱，于是我就可以将狼人召唤到我们的世界来。第一次我召唤了三十个狼人，并带领他们上了战场。我支配着他们无穷的蛮力，向费伍德森林中的恶魔发起猛烈的攻击。$B$B 伊露恩满足了我的愿望，森林将被彻底净化。$B$B"
D.Strings[116508]="一切都进行得很顺利。我召唤了大群狼人和我一起战斗。虽然他们思维简单，但是作为一个整体，狼人显示出了强大的攻击能力。$B$B 我任命了一些首领，让他们各自领导一小队狼人行动。我们同时在森林的许多地方展开了战斗，在与恶魔的对抗中获得了丰厚的战果。$B$B"
D.Strings[116509]="有一队狼人失踪了，我派他们在整个森林里巡查以找出恶魔的巢穴，可是他们没有回来。我开始担心那些首领，我把控制权交给他们，然而他们的头脑非常简单，也许会滥用我给他们的那点权力。我是不是已经失去了对他们的控制?也许我应该暂停召唤其他的狼人。$B$B"
D.Strings[116510]="虽然我没有再召唤狼人，但它们的数量还是在继续增加。似乎镰刀已经不需要我参与召唤的过程了，这一点很麻烦。我尽力召回狼人小队，让他们留在神殿附近。$B$B 同时，我去了一趟达纳苏斯的图书馆，还谘询了黑海岸的古树议会，但没有找到任何关于这些狼人的资讯。"
D.Strings[116511]="我听说过一个名叫阿鲁高的肯瑞托法师，似乎这个法师也召唤过狼人。虽然去找他是件令我不快的事，但我还是想问问他对狼人有什么了解。$B$B 狼人很危险，我一定要抑制它们数量激增的趋势。次日，我就去了贫瘠之地的港口，预定了前往新世界的船票。$B$B $B 愿伊露恩的赐福护佑我完成任务。"
D.Strings[116512]="我写这本日记是为了记录我肩负的帮助?q谷的任务。不久前发生的事有些奇怪，不过我希望能帮助我的同胞解开这个谜。$B$B让我先记下这些事情，免得以后忘记。$B$B我最近发现了有关法师达图尔的传闻的真相。"
D.Strings[116513]="我曾经觉得人类来到我们的土地上学习我们的东西是一件荒谬的事，然而这个法师，这个恶魔，他不仅在这里扎了根，还学到了我们的一些知识。我仍然无法确定他是如何……$B$B我一直没有搞清楚他的目的是什么，但是他的计划好像很简单：利用德鲁伊法术成为熊怪的朋友，然后控制它们。如果他企图伤害我的族人，或者有其他什么险恶的打算，那么我希望在我的生命终结之前能找到答案。"
D.Strings[116514]="不管怎样，他所执行的计划显然已经获得了一定的成功。他是不是想先在熊怪身上施展他的诡计，然后再用到我的同胞身上？抑或他垂涎熊怪手上的某种东西？谁知道呢？$B$B他试图利用他所创造的东西（一种法杖或是别的什么）渗入到?q谷的熊怪部落中去。虽然具体的细节还不清楚，但是可以确定的一点是：当他试图操纵熊怪互相攻击的时候，他被熊怪们发现了。"
D.Strings[116515]="我知道如果精灵发现自己被如此摆弄的话，他们一定会勃然大怒，熊怪也是如此，不过它们的反应更为强烈，还将达图尔杀掉了。$B$B至少在那一刻，熊怪表现得并不像通常那样堕落。它们还是保持了理智与智慧，而且和我们的关系也很融洽。$B$B我希望如果能在林精莎尔蒂恩的帮助下重铸达图尔的魔棒，我就可以利用它的力量来帮助我们的同胞……还有可怜的熊怪。"
D.Strings[116516]="并非所有熊怪都堕落了，有些幸存者还在保卫着森林。在它们堕落的时候，有些熊怪逃走了，有些被杀，其他的则被迫离开了自己的部族。$B$B我在密斯特拉湖畔发现了一个令人尊敬的污林部族熊怪，他的名字叫做克罗格。$B$B我观察了他好几天。如果我能扮作熊怪接近他的话，我想我可以为他提供一些帮助，并重新建立我们和熊怪之间的联系。"
D.Strings[116517]="杀了达图尔之后，熊怪把他的魔棒分成三部分，使得它不能再对他们造成影响。事情变得有些困难了，但是我知道那三个部分放在哪里。$B$B宝石$B魔棒的第一部分，也就是那块神奇的宝石，它被藏在?q谷西北部的一座神殿中。我知道这座神殿现在已经成了法拉希姆湖中央的一座废墟，哨兵告诉我，有大批鱼人在那里游荡。"
D.Strings[116518]="如果我在神殿中找不到宝石的话，那它有可能是被某个鱼人拿走了。$B$B魔棒的杆$B这个部分落在了树人手中，他们现在生活在费伍德森林附近。熊怪和我的同胞都没有想过，侵袭了这片土地的堕落也会影响到高贵的树人。$B$B我的调查表明，树人将魔棒的杆藏在了一小片树林中的一个上锁的箱子里。要想了解更多细节的话，我还得和莎尔蒂恩交谈。"
D.Strings[116519]="1. 找到一个或八个人$B$B 2. 使劲打人$B$B 3. 继续打人$B$B 4. 把人扔到火里$B$B 5. 吃人"
D.Strings[116520]="莎尔蒂恩是在伊瑞斯湖东北部保护月井的林精。她拒绝离开森林，也不愿让森林变得堕落。我知道她有能力修复魔棒，至少她能告诉我如何修复它。$B$B魔棒的圆头已经交给了朵丹尼尔的德鲁伊。问题在于，那些德鲁伊都已经死了。$B$B他们的灵魂现在盘踞在那里，已经远没有原来那样友好了。"
D.Strings[116521]="这些还需要进一步调查。我不敢肯定自己是否能对付得了这些死去的同胞……更不用说在朵丹尼尔的深处找到圆头了。$B$B（备注：我最近在阿斯特兰纳作准备的时候曾遇到了一个矮人猎人，他在?q谷花了很多时间来帮助我们的同胞。他来自一个叫作暴风城的地方。$B$B有一晚，我们喝着啤酒聊了一会儿，他的故事让我看到了找回圆头的希望……"
D.Strings[116522]="他告诉我说，他已经走遍了整个朵丹尼尔，但从未看到过箱子或任何可能用来放置圆头的容器。$B$B他还告诉我那个地区已经有了腐烂的软泥怪，它们会吞食任何比它们小的东西。这个矮人亲眼看到它们“吃掉”桌子、雕塑、熊，甚至还有几个地精！$B$B那些软泥怪似乎拥有很强的魔法力量。如果装圆头的箱子被施了魔法，那么它有可能已经被软泥怪吃掉了。"
D.Strings[116523]="这是一场赌博，但是我此时没有其他的线索了……$B$B等我查出真相之后，我会记下详细的资料，但是在那之前，我得先找到魔棒的各个部分，帮助阿斯特兰纳。"
D.Strings[116524]="金吉尔：$B 好久不见了，但是我想，当你知道血羽部族的最后一个鹰身人已经被杀死的时候应该会很高兴吧。不用感谢我，送信的这个$c才是功臣。如果你愿意的话，在商队经过贫瘠之地的时候，我可以把她的头颅捎给你。我知道你的巫毒魔法需要那种东西。$B 老朋友，保重。$B$B - 达索克·快刀"
D.Strings[116525]="好吧，你得把你的NG-5炸药和雷管准备好。我已经给它们作好了标记……蓝色的用在伐木场，红色的用在风剪矿山。$B$B我事先进行了一些侦察工作，发现狂风峭壁那边已有足够的炸药了，你要潜入那里，放入炸药，然后在引爆之前跑出来，这应该不是件难事。$B$B记住，这样做只是为了声东击西。在哥布林去那儿检查发生了什么事之前要离货车远点，然后偷偷从他们后面绕进去。"
D.Strings[116526]="路上小心点，单是复合式硝酸塑胶炸药就能把你炸成粉末。我把一些液体装在铜管里，以保证炸药的安全稳定。$B$B我已经把你从科林那边给我拿来的卷轴应用在引爆装置上了，在你安置炸药之后，引爆装置会负责引爆NG-5炸药。我用简单的斯塔瑟瓦格机制保证最佳的引线传导性，并保证不同的复合式硝酸塑胶炸药之间的电流传导率高于一般水准。"
D.Strings[116527]="在我详细说明整个设计之前，让我先告诉你该把炸药放在哪里。$B$B一号计划 - 伐木场：$B在伐木场门前有一架货车（伐木场位于他们采伐森林和收集木材的设施的东北部），我怀疑工程设计图就在伐木场里。放好炸药之后就赶紧跑远点。"
D.Strings[116528]="准备好之后就点燃炸药。$B$B通过使用梅尔苏斯天线连接铜线和银线，可以保持较强的信号，这样你就能在安全的距离之外引爆了，只要小心附近的哥布林即可。如果他们把你抓了个正着，那你可就吃不了兜着走了。$B$B哦，为了以防万一，我还是提醒你一句吧，不要在货车爆炸的时候接近它……你会很惨的。"
D.Strings[116529]="二号计划 - 风剪矿山：$B$B我看到哥布林北面矿山的入口处停放了另一车炸药。我想那个地方应该适合放置NG-5炸药（红色）。把炸药放到货车后面，然后离远一点，按下按钮。$B$B如果哥布林没有过来的话，那就可能是爆炸的山石砸开了他们的脑袋瓜。"
D.Strings[116530]="-- 第一天 --$B$B 我从铁炉堡出发,经过漫长的旅途之后,终于到达了卡利姆多!$B$B 巴尔莫丹的勘矿员卡兹戈姆那边的进展相当不错。他今天又挖出了一块化石,挖掘站里的学者们认为这是某位古代神灵的骨骼碎片,卡兹戈姆则认为这块化石是某种神秘生物的一部分。身为这座挖掘站的管理者,他决定派我去寻找更多的碎片以揭开这个秘密。$B$B 我的任务就是:到南方去寻找更多的线索。"
D.Strings[116531]="-- 第二天 --$B$B 贫瘠之地是如此广袤无垠，到目前为止，我的旅程艰辛又无聊，也没什么有趣的事可以写进探险者协会的档案里去。$B$B 唯一值得一提的事情发生在黄金之路附近。我远远地看见了一些奇怪的生物朝我这边走了过来，它们一半像人，一半像猪。于是我迅速藏了起来，等它们过去。天哪，那帮家伙身上的味道真是臭死了!"
D.Strings[116532]="-- 第三天 --$B$B 啊,这是多伟大的发现呀!$B$B 我在旅途中偶然发现了很令人惊诧的东西:某种野猪类生物的巨大遗骸。它的骨头堆得极高,几乎成了一座小山。矮人站在这只野兽的獠牙旁边会显得像个……呃,像个矮人。从这种尺寸来看,我坚信这是传说中的某位古代神灵的遗骸。"
D.Strings[116533]="我记得不久前，首席考古学家杜瑟·灰须在铁炉堡的探险者协会总部做了一次讲座。那个老家伙提到过一位神灵，传说那位神灵具有无私的品性，因此受到达纳苏斯的那些精灵的崇敬……$B$B 嘘!等一下，我听见帐子外面有鼻息声，一定是些土头土脑的野猪想要偷我的苹果……"
D.Strings[116534]="-- 第四天 --'C:$B$B 我被抓住了'!$B$B 必须……赶紧……写下来。$B$B 我被剃刀部族的野猪人袭击。我以为他们会把我带到野猪遗骸那里,不过,他们却绕过它,直接穿过黄金之路去了西边。"
D.Strings[116535]="我被粗鲁地拖到一个被称作剃刀沼泽的地方，这里充满了恶臭和荆棘。我被扔进一间简陋的小屋，和一个垂死的夜精灵关在一起。$B$B 我身上的东西都丢了，除了这本日记和我的笔、怀表……$B$B 好像有什么人来了……"
D.Strings[116536]="-- 第五天 --$B$B 我的夜精灵狱友伤得很重。野猪人不断鞭打他,我觉得他不久就会死去,除非奇迹从天而降,营救队来到这个凶险的地方。他不断地昏迷又不断地醒过来,当他醒着的时候,我就尽可能扶着他多喝点水。"
D.Strings[116537]="昨晚他第一次开口说话。他叫赫尔拉斯，是一个德鲁伊。他被派到这里来调查关于野猪人之神的传闻。$B$B 他用虚弱的声音告诉我，他相信大野猪残骸那里就是一万多年前的上古战争时期野猪之神阿迦玛甘和燃烧军团激战的地方。阿迦玛甘的庞大身体最终倒下了，他的血慢慢渗入了大地，血流过的地方都长出了巨大而扭曲的荆棘……"
D.Strings[116538]="赫尔拉斯和他的同伴寻找在这一地区的堕落之源。他告诉我说，阿迦玛甘应该是个纯洁的神，但是这片土地为什么会遭到这些邪恶的野兽和恶性荆棘的污染呢？现在这还是一个谜。$B$B 我还想询问更多的消息，可是赫尔拉斯又一次失去了知觉……"
D.Strings[116539]="-- 第六天 --$B$B 赫尔拉斯的情况变得更糟了。$B$B 他今天只醒过一次。他痛苦地呻吟着，不过他所要表达的资讯很明显：如果我能从剃刀沼泽逃出去，那么我就必须必须把消息传达给萨兰纳尔的法芬德尔，卡尔加·刺肋的势力正在南贫瘠之地不断膨胀，它的力量正在迅速壮大。在这股邪恶而堕落的势力涌出剃刀沼泽之前，我们必须阻止它！"
D.Strings[116540]="可怜的赫尔拉斯看起来苍白得就像一把骨头，发烧也越来越厉害。野猪人一直在为某种军事行动做准备，我担心如果我还不快点逃跑的话，我将会遭遇和我的精灵狱友一样的命运。$B$B 我的计划是在野猪人下一次出去打猎的时候逃跑。守卫我的野猪人很懒，经常在当班的时候呼呼大睡。"
D.Strings[116541]="从沼泽跑出来之后，我就往千针林的方向走，然后向西到菲拉斯森林边界的萨兰纳尔去。我要到那里去找到那个名叫法芬德尔的德鲁伊。$B$B 起初我只是在寻找我们的过去，而现在事情变得愈加复杂和艰钜了。联盟的安危就掌握在我手中……"
D.Strings[116542]="订单号：45TK-3$B 买家：克拉维尔·浓须$B$B 发货单：$B$B 水棘轮 (3)$B 转发栓 (50)$B深怒牌鼻烟粉 (1)$B 高级棱镜 (3)"
D.Strings[116543]="我很想亲自把信交给您，不过我担心如果我离开这里的话，也许会错过一些重要的事情。$B$B 如果你想要了解到更多关于奥萨拉克斯之塔的资讯，可以问问递送这封信的信差，$g他:她;协助我完成了任务，你应该可以信任$g他:她;。$B$B 巴苏尔·影击"
D.Strings[116544]="哥布林纳兹·斯迪波尔据称是某位商业大亨的儿子（哪位商业大亨?这条情报的价钱可高了）。$B$B 看起来，他非常喜欢花家里的钱，而不是花自己挣到的钱。所以他从他家里的藏宝室里偷了出一些财产出来，现在就把它藏在闪光平原上。$B$B 如果他的父亲知道了他的去向，那老爷子肯定会去把他揪出来，拖回家……然后砍掉他的一根脚趾，以惩罚他的傲慢。"
D.Strings[116545]="菲兹巴布先生：$B$B 送来这封信的$r和我希望您能够参与我们的一桩生意。$B$B 正如您所知道的那样，我在闪光平原上待了不少日子了——我刚刚提到的生意是和这里进行的赛车比赛有关的。$B$B 如果赛车以及与之相关的赌博能让你感兴趣的话，那就请继续读下去，我相信您的知识对于我们的计划来说是非常有用的。"
D.Strings[116546]="菲兹巴布先生：$B$B 您交给我的合作人的那些酒非常棒。酒味醇厚，而且很容易让人上瘾。我相信喝过它的人一定会想要喝更多的。$B$B 我们为此向您表示感谢，克兰克。$B$B 我诚心邀请您来闪光平原来和我们一起把握这里的赌车机会，或者如果你公务繁忙的话，也可以让某位好友来这里玩一玩。$B$B - 克拉维尔"
D.Strings[116547]="善良的马特克：$B$B 现在我遇到了一些困难，所以需要你的帮助。$B$B 我兄弟和我要造一辆赛车，所以我们需要一些强力的活塞。我试过的那些都不够结实，用那种破玩意根本没办法把我们新车的速度给提起来，而且引擎还老抛锚!$B$B 你是最优秀的金属工匠，你一定能帮上忙，而且你是我们唯一的指望啦!"
D.Strings[116548]="如果你想要找到霜喉雪人的话，就必须用它最喜欢的食物把它引诱出来。$B$B 前往奥特兰克山脉，在那里杀掉一只巨型山地狮，把它的肉带到无草洞去。$B 将山地狮的肉放到尤基尔之焰上烧烤，很快，香味就会引来霜喉雪人。"
D.Strings[116549]="利用仇恨来利用别人实在是太简单了，我对此深有体会。兽人和食人妖就是最好的例证，他们对联盟的仇恨已经使他们愿意对暗滩教派的任何指示无条件地服从，但是他们对自己所效忠的对象有哪怕一丁点的了解吗?$B$B 那个总是给我们带来麻烦的圣骑士——净化者德尔葛兰——如今已经卷入了梣谷森林的事情里，而他的侍从巴苏尔却正在我的塔外侦察，他还以为为我不知道他在这里呢。"
D.Strings[116550]="德尔葛兰认为我们的威胁不大，没准只是又一个崇拜死亡的小教团而已。他根本不知道我们其实是暗影议会下的一个分支。$B$B 当我还是个孩子的时候，别人就告诉我，昆虫也能杀人，尽管它看起来根本就不起眼。你最忽视的东西往往伤害你最深，并且还会让你死得很惨。"
D.Strings[116551]="这种用于平原赛车的火箭车需要高度的协调性和十分细致的维护。所以说，工作站里的维修人员们一直没法休假也是很正常的。$B$B 维修人员们一直在测试他们的车子，并且正在尽可能地对其进行改进和调校，这是保持车子具有上佳表现的唯一方法。$B$B 所以……我们得用点什么手段让他们的工作人员出点小差错，这些小差错会让车子彻底报废，并让他们退出比赛。"
D.Strings[116552]="如果我们能够控制哪辆车的状态好哪辆车的状态糟的话，那么……我想，不用再多解释，你也应该知道这对于我们赌车有多大的好处。$B$B 所以，善良的菲兹巴布，我们需要由你来找到一种能把他们的工作人员搞糊涂的方法。$B$B 你知道荆棘谷里有什么植物、药草或者饮料可以让地精和哥布林们变成笨蛋吗?$B$B - 克拉维尔·浓须"
D.Strings[116553]="我对于守护神龙和泰坦进行了大量的研究——几乎花费了我一生的时间。在泰坦离开这个世界的时候，他们留下了五头守护神龙。这些强大的龙负责守卫着艾泽拉斯这个世界。它们的传说广为流传，直到今日。除了现在我所收集到的资讯之外，关于这种神奇的生物还有很多需要研究的东西。"
D.Strings[116554]="药剂师林度恩：$B$B 我希望这封信能安然地送达你那里，遥远的卡林多大陆需要你的帮助。$B$B 现在在离我们牛头人盟友的老家莫高雷地区很近的石爪山一带出现了重大的危机，哥布林风险投资公司在山里肆意砍伐树木，开采矿物，这已经激怒了那里的山灵。"
D.Strings[116555]="我猜想牛头人萨满和德鲁伊正在努力平息这些山灵的愤怒，牛头人认为石爪山的哥布林风险投资公司是个可怕的威胁。$B$B 无论他们的观点是否正确，我们都必须去帮助我们的盟友。$B$B 林度恩，你在毒药方面颇有建树，能否推荐一种可以在石爪山的哥布林中传播的毒药?$B$B 札玛"
D.Strings[116556]="单靠我自己绝对无法学到如此多的知识，因此我要感谢那些夜精灵。他们帮助我学到了许多东西，通过与他们的交流，我发现他们的起源与守护巨龙有很密切的关系，这一点是我所没有料到的。然而，他们似乎对这一秘密显得非常谨慎，即使对我也从未多透露些什么。"
D.Strings[116557]="关于我所了解到的守护巨龙的资讯，我将在下文中进行详细的叙述，以便供后世的读者参考。我认为它将会非常有用，因为我感觉到随着时间的流逝，这些龙将会对我们的世界产生非常重要的影响。"
D.Strings[116558]="雅立史卓莎：$B 雅立史卓莎，强大的上古红龙女王，被泰坦赐予生命守护者的称号。她是第一头被泰坦巨人创造出来的守护巨龙。据说她见证了艾泽拉斯世界中的所有现代种族的诞生。她那优雅而高傲的红龙军团曾经统治着所有的龙类。"
D.Strings[116559]="在夜精灵的传说中，雅立史卓莎与半神塞纳留斯是非常亲密的朋友，在燃烧军团第一次入侵的过程中，正是塞纳留斯召唤她参战的。"
D.Strings[116560]="伊瑟拉：$B 梦境之龙伊瑟拉象征着所有生物的潜意识，翡翠梦境就是她的杰作。虽然她鼓励普通的生物族群发展自己的想像力、创造力和雄心壮志，但她和她的后代却认为真实的世界只是一个幻象而已。伊瑟拉是世界上最优雅和强大的生物之一。"
D.Strings[116561]="玛里苟斯：$B 玛里苟斯被称为魔法使者或织法者，他的外形看起来并不是一头典型意义上的龙，据说他可以随意改变自己的外形。自从他在极北之地隐居之后就很少有人见过他，他几乎总是以一种昆虫的形态出现，但是当显出龙形的时候，玛里苟斯与他的后代总是覆着蓝色的鳞片。"
D.Strings[116562]="诺兹多姆：$B 诺兹多姆是时间之王。这头青铜色的龙对所有旧日的事物都很感兴趣，他专注于收集各个时代的神器，而对现实中的事情不感兴趣——即使是其他守护巨龙的事情对他来说也无关紧要。但是，他的这种性格并不意味着他只沉迷于过去的事务。"
D.Strings[116563]="作为保护者，青铜龙对于有文明迹象的地区非常感兴趣。他们具有与生俱来的耐性，在每次行动之前都会进行仔细的观察和计划。诺兹多姆一直致力于保护时间流和那些面临巨大危机的普通种族。"
D.Strings[116564]="奈萨里安：$B 奈萨里安被称为大地的守卫者，他比其他的守护巨龙更加兢兢业业地守卫着艾泽拉斯世界。他的黑龙军团的职责是创造山岭，以及为各种普通的种族构筑疆界。他的堕落至今仍然是个谜，究竟是外在的原因还是内在的原因造成了他的堕落，这一点尚无定论。我猜想，上古之神也许曾涉足其中。"
D.Strings[116565]="这条黑龙发生了完全的改变，最后奈萨里安彻底消失了，取而代之的是死亡之翼，一头充满憎恨与哀怨的恶龙。他不再是大地的守卫者，而变成了死亡的象征。死亡之翼是混乱与邪恶的化身，他永远渴望着进行毁灭。他成为了自上古之神被驱逐后的最邪恶的势力。"
D.Strings[116566]="恭喜您!$B$B 您已经成为了这只地鼠的新主人!虽然它看起来很害羞，但我们确信您会发现它非常可爱，而且具有出色的能力。$B$B 在接下来的几页中，您将找到关于地鼠的详细资讯：$B$B$B 再一次对您表示祝贺。您是绝对不会对它失望的。$B$B - 玛维格·铜拴$B 地鼠有限公司"
D.Strings[116567]="第十六天$B 乌里克和萨吉尔已经完成了任务,从塞拉摩港回来了。他们在港口中发现了一条名叫“失血麻雀”的新船,这条船来自于艾泽拉斯大陆的米奈希尔港。$B$B 明天乌里克和萨吉尔会回到港口并偷偷地上船。他们希望能找到一些政治文件,从而搞清楚塞拉摩和联盟之间的关系。"
D.Strings[116568]="随着科尔苏加德在罗德隆方面的节节胜利，巫妖王同时也已经完成了毁灭人类文明的最后准备工作。耐奥祖已经将他的致疫能量体分装入了数个名为瘟疫炉的可携式容器之中，并命令科尔苏加德将这些瘟疫炉运至罗德隆大陆，他们应该会把它们藏在被教会控制的村民那里。"
D.Strings[116569]="这些瘟疫炉由一些忠诚的信徒们守卫着，它们将起到一个产生瘟疫，并将瘟疫散布到从乡村到城市的整个罗德隆大陆北部地方的作用。$B$B 巫妖王的计划目前进展非常顺利。目前瘟疫已经在大陆北部的许多村落中爆发了。与诺森德大陆目前的状况完全相同，所有感染上瘟疫的人都已经死亡，成为巫妖王的奴隶。"
D.Strings[116570]="克尔苏加德麾下的信徒们正渴望着死亡并被转化为亡灵，继续为他们的黑暗领主服务。他们为由经转化为亡灵所以获得的永恒生命而狂喜。随着瘟疫的继续传播，更多的未被凶悍的僵尸出现在了诺森德大陆之上。克尔苏加德将这些僵尸编入成了一支只效忠于巫妖一人的军队，这支军队正逐渐壮大起来，并有了名字——天灾军团。很快，他们将远征洛丹伦大陆……并将给全世界的人类带来真正意义上的天灾。"
D.Strings[116571]="没有人知道宇宙到底是怎样形成的。一些人认为，最初是在宇宙的中心产生了一次剧烈的宇宙爆炸，从而将无穷无尽，繁华万千的世界送入到了混沌黑暗里的巨大物质空洞之中，将那个本与现在的世界有着巨大的差距，并有着大量奇异的生命形式存在于其中的另一个世界——混沌黑暗所彻底取代了。另一些人认为正入宇宙本身的存在与运转一般，宇宙是由某种人们认知之外的单一的，绝对的，至高无上的精神所创造的。"
D.Strings[116572]="尽管这个混沌宇宙的真正起源仍不得人们所知，但可以确定的是，是一个强大的种族将未来万物的存在之基石带到了当初仍处于混沌状态的世界中来，并按自己的意愿为他们之后的生物设计了生存的模式与发展的轨道。$B$B 是的，他们就是泰坦巨人，那种有着巨大的身形与金属质的皮肤，从宇宙之尽头来到这里的神们。他们来到这里并改变了这个世界。他们以自己的力量创造出了巍峨的高山与广阔的大海。"
D.Strings[116573]="他们擎起了天空并聚集起了大气——他们所做的一切，都是为了他们神秘的长远计划，他们要用秩序取代这世上的一切混沌。他们甚至加强了某些原始生物种群的力量，以便利用他们帮助自己完成工作，并使他们的理想世界的达到最终的完善。$B$B 泰坦巨人们由一个名为“万神殿”的精英组织所领导着，自第一创造纪元之后，他们已经秩序化了近乎一千万个从混沌黑暗中分离出来的世界。"
D.Strings[116574]="仁慈的万神殿寻求的是维持他们所创造出的世界的和平，因此他们必须永远与那些来自秽恶而黑暗的异次元空间——扭曲虚空中的阴险生物为敌。扭曲虚空是一处充斥着混乱魔法效果的，由乙太质构成的次元空间，它与多元宇宙中无数的世界都联系在一起，它也是许多只知毁灭其他生命体与吞噬宇宙中一切能量的邪恶生物或恶魔类存在的地方。"
D.Strings[116575]="-- 第十七天$B 乌里克回到了这里,他失败了。萨吉尔被抓住了。我只好派乌里克去把他的任务报告递交给纳泽尔。$B$B 我必须要留在这里,我必须得监视塞拉摩海岸的船只活动情况。我会继续监视,并及时汇报任何有价值的情报。"
D.Strings[116576]="第一套计划已经失败了！$B$B 我们的卧底成功地修改了值班表，并得以在那天晚上轮入隧道值勤，但是由于来自暴风城的某些不可预料力量的干扰，目标竟然在我们的眼皮底下安然逃脱了。好在我们对这种情况早有准备，在伏兵撤离暴风城之前，已经秘密地启动了第二套计划，并且进展非常顺利。"
D.Strings[116577]="第二套计划非常简单，但需要我们付出更多的耐心。我们安插在米奈希尔港的人已经竭尽全力了，而且他干得非常漂亮。我们很容易就可以跟上我们的目标，并在起程的时候把他抓住。"
D.Strings[116578]="攻击行动最好能在离他们的目的地不远的地方展开，据说我们的盟友也埋伏在那一带。我真是不明白，我们为什么要和那种生物结成同盟，但我也没有什么办法，我们是迫不得已。不过算了，这也没什么。只要我们能把目标握在我们自己的手掌中，就一定可以从暴风城那里拿回当初他们从我们手中偷走的东西！"
D.Strings[116579]="长须先生：$B$B 正如阁下所知，我们雷矛家族有着全大陆最挑剔的眼光和品味，您所制作的盾牌品质之高也是令我们非常欣赏的。$B$B 因此，我非常希望能得到一面由您亲手打造的盾牌。以下是我对盾牌的一些个人要求："
D.Strings[116580]="在洛丹伦联盟与兽人部落之间爆发的惨烈的第二次大战留给联盟的只有激烈的动荡与巨大的混乱。那些嗜血的兽人在他们优秀的酋长奥格瑞姆·毁灭之锤的领导下，不仅攻陷了矮人们的卡兹莫丹，甚至还攻入了洛丹伦王国中部的好几个省。那些冷酷的兽人甚至还在他们的暴行最终结束之前成功地劫掠了远在大陆一隅的精灵王国奎尔萨拉斯。"
D.Strings[116581]="联盟军队在三位最高指挥官安度因·洛萨爵士，光之使徒乌瑟，以及迪林·普劳德摩尔海军上将的领导下，将那些兽人们驱赶向艾泽拉斯南方的那片焦土之上——那里也是当初被兽人所毁灭了的第一王国的遗址。$B$B 最终，在洛萨爵士的领导下，联盟军将末日锤麾下的诸氏族又赶回了当初的兽人在艾泽拉斯大陆上控制的区域里。而洛萨的军队则一直追击着兽人，直到他们退回兽人的主城黑石塔，在那里，双方进行了最后一次攻防战。"
D.Strings[116582]="毁灭之锤决定进行最后的一搏，他和他的军官们领军从塔中主动出击，并与洛萨手下的圣骑士们在燃烧平原的正中央展开了一场史诗般的战争。毁灭之锤与洛萨都倾其所有兵力投入了此次大战，并留下了无数的尸体。尽管最后毁灭之锤以极其微弱的优势击败了洛萨，但这位大英雄的死却并不是这位酋长所希望得到的结果。"
D.Strings[116583]="图拉扬，洛萨最信任的一位上尉，拾起了沾满了鲜血的洛萨的盾牌，并将重新聚集起了他那些悲痛欲绝的同袍们展开了一次绝地大反击。坟墓遍布整个艾泽拉斯与洛丹伦，图拉扬的军队最终在一次正面战斗中击溃了毁灭之锤最后的残余部队，带着光荣与鲜血取得了最后的胜利。"
D.Strings[116584]="那场大战之后，被击溃了的兽人们已经一无所有了，只得带着愤怒逃向兽人在大陆上的最后一处堡垒——黑暗之门。$B$B 图拉扬和他的战士们将兽人残部一直驱赶到了悲伤沼泽之中，并进入了黑暗之门所在的诅咒之地。在那里，巨大的黑暗之门脚下，为了生存的部落残兵与为了复仇的联盟先锋展开了第二次大战中最后一场血腥的战役。"
D.Strings[116585]="兽人的数量远远少于联盟，而且他们的脑海已经彻底被伴随着复仇而生的嗜血之诅咒所占据住了，于是，兽人无可避免地倒在了愤怒的联盟军脚下。毁灭之锤被俘虏了，并被押往洛丹伦，但他手下的各氏族此时却又重新在北方聚集了起来，他们回到了洛丹伦大陆。"
D.Strings[116586]="仅仅在守望堡完成后的几个月，黑暗之门的能量再度高涨起来，并且打开了一条通向德拉诺的通道。部落中残余的兽人们在萨满长老耐奥祖的领导下，再次对艾泽拉斯的产生了野心。为了增加耐奥祖的法力，兽人计划去偷取一些的古老的法器，他们计划在德拉诺打开一个新的入口，以便使他们永远地逃离那个命中注定的红色世界。"
D.Strings[116587]="在得知了耐奥祖再次计划侵攻联盟的领地之后，洛丹伦王国国王泰瑞纳斯定派出大军远征德拉诺，以一劳永逸地彻底铲除兽人势力对艾泽拉斯的任何威胁。在大法师卡德加与大将军图拉扬的领导下，联盟军彻底在燃烧之地彻底击败了兽人势力。但尽管有着精灵巡逻员艾拉莉娅与矮人库尔丹麾下的精锐部队加盟联盟军，卡德加还是未能阻止耐奥祖打开传送门并逃到其他大陆去。"
D.Strings[116588]="由于入口聚积的能量过于剧烈，因此德拉诺世界中骤然出现了巨大的风暴。当卡德加正竭尽全力带领着他的同袍们为回到艾泽拉斯而拼命地战斗时，耐奥祖却仅仅带着他最信任的仆人们成功地从一个传送门中逃走了。了解到他们的最终命运只有死亡之时，卡德加与他绝望的同伴们无私地决定毁掉黑暗之门，以使艾泽拉斯不会受到德拉诺被毁灭的波及。"
D.Strings[116589]="想尽了各种办法，英雄们终于成功地毁掉了黑暗之门，拯救了艾泽拉斯。然而，他们是否德拉诺唯一能赋予他们的死亡之命运，这就不得而知了。"
D.Strings[116590]="在人类与兽人之间爆发第一次大战的一千年以前，艾泽拉斯世界上的所有文明都孕育于一片为无尽且暴戾的海洋之中的一片广袤大陆之上。而当时的卡利姆多大陆上只有一些奇异的种族和生物，它们还在为了和这片觉醒之地上的元素进行着生存的斗争。在这边黑暗大陆的中心，有着一个汹涌着炽热能量的神秘湖泊。"
D.Strings[116591]="被称为永恒之井的湖是世界魔力和自然力的中心。这口井从无穷无尽的浑沌黑暗之中汲取能量，并以独特的方式用这些能量滋养着整个世界。$B$B 有一天，一个古老的崇拜着黑夜的人形生物氏族小心翼翼地来到了这个充斥着超自然力量的魔法之湖的边上。"
D.Strings[116592]="这个当时尚未开化的，过着游牧生活的类人生物族群被井中的奇异能量所吸引而来，并在它宁静海岸边上建立起了永久性的居所。随着时间的流逝，井中的大宇宙力量对这个族群产成了潜移默化的影响，让他们更加强壮，睿智并拥有了不朽的生命。这个部族自称为卡多雷，这个名字在他们的语言中意为“星辰之子”。为了庆贺新的社会制度的诞生，他们沿着湖泊建立起雄伟的居所与庙宇。"
D.Strings[116593]="卡多雷，或称呼他们为夜精灵，崇拜月神伊露恩。他们相信她白天就睡在井中心最闪光的地方。由于受到井中所蕴涵着的秘密与魔力所吸引，早期的夜精灵祭司和先知们总是对井充满好奇，并孜孜不倦地研究着它。随着他们社会的发展，夜精灵终于了解到了卡利姆多大陆的宽广幅度并发现了生活在这片大陆上的无数居民。"
D.Strings[116594]="唯一能阻止他们探索这片大陆的只有古老而强大的龙了。虽然$B 这些身形巨大而蜿蜒的生物总是过着遁世隐居的生活，但它们会为防止任何潜在的威胁波及这片大陆而做出努力。夜精灵们认为这些龙正是这个世界的守护者，并且最好不要打扰它们和它们的秘密。"
D.Strings[116595]="无疑，正是夜精灵的好奇心使他们和具有强大能力的神祗们相遇，并且成为了好朋友。例如塞纳留斯，一位在原始森林中颇有势力的半神。塞纳留斯很喜欢这些好奇的夜精灵，并花了许多时间教他们认识这个美丽而富饶的大自然。天性喜好宁静的卡多雷也对卡利姆多的森林产生出了共鸣一般的感觉，并为大自然的和谐感到欣喜。"
D.Strings[116596]="随着看似无尽的时间的流失，夜精灵的文明无论是在土地还是文化上都有了长足的发展。他们的庙宇，道路以及居所正逐渐遍布整块黑暗大陆。夜精灵们美丽而天赋鼎异的女王阿斯萨拉在永恒之井的岸边建立起了一座庞大而雄伟的宫殿，并带着她最宠幸的仆人们住进了这座金碧辉煌的宫殿中。"
D.Strings[116597]="她最宠幸的那些仆人们被唤作“奎尔多雷”，或叫他们贵族，他们只对她一个人宣誓效忠，从不违背她的任何旨意，并坚信他们比其他的低阶夜精灵同族要强。尽管阿斯萨拉女王能够得到所有夜精灵的爱戴，但这些贵族们却是在被某些抱着妒意的族人所嫉恨着的。$B$B 贵族们与祭司们同样对永恒之井充满了好奇，于是阿斯萨拉女王也乐得命令这些贵族一同去研究井中奥秘，并揭露开它与这个世界的真正联系。"
D.Strings[116598]="奎尔多雷们全力工作，日夜不停地研究月井。再这个过程中，他们得到了一种能够控制井中宇宙能量的能力。在不断的研究与实验进程结束之后，卡多雷发现这种新的能量既可以用于创造万物，也可以用于摧毁万物。奎尔多雷们对于那些原始魔力感觉无从入手，所以他们下定决心要掌握这种新生的力量。"
D.Strings[116599]="尽管他们明白，如果不负责的使用这种新生的力量，将会给世界带来极大的威胁，但是阿斯萨拉女王和她的贵族们还是不计后果地继续练习他们的施法能力。塞纳留斯和许多夜精灵学者都警告他们说，若不能正确地对待这种魔法的话，必定会导致灾难。但是，阿斯萨拉女王和她的手下此时已经什么都听不进去了。"
D.Strings[116600]="随着他们的力量变得越来越强大，艾萨拉女王和她身边的贵族们身上发生了剧变。这些高傲的上位者们开始对他们的臣民们越来越冷淡，越来越残忍。似乎是有一块黑色的面纱罩住了艾萨拉那曾经令人痴迷的美丽。她开始不再在意她曾喜欢过的东西，并拒绝与她唯一信任的贵族祭司们以外的任何人接触。"
D.Strings[116601]="一位名叫法里奥·怒风的年轻且无畏的学者也花了大量的时间来研究永恒之井。他开始怀疑永恒之井的力量已经使得贵族们——甚至是他所敬爱的女王陛下的精神堕落了。尽管他还不能确信这种邪恶力量是什么，但他确信夜精灵们的生活很快就要发生永久的变化了……"
D.Strings[116602]="- 漂亮的边缘,长度从拳到肘。$B$B - 边上是银色的铆钉。$B$B - 中间有一枚三指宽的银色大铆钉。$B$B - 橡木材料,用铁加固。$B$B - 把我的名字,格林戈·雷矛,嵌在盾牌顶部边缘。"
D.Strings[116603]="艾泽拉斯大陆上的亡灵们并非是随着阿尔萨斯王子的堕落而诞生的，他们的诞生还可以追溯到更早些的时候。这件导致了洛丹伦大陆沦陷的时间很早以前就埋下了种子；它在兽人诸氏族及燃烧军团来到大陆的时候就开始了。"
D.Strings[116604]="来自德拉诺（兽人原本居住的世界）的兽人们本是信奉着萨满教的，并有着高贵的传统。他们都是强大的战士，无论是肉体还是精神都十分的坚韧。因此燃烧军团找到了他们。军团中最强大的一位恶魔基尔加丹希望能将驾驭这些兽人氏族为他所用，利用他们的武力来为燃烧军团征服一个又一个的世界。"
D.Strings[116605]="基尔加丹找到那些氏族的领袖，一位名为耐奥祖的强大萨满。他向耐奥祖许诺以神秘的力量与知识来换取兽人诸氏族为燃烧军团效力，耐奥祖答应了他，与他签定了条约。这份条约不仅就此注定了他们的命运，也毁灭了他们的世界。"
D.Strings[116606]="随着时间的流逝，耐奥祖意识到了氏族的命运已经落入了燃烧军团的手中，并且，这位兽人中最伟大的萨满开始逐渐对基尔加丹表示出了不满。基尔加丹被耐奥祖的反叛行为彻底激怒了，他决定换一个手下，于是便转向了耐奥祖的学徒古尔丹，古尔丹显然比耐奥祖更加堕落。"
D.Strings[116607]="正是古尔丹应该为氏族中的萨满之道的逐渐没落而负全部的责任。对力量的渴求与试图控制一切的野心使他彻底拜倒在这些诱惑前。在基尔加丹的帮助下，古尔丹开始了他对诸氏族的统治。曾经高贵的兽人们就此而堕落了，成为了一群没有心智的野蛮人。自恶魔的血液被注入了他们的身体之后，兽人们比以前更加野蛮和残忍了。"
D.Strings[116608]="尽管基尔加丹在耐奥祖身上遭遇了失败之后立刻转向古尔丹仍是堕落，但他仍然非常憎恶那位老萨满，并发誓一定要让耐奥祖履行他们之间的合约。基尔加丹最终抓住了耐奥祖，并使用了一系列残酷的刑罚来折磨他，迫使这位老萨满就范。耐奥祖只求一死，但基尔加丹提醒他，合约仍然束缚着两人。基尔加丹最终还是杀死了他，但这仅仅是在肉体上，这位老萨满的灵魂在进入扭曲虚空之前却被基尔加丹擒获了。"
D.Strings[116609]="基尔加丹将耐奥祖的灵魂封入了一块由扭曲虚空采集来的冰块中。然而在被封入冰块时，耐奥祖从中汲取到更多的力量。肉体上的伤害与如此强大力量的灌注使得耐奥祖彻底变了。"
D.Strings[116610]="基尔加丹将这块封锁着耐奥祖灵魂的冰块透过次元门丢回了艾泽拉斯，落在一片名为诺森德大陆的地方。此举无疑是将这个最邪恶的人引入我们的世界。耐奥祖就此留在了那里；在他的位置下出现了冰霜与憎恨相结合的王座。曾经最受爱戴与尊敬的萨满领袖如今成了一位无比强大的巫妖王。"
D.Strings[116611]="因为基尔加丹仍对巫妖王心存忌惮，于是他派出了他手下恐惧魔王们去监视耐奥祖的灵魂，并确保这位巫妖王能乖乖服从他的命令。这些吸血鬼般的仆人带着毁灭巫妖王的阴谋与对他无比力量的欲望，非常兴奋地来到艾泽拉斯大陆，并计划将这个世界上现存的所有种族全部消灭。"
D.Strings[116612]="一段时间过去了。在这段时间中，巫妖王利用他强大的法力彻底控制了诺森德大陆上所有生物的心智，强迫着它们在他的冰封王座周围建立了一座宏大的根据地。如今，诺森德大陆如今已经完全落入了巫妖王的统治之下，耐奥祖也已经决定了，他的下一个目标将是洛丹伦大陆。由于被封在冰中，这位前兽人萨满开始寻找更多可供他操纵与摆布的思想。他的诱惑与召唤已经跨越了大海，遍及各个大陆。"
D.Strings[116613]="没有人能够忽视巫妖王的召唤，这一点在一小部分拥有着强大力量的人群中尤其明显。在这其中有一人特别值得一提，他就是达拉然法师的执政团体肯瑞托中的重要一员，大法师克尔苏加德。他热衷于追寻包括黑魔法在内的各种魔法，甚至不惜为此与肯瑞托的政策为敌。克尔苏加德为了能从巫妖王那里学到更多的东西而不顾肯瑞托的阻挠，他切断了他与大陆上其他任何人的联系，来到到巫妖王的身边。"
D.Strings[116614]="于是，两人之间签定下了一份合约。克尔苏加德以对巫妖王的效忠换取到了不朽的生命与无穷的力量。而克尔苏加德第一个任务就利用他在洛丹伦大陆上的财产与影响力在大陆上建立一个教派——诅咒教派。这个教派向他们的信徒们承诺，只要宣誓永远追随与崇拜诅咒教派的神——耐奥祖，他们就将得到平等的对待与永恒的生命。"
D.Strings[116615]="耐奥祖随后制造出了一种用于向洛丹伦大陆上的人类文明散布瘟疫的器物，并将这些器物交给克尔苏加德。他命令法师将这种瘟疫传遍大陆。而他的信徒们则将不计代价的保护好这些器物，以便传播行动的进行。"
D.Strings[116616]="一旦进入了适当的地区，瘟疫病毒便会渗透入地表并开始在那些对此一无所知的市民进行传播。而在克尔苏加德的管理下，巫妖王的军队迅速壮大起来，并控制了洛丹伦的大部分土地。这支军队就是后来的天灾军团，它的唯一目标就是将艾泽拉斯大陆上的人类全部都清除干净。"
D.Strings[116617]="墓碑上被潦草地刻上了“叛徒”这两个字，除此之外，碑文还清晰可见：$B 尤瑞夫安眠于此。$B 挚爱的父亲，丈夫，圣骑士。$B 让他的孩子们见证他对圣光奉献的事实是无庸置疑的。$B 他从不要求他的孩子们做他自己做不到的事。"
D.Strings[116618]="日记 - 第4天$B$B我已经在这个岛上被困4天了，我很孤独，只有我的思想与我为伴。香蕉的味道很好，但我得爬上很高的树才能摘到。等到我不能再去寻找食物，也不能再保护自己免受阵雨之苦时，我满脑子想的，都是如何逃出这里。$B$B要是不再有纸和瓶子被冲上海滩来，我就要彻底绝望了。我坐的那条该死的船，居然装满了链金药剂和药方，它们对我一点用都没有。"
D.Strings[116619]="日记 - 第512天$B$B 我最近和香蕉们聊了很多，我也从它们的话中了解到了许多有关它们文化的东西。我对自己无意之间毁灭了它们的家园、吃了它们的孩子表示万分的歉意。对于这个差点被我毁灭的文明，我了解得实在是太少了。$B$B 似乎我的纸和瓶子都快用光了。我第一眼看到海滩上堆着的这些纸和瓶子的时候，还以为那是取之不尽用之不竭的呢。我的生命快要结束了，我的日记也是。"
D.Strings[116620]="$B 艾泽拉斯世界中总是会有着各式各样的奇迹。植物，动物，文明，魔法，这些都是永远不变的主题。事实上，世界上有着无穷无尽可以勾起人们好奇心的东西，很难把它们看尽。$B$B 但只要一个人能真正深入地观察，他的面前就会出现无数全新的世界，而每一个世界中都还有属于它们自己的奇迹。$B$B 这就如同每个世界都有属于它们的恐怖一般。"
D.Strings[116621]="$B 我写这本书的目的就是将这些东西仔细归类，这些来自异世界的恶魔们的唯一目的就是摧毁我们的世界，所以当冒险者们遇到它们时，一定要能准确地认出它们来。$B$B 所以，如果你也愿意承担起保卫艾泽拉斯的职责，就请仔细阅读这本书，以了解你的敌人。$B$B - 乌尔$B 达拉然法师"
D.Strings[116622]="我所写的这种怪物是狼人。$B$B 古老的乡村民谣或传说里经常会提到类似的生物，哪个农村里的孩子会没有听说过这种半人形直立行走的野兽呢?$B$B 事实就是隐藏在这类传说背后的——或许人们正是利用这种故事来警告狼人，就好像用这些故事来吓唬小孩子一样。"
D.Strings[116623]="在你将这些故事当作耳旁风而不屑一故之前，请先允许我告诉读者们：狼人是确实存在的。它们或许与我们不处在同一个世界中，但他们的家乡与我们的世界之间却存在着某种通路，而某种强力的魔法力量则可以通过它将狼人带到我们这里来。$B$B 这种魔法最好永远无人知晓，因为狼人所到之处，留下的只有恐惧与鲜血。"
D.Strings[116624]="将它们与我们世界中的狼对比后，你会对它们有更多了解。当你看见狼人的时候，你很快就会发现它那卷曲的毛发、尖锐的耳朵、修长的口鼻部位，这些都与我们所熟知的狼非常类似。$B$B 但你也很容易地看出两者的区别：它们的毛皮下包裹着一副更加强健的躯体，它们可以双足直立行走，并有着如匕首一般锋利的尖牙利爪。在它们凄惨的嚎叫声中隐藏着一种其他野生兽类绝不会有的凶残。"
D.Strings[116625]="狼人生存的世界是个充斥着梦魇的黑暗之所。如果你要问那个世界上有什么地方可以不被这些狼人肆虐，我的研究显示：没有。$B$B 其实，只要想一想狼人这种生物是多么的残忍与邪恶，就知道那种地方是不可能存在的了。$B$B 不过，狼人似乎很满足于留在它们自己的世界里，尽管它们中间的一部分成员掌握着强大的魔法力量，但却从没有试图向艾泽拉斯世界进军。$B$B 这对我们来说未尝不是一件幸事。"
D.Strings[116626]="正如之前所提到的，一些狼人有相当成熟的魔法造诣，而且他们的魔法中蕴涵着黑暗与堕落的力量。$B$B 诅咒与超自然的毒素是他们经常使用的东西，所以在面对这些狼人魔法师的时候，你必须要有对抗暗影魔法的准备。"
D.Strings[116627]="身为卡加斯派出的斥候，我对周围环境的描述如下：$B$B - 红色的岩石丘陵与干燥的平原，只有极少数生物才能在此生存。$B - 阳光炽烈，强风。$B - 没有湖泊和溪流，也没有任何池塘。想要找水的话，就必须挖出泥泞的深井，或者从仙人掌与其他针刺类植物中榨水。$B$B 简而言之：燥热，难以生存。"
D.Strings[116628]="荒芜之地中满是我们的敌人。巨魔会从沙中咆哮着突然钻出，伏击任何缺乏警惕的冒险者。黑铁矮人则在卡加斯的东部建立了一处基地，并和他们那些浅色皮肤的表亲们在洛克莫丹北部地方交战。某种野蛮且原始的名为穴居人的种族疯狂地占据着这里的每一片土地，并寸步不让地保护着他们的领地。$B$B 那么荒芜之地东部的莱瑟罗峡谷呢?它彻底被龙占据了。我们不知道那里的龙有多少，也不知道他们有多强大，因为派去那边侦查的斥候没有一个能活着回来的。"
D.Strings[116629]="不用说就知道，我们卡加斯卫戍部队对能够被部署在这里感到非常高兴。我们已经在这里坚强地扎下了根，因为只要我们略微示弱，就会死在这里。$B$B 在这里也没有别的办法可以生存下去了。$B$B 尼卡·血痕$B 斥候队长，卡加斯"
D.Strings[116630]="活塞的技术参数：$B$B 长度：32胡展$B 宽度：12胡展$B 重：23.5豆克 - 25.5豆克$B 传导：70趾曲$B 杆部强度：大于等于98$B 连结指数：烈酒级或更高$B$B 若你忘了地精的度量衡单位，说明如下：$B 胡展=一根胡子的长度$B 豆克=一块鹰嘴豆的重量$B 趾曲=脚趾的曲度"
D.Strings[116631]="我带着队伍继续往海边走去，希望在那里的海岸线旁找到某个可以避开迅猛龙的地方。但是在匆忙之中，我们跑到了一处危险的高地，这是个可怕的错误，全都是我的错。我们停在了一个陡峭的悬崖边，而那些迅猛龙距离我们仅有几步之遥。"
D.Strings[116632]="喂食和照料须知：$B$B 我们郑重承诺为您提供照料宠物所需的一切资讯，让您从地鼠有限公司得到专业的服务!$B$B 为了达到这一目标，我们为牢固的地鼠笼设计了一些小孔，这让您的宠物可以在其中安逸地生活，而且不用受日晒雨淋之苦。$B$B 为了您的方便起见，每只笼子中都安装了一个喂食器，它带有诱人的蓝叶薯的味道（这是地鼠最喜欢的食物）!"
D.Strings[116633]="我们的世界有着悠久的历史，一段由新生的种族与古老的种族共同谱写的历史，一段神祗之间互相征伐的历史。$B$B 一段秩序之神从天而降的历史，一段有关长眠地下的上古之神的历史。$B$B 我要讲述的就是这些上古之神的故事，他们在艾泽拉斯世界形成之初就居住于此。"
D.Strings[116634]="上古之神代表了我们这个世界的意志。他们的笑声从暴风中传出，他们的气息蕴含在烈焰中。当上古之神走动的时候，地表也随之振颤，所有的生灵都绝望地悲鸣，将自己的血肉撕裂。$B$B 他们确实应该感到绝望，因为就像烈火会无情地灼伤好奇的小孩子那样，上古之神是不会关心那些卑贱的生物的。说得好听一些，我们只是一些走卒。说得难听一些，我们就是玩物。"
D.Strings[116635]="上古诸神是这个世界最早的主宰，他们控制了所有的力量。虽然他们现在被困住，处於长眠之中，但他们的仆从依旧在横行，而我们弱小脆弱的凡人，是无法和他们的力量相比拟的。$B$B胆敢挑战他们的蠢货都被吞噬了。只有那些为了自保而去逢迎上古诸神的仆人的人才能生存，虽然其代价是牺牲自己的灵魂和意志……"
D.Strings[116636]="深渊公主阿库麦尔一直以来都为上古之神效力，她运用上古的智慧为自己的洞穴祈祷。阿库麦尔是由古老的凡人带入黑暗深渊的，她是神的象征。虽然她只拥有上古之神的很小一部分的力量，但是她已经是如此的深不可测。$B$B 她被信徒们崇拜着，畏惧着，热爱着。$B$B $B - 洛迦里斯"
D.Strings[116637]="计划正在执行中。$B$B 控制那座伟大的堡垒——英雄岗哨，将它作为我们的基地，一旦你准备完毕之后，就可以要求我们从西部荒野派遣增援力量。$B$B 这块区域已经被暴风城的人完全遗忘了，所以正好可以作为我们发动攻击的起点。$B$B 迪菲亚兄弟会必将再次进入暴风城!$B$B 我等待你的恢复。"
D.Strings[116638]="那些肮脏的石腭怪实在是太好唬弄了。它们对于我们的极端憎恨使得我们可以反过来利用它们……看来什么样的同盟都可以形成啊，但是我们的那些同胞对于石腭怪来说确实有很大的威胁，至少现在是如此。$B$B 战斗开始之后，他们双方的力量必然都会被削弱，然后我们就可以进军盔枕湖并等待下一步的指示了。$B$B 铁炉堡终将是我们的。"
D.Strings[116639]="烧焦的蜘蛛牙：$B$B 在瑟根石附近的一个洞穴中发现的火岩矿石对栖息在那里的蜘蛛产生了烧灼影响。$B$B 它们毒牙中的毒素被蒸发，并与牙齿本身产生了反应，因而造就出了一种非常坚硬的物质。"
D.Strings[116640]="烧焦的奇美拉角：$B$B 与烧焦的蜘蛛牙类似，卡利姆多石爪山地区的焦炭谷中有许多奇美拉，它们身上的烧焦的奇美拉角也有着惊人的高品质。$B$B 只要把它敲平并进行妥善的处理，它就将是最具延展性的上好材料。"
D.Strings[116641]="光滑的奇美拉角：$B$B 光滑的奇美拉角非常稀有，也非常坚硬，我可以用它制造出浑然一体的整片铠甲来，所以这种材料是我必需的。$B$B 你可以在焦炭谷中的奇美拉身上找到这种材料。"
D.Strings[116642]="燃素：$B$B 制造铠甲的最后一步需要用到一种特制的高温炉。要生成那种程度的高温，必须要使用燃素才行。$B$B 我知道的唯一一个会制造这种东西的工匠是个名叫鲁古格的野猪人，恐怕你得打败他才能拿到东西。鲁古格就住在贫瘠之地南方的剃刀沼泽里。"
D.Strings[116643]="以下是我施放召唤塞克隆尼亚的法术所必需的物品列表。祝你好运。$B$B - 捕风者巴斯拉"
D.Strings[116644]="活根草：$B$B 这种草可以在野外采集到，或者在尘泥沼泽中的枯藤兽身上收集到。它的力量可以帮助我们将塞克隆尼亚的生命精华抽取到这个世界中来。"
D.Strings[116645]="血顶食人妖的獠牙：$B$B 荆棘谷中的血顶食人妖长着高品质的獠牙。血顶食人妖的堕落特质主要集中在他们的獠牙上，如果把这种獠牙磨成粉末，其中的邪恶力量就会被释放出来。"
D.Strings[116646]="流放精华：$B$B 提炼这种精华所必需的符咒可以从阿拉希高地的那些被放逐的元素生物身上找到。我们需要雷霆符咒、燃烧符咒和海浪符咒，每样八个，然后把它们放进我的容器中。$B$B 有了符咒之后，我就可以合成流放精华了。"
D.Strings[116647]="流放精华:$B$B提炼这种精华所必需的符咒可以从阿拉希高地的那些被放逐的元素生物身上找到。我们需要雷霆符咒、燃烧符咒和海浪符咒，每样八个，然后把它们放进我的容器中。$B$B有了符咒之后，我就可以合成流放精华了。"
D.Strings[116648]="$N：  首先，请允许我对你为我和我的妻子所做的一切再次表示感谢。你救了她的命，单凭这个，我就永远也无法偿还你这个人情了。她对我来说就意味着一切。如果她死了……我都不知道我会干出些什么。    以下是铸造一把神圣武器所必需的材料，你把这些东西都找齐，我就可以马上帮你把它铸造出来。我按照从易到难的顺序对它们进行了排列——希望这样可以让你更加便捷地找到它们。"
D.Strings[116649]="白石橡木：在西部荒野的月溪镇被迪菲亚盗贼占领之前，那里的矿井中有很多这样的木材。它具有良好的耐热耐压能力，经常用来制作矿井的支撑架和其它工具。    那些白石橡木应该是从别的地方运过去的。这是一种稀有而坚硬的木材，可以用于你的武器。如果矿井中还有这种木材的话，你应该可以在地精木匠身上找到它们。"
D.Strings[116650]="精炼矿石：在塞尔萨玛有个叫白洛尔·石手的矮人铁匠，我曾经在他手下接受过训练。他能够制作一种非常特殊的合金，这种合金在你的武器中也是一个非常重要的组成部分。原本应该有一批这种合金被运到铁炉堡来的，但至今我还没有得到相关的消息。    去找到他，帮我询问一下那批货的下落。如果他不在洛克莫丹的话，那我至少想要知道我的老师去哪里了。"
D.Strings[116651]="铁匠之锤：在大瘟疫来袭和阿尔萨斯堕落之前，我居住在银松森林里的焚木村。现在这座森林已经不再美丽，而我学习锻造技术的城堡也早就被可怕的邪恶力量玷污了。    当我和我的妻子离开影牙城堡的时候，我把一些非常重要的工具留在了那里。"
D.Strings[116652]="在这些东西中，铁匠之锤是我父亲留给我的。他曾告诉我说这把锤是被附过魔法的，我也曾怀疑过这一点，但是不管怎么样，它是我父亲留给我的最后一件东西。    $N，请找到它，把它交给我，这样我就能找回往日的激情了。如果它确实被附加了魔法，那对于你我来说都是有利的。    我把它留在了城堡庭院的马厩里了。那里的怪物理论上是不会做铁匠活的，所以我相信那把锤子应该还在那里。"
D.Strings[116653]="这张手卷上画满了旋转的记号和复杂的象形文字，这些奇怪的符号让你难以理解。"
D.Strings[116654]="一块翡翠。很多地方都有翡翠。它们很稀有，但是如果你去找某位铁匠或技师谈谈的话，他们或许会有多余的翡翠可以卖给你。"
D.Strings[116655]="$N，你需要以下的东西来铸造你的护甲：$B$B 石爪山狂风矿坑里的狗头人身上携带的烟雾铁锭。$B$B 希尔斯布莱德矿坑里的蓝铜粉。$B$B 铁锭则要从矿工们那里获取，当然如果你自己也会采矿的话就更好了。$B$B 至于燃素，你必须从剃刀沼泽那边的一个名叫鲁古格的野猪人身上抢来。"
D.Strings[116656]="星辰的孩子已经在永恒之井闪光的湖水边定居了很久。众所周知，象征永恒曙光的伊露恩在就在这水中休憩。岸边住着星辰的孩子们，伊露恩眷顾着他们，给他们安家，而他们也总在夜晚虔诚地凝望月空。"
D.Strings[116657]="奥达曼，第四天$B$B ……在奥达曼深处，我发现了第一条线索，那里有一头凶恶的石腭怪正在摆弄一大块蓝宝石——这块蓝宝石正好能够安在项链上。我记得暗炉矮人曾经提起过这头石腭怪的名字：格瑞姆洛克。它长得真是非常强壮……"
D.Strings[116658]="奥达曼，第五日$B$B ……那头石腭怪拿着从它那被杀掉的同族身上抢来的黄玉进入了大厅前面的侧室……$B$B ……它把黄玉放进了一只很显眼的、正对着墓室后面的石棺中……$B$B ……不过，有三个矮人守在那里!他们挡住了石腭怪的去路。引起他们的注意无异于自杀，我真怕现在这样虚弱的我被石腭怪一口给吞了。不过，如果我知道了第三块宝石的下落，我就要……"
D.Strings[116659]="奥达曼，第六日$B$B ……好饿啊。我已经断水断粮很多天了，现在即使给我一块发霉的面包，我也会当它是盛宴。我刚才甚至把一个石腭怪的头看成一块肉排……"
D.Strings[116660]="奥达曼，第七天$B$B ……这是我最后一次弥补自己犯下的错误的机会了。我相信红宝石就藏在矮人们上次挡住石腭怪不让它进入的地方。他们的战斗无疑就是因为这块宝石和其他宝物而展开的。那些可恶的矮人肯定把它藏在什么地方了。不管这些了，我无论如何也得从这里走出去。或许直接向上挖条出路是最好的选择……"
D.Strings[116661]="去找一把电能草莓来。要想得到这个东西的话，你必须从阿拉希高地上的枯木食人妖那里收集10根冰木图腾，把这些图腾柱带到那里的外禁锢法阵去。将图腾柱放在法阵中心的石头上，等着它被雷击中。然后一把电能草莓就这么形成了。"
D.Strings[116662]="能得到这份证书的盗贼也必将得到所有初级盗贼的尊敬和关注。"
D.Strings[116663]="我发现了进入卡兹莫尔大厅的方法!$B$B 从我的箱子中拿到尼基夫徽章。$B$B 击败那个放着地图的房间前面小房间里的石腭怪鲁维罗什，然后拿到萨尔之杖。$B$B 将这两者合成史前法杖。$B$B 在那个布置着地图的房间里使用法杖，就可以打开卡兹莫尔大厅的门。$B$B 只要按照以上步骤来做，你就可以进入那个房间了!$B - 巴尔洛戈"
D.Strings[116664]="这座塔中的守卫在我的攻击下显得非常脆弱。当时我正在塔的后方侦察，一个巡逻中的守卫发现了我，并向我展开了攻击。我很轻松地就了结了他。$B$B 然后，我躲入了阴影中，等着他的同伴前来调查这次小骚动。另一名巡逻兵走进了我掩藏尸体的那处灌木丛，并开始四下搜索。而我则从他身后小心谨慎地爬了出来，跟在他后面，他一点都没有察觉到。"
D.Strings[116665]="我看准机会，猛地将匕首刺入了他的背后!他的胸口一下就被我刺穿了，尸体沉重地倒在了地上。$B$B 这次伏击实在是太突然了，这个可怜的家伙甚至连惨叫的时间都没有。不过，令人好奇的是，当我把匕首从他背后拔出来的时候，一种腐臭的气味从他的尸体中弥漫了出来。"
D.Strings[116666]="指挥官：$B$B 速回奥格瑞玛。现在不宜采取行动，我们必须根据最新情报重新分析我们的战略部署。$B$B 在那里有很多恶魔的信徒和巨魔出没，还有许多恶魔守护着黑暗之门。$B$B - 萨尔，部落酋长"
D.Strings[116667]="祖尔法拉克之槌    想要创造祖尔法拉克之槌，你首先要从祖尔祭坛的巨魔守护者手中夺取神圣之槌。    将神圣之槌拿到巨魔城市辛萨罗顶部的祭坛上。    在祭坛上使用神圣之槌，将祭坛的力量灌入其中，这样就能创造出祖尔法拉克之槌了。"
D.Strings[116668]="超级临界三倍编码资料卡$B$B 01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111"
D.Strings[116669]="风险投资公司<字迹模糊的文字>看来那些笨蛋为了稳定混合物几乎把整个计划都搞砸了。    <接下来的几页都已经被撕碎>"
D.Strings[116670]="我注意到辐射的威力非常大。想象一下，如果<字迹模糊的文字>哈哈哈！"
D.Strings[116671]="我要疯了吗？今天我把我最信任的一个巡逻兵的头砍了下来，仔细观察他的灵魂。在我看着他的脑袋时，我突然想起来——已经好几天没吃东西了！"
D.Strings[116672]="马迪亚斯·肖尔派了个蠢货来刺杀我。<字迹模糊的文字>    他现在正在外面为我巡逻，而且是个没有脑子、没有生命的傀儡。    哈哈哈！"
D.Strings[116673]="范克里夫……<字迹模糊的文字>    召唤我？！我是克拉文·摩特维克！我怎么会被你这样一个无名小辈指挥！    <这本书剩余的部分都不见了>"
D.Strings[116674]="克格尔：$B$B我一直都在急切盼望着得到你的最新发明，我已经等不及要用它来记录我的研究成果了！$B$B请将你的发明交给我的信差。$B$B此致$B$B达蕾恩?轻风"
D.Strings[116675]="重要资料!安全等级5122!$B$B 01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101"
D.Strings[116676]="决不能让以下资讯落入敌人手中!$B$B 01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010"
D.Strings[116677]="安全等级10^10000，最高机密！$B$B 01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001"
D.Strings[116678]="以下资料的安全等级非常高，必须重新发明一种数位记录方式才能对其进行安全等级定义!$B$B 01001101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01110100 01101111 00100000 01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00111010 00100000 01111001 01101111 01110101 01110010 00100000 01101100 01100001 01110101 01101110 01100100 01111001 00100111 01110011 00100000 01110010 01100101 01100001 01100100 01111001 00100000 01100110 01101111 01110010 00100000 01110000 01101001 01100011 01101011 01110101 0111"
D.Strings[116679]="遛地鼠$B$B 地鼠喜欢狭窄黑暗的地方，它非常害羞。$B$B 如果您希望让地鼠到处走走的话，那么您一定要把它带到有家的感觉的地方，要让它闻到它最喜欢的食物——蓝叶薯的味道!$B$B 这附近最适合的地方就是剃刀沼泽附近的沟槽。如果您在那里打开笼子，您的地鼠就会闻到周围蓝叶薯的味道，然后它就会走出来跟着您了。"
D.Strings[116680]="地鼠指挥棒(tm)$B$B 地鼠是一种非常惊人的动物，它不仅能激起心胸最狭窄的平原陆行鸟的关爱，还能嗅出50码以内的蓝叶薯的味道!$B$B 如果您想要让你的地鼠找到一块蓝叶薯，那么您可以使用我们的专利产品：地鼠指挥棒（不包含在本产品中，需另外购买）。$B$B 请参考后面几页的详细使用说明……"
D.Strings[116681]="我们所有的地鼠都经过严格训练，您只需简单地挥动指挥棒，就可以让身旁的地鼠进入“搜索状态”。它会用嗅觉搜寻蓝叶薯，并会自己去把它挖出来。$B$B 如果您在地鼠搜索蓝叶薯的时候再次挥舞指挥棒，那么它就会停止搜索，回到您的身边。$B$B 我们相信您一定会发现我们的地鼠都是经过严格训练的搜寻专家，实乃居家旅行、发财致富的必备伴侣!"
D.Strings[116682]="这份契约是为了证明$N杀掉灼热峡谷中的一大祸害：狂暴的玛尔戈。$B$B 铁炉堡博物馆特此颁发奖状，以表示我们对此举的认可，并对这份奖状的获得者表示感谢。$B$B - 馆长 杜里奥斯·裂石"
D.Strings[116683]="这几个月以来，我花了很多时间进行思考，我以前的信念和固执的理念开始动摇。联盟?部落?正义?邪恶?这些对我来说曾经含义清晰的辞汇，现在看来却如同无尽之海那样朦胧而模糊。$B$B 现在我知道什么是最重要的了。我后面都是香蕉。$B$B 它们栖息在树木上，用恶毒的眼光盯着我。我刚才吃的那一只香蕉差点把我噎死了!当我把它扔到礁石上的时候，我甚至可以听到它的惨叫。$B$B 这是战争，我会获胜的。"
D.Strings[116684]="工程学分支$B$B也许“哪个种族首先在艾泽拉斯大陆开创了工程学这门学科”的问题在学术界依然没有定论，但是对于支撑工程学的两大重要支柱，想必大家都有共识——那就是地精和哥布林。他们所创造的工程学发明不仅给这个魔法时代添加了许多色彩，而且还使两个种族之间的争端进一步加剧。他们两个种族的分歧在这一点上显得尤其突出。"
D.Strings[116685]="地精工程学$B$B地精这个种族非常善于设计那些供用户控制和操作各种物体的装置。虽然他们也把一部分注意力放在爆炸品和武器上，但总的来说，地精工程学主要的方向是设计那些使生活更加简便的物品。所有的地精设计都会经过严密的可行性分析，而实际上有许多设计根本就没有付诸于执行。"
D.Strings[116686]="哥布林工程学$B$B作为一个中立种族，哥布林成功地将科学转化为他们的利润。他们将工程学的理论运用于实际的生产中，并将其转化为可观而稳定的利润——这些理论包括他们广泛应用的爆破、火器和机械科学。哥布林工程学对于工程学理论的兴趣很小，因为他们的发明几乎不存在无法工作的问题，它们只是工作得太出色了。显然，这些发明不是为了懦夫而设计的。"
D.Strings[116687]="理论学习$B$B地精和哥布林互相之间保持着知识的隔阂，所以你根本无法同时学习到这两套理论。无论你持何种政治观点，只有当你同意永远不接触另一个种族的工程学理论事，你才能学习某个分支的工程学。如果一个学生选择了地精工程学，那么他就永远不能学习哥布林工程学。"
D.Strings[116688]="永久性的选择$B$B前面的部分强调了两个工程学派系的主要区别。选择任何一种分支，都等于永远放弃另一个分支。虽然这有可能造就一个二流的技师，但是你应该可以理解，地精和哥布林是在尽自己的所能来保护自己的工程学秘密；有一点知识总比什么都没有要好。"
D.Strings[116689]="引用$B$B“你想要了解更多关于哥布林工程学的东西?那就问问我们最优秀、最聪明的技师吧——我想他的名字应该是努比·斯塔普芬格斯。想要知道他为什么叫这个名字吗?这就是哥布林工程学!”-- 林戈·特拉格迪克，哥布林技师$B$B“如果你想要知道什么就直说，但是我会告诉你：我们有炸弹!”$B-- 雅兹·尼托斯伯克，哥布林投弹手"
D.Strings[116690]="召唤：$B$B 想要召唤地狱寻踪犬，你就必须使用魔珠。$B$B 注：$B$B 召唤而来的地狱寻踪犬只能在这个世界上存在30分钟。$B$B 它只会协助你寻找艾萨拉晶体物质。$B$B 它不会做以下事情：玩耍，攻击任何目标，协助任何人，跳舞，摧毁魔法物品。$B$B 请继续阅读下一页……"
D.Strings[116691]="野兽控制：$B$B 地狱寻踪犬只对野兽般的吼叫有反应。为了让你的地狱寻踪犬帮你找寻艾萨拉晶体物质，你必须用力对它吼叫!（点击地狱寻踪犬，然后输入/roar指令）$B$B 当地狱寻踪犬找到艾萨拉晶体物质之后，它会不顾一切地冲到目标旁边。虽然你并不需要保护地狱寻踪犬，但你也需要和它靠得够近，从而不至于失去它。"
D.Strings[116692]="解散：$B$B$B 注：$B$B 它的能量十足，因此有可能掉落山崖，或者从山上坠落。不要为此而感到悲伤，你可以马上召唤另外一个。"
D.Strings[116693]="致读此信者：$B$B 如果你读到了这封信，那么你只可能在两个地方：$B$B （1）在艾萨拉的南部半岛上。$B$B （2）在峭壁巨人的胃里。$B$B 这两处都不是什么好地方。$B$B 你要知道，我曾经在前面的那个地方待过，至于写这份信的时候，我在后面的那个地方。"
D.Strings[116694]="在一个巨人的胃里待久了，我身上起了不少反应。$B$B 随着我的身体逐渐变得水晶化，我开始认为这世上应该有许多的英雄。如果我能逃出这里的话，我一定会扭断那个兽人的脖子!$B$B -- 温丹·沙恩"
D.Strings[116695]="我在想什么?$B$B 也许这个问题应该有更好的问法：我坐在巨人的胃里还写什么便笺?$B$B 这两个问题都很好，而且我都不能马上回答……$B$B 我承认，我来这里并没有什么崇高的目的。我是来找艾萨拉水晶的，这是一种艾萨拉南部特产的水晶。我找到它之后就可以富甲天下了!$B$B 不过，看看我现在的样子……"
D.Strings[116696]="尼尔斯修士：$B$B 我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然后带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B 你可以在你的商店中再次供应葡萄了。$B$B 愿圣光保佑我们，$B - 米莉·奥斯沃斯"
D.Strings[116697]="沃弗克·铁壶$B$B 沃弗克在黑铁酒窖的储藏室工作，他为黑暗守护者做出的牺牲意义重大。$B$B 愿他的灵魂坚定而顽强。"
D.Strings[116698]="比塞克·雷眉$B$B 比塞克的游荡将他引入了黑石深渊，山脉的秘密在召唤着他。$B$B 愿他的灵魂永远不要踌躇。"
D.Strings[116699]="尤格尔·锤手$B$B 尤格尔是一位技巧高超的凿工，当他还没有遇到黑暗之钥的时候，他在工匠大厅中雕琢伟大的作品。"
D.Strings[116700]="希姆雷尔·暗齿$B$B 当黑暗之钥的疯狂占据希姆雷尔时，只有死者的尖叫可以使他平静。$B$B 希姆雷尔总是在竞技场旁坐着。愿我们的血腥搏杀可以平息他心中的怒气。"
D.Strings[116701]="奥弗加特·石拳$B$B 丧命于黑暗守护者奥弗加特锤下的挑战者不计其数。$B$B 西部兵营的士兵们在他走过时卑躬屈膝。他们之中有谁敢直视奥弗加特的双眼并看到黑暗之钥的秘密呢?"
D.Strings[116702]="佩沃尔·铁足$B$B 黑暗守护者佩沃尔是我们最为尊重的信徒。他携带黑暗之钥的时间远远超过其他黑暗守护者，这使他付出了惊人的代价。$B$B 他的牺牲让我们感到惋惜，对他的怀念会一直留在我们心中……自从黑暗占据了他。"
D.Strings[116703]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\"><BR/> 第一章：北部水晶塔<BR/> </H1><BR/> <BR/><BR/> <BR/><BR/> <IMG src=\"InterfacePictures11482_crystals_mini_north\"/><BR/> <P align=\"right\">北部水晶塔<BR/><BR/> 可以接受<BR/><BR/> 黄色、红色<BR/><BR/> 以及绿色的<BR/><BR/> 水晶。</P><BR/> <BR/><BR/> <BR/><BR/> <BR/><BR/> <BR/><BR/> <P align=\"left\">水晶塔依靠黄色水晶作为主要能源来制造特殊的物品。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[116704]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">$B 北部水晶组合$B </H1>$B <BR/><BR/> <P align=\"left\">可能产生两种效果：一种制造伤害，另一种则可以抵消伤害。</P>$B <BR/><BR/> <P align=\"left\">爆炸水晶：需要红色和黄色水晶。<BR/>它将产生大爆炸，并且令你的敌人昏迷。</P>$B <BR/><BR/> <P align=\"left\">恢复水晶：需要黄色和绿色水晶。<BR/>它将为你提供一个治疗光环。$B </P>$B </BODY><BR/> </HTML>"
D.Strings[116705]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\"><BR/> 北部水晶塔图表<BR/> </H1><BR/> <BR/><BR/> <IMG src=\"InterfacePictures11482_crystals_north\"/><BR/> </BODY><BR/> </HTML>"
D.Strings[116706]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\"><BR/> 第二章：东部水晶塔<BR/> </H1><BR/> <BR/><BR/> <BR/><BR/> <IMG src=\"InterfacePictures11482_crystals_mini_east\"/><BR/> <P align=\"right\">东部水晶塔<BR/><BR/> 可以接受<BR/><BR/> 蓝色、黄色<BR/><BR/> 以及绿色的<BR/><BR/> 水晶。</P><BR/> <BR/><BR/> <BR/><BR/> <BR/><BR/> <BR/><BR/> <P align=\"left\">水晶塔依靠蓝色水晶作为主要能源来制造物品。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[116707]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\"><BR/> 东部水晶组合<BR/> </H1><BR/> <BR/><BR/> <P align=\"left\">可能产生两种效果：一种提高你的精神属性，另一种则能够制造一种护盾。</P><BR/> <BR/><BR/> <P align=\"left\">精神水晶：需要蓝色和绿色水晶。<BR/>它可以提高你的精神属性。</P><BR/> <BR/><BR/> <P align=\"left\">尖刺水晶：需要蓝色和黄色水晶。<BR/>它可以为你提供一层能对攻击你的敌人造成伤害的护盾。<BR/> </P><BR/> </BODY><BR/> </HTML>"
D.Strings[116708]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\"><BR/> 第三章：西部水晶塔<BR/> </H1><BR/> <BR/><BR/> <BR/><BR/> <IMG src=\"InterfacePictures11482_crystals_mini_west\"/><BR/> <P align=\"right\">西部水晶塔<BR/><BR/> 可以接受<BR/><BR/> 红色、绿色<BR/><BR/> 以及蓝色<BR/><BR/> 水晶。</P><BR/> <BR/><BR/> <BR/><BR/> <BR/><BR/> <BR/><BR/> <P align=\"left\">水晶塔依靠红色水晶作为主要能源来制造特殊的物品。</P><BR/> </BODY><B"
D.Strings[116709]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\"><BR/> 西部水晶组合<BR/> </H1><BR/> <BR/><BR/> <P align=\"left\">可能产生两种效果：一种可以增强你抵抗伤害的能力，另一种则能降低敌人的防御力。</P><BR/> <BR/><BR/> <P align=\"left\">防御水晶：需要红色和绿色水晶。<BR/>它将提高你的护甲值。</P><BR/> <BR/><BR/> <P align=\"left\">破甲水晶：需要蓝色和红色水晶。<BR/>它将降低指定目标的护甲值。<BR/> </P><BR/> </BODY><BR/> </HTML>"
D.Strings[116710]="你好，冒险者，我向你致敬!$B$B 我，克林科·古德斯迪尔，需要一些人帮我完成一些艰钜的任务。因为我自己有很多工和工作，因此得由一个足够勇敢的冒险者来找到清单里列出的物品，并把它们交给我，我保证支付丰厚的报酬。$B$B 清单将在下几页中列出……"
D.Strings[116711]="水晶蜘蛛腿 -$B$B 灼热峡谷中生活着许多晶网蜘蛛，它们的身体是由坚固的水晶构成的。如果你在杀死它们的时候没有打断它们的腿，就可以帮我的伙伴收集这种在工程学中必不可少的传导材料。$B$B 我需要一定数量的水晶蜘蛛腿来进行实验，对于一名坚定的战士或者训练有素的法师来说，从八条腿的蜘蛛身上找到一条完整的腿似乎不是什么问题。"
D.Strings[116712]="延误的包裹 -$B$B 我雇佣了一个我原以为足够可靠的飞行员，让他帮我从塞拉摩带一个包裹过来。显然我错了。虽然那个飞行员活了下来，但他是在放弃了自己的飞艇和上面所有的货物之后才保住自己性命的……$B$B 好吧，重点是，我要我的包裹。根据比吉尔的描述，他的飞艇就坠毁在塞拉摩海港西边的尘泥沼泽里，是在翻过水边的小山时开始坠落的。$B$B 嗯……我根本不知道他的飞艇是怎么坠毁的……"
D.Strings[116713]="古德斯迪尔的长剑 -$B$B 最后，我要找回的是我最好的武器。我将这把神奇的长剑给了一名我非常尊重的战士。嗯，不过他被一个名叫加奎亚还是什么的鱼人给袭击了。$B$B 当他在悲伤沼泽那一带的海边旅行的时候遭到了那个家伙的攻击。他被打得落荒而逃，但是他没有把那把武器也一起带走，而是留给了那个鱼人。"
D.Strings[116714]="帮我找到这些东西，然后带到加基森来——别忘了还有这个帐本，我会重赏你的。"
D.Strings[116715]="这块铁砧是乔丹·斯迪威尔的财产 - 请不要使用!$B$B - 乔丹"
D.Strings[116716]="你好，菲诺克!$B$B我在燃烧平原的研究进行得非常顺利。而且我欠了$N很多因为$g他的:她的;大力帮忙!以下是我继续研究所需要的物资:$B$B钢螺钉若干$B17号扳手一个$B12磅重的鸭毛$B一罐你制造的胶水$B$B非常感谢你，菲诺克，下次我们碰面的时候记得提醒我，不要把煤放在你的鞋子里!$B$B- 丁奇"
D.Strings[116717]="给峭壁卫兵图林·长角的急件$b$b一大群半人马部队从伊索克营地出发并袭击了我们的补给营地。所有的守卫都已战死，所有的资源全部被劫掠一空。这是半人马发起的空前大胆的袭击，我担心将来还会有更多这样的袭击。"
D.Strings[116718]="洛丹伦的最后一位国王，泰瑞纳斯·米奈希尔二世在此长眠。$B$B 他的一生做出了无数伟大的功绩，他的陨落令人扼腕叹息。$B$B          “愿这位父王宽恕其子嗣所做的一切。$B           愿血染的王冠永远被遗失和忘却。”"
D.Strings[116719]="在格瑞姆巴托的战斗结束之后不久，这头巨大的红龙遗体在湿地被发现了。据传闻，塔兰尼斯塔兹是雅立史卓莎雅立史卓莎较年长的配偶。"
D.Strings[116720]="这只鸟爪化石发现于荆棘谷的南岸。生态学家认为它是属于古代阳鹏的。虽然阳鹏主要出现在牛头人的神话之中，但是这只爪子证明它确实存在过。"
D.Strings[116721]="作为世界上体型最大的陆行鸟，格鲁陆行鸟的数量稀少，非常罕见。"
D.Strings[116722]="这是磨齿羊的骨骼复制模型。这种传说中的山羊是卡兹莫丹的奇迹，也是许多矮人传说中的主角。直到今天，生态学家都无法对这种山羊的体积或力量做出估算。"
D.Strings[116723]="这枚卵是在遥远的安戈洛环形山的雨林中找到的，其中孕育着一只胚胎状态下的魔暴龙。其中包含的蜥蜴类基因对于探险者协会的生态学家来说是无价之宝，因为它可以提供中和魔暴龙毒液所需的血清。"
D.Strings[116724]="这枚从苏拉玛水下遗迹中找来的星盘是在一万两千年前由夜精灵中的高等精灵所制造的。那些痴迷于魔法、超自然现象和星象学的高等精灵发明了一系列令人匪夷所思的物品。这些创造为我们提供了关于古代夜精灵科学认识水准的研究依据。"
D.Strings[116725]="这些陶器发现于奥达曼挖掘场。虽然它们的表面上并未包含很多有用的符文或者象形文字，但是我们可以由此得到有关古代矮人的手工艺水准和日常活动的记录。"
D.Strings[116726]="这些浮雕也许是奥达曼第一大厅中最引人注目的发现了。它们清晰地显示了矮人与如同石像一般的土灵之间的关系。随着调查研究的不断深入，我们对于泰坦创造矮人的假说终会得到有力的证据。"
D.Strings[116727]="这枚特别的卵是在塔纳利斯沙漠的一处闷热的废墟中发现的，它至今对于生态学家来说都是一个谜。日期鉴定显示这枚卵可能有一千年的历史，虽然从某些方面来看，它具有昆虫的结构特征，但是其真实的来源还无从考证。何种生物产下了这样一枚奇怪的卵也是个让人疑惑不解的谜。"
D.Strings[116728]="这些第二次兽人战争时留下的遗迹时刻提醒我们，当时部落距攻克铁炉堡只有一步之遥。"
D.Strings[116729]="这些恶魔的铠甲曾经由那个诅咒了我们的生物所穿戴着。一名英勇的兽人战士击败了他，毁灭者玛诺洛斯已不复存在。让这副铠甲时刻提醒我们，我们经历了多少苦难，我们经过了多么艰苦的斗争才夺回了我们的荣誉。$B$B - 萨尔，部落的酋长"
D.Strings[116730]="维姆萨拉克：$B$B 我从你的主人奈法利安那里得到直接命令，如果再有任何外来者进入城堡内部的话，你就要受到惩罚。$B$B 不要忘记是谁在命令你，爬虫。$B$B 黑手之子，刀锋和战争的主人，真正的酋长。$B$B -  雷德·黑手"
D.Strings[116731]="为了与来自扭曲虚空不断侵犯泰坦世界的邪恶力量作战，万神殿选中了他们最强大的战士萨格拉斯作为他们的第一道防线。由熔化的青铜铸造的高贵战士萨格拉斯在上百万年的时间里一丝不苟地履行着他的职责，搜寻并摧毁一切他能找到的恶魔。在度过了无尽的岁月之后，萨格拉斯遭遇了两支从实体世界中获得了巨大能量的强大恶魔种族。"
D.Strings[116732]="邪恶的巫术种族埃瑞达使用他们的巫术侵入并控制了许多世界，这些世界中的原住民都被埃瑞达的混乱力量变成了恶魔。"
D.Strings[116733]="强大的泰坦无法感知这种恶毒和腐化到底有多么深重， 他自己也陷入了不断膨胀的消极情绪之中。尽管如此，萨格拉斯仍然坚强地振作起来，尽全力与埃瑞达的术士们作战，并将他们逼到了扭曲虚空的一个角落里。"
D.Strings[116734]="在萨格拉斯的疑惑与消沉日益加深时，他又被迫与另一组试图破坏泰坦秩序的恶魔作战。黑暗的吸血恶魔纳斯雷兹姆（他们也被称作恐惧魔王）通过控制敌人的思想征服了许多世界，并将敌人变成了自己的爪牙。"
D.Strings[116735]="邪恶狡诈的恐惧魔王可以让整个国家的人由于莫名其妙的憎恨和猜疑而互相杀戮，虽然萨格拉斯轻易击败了纳斯雷兹姆，但他们的引诱却对他产生了巨大的影响。"
D.Strings[116736]="高贵的萨格拉斯无法控制思想中不断翻腾的疑惑和失落，继而失去了他的信仰和作为泰坦的理智。萨格拉斯开始认为秩序的教条本身就是愚蠢的，并且开始认为只有混乱和堕落才是黑暗寂寞的宇宙中唯一的真理。"
D.Strings[116737]="虽然他的泰坦伙伴们试图劝说他放弃错误的想法并平息愤怒的火焰，但他坚持认为他们的说辞都是谎言。在和泰坦永远决裂后，萨格拉斯开始寻找自己在宇宙中的位置。虽然诸神对他的背叛感到很悲伤，但他们永远也不会想到他们这位迷失的兄弟今后会变成什么样子。"
D.Strings[116738]="当萨格拉斯的疯狂吞噬了他最后的一点高贵的灵魂之后，他开始认为泰坦才是导致造物失败的 罪魁祸首。他最终决定组织一支不可阻挡的大军，以地狱的烈焰毁灭所有世界，以此来纠正泰坦们犯下的“错误”。"
D.Strings[116739]="萨格拉斯巨大的身躯也因为侵蚀他心智的堕落力量而发生了扭曲。他的眼睛、头发和胡须变成了燃烧的烈焰，他的青铜皮肤也裂开，从裂缝中喷出了无尽的仇恨和烈焰。"
D.Strings[116740]="疯狂的萨格拉斯摧毁了囚禁埃瑞达和纳斯雷兹姆恶魔的牢笼，这些狡诈的恶魔匍匐在这位黑暗泰坦的暴怒和力量面前，发誓要披肝沥胆地为他服务。萨格拉斯从强大的埃瑞达恶魔中挑选了两名勇士来领导他那邪恶的毁灭势力。"
D.Strings[116741]="欺诈者基尔加丹负责寻找宇宙中最黑暗的种族，并将他们收入萨格拉斯麾下。污染者阿克蒙德负责带领萨格拉斯的大军与任何胆敢抵抗黑暗泰坦的敌人作战。"
D.Strings[116742]="基尔加丹的第一步行动就是用他可怕的力量奴役吸血的恐惧魔王，这些基尔加丹的精英卫队和遍布宇宙的爪牙很乐意为他们的主人寻找可以引诱的原始种族。恐惧魔王中的首领，黑暗魔王提克迪奥斯是基尔加丹梦寐以求的优秀战士，他也宣誓效忠于萨格拉斯的意志。"
D.Strings[116743]="强大的阿克蒙德也有属于自己的强大军队。他控制着残暴的深渊领主和他们野蛮残暴的领导者——玛诺洛斯，致力于建立一支可以毁灭一切生命的精英部队。"
D.Strings[116744]="萨格拉斯在看到他的部队已经足够强大、并且对他的所有命令都绝对服从之后，率领他的大军进入了无边的黑暗。他将这支部队称为燃烧军团，不知有多少个世界被他们跨越整个宇宙的邪恶远征所毁灭。"
D.Strings[116745]="泰坦似乎并没有察觉萨格拉斯毁灭秩序的计划，他们继续从一个世界来到另一个世界，按照他们的意愿塑造这些世界，并且让它们归于秩序的统御。在旅途中，他们来到了一个较小的世界——这个世界后来被称为艾泽拉斯。"
D.Strings[116746]="在这片混乱的土地上，泰坦们遇到了大量与他们为敌的元素生物。这些元素生物信仰着一个被称为上古之神的无比邪恶的种族，并且拒绝让泰坦改造它们的世界。"
D.Strings[116747]="诸神对上古之神的邪恶嗜好感到忧虑，于是他们派出部队与元素生物和他们邪恶的主人作战。上古之神的军队由最强的元素首领率领：炎魔拉格纳罗斯  石母瑟拉塞恩  驭风者奥拉基尔和猎潮者耐普图隆。"
D.Strings[116748]="他们的混乱力量席卷大地，直冲巨大的泰坦而去。不过，虽然元素生物的力量非常可怕，但那也远远不敌强大的泰坦。元素首领们接连倒下，他们麾下的军队四散而逃。"
D.Strings[116749]="诸神摧毁了上古之神的城堡，并把藏在城堡中的四个邪恶生物囚禁在远离地面的地下监狱中。元素生物失去了上古之神的力量，无法在实体世界中保持自己的形态，很快就纷纷化为乌有，溶入了大地。整个世界顿时恢复了一派和谐的景象。泰坦看到危机消除，就开始了他们的工作。"
D.Strings[116750]="为了帮助自己改造世界，泰坦创造了许多种族。为了在大地上挖掘深不可测的洞穴，泰坦用具有魔力的石头创造了土灵；为了创造海洋并将陆地从海床上搬走，泰坦创造了巨大温顺的海巨人。泰坦们花费了数个世纪来改造这个世界，直到最后，艾泽拉斯世界上出现一块完美的大陆。"
D.Strings[116751]="泰坦在这块大陆的中心凿出了一片充满魔法能量的湖泊，并将它命名为永恒之井，以此作为这个世界生命的源泉。湖中蕴含的无限能量可以支撑世界的骨架，并帮助各种生命在这片肥沃的土壤上生根发芽。随着时间的推移，树木、小草、怪物和各种生物都在这片大陆上繁盛起来。"
D.Strings[116752]="当夜色降临时，泰坦为这片大陆起了一个名字：卡利姆多——“永烁星光之地”。"
D.Strings[116753]="泰坦对他们在这片大陆上建立的秩序感到满意，于是决定启程离开艾泽拉斯。在他们动身之前，泰坦们决定赋予这片大陆上最强大的物种以守护世界、保卫这里的平衡和谐不被破坏的职责。在那个时代有许多巨龙。"
D.Strings[116754]="它们由五条巨龙分别统治。泰坦选择了这五条巨龙来守护这个崭新的世界。最强的神们分别将自身的一部分神力赠与一条巨龙，这五条巨龙就是广为人知的守护巨龙。"
D.Strings[116755]="众神之父阿曼瑟尔将他的一部分力量赋予巨大的青铜龙诺兹多姆。这位众神之父赋予诺兹多姆以守护时间和命运之路的职责，淡泊高贵的诺兹多姆成为了永恒之王。"
D.Strings[116756]="生命的赋予者艾欧纳尔将她的一部分力量赋予红龙雅立史卓莎。此后雅立史卓莎成为生命之王，守护世界上所有的生物。由于她无穷的智慧和对所有生物的无限怜悯，雅立史卓莎成为了统治所有红龙的女王。"
D.Strings[116757]="艾欧纳尔也以一部分自然的力量祝福了雅立史卓莎的姐妹，优雅的绿龙伊瑟拉。伊瑟拉陷入了永恒的迷思之中，与实体世界中所有生物的睡梦联系在一起。伊瑟拉成为了梦幻之王，在翡翠梦境中守护着生机勃勃的世界。"
D.Strings[116758]="掌御着知识和魔法的诺甘农将他巨大力量的一部分赋予蓝龙玛里苟斯，从此玛里苟斯成为魔法之王，守护着魔法和神秘的圣殿。"
D.Strings[116759]="世界的锻造者卡兹格罗斯将他的一部分力量赋予了强大的黑色巨龙耐萨里奥。耐萨里奥成为大地之王，统御着艾泽拉斯世界的大地与深渊。他代表着世界的力量，是雅立史卓莎最强大的支持者。"
D.Strings[116760]="五个守护者被赋予在泰坦离开后守卫世界的责任。泰坦在巨龙做好守护世界后的准备之后永远地离开了艾泽拉斯。不幸的是萨格拉斯不久之后就会察觉到这个新生世界的存在……"
D.Strings[116761]="高等精灵无节制地使用魔法，使得永恒之井的魔法波动传入了浑沌黑暗中，并且传播到了扭曲虚空，最终被盘踞在那里的恶魔感觉到了。萨格拉斯——所有生命的死敌，世界的毁灭者——感觉到了这股强大的魔法波动，并且找到了这股波动的来源。"
D.Strings[116762]="在观察了艾泽拉斯世界并感受了永恒之井的无限能量之后，萨格拉斯急切地渴望占有这一切，他要摧毁这个世界，将它的能量据为己有。"
D.Strings[116763]="萨格拉斯纠集了他的恶魔大军——燃烧军团，开始向艾泽拉斯进军。燃烧军团由数以百万计的咆哮着的恶魔组成，他们来自宇宙的各个角落，思想中燃烧着的全都是征服的欲望。萨格拉斯的副官——污染者阿克蒙德和毁灭者玛诺洛斯——已经准备好要率领他们的爪牙发起进攻了。"
D.Strings[116764]="被自己强大的魔法能量折腾得筋疲力尽的艾萨拉女王成为了萨格拉斯的第一个牺牲品，她同意为他提供进入艾泽拉斯世界的入口，甚至连她的仆从都放弃了对魔法的追求，转而将萨格拉斯作为神来膜拜。为了表示对燃烧军团的忠诚，他们协助女王在永恒之井里打开了一扇巨大的、漩涡般的传送门。"
D.Strings[116765]="在所有事情都准备妥当之后，萨格拉斯开始了他对艾泽拉斯毁灭性的入侵。燃烧军团的恶魔们从永恒之井中涌出来，对夜精灵的城市发动了突然袭击。在阿克蒙德和玛诺洛斯的率领下，燃烧军团横扫卡利姆多大陆，所到之处片瓦无存。"
D.Strings[116766]="恶魔术士从天空中召唤灼热的地狱火，它们像陨石一样撞击着夜精灵优雅的神殿。末日守卫穿过卡利姆多的原野，屠杀它们看到的一切生物。狂暴的地狱犬在乡村中狂奔，没有遇到任何抵抗。虽然勇敢的卡多雷战士迅速组织起来为保卫他们古老的家园而战，但是在势不可挡的燃烧军团面前，他们只能节节败退。"
D.Strings[116767]="玛法里奥·怒风在此刻担任起了为他的那些被围困的同胞寻求帮助的任务，他的兄弟伊利丹曾经学习过高等精灵的魔法，但他因为对在上层阶级中逐渐滋生的堕落感到愤怒而离开了他们。在确信伊利丹已经放弃了对这种力量的追求之后，玛法里奥开始启程去寻找塞纳留斯并组织了一支反抗军。"
D.Strings[116768]="年轻美丽的女祭司泰兰德同意在月亮女神伊露恩的的名义下与这两个兄弟同行。虽然玛法里奥和伊利丹都爱着这位美丽的女祭司，但泰兰德的芳心只属于玛法里奥。伊利丹很嫉妒他的兄弟与泰兰德的爱情，但他知道这点伤心与他嗜之如命的魔法给他带来的痛苦相比，是微不足道的事情……"
D.Strings[116769]="伊利丹对魔法能量有很大的依赖性，他为了克制自己重新汲取永恒之井中的魔法能量的强烈欲望而时刻遭受着巨大的痛楚。尽管如此，在泰兰德的耐心帮助下，他仍然能够保持足够的理智来协助他的兄弟找到隐居的半神塞纳留斯。"
D.Strings[116770]="在遥远的海加尔山中的月光林地里，他们找到了定居于此的塞纳留斯。塞纳留斯决定帮助夜精灵找到古老的巨龙并寻求他们的帮助，由红龙雅立史卓莎领导的巨龙答应派出它们强大的龙群，与恶魔和它们的首领作战。"
D.Strings[116771]="塞纳留斯通过呼唤森林之灵集结了一支由古老树人组成的部队，并带领它们对燃烧军团发动了一次大胆的突袭。夜精灵的盟军都聚集在永恒之井和艾萨拉的神殿旁准备进行战斗。虽然这些新的盟友拥有强大的力量，但玛法里奥和他的同伴们意识到仅靠军事力量是无法击败燃烧军团的。"
D.Strings[116772]="当规模空前的战斗在艾萨拉的首都打响时，被迷惑的女王还在静静地等待萨格拉斯的到来。燃烧军团的首领准备穿越永恒之井来到这个饱经蹂躏的世界，当他那无比巨大的阴影在永恒之井那波涛澎湃的水面下出现时，艾萨拉召集了最强大的高等精灵。只有将他们的魔法能量集中在一起，才能打开一个足够巨大的传送门，让萨格拉斯顺利地踏入艾泽拉斯世界。"
D.Strings[116773]="在战斗席卷卡利姆多燃烧的大地时，出现了可怕的转折。具体情形已经无从考据，据说大地的巨龙守护者耐萨里奥在对抗燃烧军团的一场激战中发疯了。他的身体裂开，火焰和热量从他黑色的皮肤下喷涌而出。这条燃烧的巨龙将自己改名为死亡之翼，转身对付自己的同胞，将其他的巨龙赶离战场。"
D.Strings[116774]="死亡之翼的突然背叛造成的伤害非常巨大，五色巨龙再也没有恢复元气。雅立史卓莎和其他高贵的巨龙在伤痛和震惊下被迫离开了联军，玛法里奥和他的伙伴无助地处于劣势，侥幸在随后的攻击中存活了下来。"
D.Strings[116775]="从大爆炸中幸存的夜精灵爬上做工粗糙的木筏，缓慢地向视野中唯一可见的陆地划去。值得庆幸的是，在月亮女神伊露恩的护佑下，玛法里奥、泰兰德和塞纳留斯在大灾变中幸存了下来。疲惫的英雄们同意领导他们幸存的人民建立一个新的家园。"
D.Strings[116776]="在夜精灵们沉默的旅途中，他们看到了大地的残骸，并且意识到是他们对魔法的狂热导致了这场可怕的灾难。虽然萨格拉斯和他的燃烧军团被永恒之井的毁灭摧毁了，玛法里奥和他的同伴却不得不思考他们为这次胜利付出的代价。"
D.Strings[116777]="仍然有许多高等精灵在大爆炸中幸存了下来，他们和其他夜精灵们一起到达了陆地上。虽然玛法里奥并不相信这些高等精灵，但他知道，没有永恒之井，这些精灵无法兴风作浪。"
D.Strings[116778]="当疲惫的夜精灵们在新大陆的海岸登陆时，他们发现圣山海加尔在大灾变中幸存了下来。为了寻找一片新的定居点，玛法里奥和其他夜精灵一起攀登到了海加尔山的最高峰顶端。当他们俯视山下无边的森林时，精灵们发现了一片平静的小湖泊。令他们恐惧的是，这片湖泊的湖水充满了魔法能量。"
D.Strings[116779]="伊利丹也从大灾变中幸存了下来，并且在玛法里奥之前到达了海加尔山。他疯狂地想要延续这个世界上的魔法源泉，于是他将永恒之井的湖水倒入了这片小湖泊。"
D.Strings[116780]="这些湖水所蕴含的能量迅速溶入了这片小湖泊的湖水中，形成了一个新的永恒之井。兴奋的伊利丹认为这个新的永恒之井是一个为他的后代准备的丰厚礼物，在他手舞足蹈时，玛法里恩击倒了他。玛法里恩向他的兄弟解释道，魔法是天生的混乱之源，使用魔法最终将导致堕落和纷争，但固执的伊利丹仍然不愿放弃他的魔法力量。"
D.Strings[116781]="玛法里奥知道伊利丹的邪恶计划将会导致什么样的后果，于是他决定永远地解决他那疯狂的兄弟带来的问题。在塞纳留斯的帮助下，玛法里奥将伊利丹囚禁在一个巨大的地下室中，直到他生命的终结。为确保他兄弟的监禁，玛法里奥授权年轻的典狱官玛维·影歌为伊利丹的专职守卫。"
D.Strings[116782]="考虑到摧毁这个新的永恒之井可能导致更大的灾难，夜精灵决定留下它。但是玛法里恩宣布，夜精灵永远都不能进行魔法研究。在塞纳留斯的关注下，他们开始学习古老的德鲁伊法术，学习如何治愈伤痕累累的大地，并开始在海加尔山脚下种植他们喜爱的树木。"
D.Strings[116783]="在这之后的许多年里，夜精灵们不知疲倦地为重建他们的古老家园而工作。他们遗弃了破损的神殿和道路，在海加尔山脚下的茂密丛林和隐蔽的山脉中修建了新的家园。一段时间之后，在大灾变中幸存下来的龙来到了夜精灵的家园。"
D.Strings[116784]="红龙雅立史卓莎、绿龙伊瑟拉以及青龙诺兹多姆俯视着德鲁伊的宁静家园和夜精灵种植的水果。拥有强大力量的大德鲁伊玛法里恩欢迎这些巨龙的到来，并且将有关新永恒之井的事情告诉了他们。"
D.Strings[116785]="巨龙们在听到这个可怕的消息时大吃一惊，它们认为只要永恒之井仍然存在，燃烧军团就不会放弃征服这个世界的念头。玛法里奥和三条巨龙定下了一个契约，以此保证永恒之井的安全，并确保燃烧军团的爪牙永远也无法找到重回这个世界的门路。"
D.Strings[116786]="生命的赐予者，红龙雅立史卓莎，在永恒之井的中心投下了一颗附有魔法的橡子，这颗橡子一遇到充满魔法力量的湖水就开始生根发芽，长成了一棵巨大的橡树。大树的根须深入湖底，而巨大的树冠几乎要笼罩整个天空。"
D.Strings[116787]="这棵巨大的橡树是夜精灵与自然和谐关系的永恒象征，它所散发的生命能量可以慢慢地扩散并治愈整个世界的创伤。夜精灵将他们的世界之树命名为“诺达希尔”，这在夜精灵语中的意思是“苍穹之冠”。"
D.Strings[116788]="时间之王诺兹多姆对世界之树附加了魔法——只要这棵世界之树仍然存在，夜精灵就永远不会衰老，也不会生病。"
D.Strings[116789]="“一门可以让你度过重重难关的技能。”菲琳萨就是这样描述她的那套本事的。$B$B 如果你相信她所说的，那么就到达纳苏斯北部的塞纳里奥区去吧，她在那里传授她的课程。"
D.Strings[116790]="包括玛法里奥在内的夜精灵德鲁伊都通过世界之树和翡翠梦境建立了连接，作为神秘契约的一部分，德鲁伊们同意进行每次持续时间长达数百年的休眠，他们的灵魂可以在伊瑟拉的梦幻国度中自由徘徊。虽然夜精灵对耗费如此漫长的时间进行休眠感到惋惜，但他们仍然无私地接受了和伊瑟拉订下的契约。"
D.Strings[116791]="数百年过去了，暗夜精灵的社会逐渐发展壮大，并从他们世代生活的灰谷拓展到更广阔的疆域。在大灾变前分布广泛的野生动物——比如熊怪和野猪——在这片土地上重新出现并日益活跃起来。在德鲁伊的英明领导之下，暗夜精灵享受着与世无争的宁静生活。"
D.Strings[116792]="但是，许多原先的上层精灵越来越不安分。他们无法忍受失去魔法能量的空虚感，开始重新汲取永恒之井的能量，并沉浸在使用魔法的喜悦之中。上层精灵那直率急躁的领导人达斯雷玛开始公开抨击德鲁伊，称他们为不敢使用魔法的懦夫。"
D.Strings[116793]="玛法里奥和德鲁伊们对达斯雷玛的挑衅一笑了之，并警告上层精灵，任何使用魔法的行为都将招致死亡的惩罚。傲慢的达斯雷玛和他的追随者们对灰谷施放了一场可怕的魔法风暴，妄图迫使德鲁伊废除他们的法律。"
D.Strings[116794]="德鲁伊们无法对数量如此众多的同胞痛下杀手，只好决定流放这些鲁莽的上层精灵。达斯雷玛和他的追随者们对摆脱他们保守的同胞感到十分高兴，他们登上了经过特殊加工的船只并驶向了大海。虽然他们之中没人知道在狂暴的大漩涡对面有什么样的命运在等待他们，但起码他们可以找到一片属于自己的家园，一片可以使他们在不受干扰的情况下尽情练习魔法的家园。"
D.Strings[116795]="上层精灵——或者说是数百年前艾萨拉女王所说的“奎尔多雷”——最终登上了东方大陆的海岸，这块大陆后来被称为洛丹伦大陆。他们计划在这里建立他们自己的魔法王国——奎尔萨拉斯，并废除暗夜精灵对月亮女神的信仰和夜间活动的习惯。从此之后，他们的身份就变成了“高等精灵”。"
D.Strings[116796]="在与他们的同胞决裂之后，夜精灵们将注意力转回了对他们家园的保护上。这些德鲁伊在感到他们的休眠期又将来临之后，准备离开他们的爱人和家人去进行休眠。"
D.Strings[116797]="月亮女神伊露恩的首席女祭司泰兰德央求他的爱人玛法里奥不要离开她而陷入伊瑟拉的梦幻世界，但充满荣誉感的玛法里奥仍然坚持向女祭司告别，并且发誓在有生之年永远不会与她分离。"
D.Strings[116798]="泰兰德独自承担起保护卡利姆多大陆的重任。她挑选了她的夜精灵姐妹中的精英力量组成了一支强大的部队，这些受过严格训练的无畏女战士宣誓成为卡利姆多的保卫者，也就是哨兵部队。虽然她们喜欢在梣谷周围的茂密森林中独自巡逻，但哨兵们也有许多在紧急关头可以提供帮助的同盟。"
D.Strings[116799]="半神塞纳留斯一直住在海加尔山的月光林地附近。他的儿子——丛林守护者们对夜精灵保持着密切的关注，并帮助哨兵部队维持这片大地的平衡。塞纳留斯的女儿——林精们也开始频频在公开场合露面。"
D.Strings[116800]="虽然在梣谷巡逻的任务使泰兰妲忙碌不已，但她仍然感到孤单寂寞。在德鲁伊们沉睡着的几百年中，泰兰妲感到恶魔的第二次入侵不会太远了。她预感到燃烧军团仍然存在，预??到他们正在天外无边的黑暗中策划着对夜精灵和艾泽拉斯的复仇。"
D.Strings[116801]="达斯雷玛领导的高等精灵离开了卡林多并成功穿越了波涛汹涌的大漩涡。他们的船队在这破碎的世界中徘徊了许多年，在旅行中发现了无数神奇的奥秘与失落的国度。达斯雷玛为自己取了个“逐日者”的称号，不懈地寻找着一个蕴藏着大量魔法能量的地方来为他的子民建造一个新的家园。"
D.Strings[116802]="他的船队最终在某块大陆的海岸边上靠了岸——那块大陆后来被称为洛丹伦。在向内陆推进的过程中，高等精灵们在安静的提瑞斯法林地里建立了他们的安身之所。几年后，他们中的许多人开始发狂。据说那是因为有些恶灵正沉睡在提瑞斯法林地的下面，不过这个传说从来也没有被证实过。高等精灵不得不卷起铺盖，向北移居到了另一片充满能量的土地上。"
D.Strings[116803]="当高等精灵穿越了此起彼伏、群山连绵的洛丹伦后，他们的旅行变得更危险了。由于精灵们与给予他们活力的永恒之井之间的联系已经完全被切断， 他们中的许多人不是在天寒地冻中病倒，就是死于极度的饥饿。然而最让人不安的变化却是他们已经不再拥有永恒的生命以及对元素魔法的免疫能力。"
D.Strings[116804]="他们的身材变矮了，肌肤也失去了独特的紫罗兰色。尽管面对如此严峻的形势，高等精灵们还是见识到了许多在卡利姆多从没见过的奇怪物种，他们也发现了一些原始的、以在原始森林中打猎为生的人类部落，然而他们遭遇到的最可怕的威胁还是祖阿曼的那些贪婪而狡猾的森林食人妖。"
D.Strings[116805]="这些皮肤上长满苔藓的食人妖不仅可以断肢再生，而且他们的身体即使受到了严重的创伤，也能很快自行愈合，不过他们的行为表明这些食人妖还只是一个野蛮邪恶的种族。阿曼尼帝国的疆土覆盖了北罗德隆的大部分土地，食人妖们对贸然闯入的那些不速之客施以迎头痛击，把他们驱离祖-阿曼的边境。精灵们对这些恶毒的食人妖逐渐感到深恶痛绝，无论在哪里看到他们都会将其格杀勿论。"
D.Strings[116806]="许多年后，高等精灵终于找到了一片可以追忆卡林多的土地。他们在大陆以北的森林深处建立了奎尔萨拉斯王国，并誓言要建立一个远比他们的卡多雷同胞更强大的帝国。不幸的是，不久以后他们就发现奎尔萨拉斯其实是建在了一座受到食人妖顶礼膜拜的食人妖古城上。食人妖们几乎在第一时间就向精灵的定居点发起了大规模的进攻。"
D.Strings[116807]="固执的精灵不愿放弃他们刚刚获得的土地，于是他们利用自己从永恒之井得到的魔法遏制了野蛮食人妖的疯狂攻击。在达斯雷玛的领导下，他们成功地击败了超过己方数量10倍的阿曼尼军队。一些精灵想起了卡多雷的古老警示，觉得他们对魔法的使用可能会引起那已被驱逐的燃烧军团的注意。"
D.Strings[116808]="因此，精灵们决定把他们的土地用结界隐藏起来，以便让他们能够继续对魔法进行研究。他们在奎尔萨拉斯周围的多个地点建造了一系列庞大的符石作为魔法结界的边界节点，这些符石不仅可以把精灵的魔法隐藏起来以躲避来自其他位面的威胁，还可以帮助他们吓阻迷信的食人妖军队。"
D.Strings[116809]="随着时间的流逝，奎尔萨拉斯逐渐成为了高等精灵不懈努力与魔法威力的象征，它美丽的宫殿保持着与卡林多古代城市一样的建造风格，与大自然的地形地貌完美地融合在了一起。奎尔萨拉斯成为了一颗精灵们渴望已久的耀眼珠宝。"
D.Strings[116810]="尽管此时逐日者王朝还保留了少许的政治权利，但统治这个王国的却是一个名叫银月议会的统治机构。议会由高等精灵中最伟大的7位领主组成，负责确保高等精灵领土与子民的安全。由于有防御结界的保护，高等精灵们仍旧对卡多雷的古老警示无动于衷，并且几乎在他们所有日常生活中都频繁地使用魔法。"
D.Strings[116811]="高等精灵在他们与世隔绝的王国中和平安宁地生活了将近四千年，然而复仇心切的食人妖不是那么容易被打败的。他们在森林深处囤积力量，等待着他们的军队发展壮大的一天。终于，一支强大的食人妖军队从阴暗的森林中发动了攻势，再一次大举进犯奎尔萨拉斯。"
D.Strings[116812]="当高等精灵正在为生存而抵抗着食人妖大军猛烈的冲击时，洛丹伦大陆上的人类游牧民们则正在为巩固他们自己的部落领地而战，这些原始人的部落在袭击其他族群的定居点时丝毫不在乎什么荣誉和种族团结。"
D.Strings[116813]="最终，一个名叫阿拉希的部落意识到食人妖已经成为了对人类来说不可忽视的威胁。阿拉希部落希望把所有部落收归自己的麾下，那样他们就能组织起一条统一战线来对抗食人妖军队了。"
D.Strings[116814]="足智多谋的阿拉希部落花了6年的时间，用计谋和武力打败了所有与他们对立的部落。每击败一个部落，阿拉希部落都给予被他们征服的人民以和平的生活与平等的权利，因此，他们赢得了战败者的忠诚。最终阿拉希部落容纳了许多各种各样的部落，他们的部队也迅速壮大了起来。"
D.Strings[116815]="他们自信可以凭一己之力来击败食人妖军队，甚至若有必要还可以击败那些与世隔绝的精灵，阿拉希的军阀们决定在洛丹伦南部建造一座强大的要塞城市。这个被叫做激流城的城邦成为了阿拉希人的国家——阿拉索的首都。随着阿拉索的繁荣昌盛，大陆各处的人类都不远万里来到了安全可靠的激流城定居。"
D.Strings[116816]="人类团结在同一个信念下，众多部落逐渐发展出了一个强大的文明。阿拉索国王索拉丁知道北方的精灵正在遭到食人妖持续不断的围攻，但是他却拒绝用他人民的生命作赌注来冒险帮助陌生的精灵。许多月过去了，关于精灵们正在节节败退的传言逐渐传遍了洛丹伦大陆。当疲惫的奎尔萨拉斯大使来到激流城的时候，索拉丁才意识到食人妖的威胁竟然是如此巨大。"
D.Strings[116817]="精灵们告诉索拉丁，食人妖的军队非常庞大，一旦奎尔萨拉斯被食人妖摧毁，他们的军队马上就会南下。绝望的精灵们由于迫切地需要军事援助，草草地答应向那些被选中的人类传授魔法，以此来换取他们在抵抗食人妖军队时为精灵提供帮助。"
D.Strings[116818]="虽然索拉丁对任何魔法都不信任，但出于必要性的考虑，他还是答应支援精灵们。很快就有一批精灵法师火速赶到激流城，开始向一小群人类传授魔法的记忆。"
D.Strings[116819]="精灵们发现虽然人类在掌握施法方面显得比较笨拙，但他们对魔法却有一种惊人的天赋。有100个人学习了一些非常基本的精灵魔法，这些人正好足够帮助精灵对抗食人妖。精灵们深信他们的人类学徒已经为在战斗中提供援助做好了准备，于是就离开了激流城回到北方，与索拉丁国王的强大军队并肩作战。"
D.Strings[116820]="精灵与人类的联军在奥特兰克山脚下猛烈冲击着在数量上有着压倒性优势的食人妖军队。战斗持续了许多天，但是不屈不挠的阿拉索军队从没懈怠过，他们在食人妖的攻击中从未后退一步。精灵的领主们认为是时候将他们的魔法力量施放到敌人头上去了。"
D.Strings[116821]="于是百多名人类魔法师与众多的精灵巫师从空中召下天火，将食人妖军队包围在了烈火之中。元素火焰阻止了食人妖伤口的重生，将他们烧成灰烬。"
D.Strings[116822]="食人妖的军队崩溃了，当他们准备逃跑的时候，索拉丁的军队乘胜追击，直到最后一个食人妖士兵倒下为止。在经历了这次惨重的失败之后，食人妖遭到了毁灭性的打击，从此他们再也没能建立起新的食人妖国家。在从毁灭的边缘拯救了奎尔萨拉斯之后，精灵向阿拉索王国与索拉丁的血脉许下了忠诚与友谊的誓言，人类与精灵在后来的年代中一直保持着和平的关系。"
D.Strings[116823]="由于北方没有了食人妖的威胁，奎尔萨拉斯的精灵们开始致力于重建他们的家园，获胜的阿拉索军队回到了他们南方的家园激流城。"
D.Strings[116824]="阿拉索的人类社会逐渐发展繁荣了起来，后来索拉丁由于担心他的国家继续扩张下去迟早会四分五裂，就一直努力保持激流城在王国里的中枢地位。在阿拉索王国经过许多年的和平发展与通商后，伟大的索拉丁寿终正寝了，阿拉索的年轻一代开始自由拓张激流城以外的王国疆界。"
D.Strings[116825]="最初的那100名受到精灵教导的魔法师继续增强着他们的力量，更加细致地研究着如何操纵法术这一神秘学科。这些魔法师起初是由于他们强大的意志与高贵的灵魂被挑选出来的，他们也始终抱着小心负责的心态来使用魔法。然而，当他们把魔法的秘密与力量传递到新一代的手中之后，那些年轻人对战争的严酷与自制的必要性完全没有概念。"
D.Strings[116826]="年轻的魔法师们逐渐开始为了一己私利使用魔法，而不是为了保护同胞的责任。"
D.Strings[116827]="随着王国的发展，新的土地被开拓，年轻的魔法师们也来到了南方。魔法师们施展着他们神秘的力量，保护他们的同胞免受野兽的袭击，并使得在荒园上建立新的城邦成为可能。但是随着他们的力量越来越大，他们变得越来越自以为是，与社会也变得越来越疏远。"
D.Strings[116828]="阿拉索的第二个城邦达拉然在激流城以北建立了，许多初出茅庐的巫师离开了压抑的激流城来到达拉然，期望在这里能更自由地使用他们新得到的力量。这些魔法师制造了达拉然的魔法尖塔，狂热地进行着魔法研究。"
D.Strings[116829]="达拉然的居民们尊重魔法师的努力研究，并且在他们的保护下建立起了一个热闹的贸易体制。然而，随着越来越多的魔法师使用魔法，达拉然周围的空间变得脆弱，开始破裂。"
D.Strings[116830]="由于达拉然魔法师没有节制的使用魔法，一些在永恒之井崩溃时被驱逐的燃烧军团爪牙被重新引回了这个世界。虽然这些相对比较弱的恶魔并没有大批出现，不过他们还是在达拉然造成了一定的混乱。"
D.Strings[116831]="大多数与恶魔的遭遇都是些零散的事件，而且当政的玛苟克拉斯议会使尽全身解数把这些事件从大众的目光中掩盖了起来。一些最强大的魔法师被派去活捉这些狡猾的恶魔，不过通常他们都会发现这些强大的燃烧军团爪牙虽然只是孤身作战，不过却强大得远远超出他们所能应付的极限。"
D.Strings[116832]="数月后迷信的农民开始怀疑他们的巫师统治者们有意向他们隐瞒了一些可怕的事情，随着胡思乱想的市民质疑起他们一度曾经赞美过的魔法师的动机与行动，关于革命的谣言开始到处流传起来。由于玛苟克拉斯议会担心农民们发动起义，继而导致激流城采取一些对他们不利的行动，于是他们不得不向精灵——他们觉得唯一有可能理解自己现在面对的特殊难题的盟友——寻求帮助。"
D.Strings[116833]="在听取了玛苟克拉斯议会关于恶魔在达拉然活动的报告后，精灵们迅速把他们最强大的巫术师们派往人类的领土。精灵巫术师们研究了达拉然的能量流，然后对每件他们目击到的恶魔活动写了详细的报告。他们的结论是，尽管现在只有很少的恶魔在世界上肆虐，但是如果人类继续滥用魔法的话，燃烧军团对这个世界来说仍然是一个不可忽视的巨大威胁。"
D.Strings[116834]="统治奎尔萨拉斯精灵的银月议会与达拉然玛苟克拉斯议会的领主们达成了一个秘密契约。精灵们告诉了玛苟克拉斯议会一些关于古卡林多和燃烧军团的历史，那些至今仍然威胁着这个世界的往事。他们告诉人类，只要他们还使用魔法，就得想办法保护他们的子民免受燃烧军团的威胁"
D.Strings[116835]="玛苟克拉斯议会提议将他们集体的力量授予一个最强的凡人，让他来与燃烧军团进行一场永不终结的秘密战争。由于担心人们会由于恐惧和猜疑而发生骚乱，他们强调绝不能让大多数人类知道守护者的存在或者燃烧军团的威胁。精灵对此表示赞同，并且成立了一个秘密社团来监督守护者的选举以及协助遏制混乱在这个世界的抬头。"
D.Strings[116836]="这个社团在阴影笼罩的提里斯法林地举行秘密会议，那块地方就是精灵们最初在罗德隆定居的地方。因此，他们把这个秘密组织命名为提里斯法守护者。最强的凡人们被选为守护者，被给予包含着精灵和人类魔法的惊人力量。虽然守护者一直是独来独往，但是由于拥有如此强大的力量，所以无论在什么地方，他们都可以凭一己之力来抵抗燃烧军团。"
D.Strings[116837]="由于守护者的力量极端强大，所以只有提里斯法会有权力从具有潜质的法师中挑选足以继承守护者衣钵的人。无论何时，当一个守护者太过衰老，或者厌倦于这场与邪恶抗衡的秘密战争时，议会就会选出一个新的强者，在确保万无一失的情况下正式将守护者的力量导入这个新代理人的体内。"
D.Strings[116838]="随着时间的推移，守护者们一直暗中保证人类免受遍布阿拉索和奎尔萨拉斯大地上的燃烧军团爪牙的伤害。阿拉索随着遍布全国的魔法普及而发展繁荣着，同时，守护者们也在继续小心谨慎地监视着恶魔的活动。"
D.Strings[116839]="在泰坦们离开艾泽拉斯后，他们创造出的土灵们继续雕琢和守护着世界的深处。土灵在很大程度上不关心居住在地面上的各个种族的事务，他们只专注于探索地下世界。"
D.Strings[116840]="永恒之井的大爆炸把艾泽拉斯世界撕裂的同时，也深深影响到了土灵。他们随大地的痛苦而遭受到了巨大的打击，并因此丢失了自我意识，将自己封闭在他们诞生的那些石室中。奥达曼、奥丹姆和奥杜尔是土灵最先建造的以远古泰坦命名的城市。而现在，这些城市被深深埋到了地下，土灵在这里沉睡了将近8000年。"
D.Strings[116841]="虽然还不清楚究竟是什么惊醒了他们，但终于有一天，奥达曼的土灵们从沉睡中醒来了。这些土灵发现自己的身体在沉睡期间发生了很大的变化。他们原本像石头一样坚硬的皮肤变得柔软光滑，他们控制大地和石头的能力也变弱了很多。他们变成了更为普通的生物。"
D.Strings[116842]="他们把自己称作“矮人”，这些硕果仅存的土灵们离开了奥达曼城，在逐渐苏醒的艾泽拉斯世界里到处探险。由于他们仍然被地底深处的奥秘和安全感所吸引着，因此矮人们在陆地上最高的山峰中建造了一个巨大的王国。"
D.Strings[116843]="他们以泰坦的建造之神卡兹格罗斯的名字为自己的的王国命名，称之为“卡兹莫丹”或“卡兹之峰”。矮人们为自己的泰坦父亲建造了祭坛，并在山峰的中央建造了一座巨大的熔炉。 从此，一座被称为铁炉堡的城市就在这座熔炉旁兴起了。"
D.Strings[116844]="矮人天生沉迷于加工宝石和岩石，喜欢在山峰深处开矿挖掘稀有的矿藏。他们满足于自己在地底的工作，与地面上的其他种族互无往来。"
D.Strings[116845]="激流城继续扮演着阿拉索中心的角色，不过就和达拉然一样，许多新城邦在洛丹伦大陆逐渐建立了起来。吉尔尼斯、奥特兰克，以及库尔提拉斯都是第一批建立起来的城邦，虽然这些城邦每个都有着他们自己的习俗和贸易活动，但他们都一致听命于激流城。"
D.Strings[116846]="在提里斯法会谨慎警惕的监控下，达拉然成为了这片土地上主要的魔法学习中心。统治达拉然的玛苟克拉斯议会成立了肯瑞托，这个教派专门负责记录和研究他们发现的每一个魔法和每一件魔法物品。"
D.Strings[116847]="吉尔尼斯和奥特兰克成为了激流城强大的支持者，并发展起了强大的军队，他们的远征队一直探索到了卡兹莫丹以南的那片山岳连绵的土地。就在这期间，人类首次遇到了古代种族矮人，他们旅行来到了矮人们的地下洞穴城市——铁炉堡。人类和矮人分享了许多金属锻造和工程学方面的知识，并发现他们对战斗和讲故事都有着共同的爱好。"
D.Strings[116848]="库尔提拉斯城邦建立在洛丹伦以南一个巨大的岛屿上，他们发展出了建立在渔业和远洋航运基础上的繁荣贸易。随着时间的流逝，库尔提拉斯建立起了一支强大的商船队，他们穿越了所有已知地区，在世界各地搜寻供交易与贩卖的奇珍异宝。但是，虽然阿拉索王国越来越繁荣昌盛，但它最强大的核心却开始分崩离析。"
D.Strings[116849]="此时，激流城的领主们开始逐渐把他们的财产转移到繁华的洛丹伦北部地方，将贫瘠的南方遗弃不顾。索拉丁国王的继承人——阿拉希血脉中最后一个子嗣——争论道他们不该放弃激流城，因此招来了那些同样迫切想要离开的高阶市民的不满。"
D.Strings[116850]="激流城的领主们决定丢下他们的古城，指望到未开化的北方去寻求纯洁与教化。在达拉然以北很远的地方，激流城的领主们建立了一个的新城邦，它被称作洛丹伦，这整片大陆的名字便是源自这个城邦。洛丹伦成为了一个朝圣者和所有寻求内心的和平安宁者所渴望的胜地。"
D.Strings[116851]="阿拉希的子孙们被丢在了古激流城那崩坏的城墙中，于是他们决定到南方卡兹莫丹的岩石林立的山脉中去。许多个漫长的年头过去了，他们终于结束了自己的旅程，在大陆北方的一个名叫艾泽拉斯的地方定居了下来。他们在一个富饶的山谷中建立了暴风王国，不久这里就变成了一个有了自己自足能力的地方。"
D.Strings[116852]="还有少数战士仍然留在激流城中，他们决定继续居住在那里，守护他们古城的城市。激流城早已不是帝国的中央了，但它逐渐发展成了一个新的城邦国家——激流堡。尽管每个城邦都在自己的管辖下繁荣了起来，阿拉索帝国却彻底四分五裂了。随着每个国家都发展起了他们自己的习俗与信仰，每个城邦之间的差异都越来越大。索拉丁国王统一人类的梦想最终还是随风消散了。"
D.Strings[116853]="就在七个人类王国之间的政治军事斗争此起彼伏之时，守护者仍然履行着他们对抗混乱的职责。在这许多年中曾有多人担任守护者，但在同一时间内只有一个人能拥有提里斯法会的魔法力量。作为这时代最后的守护者之一，她是一个足以抗衡邪恶与黑暗的强大战士。"
D.Strings[116854]="艾格文，这个热情的人类女孩，赢得了提里斯法会的认可，并被授予了守护者的披风。艾格文精力充沛地工作着，猎杀和根除每个她找到的恶魔，但是她始终对被男性垄断的提里斯法会的权力表示怀疑。"
D.Strings[116855]="她相信由远古的精灵和长者们掌握的议会的思想已经过于陈旧狭隘，不能下达高瞻远瞩的果断命令来对抗混乱。亢长枯燥的谈话和辩论让她感到极度不耐烦，她渴望向上级和同伴证明自己的价值，所以往往在许多紧要关头时作出英勇却有失明智的事情来。"
D.Strings[116856]="随着她所掌握的提里斯法力量逐渐增强，艾格文开始注意到一些潜伏于冰雪覆盖的诺森德大陆的强大恶魔。她千里迢迢赶到北方，进入深山中追踪恶魔。 在那里，她发现恶魔们正在猎杀一支幸存的龙族，企图吸取这些远古生物天生的魔力。"
D.Strings[116857]="这些刻意避开日新月异的人类社会的强大龙族和燃烧军团的恶魔打得难分难解。艾格文在龙族的帮助下消灭了这些恶魔，在最后一个恶魔从这个世界消失的时候，一股巨大的风暴出现在北方。一个庞大的黑暗身影出现在诺森德上空。"
D.Strings[116858]="一个庞大的黑暗身影出现在诺森德上空，燃烧军团的首领——恶魔之王萨格拉斯出现在艾格文眼前，周身散发着地狱般的能量。他告戒年轻的守护者，提里斯法会的时代就要结束了，这个世界将会被燃烧军团征服。"
D.Strings[116859]="骄傲的艾格文相信自己有能力对抗这个神一般的恶魔，她释放全身的力量攻击萨格拉斯的躯体。大大出乎她意料的是，艾格文很轻松地击倒了恶魔之王，并成功地摧毁了萨格拉斯的躯体。由于怕萨格拉斯的灵魂仍然徘徊不止，天真的艾格文将他的躯体残骸封印在了一个当永恒之井爆炸时沉没到海底的远古大厅中。"
D.Strings[116860]="艾格文没有意识到她所做的恰恰就是萨格拉斯所预期的。她在不经意间定下了艾泽拉斯世界的命运，因为萨格拉斯的灵魂已经在他的躯体死亡的瞬间潜入了艾格文孱弱的身体中。在年轻的守护者毫不知情的情况下，萨格拉斯将在她灵魂的黑暗面中潜伏很长时间。"
D.Strings[116861]="铁炉堡的矮人在和平的环境中生活了很多个世纪，然而他们的山中城市疆界太有限，而他们的社会又发展得太大了。虽然强大的高山之王莫迪姆斯·安威玛运用正义和智慧统治着所有的矮人，但在矮人社会中，三个强大的部族已经出现了。"
D.Strings[116862]="作为铁炉堡的传统卫队，由亲王玛多兰·铜须领导的铜须部族和高山之王的联系最紧密；由亲王卡德罗斯·蛮锤领导的蛮锤部族居住在山脉下方的小丘上和峭壁边，他们希望能得到更多对城市的控制权。"
D.Strings[116863]="第三个强大的部族是由法师亲王索瑞森领导的黑铁部族，他们隐居在山脉矿坑的最深处，计划着要推翻他们那些铜须部族和蛮锤部族的兄弟们。"
D.Strings[116864]="三个部族保持了一段摇摇欲坠的和平状态，但高山之王的过世让这脆弱的和平彻底消失了。 三个部族为争夺铁炉堡的控制权展开了一场战争，矮人的内战在地下激烈地持续了很多年。 最终，拥有最强大军队的铜须部族把蛮锤部族和黑铁部族驱逐出了铁炉堡，赢得了战争的胜利。"
D.Strings[116865]="卡德罗斯和他的蛮锤战士向北迁徙，穿过了丹奥加兹之门，在格瑞姆巴托峰顶建造了自己的王国。蛮锤部族在那里繁荣兴旺了起来，并重建了他们的宝藏仓库。索瑞森和他的黑铁部族则没有那么好运，战败的耻辱让他们更加愤怒，他们发誓一定要报复铁炉堡。索瑞森在美丽的红岭山脉建造了一座城市（以他自己的名字命名）。"
D.Strings[116866]="生活富足和岁月的流逝并没有消除黑铁部族对他们兄弟的仇恨，索瑞森和他的女巫夫人莫德古德兵分两路对铁炉堡和格瑞姆巴托发动了进攻。黑铁部族准备将卡兹莫丹的所有土地收归囊中。"
D.Strings[116867]="黑铁部族的军队横扫了他们两个兄弟部族的军队和堡垒，差点就攻下了两个王国。但是，玛多兰·铜须亲自领导他的部族击败了索瑞森的法师部队。索瑞森和他的随从不顾格瑞姆巴托的战局逃回了自己的城市，导致莫德古德的军队在面对卡德罗斯和他的蛮锤部族部队时的处境更加艰难。"
D.Strings[116868]="当莫德古德面对她的敌人时，她总是运用自己的力量，将恐惧深深烙进敌人的内心。阴影随着她的命令而移动，黑暗的物体从地底深处浮现出来，潜伏在蛮锤要塞中。最终，莫德古德攻破了大门，直接开始进攻最后的堡垒。蛮锤战士们团结一致，卡德罗斯亲自上阵，在千军万马中击杀了法师女王。"
D.Strings[116869]="莫德古德的阵亡让黑铁军队在暴怒的蛮锤大军面前一溃千里，他们在向南逃往自己的城市时却遇到了从铁炉堡赶来增援格瑞姆巴托的军队。剩余的黑铁部族部队被两面夹击，全军覆没。"
D.Strings[116870]="铁炉堡和格瑞姆巴托的联军随后转向南面，准备彻底消灭索瑞森和他的黑铁部族。但他们并没有走多远，索瑞森的怒火导致了洪水般的魔法波动。他为了战斗的胜利而开始召唤强大的超自然生物，并不顾一切地召唤沉睡于地下的远古力量。令他震惊（并最终毁灭他）的是，他所召唤的生物远远比他能够想像到的任何一个噩梦都要可怕。"
D.Strings[116871]="炎魔拉格纳罗斯是在初建这个世界的时候被泰坦封印的火元素之王，他由于索瑞森的召唤而再次重生。拉格纳罗斯在艾泽拉斯的重生粉碎了赤脊山脉，他的力量使得一座怒哮的火山拔地而起。"
D.Strings[116872]="形成了一座北接灼热峡谷南连燃烧平原的火山——黑石塔。虽然索瑞森被他释放出来的力量杀死了，但他那些幸存下来的同类们却大多被拉格纳罗斯和他麾下的元素生物们奴役了起来。至今，他们还被留在黑石塔里。"
D.Strings[116873]="在目睹了可怕的毁灭景象和南部山脉肆虐的火焰后，玛多兰国王和卡德罗斯国王止住了他们军队的脚步，匆忙掉头向他们自己的国家撤退，以免面对拉格纳罗斯可怕的力量。"
D.Strings[116874]="铜须部族返回铁炉堡，重建了他们荣耀的城市，蛮锤部族也返回了他们在格瑞姆巴托的家园。然而莫德古德的死在这个山丘要塞上留下了一个充满邪恶的瑕疵，蛮锤部族的矮人们发现那里已经不再适合居住了。"
D.Strings[116875]="他们对于失去自己深爱的家园感到无比悲痛。铜须部族的国王给蛮锤部族在铁炉堡的疆界内提供了一个栖身之所，然而蛮锤部族却顽固地拒绝了他。卡德罗斯带着他的子民北上来到了洛丹伦的土地，在富饶的辛特兰森林里居住了下来，蛮锤部族在那里的鹰巢山上建造了自己的城市，并逐渐亲近了大自然，而且甚至与当地的狮鹫兽成为了朋友。"
D.Strings[116876]="铁炉堡的矮人们希望与同胞保持联系与贸易，于是他们建造了两座连接着卡兹莫丹与罗德隆之间山口的巨大拱桥——萨多尔大桥。两个国家靠着互相通商而繁荣了起来，玛多兰和卡德罗斯死后，他们的儿子为缅怀父亲而共同发起雕刻了两尊巨大的雕像。"
D.Strings[116877]="这两尊雕像守护着通往南方那片火山遍布的大地的通道，它们就像是在共同警告着试图攻打矮人王国的家伙，提醒他们黑铁部族为他们的罪行付出了多么惨重的代价。"
D.Strings[116878]="两个王国继续保持了数年的密切关系，但蛮锤部族的矮人却由于他们在格瑞姆巴托看到的恐怖景象而发生了很多改变，他们开始居住在鹰巢山的高处，而不再在深山中挖掘自己的王国。由于意识形态之间存在着巨大的差异，两个矮人部族最终分道扬镳了。"
D.Strings[116879]="时光一年年地飞逝，守护者艾格文变得越来越强大，她运用提里斯法的能量大大延长了自己的寿命。 她错误地认为自己已经消灭了萨格拉斯， 并在接下来的九百年中继续为保护这个世界而与恶魔之王的爪牙斗争。但是，提里斯法会最终决定终结她的守护者职责。"
D.Strings[116880]="议会命令艾格文回到达拉然，以便让他们选择新的守护者。然而艾格文并不信任议会，她决定自己选择接班人。"
D.Strings[116881]="骄傲的艾格文计划生一个孩子来继承她的力量，她决不容许提里斯法会像操纵她一样操纵自己的继承人，于是她来到南方的艾泽拉斯，在那里，她找到了一个最佳人选：人类魔法师聂拉斯·埃兰。"
D.Strings[116882]="埃兰是艾泽拉斯国王的御用法师跟顾问。艾格文引诱了这个魔法师并让她怀了自己的孩子。聂拉斯天生对于魔法的喜好将会深深的埋藏在这个还未出生的小孩的身上，并且会设定好这个孩子将来所要采取的悲剧步骤。提里斯法的力量也会深植在这个孩子的身上，直到他的身体真正长大，这股力量才会真正的觉醒。"
D.Strings[116883]="时光飞逝，艾格文在一处与世隔绝的森林里生下了她的儿子。他被取名为麦迪文，在高等精灵的语言中，这个词的意思是“保守秘密的人”。 艾格文相信她的儿子将成长为下一个守护者。然而不幸的是，萨格拉斯恶毒的灵魂隐藏在她的体内，并且早在她怀孕的时候就占据了她的孩子的躯体。艾格文根本没有想到，刚刚来到这个世界的新的守护者已经被他最大的敌人占据了。"
D.Strings[116884]="在确认了麦迪文正在健康活泼地成长之后，艾格文将幼小的孩子送到艾泽拉斯的宫廷中，让他的人类父亲和其他人抚养他长大。她自己则漫游在荒野中，准备一个人渡过余生。麦迪文健康地成长为一个强壮的孩子，但他完全没有意识到他体内拥有多么强大的力量。"
D.Strings[116885]="萨格拉斯等待着时机，等待着这个年轻人体内的力量自动显现出来。当麦迪文成长到了少年时期，他高超的魔法技巧让他在艾泽拉斯很受欢迎。同时，他也经常和他的两个朋友一起去探险，这两个朋友一个是艾泽拉斯的莱恩王子，另一个是阿拉希血统的唯一传人，安杜因·洛萨。虽然这三个小孩子经常在王国内搞恶作剧，但平民百姓都非常喜欢他们。"
D.Strings[116886]="当麦迪文到了14岁时，他体内强大的力量觉醒了，这股力量和潜藏于他灵魂中的萨格拉斯的灵魂发生了激烈的冲突。麦迪文因此陷入了长达数年的昏睡。"
D.Strings[116887]="当他从昏迷中醒来的时候，他发现自己已经长大成人，而他的朋友莱恩和安杜因也已经成为了艾泽拉斯的摄政王。虽然他希望运用身体里那不可思议的力量来保护这片被自己称做“家园”的土地，但萨格拉斯的灵魂将他的意志和情感扭向了阴暗的一面。"
D.Strings[116888]="萨格拉斯出现在麦迪文心中的阴暗面，他知道第二次入侵这个世界的计划已经快要成功了，而这个最后的守护者将帮助他们完成这个计划。"
D.Strings[116889]="在麦迪文降生的前后，欺诈者基尔加丹正和他的随从们在扭曲虚空中谋划着下一步的行动。这个狡猾的恶魔领主在他的主人萨格拉斯的命令下，计划着燃烧军团对艾泽拉斯世界的第二次入侵。"
D.Strings[116890]="这一次，他不能允许有任何的闪失。基尔加丹认为他需要先派遣一支新的力量去削弱艾泽拉斯的防御力量，然后燃烧军团才能轻松征服这个世界。如果艾泽拉斯大陆的原生种族——比如夜精灵和龙族——在被迫对付新的威胁时遭到损失，那么当燃烧军团真正入侵的时候，他们就会因为实力太弱而不能构成任何实质性的抵抗。"
D.Strings[116891]="正是在这个时候，基尔加丹发现了在浑沌黑暗中静静地漂浮着的德拉诺，一个生机盎然的世界。这片充满田园风情的广阔土地是有着萨满传统、以氏族为社会组织形式的兽人和爱好和平的德莱尼人的故乡。"
D.Strings[116892]="高贵的兽人氏族在广阔的草原上游牧、打猎，而好学的德莱尼人在高耸的悬崖和山峰上建立了原始的城市。基尔加丹意识到，只要通过恰当的培养，这些德拉诺的原住民就可以有为燃烧军团效命的巨大潜力。"
D.Strings[116893]="在比较了这两个种族之后，基尔加丹认为尚武的兽人更容易受到燃烧军团的影响而走向堕落。他采取了和很久之前萨格拉斯控制女王艾萨拉几乎完全相同的手法奴役了年长的兽人萨满耐奥祖。通过这个萨满的引导，恶魔将杀戮的欲望和野性传播到了整个兽人氏族中。"
D.Strings[116894]="不久之后，这个高贵的种族便被转化成了一群嗜血的奴仆。基尔加丹驱使耐奥祖和他的子民走完堕落的最后一步：使他们完全为了追逐死亡和战争而存在。但是耐奥祖意识到他的人民将会被仇恨永远束缚，基于某种原因，他拒绝听从恶魔的命令。"
D.Strings[116895]="由于耐奥祖的拒绝合作而受挫的基尔加丹很快开始寻找另一个能将他的同胞交与燃烧军团掌握的兽人。狡诈的恶魔领主最终找到了一个令他满意的忠实门徒——耐奥祖那野心勃勃的学生，古尔丹。基尔加丹承诺将会给予古尔丹无尽的力量，并以此来换取他绝对的忠诚。"
D.Strings[116896]="这个年轻的兽人渐渐成为了恶魔魔法的贪婪学徒，成为了有史以来世界上最强的术士。他向其他的年轻兽人传授这种神秘的妖术，并力求根除兽人氏族中高贵的萨满教传统。古尔丹向他的同胞们展示了一种新的魔法，一种可怕的、散发着死亡气息的能量。"
D.Strings[116897]="基尔加丹力求对兽人有着绝对的控制权，因此他帮助古尔丹建立了影子议会，这是一个秘密的宗派组织，其作用是操纵兽人氏族并利用巫术魔法在德拉诺大陆上扩张。当越来越多的兽人开始修习巫术魔法时，安宁而生机勃勃的德拉诺世界开始变得黑暗和枯萎。随着时间的流逝，辽阔的草原留给兽人们繁衍生息的土地已渐渐萎缩，到处都是红色的荒土。恶魔的能量正在慢慢地毁灭这个世界。"
D.Strings[116898]="在古尔丹和他的影子议会的控制下，兽人们变得越来越具有侵略性。他们建造了宏大的竞技场，使兽人们在其中磨练杀戮技能并体验战争和死亡。在这段时期里，一小部分氏族酋长对于种族的堕落表示了强烈的不满。"
D.Strings[116899]="其中霜狼氏族的酋长杜洛坦就告戒说，兽人已经迷失了自我而处于仇恨和狂暴之中。然而，他的警言却没有人听取，一些强大氏族的酋长——例如战歌氏族的葛罗·地狱吼——却站出来迎接这个充满战争和征服的新时代。"
D.Strings[116900]="虽然基尔加丹知道兽人氏族已基本做好了准备，但他还是需要确认兽人对他的绝对忠诚。他通过影子议会秘密召唤了破坏者玛诺洛斯——一个充满毁灭欲望的狂暴恶魔。同时古尔丹也将氏族酋长们召集到一起，并使他们确信自己在喝过玛诺洛斯的狂暴之血后将变得不可征服。"
D.Strings[116901]="除了杜洛坦之外，所有的氏族酋长都在葛罗·地狱吼的带领下喝下了狂暴之血，就此将自己的命运彻底交给了恶魔，成为了燃烧军团的奴隶。在玛诺洛斯之血的引诱下，酋长们不自觉地将征服的欲望扩散到绝对信任他们的同胞之中。"
D.Strings[116902]="兽人完全被这个嗜血的诅咒所吞没，准备将怒气发泄到任何阻挡他们的人身上。古尔丹觉得时机已经成熟了，就将互相征伐的各个氏族联合成了一个统一的、无可阻挡的部落。"
D.Strings[116903]="然而，在考虑到某些酋长比如葛罗姆．地狱吼和奥格瑞姆·毁灭之锤可能会为了最高统帅的地位而互相争执之后，古尔丹设立了一个傀儡酋长来统治这个新的部落。毁灭者布莱克汉，一个异常堕落和邪恶的首领，被选中成为了古尔丹的傀儡。在布莱克汉的指挥下，兽人部落开始用纯朴的德莱尼人测试自己的战斗能力。"
D.Strings[116904]="几个月之后，部落几乎根除了德拉诺大陆上的所有德莱尼人，只有一小部分德莱尼人的幸存者苟延残喘地躲避兽人那可怕的狂怒。因为胜利而得意的古尔丹整日沉迷于部落的力量和权力之中。然而，他清楚地知道，如果没有可以杀戮的敌人，兽人部落就会因为自己无法控制的屠杀欲望在无休止的内战中毁灭。"
D.Strings[116905]="基尔加丹也意识到部落已经完全准备好了，兽人已经成为燃烧军团手中最为强大的武器。他把这条消息告诉了他的主人，萨格拉斯也认为他复仇的时刻终于来临了。"
D.Strings[116906]="当基尔加丹紧锣密鼓地让部落为入侵艾泽拉斯做好准备时，麦迪文仍然在与萨格拉斯争夺着自己灵魂的控制权。暴风城的莱恩国王渐渐对那些侵蚀了麦迪文灵魂的黑暗气息感到不安。"
D.Strings[116907]="他把自己的担忧告知了安杜因·洛萨——阿拉希最后的血脉，莱恩国王亲自任命的军队统帅。但是，两人都没有能想像到麦迪文渐渐堕入疯狂后会带来什么样的灾难。"
D.Strings[116908]="萨格拉斯向古尔丹许诺道，如果古尔丹答应率领部落侵入艾泽拉斯，那么他就将给予古尔丹强大的力量作为回报。他通过麦迪文之口告诉古尔丹，如果他能找到一千多年前守护者艾格文封存萨格拉斯残骸的水下墓穴，他就可以成为世界的主宰。"
D.Strings[116909]="古尔丹接受了萨格拉斯的条件，并决定在击败艾泽拉斯的原住民之后找到传说中的古墓并索取他应得的报酬。在确认兽人们会服从他的支配之后，萨格拉斯命令兽人开始入侵行动。"
D.Strings[116910]="麦迪文与影子议会的术士们合力打开了一条被称为黑暗之门的空间通道。这个通道连接艾泽拉斯与德拉诺，并且大到足以让整支部队通过。古尔丹派遣兽人斥候穿过黑暗之门去侦察这块他们即将征服的大陆，斥候所带回的情报使影子议会确信夺取艾泽拉斯的时机已经成熟。"
D.Strings[116911]="杜洛坦仍然认为古尔丹的堕落将会导致部落的灭亡，他再一次向术士们提出了抗议。这位勇士声称术士正在背离高尚纯洁的兽人精神，而他们这种不计后果的入侵最终将给兽人带来厄运。由于古尔丹不敢冒险杀害如此着名的英雄，他就施计将杜洛坦和他的霜狼氏族流放到了新世界的边缘地带去了。"
D.Strings[116912]="在被流放的霜狼氏族冲过了通道后，只有少数兽人氏族跟着去了新世界。这些兽人很快在黑色沼泽——一个位于暴风王国东面的阴暗的沼泽地带——建立了军事基地。当兽人开始在这块新土地上扩张与探索时，他们立即与暴风城的人类守卫发生了冲突。"
D.Strings[116913]="尽管这些小冲突很快就结束了，但它们充分体现出冲突双方各自的优势和劣势。莱恩与洛萨从来都无法得知兽人的确切数量，只能依靠猜测来判断他们将要面临的威胁有多大。"
D.Strings[116914]="几年之后，大部分兽人部落都进入了艾泽拉斯，此时古尔丹认为对人类发起总攻的时机已经到了。兽人部落聚集起所有的力量对毫不知情的暴风王国发起了进攻。"
D.Strings[116915]="当人类与兽人的冲突在整个艾泽拉斯王国蔓延开来时，交战的双方都为此付出了代价。莱恩国王坚信残忍的兽人无法征服艾泽拉斯大陆，他轻蔑地在暴风王国的首都按兵不动。然而洛萨爵士认为应该直接与敌人进行正面交锋，这使他不得不在自己的想法与对国王的忠诚之间作出抉择。"
D.Strings[116916]="最终他选择了自己的本能，在麦迪文的年轻学徒卡德加的帮助下，洛萨爵士对麦迪文那座位于卡拉赞的法师塔发起了闪电般的突袭。卡德加和洛萨成功地击败了疯狂的守护者——那个引发战争的罪魁祸首。"
D.Strings[116917]="通过毁灭麦迪文的肉身，洛萨与卡德加在不经意间将萨格拉斯的灵魂打入了深渊。纯洁而善良的麦迪文的灵魂也因此得到了解放，并在星界位面中徘徊了多年。"
D.Strings[116918]="尽管麦迪文被击败了，但是兽人部落依然占有优势。当兽人的大军即将获取胜利的时候，最伟大的兽人酋长之一的奥格瑞姆·毁灭之锤开始察觉到了那股当他们还在德拉诺的时就开始在部落中蔓延的堕落力量。"
D.Strings[116919]="他的老朋友杜洛坦从流放之地赶回来，再次向他揭露了古尔丹的背叛行为。古尔丹的杀手很快就暗杀了杜洛坦全家，只留下了他幼小的儿子。毁灭之锤不知道这个杜洛坦唯一的血脉被一个名叫埃德拉斯·布拉克摩尔的人类中尉发现，并像对待一个奴隶一样抚养着他。$B$B 那个幼小的兽人后来成为了众所周知的最伟大的兽人领袖。"
D.Strings[116920]="奥格瑞姆被杜洛坦的死激怒了，他开始着手把兽人部落从邪恶的堕落中拯救出来，最终他杀死了古尔丹的傀儡布莱克汉，取而代之成为了兽人部落的首领。在他的统御下，无情的兽人最终对暴风要塞发起了攻击。"
D.Strings[116921]="莱恩国王严重低估了兽人部落的力量，他无助地看着自己的王国落入这些绿皮肤的侵略者手中。最终，莱恩被半兽人加罗娜——影子议会中最优秀的杀手之一——所暗杀。"
D.Strings[116922]="洛萨和他的勇士们从卡拉赞归来，希望尽力减少人们的伤亡并拯救他们的家园。然而，他们回来得太晚了，他们热爱的王国已经化为一片废墟。兽人部落依然在蹂躏着每一寸土地，被迫藏匿起来的洛萨和他的同伴立下重誓，要不惜任何代价夺回他们的家园。"
D.Strings[116923]="在暴风要塞被攻陷后，洛萨爵士重新集结了艾泽拉斯的残余部队，并带领着难民远渡重洋向北方的洛丹伦大批迁徙。人类七国领袖达成了共识：如果不阻止兽人部落，他们终将征服全人类，于是这七个国家团结起来组成了洛丹伦联盟。"
D.Strings[116924]="由阿拉索分裂出去的国家三千年来第一次团结在同一面旗帜之下。被指定为人类联盟最高指挥官的洛萨爵士为迎战即将大举进犯的兽人部落精心准备着他的部队。"
D.Strings[116925]="在副官光明使者乌瑟尔、海军上将戴林·普罗德摩尔与图拉扬的帮助下，洛萨成功地使洛丹伦的各个非人类种族也意识到了迅速迫近的威胁。人类联盟成功地从铁炉堡里的顽固矮人和一小部分奎尔萨拉斯的高等精灵那里获得了支持。"
D.Strings[116926]="由安纳斯特里亚·逐日者领导的精灵对即将发生的战争并没有多大兴趣，然而他们仍然为了履行由契约定下的义务而赶来支援洛萨爵士，因为洛萨是阿拉希最后的血脉，是那些曾在几个世纪前帮助过高等精灵的人类的后代。"
D.Strings[116927]="由奥格瑞姆·毁灭之锤领导的兽人部落从家乡德拉诺带来了食人魔，并招募了那些被夺走了家园的阿曼尼森林巨魔进入自己的部队。他们发动了规模空前的战役，席卷了由矮人统治的卡兹莫丹大陆和洛丹伦南方的区域，并毫不费力镇压了所有的反对力量。"
D.Strings[116928]="第二次兽人战争从海上的零星冲突一直延伸到大规模的空中混战。不知是什么原因，兽人部落挖出了一个被称为恶魔之魂的强大神器，并用它奴役了红龙女王阿莱克斯塔萨。兽人部落以摧毁她珍贵的龙蛋为威胁，迫使阿莱克斯塔萨派遣她那些成年的孩子们参加战斗。高贵的红龙们不得不为兽人部落战斗。"
D.Strings[116929]="战争遍及整个卡兹莫丹、洛丹伦和艾泽拉斯。在北线的战役中，兽人部落将遥远的精灵王国奎尔萨拉斯的周边地区烧成了灰烬，这使得精灵们开始全力协助人类联盟作战。洛丹伦较大的市镇都被战事夷为平地，尽管缺乏援军并面临着兽人压倒性的优势，但是洛萨与他的同盟者还是成功遏制住了敌人前进的步伐。"
D.Strings[116930]="然而，在第二次兽人战争的最后几天，当兽人部落对人类联盟的胜利近在咫尺的时候，艾泽拉斯的两个最强大的兽人之间爆发了一次可怕的分裂。当奥格瑞姆·毁灭之锤为进攻洛丹伦的首都——这将是一次可能粉碎掉人类联盟最后的残余力量的进攻——作最后的准备时，古尔丹和他的追随者擅离职守出海而去。"
D.Strings[116931]="兽人部落因为古尔丹的背叛而损失了将近一半驻军，暴怒的毁灭之锤不得不后撤，因此错过了战胜人类联盟的最佳机会。"
D.Strings[116932]="极度渴望力量的古尔丹痴迷于获得神格，他拼命派出搜索队去寻找被埋葬在海底的萨格拉斯之墓，他相信在那里隐藏着终极力量的秘密。古尔丹已经将他的兽人同胞全部出卖给燃烧军团作为奴隶，他压根没有想过所谓对毁灭之锤尽职的问题。"
D.Strings[116933]="在暴掠氏族和暮锤氏族的支持下，古尔丹成功地在海底找到了萨格拉斯之墓。但是当他打开这远古地牢的大门时，古尔丹发现等待他的只有无数疯狂的恶魔。"
D.Strings[116934]="为了惩罚那些临阵叛逃的兽人，毁灭之锤命令他的部队去追杀古尔丹并押回叛变的兽人。古尔丹为他的鲁莽付出了代价，他被自己释放的疯狂恶魔撕成了碎片。在他们的领导者死后，叛变的氏族很快就被毁灭之锤愤怒的军团击溃。"
D.Strings[116935]="虽然叛变被镇压了，但兽人部落已无法弥补这次内乱所带来的损失。古尔丹的背叛给联盟带来的不仅是希望，还有重新集结的时间以及发动反击的机会。"
D.Strings[116936]="洛萨爵士看到兽人部落内部产生了分裂，就不失时机地集合了他最后的部队，将兽人逼回了已被毁灭的艾泽拉斯的腹地。在那里，人类联盟包围了兽人在黑石塔的据点。尽管洛萨在塔底不幸战死，但他的副官图拉杨在最后时刻重新聚集起人类联盟的兄弟们，将兽人部落赶进了悲伤沼泽的深处。"
D.Strings[116937]="图拉杨的部队成功地毁灭了黑暗之门——那个连通兽人的家乡德拉诺和艾泽拉斯世界的神秘通道。被截断补给与后援的兽人部落终于在联盟的力量前崩溃了。"
D.Strings[116938]="四分五裂的兽人氏族很快被赶进了戒备森严的俘虏收容所。虽然看起来兽人已经被完全击败了，但仍然有人怀疑这种和平能持续多久。此时已经赫赫有名的大法师卡德加说服联盟的高层建立了守望堡以监视黑暗之门的废墟，确保兽人不会再从德拉诺发动新的入侵。"
D.Strings[116939]="当第二次兽人战争的硝烟散尽之後，联盟以积极的态度和举措来解决兽人问题，在罗德隆南部建立了一系列俘虏收容所，用以关押被俘的兽人。在圣骑士和经验丰富的老兵的看守下，收容所取得了巨大的成功。虽然那些被俘的兽人烦躁不安地想要进行战斗，但在古老的监狱城堡德恩霍尔德要塞的控制之下，一切都显得和平而井井有条。"
D.Strings[116940]="虽然那些被俘的兽人烦躁不安地想要进行战斗，但在古老的监狱城堡敦霍尔德要塞的控制之下，一切都显得和平而井井有条。"
D.Strings[116941]="尽管如此，在地狱般的德拉诺德世界，一支新的兽人部队已经准备好要再次血洗毫无防备的人类联盟。古尔丹的导师耐祖奥重新将残留的兽族氏族集结在他的旌旗下。在影月氏族的支持下，老萨满计画在德拉诺打开几扇通向新世界的传送门。"
D.Strings[116942]="为了加强他的新传送门，他需要从艾泽拉斯取得一些上古神器。於是，耐祖奥再次开启了黑暗之门，并派出了他的嫡系部队。"
D.Strings[116943]="新的兽人部落在经验丰富的酋长─战歌氏族的葛罗·地狱吼和血窟氏族的基尔罗格·亡眼─的率领下，令联盟的防御部队大惊失色，他们横扫了四周的乡村。在耐祖奥的精密指引下，兽人迅速找到了他们需要的神器并撤回了德拉诺。"
D.Strings[116944]="罗德隆王国的泰瑞纳斯国王深信兽人已经准备好了对艾泽拉斯发动新一轮的入侵，於是召集了他最信赖的副官。泰瑞纳斯国王命令图拉扬将军和大法师卡德加率领一支远征队穿过黑暗之门去解决兽人的威胁。图拉扬和卡德加率领部队开进了德拉诺，并在荒芜的地狱火半岛上与耐祖奥的氏族激烈交战。"
D.Strings[116945]="即使有高等精灵艾兰里亚·风行者、矮人库德兰·蛮锤和勇猛的战士达纳斯·托尔贝恩的帮助，卡德加仍然无法阻止耐祖奥打开通往其他世界的传送门。"
D.Strings[116946]="最终耐祖奥打开了新的传送门，但是他没有预见到他将为此付出可怕的代价，这个传送门所散发出的巨大能量开始毁灭德拉诺世界。在图拉扬的部队为了回到艾泽拉斯拚死战斗时，德拉诺世界开始崩溃。葛罗·地狱吼和基尔罗格·亡眼意识到耐祖奥的疯狂计画会毁灭他们的整个种族，於是他们集结了残余的兽人并逃到了艾泽拉斯。"
D.Strings[116947]="在德拉诺，图拉扬和法师卡德加最终决定在他们这边毁灭黑暗之门，虽然他们明白自己将永远不能离开德拉诺，但是他们也知道这是确保艾泽拉斯不受影响的唯一方法。在葛罗·地狱吼和基尔罗格·亡眼为了获得自由不顾一切地在人类的部队里杀开一条血路时，黑暗之门在他们的身後爆炸了。对於他们，以及所有留在艾泽拉斯的兽人们来说，回到他们家乡的希望已经永远破灭了。"
D.Strings[116948]="耐奥祖和他的兽人进入了扭曲虚空——这是一片在无尽的黑暗中连接着所有世界的异度空间。然而不幸的是，基尔加丹和他手下的恶魔们正在这里等待着耐奥祖一行的到来。基尔加丹曾经发誓要让耐奥祖为他的抗命付出代价，于是他残忍地折磨着这位年老的萨满祭司，将他身上的肉一片片割了下来。"
D.Strings[116949]="基尔加丹完好地保留着耐奥祖的灵魂，让他忍受被大卸八块的痛苦。虽然耐奥祖哀求恶魔释放他的灵魂并让他痛快地死去，但恶魔只是冷酷地回答他，他们很久以前订下的血契仍然有效，因此耐奥祖仍然有利用价值。"
D.Strings[116950]="兽人未能如燃烧军团所愿征服艾泽拉斯世界，这迫使基尔加丹只好建立一支新的军队到艾泽拉斯世界去制造混乱。这支新的军队不能像兽人一样内乱不断，它必须对燃烧军团唯命是从、手段残忍，并且一心一意执行他们的任务。这一次，基尔加丹不能再失败了。"
D.Strings[116951]="基尔加丹控制着耐奥祖那被不断折磨的无助灵魂，并给他最后一次为燃烧军团服务的机会，否则就让他忍受永恒的折磨。耐奥祖又一次不顾后果地接受了恶魔提出的条件，他的灵魂被放入了一颗经过精心雕琢的冰块中，这块从扭曲虚空的远方采集的冰块如钻石般坚硬。"
D.Strings[116952]="在被装入这个冰冷的容器之后，耐奥祖感到他的思想扩展了数万倍。被恶魔的混乱力量扭曲的耐奥祖成为了一个幽灵般的生物，从那一刻起，兽人萨满祭司耐奥祖永远消失，而巫妖之王诞生了。"
D.Strings[116953]="忠于耐奥祖的死亡骑士和影月氏族的追随者也被恶魔的力量转化了。邪恶的术士们被撕成碎片并变成了骷髅般的巫妖，恶魔们用这种方法来保证即使在死后，耐奥祖的跟随者们也会死心塌地地为他服务。"
D.Strings[116954]="当时机成熟时，基尔加丹向巫妖王解释了他的计划：耐奥祖将在艾泽拉斯散布瘟疫，使死亡和恐惧笼罩艾泽拉斯，并最终毁灭人类文明。所有死在恐怖瘟疫下的生物都会变成亡灵，他们的灵魂将永远被耐奥祖的意志控制。"
D.Strings[116955]="基尔加丹向巫妖王保证，如果他能够完成毁灭人类世界的任务，就可以从他的诅咒中解脱出来并获得一个全新的健康身躯。"
D.Strings[116956]="虽然耐奥祖急切地想要完成他的任务，但基尔加丹仍然对他的忠诚感到怀疑。恶魔将巫妖王的灵魂困在冰壳中以确保他能够按照军团的命令办事，但他知道他必须时刻警惕着巫妖王。为了解决这个问题，基尔加丹召集了他的精锐恶魔守卫——吸血鬼一般的恐惧魔王——去监视耐奥祖并确保他能完成任务。"
D.Strings[116957]="最强大最狡猾的恐惧魔王提托迪奥斯接受了这个挑战，他对瘟疫的效力和巫妖王在灭绝式的大屠杀上所表现的无限创造力充满了兴趣。"
D.Strings[116958]="基尔加丹将盛放耐奥祖灵魂的冰冷容器送回了艾泽拉斯的世界。坚硬的水晶划过夜空，坠落在荒凉寒冷的诺森德大陆，埋入了深不见底的寒冰皇冠冰川。困着耐奥祖灵魂的冰壳被它本身撞击地表所爆发出的巨大能量扭曲，形成了一个王座，耐奥祖那充满复仇意念的灵魂就附着在这个王座上。"
D.Strings[116959]="耐奥祖开始在冰封王座的领域中释放他的意念并与诺森德的原住生物的思想接触。他很轻松地控制了许多当地生物的思想（比如冰巨魔和凶猛的雪怪），并且将他们笼罩在自己不断扩大的阴影下。耐奥祖发现自己的精神力量几乎是无限的，于是他使用这种力量建立了一支小型部队，让他们驻扎在寒冰皇冠的迷宫中。"
D.Strings[116960]="在恐惧魔王的监视下，巫妖王控制着他越来越强大的部队，并且在龙骨荒地的边缘发现了一个人类的移民点。耐奥祖决定用这些毫无防备的人类来检验他的力量。"
D.Strings[116961]="耐奥祖向寒冷的荒地释放了来自冰封王座深处的亡灵瘟疫。他用意志控制着亡灵瘟疫，将它导入人类的村庄。在不到三天的时间内，村庄中的所有人类都死了，然后在极短的时间里，这些死去的村民变成了僵尸。耐奥祖可以感觉到他们每个人的灵魂和思想，就好像那是他自己的一样。"
D.Strings[116962]="在他脑中回荡的哀号使他变得更加强大——就好像他们的灵魂是他急需的营养品。他发现要控制这些僵尸的行动并指派他们去做任何事情都易如反掌。"
D.Strings[116963]="在接下来的几个月中，耐奥祖继续指挥他的瘟疫横扫诺森德大陆上的每一个人类定居点。当他的亡灵军队日益壮大时，他知道真正的试炼就要来了。"
D.Strings[116964]="同时，在受战争蹂躏的南方土地上，部落散乱的遗迹为他们的生存奋斗。虽然葛罗·地狱吼和他的战歌氏族躲开了被捕的命运，亡眼和他的血之谷氏族仍被围捕并被安置在洛丹伦的拘留营地。尽管经历这些代价高的暴动，营地的典狱长很快就重建了对他们野蛮攻击的控制。"
D.Strings[116965]="尽管如此，在联盟的侦察员毫无察觉的情况下，一股强大的兽人势力仍然控制着卡兹莫丹北部的荒野。龙喉氏族的酋长——臭名昭着的术士耐克鲁斯利用一个被称为“恶魔之魂”的远古神器控制着红龙女王雅立史卓莎和她的红龙一族。由于控制着红龙女王，耐克鲁斯在被遗弃的蛮锤要塞格瑞姆巴托中建立起一支秘密的部队。"
D.Strings[116966]="他计划利用他的部队和强大的红龙军团对联盟发动新的战争，从而将四散的兽人部落重新联合起来，继续他们对艾泽拉斯的征服行动。然而他的计划没有能够实现，由人类法师罗宁领导的一个小队毁掉了恶魔之魂，将红龙女王阿莱克斯塔萨从耐克鲁斯的控制中释放了出来。"
D.Strings[116967]="暴怒的红龙将格瑞姆巴托要塞彻底摧毁，把大部分的龙喉氏族的余党都烧成了灰。当联盟将幸存的兽人投进俘虏收容所时，耐克鲁斯的计划宣告破产。龙喉氏族的失败标志着兽人部落的末日，以及兽人狂暴嗜血的彻底终结。"
D.Strings[116968]="数月之后，更多的兽人囚犯被投入了收容所。随着各地的收容所爆满，联盟不得不在奥特拉克山脉南部的平原上修建新的收容所。为了更好地维持和供给数目不断增长的收容所，洛丹伦王国的泰瑞纳斯国王向所有联盟成员国征收新的税款。"
D.Strings[116969]="这项新税和日益升级的边界争执使得联盟陷入了极其不稳定的状态。从各方面的情况看来，在人类王国最黑暗和最困难的时期签定的那些条约随时可能被撕毁。"
D.Strings[116970]="在政治骚乱的同时，许多收容所的看守开始注意到他们的兽人囚犯发生了令人困惑的变化。兽人试图越狱逃跑的行为，甚至是他们内部的斗殴都大幅度减少，兽人们变得越来越冷漠和嗜睡。"
D.Strings[116971]="虽然这很难相信，但兽人——这个曾经是艾泽拉斯大陆上最具侵略性的种族——开始丧失战斗的欲望。这种奇怪的现象令联盟的领导人感到莫名其妙并继续影响着这些急剧衰弱的兽人。"
D.Strings[116972]="一些人认为，是一种奇怪的、只会感染兽人的疾病使兽人变成了这副昏昏欲睡的样子。但达拉然的大法师安东尼达斯提出了另一种假说：在研究了他所能了解的所有兽人历史之后，安东尼达斯发现兽人已经受恶魔的力量影响长达数百年之久。"
D.Strings[116973]="他认为兽人早在第一次入侵艾泽拉斯之前就已经被恶魔的力量引诱而堕落了。很明显，恶魔毒害了兽人的血液，作为交换，他们给了兽人异乎寻常的力量、耐力和侵略性。"
D.Strings[116974]="安东尼达斯认为兽人的反常嗜睡行为并不是疾病，而是长期以来使他们变得可怕、嗜血的恶魔法术消退的后果。"
D.Strings[116975]="虽然这种症状很明显，但安东尼达斯无法找到治疗兽人目前状况的方法，而他的许多学徒和一些着名的联盟领导人都认为替兽人找出治疗的方法纯属冒险行为。在谨慎地考察了兽人目前的神秘状况之后，安东尼达斯认为治愈兽人的唯一途径是通过精神的力量。"
D.Strings[116976]="俘虏收容所的大典狱官埃德拉斯·布拉克摩尔在他的监狱堡垒敦霍尔德中监视着被俘的兽人们。有一个特殊的兽人总是引起他的兴趣：他在十八年前捡到的那个失去双亲的婴儿。布拉克摩尔将这个年青的男兽人培养成了一个才华横溢的奴隶，并给他起名叫萨尔。布拉克摩尔将关于战术、哲学和格斗的知识传授给萨尔，并将他训练成为一名角斗士。自始至终，这个邪恶的典狱官都在致力于将这名兽人青年铸造成为一件武器。"
D.Strings[116977]="尽管典狱官的养育极其苛刻，年青的萨尔仍然成长为一名健壮而聪明的兽人，但他心里明白自己的一生决不应该作为奴隶度过。当萨尔成年以后，他了解到了自己的种族，还有那些他从来都没有见过的、在战争中被击败的同类们，他们中的大多数都被关入俘虏收容所中。有传闻说兽人领袖奥格瑞姆·毁灭之锤已经从洛丹伦逃走并隐居了起来，只有一个流亡的氏族仍然试图避开联盟警惕的目光，秘密地进行着军事活动。"
D.Strings[116978]="学识丰富但毫无经验的萨尔决定从布拉克摩尔的堡垒中逃跑并寻找他的同胞。在旅途中，萨尔访问了俘虏收容所，并发现他那一度强大的族群变得懒散虚弱，在这里找不到他希望发现的值得骄傲的战士。萨尔继续寻找最后的兽人酋长，葛罗·地狱吼。"
D.Strings[116979]="虽然人类在不断追捕格罗姆，但他仍然保持着兽人旺盛的战斗欲望。在他的战歌氏族的帮助下，地狱咆哮为解放他那些被压迫的同胞而不懈战斗。不幸的是，地狱咆哮永远也找不到解救他们的办法。索尔被地狱咆哮的坚定所感动，下定决心要找回兽人的战斗传统。"
D.Strings[116980]="为了找寻他自己的氏族，萨尔向北方旅行，期望能碰到传说中的霜狼氏族。萨尔了解到古尔丹曾经在第一次战争早期流放了霜狼氏族，他也了解到了他就是兽人英雄杜隆坦——在20年前被谋杀的霜狼氏族的酋长——的唯一子嗣。"
D.Strings[116981]="在值得尊敬的萨满德雷克塔尔的保护下，萨尔学习了在古尔丹的邪恶统治下被兽人遗忘的古老萨满文化。一段时间之后，萨尔成为了一位强大的萨满并成为了霜狼氏族的酋长。在元素的帮助下，萨尔决定解放被囚禁的氏族并将他们从恶魔的诱惑中解救出来。"
D.Strings[116982]="索尔在旅程中遇到了隐居多年的的酋长奥格瑞姆·末日锤。作为索尔的父亲最要好的朋友，末日锤决定跟随年轻有为的索尔并帮助他解放那些被囚禁的氏族。在许多经验丰富的酋长的帮助下，索尔最终成功地使兽人重新充满了活力，并为他的人民确立了新的精神信仰。"
D.Strings[116983]="作为他的人民所获得新生的象征，萨尔回到了布拉克摩尔的敦霍尔德城堡并解放了收容所中的兽人。但是，在解放一座收容所的战斗中，毁灭之锤战死了。"
D.Strings[116984]="索尔拿起了末日锤那传奇般的战锤，穿上了他的黑色铠甲，成为了新的兽人领袖。在接下来的几个月里，索尔的部落扫平了许多收容所，并使联盟花费了极大精力来应付他精明的战术。在他最好的朋友兼顾问葛罗·地狱吼的鼓励下，索尔为了确保没有兽人再次成为奴隶——无论是人类还是恶魔的——而战斗着。"
D.Strings[116985]="当萨尔在洛丹伦释放其同胞弟兄的时候，耐奥祖继续在诺森德大陆巩固他的基地，他在冰冠冰川上空建立起了一座巨大的城堡以控制庞大的亡灵军团。"
D.Strings[116986]="但在巫妖王拓展他的疆域时，一个孤单、隐秘的王国开始与他的力量进行对抗。这个被称为艾兹卓-尼拉布的古老的地下王国是由一个残忍的类人蜘蛛种族建立的，他们派出精锐部队袭击了寒冰皇冠，并使耐奥祖打消了征服他们的疯狂念头。耐奥祖沮丧地发现这些蜘蛛对他的心灵控制完全免疫，并且强大到足以和他的亡灵大军一较高下。"
D.Strings[116987]="蛛网怪的蜘蛛之王控制着庞大的部队，并且拥有覆盖了诺森德一半疆域的地下隧道网路。他们的游击战术令巫妖王疲于奔命却一无所得。最终，耐奥祖艰难地赢得了对蛛网怪的战争，在狂暴的恐惧魔王和无数不死生物战士的进攻下，蜘蛛王国艾兹卓-尼拉布变成了一片废墟。"
D.Strings[116988]="虽然蛛网怪对耐奥祖的精神力量免疫，但他强大的通灵能力使他能够操纵蜘蛛战士的尸体并让他们为他作战，并为这些蜘蛛战士修建了适合他们的堡垒和建筑物。"
D.Strings[116989]="在一统诺森德大陆之后，巫妖王准备着手执行他真正的任务。巫妖王将他的意念延伸到了人类的领土，并且召唤所有愿意聆听他的声音的黑暗灵魂……"
D.Strings[116990]="在世界各地都有一些强大的人类愿意听从巫妖王从诺森德发出的精神召唤，其中最着名的就是达拉然的大法师克尔苏加德，他曾是统治达拉然的法师议会肯瑞托的一员。多年以来，克尔苏加德一直被认为是一个异类，因为他坚持研究被禁止的通灵术。"
D.Strings[116991]="在热切地学习完魔法世界中他能接触到的所有知识后，克尔苏加德对眼前的同辈们过时和缺乏想象力的教条感到很沮丧。在听到耐奥祖的召唤之后，渴求黑暗知识的大法师倾尽全力与这个神秘的声音沟通，最终发誓要从强大的巫妖王那里学习所有他能够学习的东西。"
D.Strings[116992]="克尔苏加德放弃了他的所有财产和地位，永远离开了肯瑞托和达拉然。在巫妖王的指示下，他变卖了所有财产，将得到的金钱都藏在一个秘密的地方。在经历了艰难的长途跋涉之后，克尔苏加德终于抵达了诺森德的冰冻海岸。"
D.Strings[116993]="大法师穿越了被战争毁灭的艾兹卓-尼拉布王国的废墟，在这里他看到了耐奥祖的可怕力量，他开始相信投靠神秘的巫妖之王是一个明智而且利益丰厚的决定。"
D.Strings[116994]="在冰冷的荒野上旅行了数月之后，克尔苏加德终于到达了寒冰皇冠。他来到了耐奥祖的黑暗城堡，当沉默的亡灵守卫让他通过时，大法师感到了强烈的震撼。"
D.Strings[116995]="他沿着道路一直朝下走，在冰川的最底层，他见到了霜冻王座，并且将自己的灵魂献给了巫妖之王。"
D.Strings[116996]="巫妖王对新的追随者感到十分满意。他向克尔苏加德许诺要给他不死之身和强大的力量，以换取他的忠诚和服从。渴望黑暗知识和力量的克尔苏加德马上接受了他的第一个任务--深入人类世界并建立一个将耐奥祖作为神来膜拜的新教派。"
D.Strings[116997]="为了帮助大法师完成他的任务，耐奥祖让他继续保留人类的躯体。大法师出色地完成了任务，他运用幻像和宗教的力量吸引了大批被流放的洛丹伦人，并向他们描述了一个美丽的新社会--还给他们每人都送了一个可以随时联系巫妖王的人偶……"
D.Strings[116998]="克尔苏加德秘密回到了洛丹伦，并且在那里活动了三年。他运用他的财富和智商聚集了一些愿意跟随他的人类并组建了一个名为“诅咒神教”的教派。他向信徒们许诺要赐予他们平等的社会地位和永恒的生命以换取他们对耐奥祖的服从。"
D.Strings[116999]="数月之后，大量对生活心灰意冷的人加入了他的教派。克尔苏加德的目标--令人们放弃对光明的信仰，转而膜拜耐奥祖的黑暗力量--很容易地就达到了。在诅咒教派不断发展壮大的同时，克尔苏加德也要确保洛丹伦的统治者们不会发现他们的秘密活动。"
D.Strings[117000]="当克尔苏加德在洛丹伦大获成功的时候，巫妖之王也在为进攻人类世界做最后的准备。耐奥祖将他的瘟疫能量灌入许多被称为“瘟疫之源”的神器中，并命令克尔苏加德将这些神器带往洛丹伦，隐藏在那些被教派控制的村庄中。"
D.Strings[117001]="这些被忠诚的教徒保护着的瘟疫之源将作为产生瘟疫的源泉，源源不断地放出瘟疫，横扫洛丹伦北部的城市和村庄。"
D.Strings[117002]="巫妖王的计划运作得十分成功。许多洛丹伦北部的村民几乎是瞬间就被感染了。与在诺森德一样，被瘟疫接触的人类死去，然后变成对巫妖王唯命是从的奴隶。"
D.Strings[117003]="经过数月的漫长准备，科尔苏加德率领他的诅咒教派向罗德隆发起了第一轮攻击，释放了亡灵瘟疫。乌瑟和他的圣骑士们调查了受瘟疫感染的地区，希望能找到一种解救的办法。他们不断地努力，但是瘟疫仍然在扩散，甚至威胁到了联盟的统一。"
D.Strings[117004]="不死生物的威胁横扫洛丹伦，国王泰瑞纳斯的独子——阿尔萨斯王子担当起了对抗天灾军团的重任。阿尔萨斯成功地消灭了克尔苏加德，但是不死生物的军队并没有因此而减少，反而有更多阵亡的人类士兵成为了新的不死生物。面对势不可挡的强大力量和失败的挫折感，阿尔萨斯采取了更极端的抵抗措施。最后，阿尔萨斯的战友告诫他，不要因此丧失了高贵的人格。"
D.Strings[117005]="阿萨斯的恐惧和决心导致了他最终的覆灭。他追踪瘟疫的源头直到诺森德大陆，想要彻底消除瘟疫的威胁。然而，阿萨斯王子最终成为了巫妖王的猎物，他拔出了被诅咒的魔剑——霜之哀伤，因为他深信这么做可以挽救自己的臣民。"
D.Strings[117006]="虽然这把剑的确给他带来了深不可测的力量，但它同时也夺取了王子的灵魂，使他变成巫妖王手下最强大的死亡骑士。彻底丧失心智的阿萨斯带领天谴军团回到了自己的王国。最终，阿萨斯刺杀了他的父亲——泰瑞纳斯国王，随后又率领巫妖王的大军踏平了整个罗德隆。"
D.Strings[117007]="虽然阿尔萨斯打败了他目前的所有敌人，但他却摆脱不了克尔苏加德的鬼魂。鬼魂告诉阿尔萨斯，为了巫妖王的下一步计划，他必须复活，方法就是把他的尸骨带到高等精灵王国奎尔萨拉斯的太阳之井去。"
D.Strings[117008]="阿尔萨斯和天灾军团侵入奎尔萨拉斯，将精灵围困在脆弱的防线后。银月城的游侠领袖希瓦娜斯·风行者奋勇战斗，但仍不敌阿尔萨斯。阿尔萨斯摧枯拉朽般地击溃了精灵的部队，顺利进入了太阳之井。作为展示他的力量的手段，他把希瓦娜斯的遗体变成女妖，使她永远不死，永远向阿尔萨斯这个奎尔萨拉斯的征服者效忠。"
D.Strings[117009]="最后，阿尔萨斯把克尔苏加德的尸骨浸没在太阳之井的圣水中。尽管永恒的圣水因此受到了污染，克尔苏加德却复活成为了一个法力强大的巫妖，重获新生之后的克尔苏加德向阿尔萨斯解释了巫妖王的下一步计划"
D.Strings[117010]="当阿尔萨斯和他的亡灵军队挥师南下时，奎尔萨拉斯已是死寂沉沉。屹立了九千多年的高等精灵的王城从此不复存在。"
D.Strings[117011]="克尔苏加德复活之后，阿尔萨斯就率领天灾军团杀向了达拉然。他们要在那里得到麦迪文之书，然后用它来召唤阿克蒙德，然后阿克蒙德将亲自率领燃烧军团发起最后的进攻。就连肯瑞托的法师也无法阻止阿尔萨斯的军队偷到麦迪文之书。"
D.Strings[117012]="很快，克尔苏加德就凑齐了施展魔法所需的物品。在距第一次入侵艾泽拉斯世界失败的一万年后，强大的恶魔阿克蒙德和他的部队再次浮现在艾泽拉斯世界的上空。然而，达拉然并不是他们的最终目标。在基尔加丹的命令下，阿克蒙德和他的恶魔跟随天灾军团到达了卡利姆多，他们计划要摧毁世界之树——诺达希尔。"
D.Strings[117013]="在这场混乱当中，一个孤独而神秘的预言者给危难之中的弱小种族提供了指引。这个预言者不是别人，正是最后一位守护者，麦迪文，他正在努力挽救自己犯下的错误。麦迪文告知兽人部落和人类联盟，危险就在眼前，双方应该即刻联合起来。"
D.Strings[117014]="但是由于世代交恶，他们是不可能合作的。麦迪文不得不分别警告兽人和人类，即便是使用预言术或者欺骗的手段，也要引导他们渡过大海，前往传说中的大陆——卡利姆多。兽人和人类很快就遇到了隐居很久的卡多雷文明。"
D.Strings[117015]="索尔领导兽人经历了千辛万苦，在卡林多的荒地上展开了探索。尽管友善的牛头人凯恩·血蹄和强壮的牛头人战士慷慨相助，很多兽人还是开始屈服于折磨他们多年的杀戮欲。索尔的副官——葛罗·地狱吼——甚至背叛了兽人部落，屈服于这种由恶魔带来的欲望。"
D.Strings[117016]="葛罗姆·地狱吼和他的战歌氏族在梣谷遇到了远古夜精灵的哨兵。在确认兽人再次显示出了他们好战的本性之后，半神塞纳留斯亲自前来驱逐这些兽人。然而，地狱吼和他的手下被无尽的仇恨和愤怒所控制，杀死了半神塞纳留斯，玷污了古老的森林。"
D.Strings[117017]="最后，地狱咆哮帮助萨尔打败了玛诺洛斯——这个当初利用自己充满仇恨和愤怒的鲜血诅咒兽人的恶魔领主，赢回了自己的荣誉。随着玛诺洛斯的死去，兽人也从恶魔的诅咒中永远解脱了出来。"
D.Strings[117018]="当麦迪文劝说兽人和人类组成联盟的时候，夜精灵依靠他们的力量独力对抗着燃烧军团。夜精灵的大祭司泰兰德·语风独立奋战，将恶魔和不死生物抵挡在梣谷外。泰兰德也感到她需要援兵，于是，她前去唤醒沉睡了千年的德鲁伊们。"
D.Strings[117019]="有了爱人玛法里奥·怒风的帮助，泰兰德成功地加强了防御，击退了燃烧军团。大自然在德鲁伊的帮助下击溃了燃烧军团和天灾军团。"
D.Strings[117020]="在寻找更多沉睡的德鲁伊时，玛法里奥发现了关押他的亲生兄弟伊利丹的石牢。泰兰德相信伊利丹将助他们一臂之力，于是就把他释放了出来。虽然伊利丹确实帮助了他们一段时间，但他最终还是走上了自己的道路。"
D.Strings[117021]="夜精灵团结一心，坚决抵抗燃烧军团。然而燃烧军团一刻也没有停止过对永恒之井的渴望，始终妄想得到世界之树的力量。如果他们的计划得逞，世界将在这群恶魔的手中彻底毁灭。"
D.Strings[117022]="在燃烧军团对梣谷展开入侵期间，伊利丹结束了他在地牢中近万年的囚犯生涯。他曾尽力让他的伙伴对他安心，但很快他就原形毕露，吸收了一个被称为“古尔丹之颅”的强大术士神器的能量。"
D.Strings[117023]="完成吸收之后的伊利丹变化成了一个拥有恶魔外表和强大力量的生物，他还获得了古尔丹的一部分记忆，特别是关于萨格拉斯之墓——那座传说中位于一座小岛上的，埋藏着黑暗泰坦萨格拉斯遗骸的地牢。"
D.Strings[117024]="重新获得力量和自由的伊利丹急于证明自己的价值。然而他碰上了基尔加丹，这个恶魔向他提出了一个难以抗拒的提议。基尔加丹对阿克蒙德在海加尔山的失败非常恼火，不过他还有比复仇更重要的事情要做。"
D.Strings[117025]="在觉察到自己的杰作巫妖王变得过于强大而难以控制之后，基尔加丹命令伊利丹去终结耐奥祖，并永远消灭天灾军团的力量。作为交易的条件，伊利丹将会得到巨大的力量并在燃烧军团的领导者中占有一席之地。"
D.Strings[117026]="伊利丹同意了这个计划，并立刻开始准备摧毁囚禁着巫妖王灵魂的冰晶块：冰封王座。伊利丹知道他需要一件强大的神器来摧毁冰封王座，于是他准备用从古尔丹的记忆中得到的知识去寻找萨格拉斯之墓并得到黑暗泰坦的遗物。"
D.Strings[117027]="他将那些蛇一般的纳迦从黑暗的深海巢穴中召唤出来。在狡猾的首领瓦辛的带领下，纳迦帮助伊利丹寻找传说中萨格拉斯之墓所在的破碎岛屿。"
D.Strings[117028]="在伊利丹和纳迦出发的同时，典狱官玛维·影歌也开始了对他的追捕。玛维在这一万年里一直担任伊利丹的看守，她相信自己可以重新抓获伊利丹。然而，狡猾的伊利丹让玛维和哨兵们的努力化为泡影，?|成功窃取了萨格拉斯之眼。伊利丹带着这个强大的神器来到魔法之城达拉然。"
D.Strings[117029]="城市里的能量装置强化了伊利丹的力量，他开始使用萨格拉斯之眼施展一个毁灭性的法术来对付位于遥远的诺森德大陆上的巫妖王的寒冰皇冠城堡。伊利丹的法术粉碎了巫妖王的防御力量并割裂了世界之脊。在最后的时刻，这个毁灭性的咒语被赶来支援玛维的玛法里奥和女祭司泰兰德所阻止。"
D.Strings[117030]="伊利丹很清楚，基尔加丹绝对不会对他的失败善罢甘休，便逃向荒凉的外域，这里是德拉诺的残留地域，曾经是兽人的家园。伊利丹决定在这里避避风头并计划他的下一步行动。"
D.Strings[117031]="在成功地阻止了伊利丹之后，玛法里奥和泰兰德回到梣谷的家园去照顾他们的人民。然而玛维并不打算善罢甘休，她尾随伊利丹来到外域，下决心要把他带回去接受审判。"
D.Strings[117032]="此时，天灾军团已将洛丹伦和奎尔萨拉斯彻底变成了充满剧毒的瘟疫之地。那里只有一些小规模的联盟抵抗力量仍在苟延残喘。其中的一个组织主要由高等精灵组成，他们的领导者是逐日者王朝的最后一个成员，凯尔萨斯王子。"
D.Strings[117033]="作为一名出色的法师，凯尔小心翼翼地在几近覆灭的联盟中成长。高等精灵对家园的沦陷非常悲痛，为了向死去的同胞表示敬意，他们改称自己为血精灵。当血精灵奋力遏制天灾军团的攻势时，他们因为离开了太阳之井这个力量的源泉而备受煎熬。"
D.Strings[117034]="为了缓解手下们与生俱来的对于魔法的饥渴，凯尔做了件令人无法想像的事情：他接受了他们的高等精灵祖先伸出的援手，怀着找到一个新的魔法力量之源的希望加入了伊利丹和他的纳迦部队。残余的联盟领袖谴责血精灵为叛徒，并将他们永远驱逐。"
D.Strings[117035]="走投无路之下，凯尔和他的血精灵们只得跟随伊利丹来到外域，并帮助他对付典狱官玛翼夫。玛翼夫本已将伊利丹抓获，却被血精灵和纳迦联手击败，伊利丹也被重新解放。伊利丹将外域作为自己的基地，为了向巫妖王和他的寒冰皇冠要塞发起新一轮的进攻而聚集着力量。"
D.Strings[117036]="巫妖王耐奥祖知道自己已经时日不多了。被囚禁在冰封王座之中的他怀疑基尔加丹会派出手下来毁灭自己，伊利丹的咒语造成的伤害破坏了冰封王座，巫妖王的力量因而一天天地丧失。于是，急于自保的耐奥祖将他最强大的手下——死亡骑士阿尔萨斯召唤到身边。"
D.Strings[117037]="阿尔萨斯的力量随着巫妖王的虚弱而渐渐流失，他陷入了洛丹伦的一场内战中。女妖希尔瓦娜斯·风行者领导着半数的亡灵军团发动了一场试图颠覆阿尔萨斯统治的政变。正当战斗扩散到整个瘟疫之地时，阿尔萨斯被巫妖王所召唤，领导权被移交给了他的副官克尔苏加德。"
D.Strings[117038]="最终  希尔瓦娜斯和她的亡灵叛军（他们被称作被遗忘者）将洛丹伦都城的废墟占为己有。被遗忘者在都城的残骸下建立起了自己的基地，他们发誓要击败天灾并将克尔苏加德和他的仆从赶出大陆。"
D.Strings[117039]="力量遭到削弱的阿尔萨斯仍决定去援救他的主人。他到达诺森德后却发现伊利丹的血精灵和纳迦已经先他一步到了那里。于是，阿尔萨斯和他的蜘蛛怪只得与伊利丹的部队争夺时间，他要率先到达寒冰皇冠冰川并保护冰封王座。"
D.Strings[117040]="即便是在如此虚弱的情况下，阿尔萨斯最终仍以策略战胜了伊利丹，并率先抵达了冰封王座。阿尔萨斯用他的魔剑霜之哀伤击碎了囚禁巫妖王的冰牢，并得到了耐奥祖附魂的头盔和胸甲。"
D.Strings[117041]="阿萨斯将拥有无尽力量的头盔戴到了自己的头上，成为了新的巫妖王。正如耐奥祖一直计划的那样，他和阿萨斯的灵魂合体成为一个强大的生物。伊利丹和他的军队被迫耻辱地逃回外域，阿萨斯则成了这个世界上最强大的生物之一。"
D.Strings[117042]="现在的阿尔萨斯作为新的不朽的巫妖王占据着诺森德，据说他正在那里重建寒冰皇冠城堡，而他所信任的副官克尔苏加德则统领着瘟疫之地的天灾部队。希瓦娜斯和她的反叛亡灵力量仅仅控制着提瑞斯法林地，那只是被饱经战乱的洛丹伦王国的一小部分。"
D.Strings[117043]="尽管获得了战争的胜利，但艾泽拉斯的各个种族却发现他们的世界早已被战争所摧毁。天灾军团和燃烧军团毁灭了洛丹伦的文明，卡利姆多也几乎遭受同样的命运。这里有饱经创伤的森林需要治愈，有无边的仇恨需要忘却，人民需要新的家园来定居。战争重创了每一个种族，但他们无私地合作，想要创造一个新的开端。这一切都从联盟和部落之间极为来之不易的停战开始。"
D.Strings[117044]="萨尔领导着兽人来到卡利姆多大陆，他们在牛头人同胞的帮助下建立了一个新的家园。兽人们以萨尔被暗杀的父亲的名字将这新的国家命名为杜隆坦，他们定居下来，并试图重建他们那一度辉煌的文明。"
D.Strings[117045]="现在恶魔的诅咒被终结了，部落从一股好战的狂热力量变为了一个松散的联盟，生存与繁荣是他们的首要任务。在高贵的牛头人和狡猾的暗矛部落食人妖的帮助下，萨尔和他的兽人们期盼着一个和平的新纪元的到来。"
D.Strings[117046]="珍娜·普劳德摩尔手下残存的联盟力量定居在南卡利姆多。他们在东海岸的尘泥沼泽附近建立了简陋的港口城市塞拉摩。人类和矮人同盟合力在这片充满危险的土地上生存，尽管杜隆坦和塞拉摩的防御力量彼此暂时停战，但这个脆弱的殖民地的平静并不意味着最终的和平。"
D.Strings[117047]="人类和兽人间的和平被一支抵达卡利姆多的庞大联盟舰队所破坏。海军上将戴林·普劳德摩尔（珍娜的父亲）率领这支舰队在阿尔塞斯毁灭洛丹伦之前离开了那里。海上数月的航行令人筋疲力尽，但是普劳德摩尔仍然寻找着一切他可以找到的联盟幸存者。"
D.Strings[117048]="海军上将普劳德摩尔的舰队对该地区的稳定造成了严重的威胁。作为一位在第二次战争中声名显赫的英雄，珍娜的父亲是部落的死敌，他决心在兽人站稳脚跟之前摧毁杜隆坦。"
D.Strings[117049]="普劳德摩尔强迫珍娜做出一个艰难的抉择：支持他对抗兽人并且背叛她的新同盟，或者与她的亲生父亲交战来维护联盟和部落之间来之不易的脆弱和平。在一番思想斗争之后，珍娜选择了后者，她帮助萨尔打败了她疯狂的父亲。"
D.Strings[117050]="不幸地是，海军上将在珍娜向他证明兽人已经不再是嗜血的怪物并与他和解之前就战死了。出于珍娜对部落的忠诚情义，兽人们同意让她的部队安全地回到塞拉摩的家园。"
D.Strings[117051]="阿雷拉斯·火叶血色十字军的高级巫师$B 奎尔萨拉斯的公民$B 在与死灵法师迪萨文的战斗中陨落"
D.Strings[117052]="海军上将巴厘·韦斯温$B 血色十字军舰队指挥官$B 库尔提拉斯的公民$B 失踪于诺森德的冰封海岸"
D.Strings[117053]="费伦·玛库斯血色修道院的高阶修士 $B 斯坦索姆的市民$B 在第一次血色修道院防御战中牺牲"
D.Strings[117054]="霍利亚$B 血色十字军的保卫者$B 在刺杀恐惧魔王贝塞利斯时牺牲"
D.Strings[117055]="独臂因瓦尔$B 血色十字军的首席刺客$B 达拉然的公民$B 失踪于诺森德海岸"
D.Strings[117056]="激流堡的奥玛尔$B 血色十字军的首任将领$B 激流堡的公民$B 失踪于冰冠冰川"
D.Strings[117057]="亚娜·血矛$B 血色十字军的第二刺客 $B 达拉然的公民$B 失踪于提瑞斯法林地"
D.Strings[117058]="大约16,000年以前（远早于夜精灵愚蠢地召来燃烧军团的年代），食人妖主宰了卡利姆多大陆（那个时候只有一块大陆）的大部分区域。那个时候有两个食人妖帝国并存，即东南部森林中的古拉巴什帝国，以及中部的阿曼尼帝国。"
D.Strings[117059]="在北部有些小的部族（位于现在的诺森德地区），这些部族建立了一个叫做祖尔德拉克的小国家，但是其规模和繁荣程度从来没有达到过南方这两个帝国的程度。"
D.Strings[117060]="古拉巴什帝国和阿曼尼帝国之间并不十分友好，但是也不常交战。那个时候，他们共同的敌人是一个异族的帝国——阿兹亚基文明。亚基是一种有智慧的昆虫生物，它们主要统治着西部地区。这些聪明的虫族生物具有强烈的扩张欲望，并且非常邪恶。亚基虫类的目标就是消灭卡利姆多大陆上所有的非昆虫生物。"
D.Strings[117061]="食人妖与它们进行了数千年的战争，但是从来没有对亚基虫类获得压倒性的优势。最终，由于食人妖的不断攻击，亚基帝国一分为二，它的臣民逃散到大陆北部和南部偏远地区的聚居地去苟延残喘。"
D.Strings[117062]="两个大的亚基虫类城市出现了。它们在北部的荒地中建立了埃卓-尼拉布，在南部沙漠中建立了安其拉。虽然食人妖们认为在卡利姆多大陆的地下还有其他亚基虫类的聚居地存在，但是这个观点没有被证实过。"
D.Strings[117063]="随着虫类生物被赶走，两个食人妖帝国又恢复了原来的状态。虽然他们获得了伟大的胜利，但是两个帝国都没有大举扩张。然而，我们可以从古文记录中得知，有一小部分食人妖从阿曼尼帝国脱离，在这块黑暗大陆的中心建立了自己的殖民地。"
D.Strings[117064]="在那里，勇敢的先行者们发现了汹涌的永恒之井，并从中获得了无穷的力量。据说这些食人妖就是后来的夜精灵，不过这个理论从来都没有被证实过。"
D.Strings[117065]="即便不考虑夜精灵真正的起源，但他们确实在发现了永恒之井后力量大增。食人妖并没有去努力地扩张他们的领地，而夜精灵却创建了一个强大的帝国，并且迅速在卡利姆多大陆上扩张。他们使用的魔法是那些迷信的食人妖从来都没有想像过的，因此，夜精灵轻松地完成了邪恶的亚基虫类无法做到的事情——将两个最伟大的帝国从世界上彻底抹掉了。"
D.Strings[117066]="夜精灵系统性地瓦解了食人妖的防御和攻击力量。食人妖无法对抗夜精灵毁灭性的魔法，所以只有坐以待毙。夜精灵在这段时间里体现出了和那些野蛮的食人妖一样的狡猾和嗜血——这使得后来的种族对他们非常仇恨和轻蔑。古拉巴什和阿曼尼帝国在之后的数年内便分裂为数个小国家。"
D.Strings[117067]="最终，夜精灵被他们所试图控制的魔法之火吞噬。他们对于魔法无节制的使用召来了燃烧军团。恶魔摧毁了大部分的夜精灵文明。虽然没有资料表明燃烧军团也攻击了食人妖文明，但是几乎整个大陆都陷入了战争。"
D.Strings[117068]="在这场恐怖的战争（上古战争）的最后，永恒之井爆炸了。爆炸产生的震荡波撕裂了卡利姆多大陆。大陆的中心沉入海底，只留下一些破碎零落的陆地。"
D.Strings[117069]="阿曼尼帝国和古拉巴什帝国的残余势力分别驻留于现在的奎尔萨拉斯和荆棘谷。阿兹亚其帝国的埃卓-尼拉布和安其拉城也幸存了下来，它们位于现在的诺森德和塔纳利斯。$B$B 两个食人妖文明在原始世界毁灭之后都衰落了。不屈不挠的食人妖们重建了他们被蹂躏的城市，并着手回复昔日的辉煌。"
D.Strings[117070]="大灾变之后的好几个世纪，食人妖一族都在极端艰难的环境中度过。饥荒和恐怖对于破碎的帝国来说只是家常便饭，孤注一掷的古拉巴什食人妖寻求远古神秘力量的帮助。虽然两个食人妖帝国都信奉着共同的远古诸神，但是古拉巴什却被最黑暗的神灵支配了。"
D.Strings[117071]="灵魂掠夺者哈卡——这个卑鄙嗜血的神灵——在听到食人妖的召唤后决定帮助他们。哈卡将他的血赐予古拉巴什，并帮助他们将领土扩张到荆棘谷的大部分地区，以及南海的一些群岛。虽然他给古拉巴什帝国带来了巨大的力量，但是哈卡希望得到的回报也越来越多。"
D.Strings[117072]="这个残忍的神要求每天都用灵魂为他祭祀。他梦想通过这样来到真实世界，这样他就可以吸食所有生灵的血。古拉巴什慢慢地认识到了他们曾殷勤供奉的这个神的真正面目，并奋起与之抗争。最强大的部族纷纷起义，抵抗哈卡和他忠实的牧师——阿塔莱。"
D.Strings[117073]="在哈卡的追随者与古拉巴什部族间发生的恐怖战争只在呢喃细语中流传。刚刚开始振兴的帝国被愤怒的邪神和他叛乱的子民所释放的魔法粉碎。正当这场战斗即将以哈卡获胜而结束的时候，食人妖们摧毁了哈卡的化身，将其从物质世界流放。"
D.Strings[117074]="甚至连那些阿塔莱祭司都被赶离首都祖尔格拉布，被迫在一处连地图上都未标明的北部沼泽地区中苟且偷生。在这些阴暗的沼泽中，他们为哈卡神建造了一座大神庙——阿塔哈卡神庙，并继续在那里为他们的主人工作着……"
D.Strings[117075]="这里长眠着葛罗姆·地狱吼，战歌氏族的酋长$B$B 我们人民被诅咒的开始和结束都与葛罗姆息息相关。$B 他的名字在我们的古语中意味着“巨人之心”，他名副其实$B 他如铁塔一般矗立在恶魔玛诺洛斯面前 $B ——以他的鲜血为我们赢得了自由。$B$B 向你致意，我的兄长。愿战歌永不消逝。$B$B ——索尔，部落的酋长"
D.Strings[117076]="啊，我受到了诅咒!我曾经是尖石氏族中的一个伟大的巨魔法师，我向乌洛克发起了挑战，他偷走了我的魔法，而且还诅咒了我。现在，我只能以这种可笑的样子在这里游荡!$B$B帮帮我!找到乌洛克，偷回我的魔法!这不是一件简单的事情，因为乌洛克会藏在暗处，你只有通过了一个极其困难的挑战才能将其召唤出来。$B$B这个挑战就是面对乌洛克的亲信，欧莫克大王。$B$B继续读下去，你会了解更多细节的。"
D.Strings[117077]="欧莫克大王统治着尖石部族，但是没有乌洛克的魔法，他是做不到这一点的。乌洛克给欧莫克施加了特殊的魔法，让他可以打死任何胆敢挑战他的巨魔。他多次使用过那个法术，并且把那些受害者的头骨堆在一起，放在欧莫克的房间顶部的一块地方。$B$B那里就是你要挑战乌洛克的地方。"
D.Strings[117078]="到裂盾营地去找到一支尖锐的长矛。他们经常把这些长矛堆积在靠近尖石巨魔领地入口的地方，和那些日常用品堆在一起。$B$B当你拿到长矛之后，杀到欧莫克大王那里，干掉他，把他的头颅挂在长矛上。$B$B然后就准备面对真正的挑战吧。"
D.Strings[117079]="到尖石巨魔营地上方那个充满能量的地方去，就在隧道的旁边。那里堆积着曾经挑战过乌洛克的巨魔的骸骨。你要在那里插上挂着欧莫克头颅的长矛!$B$B当你把头颅安放就位之后，乌洛克必定会到来……但是，首先他会派他的爪牙来对付你。打败他们，然后乌洛克就会现身了。$B$B杀了他，然后拿回我的魔法。当我夺回我的力量时，你也会得到奖励的。"
D.Strings[117080]="你很幸运，我有一条线索也许可以帮助你对付乌洛克的爪牙：$B$B这个法术是欧莫克用于对付巨魔的，它能一击杀死他们，即使你杀掉了欧莫克，它也能继续发挥功效。在你和乌洛克的爪牙作战时，使用欧莫克的脑袋中蕴含着的力量——如果运气好的话，欧莫克会击倒乌洛克的爪牙!$B$B这可真具有讽刺性。"
D.Strings[117081]="纪念我永远深爱着的杰茜·莫拉雷斯"
D.Strings[117082]="A：$b$b我们必须不惜一切代价地保持计划的秘密性！如果其他的牛头人部族知道我们之间的联系的话，那后果将会是灾难性的。$b$b- E"
D.Strings[117083]="攻击者……来自各个方向。$B$B木喉部族是邪恶的。敌人。$B$B必须保护冬泉部族。必须把入侵者赶出我们的土地。"
D.Strings[117084]="纳塔卡，千针石林一切安好。半人马的麻烦还没有解决……它们有时候会发起攻击，但是目前还没有形成真正的威胁。然而，似乎有消息说半人马氏族正在集结。$B$B我们总是会认真考虑那些团结在一起的残忍氏族，比如半人马……我尝试着不去过多考虑这些问题，正如你所知的那样……没有什么东西可以消解它们心中那纯粹的憎恨……即使对于它们的同胞，那种憎恨也是非常强烈的。$B$B- 峭壁卫兵图林·长角"
D.Strings[117085]="大主教阿隆索斯·法奥$B$B 光明大教堂的慈善资助者之一。$B$B 虽然阿隆索斯是在洛丹伦的斯坦索姆开始担任神职，但他一直是暴风城人民的伟大的朋友。在第二次兽人战争结束之后的黑暗日子中，他帮助重组了北郡兄弟会，并筹集了大量资金以供重建暴风城。$B$B 这座大教堂不仅是圣光信仰的象征，也是对他高贵精神和慷慨的纪念。"
D.Strings[117086]="乌瑞恩家族的莱恩国王$B$B暴风城的国王$B$B艾泽拉斯的守卫者"
D.Strings[117087]="联盟舰队指挥官$B$B暴风城的朋友"
D.Strings[117088]="在记忆之年代前，温柔的大地之母呼出金色的黎明之雾。当琥珀色的云朵沉降之後，大地上到处都是长满燕麦和大麦的田地。这是她工作的基础─孕育着生命和希望的摇篮。"
D.Strings[117089]="大地之母的眼睛，注视着她用呼吸创造的世界。她的右眼，安希(太阳)，给予这片土地温暖和光明。她的左眼，姆莎(月亮)，给予那些躁动不安的生物以和平与睡眠。这就是双眼的力量，每隔半天，大地之母就会闭起一只眼睛。就这样，她为这个初生的世界不断进行着日夜的更替。"
D.Strings[117090]="当大地之母的右眼扫过金色的黎明时，她轻柔的手就开始在肥沃的原野上拂动。她的手臂拂过的地方就有高贵的人从土地中出现。舒哈鲁(牛头人)为此向他们挚爱的母亲表示感谢。在充满黎明之光的广袤平原上，大地之母的孩子为她的优雅而祈祷，并发誓永远称颂她的名字，直到世界坠入永恒黑暗的那一天。"
D.Strings[117091]="随着大地的孩在黎明平原上行走，他们听到了来自大地中心的黑暗低语。 它向那些孩子灌输征伐的思想和欺骗别人的方法。许多舒哈鲁因此堕入黑暗，并开始变得邪恶。他们抛弃了自己的兄弟，无知地穿行在原野上。"
D.Strings[117092]="大地之母的心，因为孩子们的堕落而变得沉重，她已经无法再眼睁睁地看着他们变得堕落。在悲伤之中，她摘下了自己的双眼，将它们放在星空中任其飞翔，安希和姆莎为了抚平彼此的悲伤，只能横穿天空而互相追逐。随着时光的流逝，这两个双胞胎永远互相追逐着。"
D.Strings[117093]="虽然已经无法视物，但大地之母不会远离心灵的世界。她用她的耳朵聆听风声，聆听一切穿越黎明平原的东西。她伟大的心还是和她的孩子在一起，她爱的智慧永远不会离弃他们。"
D.Strings[117094]="大地之母不仅把勇敢的心赋予她的孩子们，她还将热爱狩猎的精神赐予他们。第一黎明纪元中诞生的生物是野蛮而又狂暴的，它们躲避着大地之母，在阴暗的野外寻找自己的栖身之地。舒哈鲁狩猎这些野兽，并以大地之母的祝福来驯化它们。"
D.Strings[117095]="然而，一个强大的灵魂却一直在躲避着他们。英勇的雄鹿阿帕罗(被夜精灵称为玛洛恩)长着白色的皮毛，它的鹿角划破天穹，它强有力的蹄子踏破世界的深渊。舒哈鲁猎捕阿帕罗，直到黎明世界的角落，并撒网捕捉那头骄傲的雄鹿。"
D.Strings[117096]="为了逃脱，伟大的雄鹿跃向空中。他的逃脱本应非常顺利，但是他的鹿角却挂住了天上的星星。虽然他不断蹬踢挣扎，但是阿帕罗却无法从天堂中挣脱。此时正在追逐安希的姆莎发现了他，她看到万能的雄鹿在奋力挣扎，并对他一见锺情。"
D.Strings[117097]="随着时间的流逝，塞纳留斯长成了和他父亲一样伟岸的生物。他成为了星辰和森林的兄弟，这个伟大的猎手徘徊在世界的远端，吟唱着黎明的和谐歌声。所有的生物都在他的优雅和美丽面前弯腰——没有什么能比月亮和白色雄鹿的儿子更加完美。"
D.Strings[117098]="渐渐的，塞纳留斯成了舒哈鲁的朋友，与他们讨论如何改造世界。大地的孩子们把他当作自己的兄弟，并且发誓要帮助他看护生命的田野以及大地之母所热爱的一切。"
D.Strings[117099]="随着黎明薄雾的消散以及岁月的流逝，半神塞纳留斯自行进入了世界的田野中。舒哈鲁(牛头人)对於他的离去感到无比悲伤，并忘却了他教给他们的德鲁伊之道。一代又一代，他们渐渐地忘却了如何与树木以及这块土地上的生灵进行交流。地底深处的黑暗低语再次出现在他们的耳边。"
D.Strings[117100]="虽然大地的孩子对於邪恶的密语不再听从，但是一个邪恶的诅咒降落在他们游荡的部族头上。在黑色土地的西边有一群凶恶的生物─半人马。残忍而野蛮的半人马如瘟疫一般蜂拥而至，虽然舒哈鲁在大地之母的祝福下勇敢地战斗，但是他们无法打败半人马。"
D.Strings[117101]="达隆郡的历史$B$B 达隆郡是一座位于罗德隆南部山脉中的村庄，这个名字来源于其西面的达隆米尔湖。镇中的居民朴实而又勤劳，达隆郡在罗德隆历史上一直都是默默无闻的，直到第二次恶魔战争的开始。$B$B 在战斗期间，无数英雄从这里诞生，无数英雄在这里陨落。"
D.Strings[117102]="达隆郡的战斗$B$B 达隆郡的战斗发生在第二次恶魔战争的中期。那时，天谴军团的力量在罗德隆的土地上横行肆虐，达隆郡与联盟主力部队的联系被切断，但是镇中有一支驻军，包括一队白银之手的圣骑士，以及由约瑟夫·雷德帕斯所领导的当地民兵。"
D.Strings[117103]="天灾军团的第一次攻击仅仅是试探性的。小队的骷髅和僵尸在小镇周边徘徊，并被很轻易地击败了。 $B$B 但是防御部队的坚韧并没有让亡灵退却，它们继续疯狂地进行攻击，一波接一波的亡灵部队接踵而来，与达隆郡的防御者激烈交战。"
D.Strings[117104]="防守部队的力量被不断削弱，但是白银之手骑士团不断支援他们。骑士团的领袖达维·克罗弗德是达隆郡的当地人，他在得知小镇即将遭到攻击时带领他的追随者来到了镇中，与卫队合力抵抗霍古斯的部队。$B$B 当霍古斯自己也加入战斗之后，他与达维正面交锋了。他们的战斗持续了很久，最终达维获胜，但是他受了重伤，在击败食尸鬼之王后不久死去了。"
D.Strings[117105]="战斗继续着，雷德帕斯队长率领民兵英勇奋战。如果不是队长被死亡骑士玛杜克的黑暗魔法控制的话，这场战斗有可能获胜的。$B$B 在战斗中，玛杜克骑马来到雷德帕斯面前，他使用黑暗魔法撕碎了雷德帕斯的意志，将他的灵魂扭曲成了一个邪恶的阴影。"
D.Strings[117106]="堕落的雷德帕斯队长将他的邪恶力量传播给达隆郡的守军，那些被感染的士兵立刻背叛了他们的同胞，并开始屠杀他们。最后他们转向达隆郡里，屠杀了那些躲在家中的民众。$B$B 剩余的亡灵部队和堕落的雷德帕斯队长离开了已成废墟的达隆郡，投入了洛丹伦的战场。"
D.Strings[117107]="掠夺者霍古斯的命运$B$B 掠夺者霍古斯在达隆郡之战中阵亡。但是他身上的邪恶气息仍然存在。获胜的天灾军团将他的头颅从达隆郡的废墟中带走，用其在仍然活着的生灵中散播恐惧的气氛。$B$B 几天之后，这群拿着头颅的天灾军团士兵被白银之手骑士团击溃，霍古斯的头颅也被扔入了黑木湖中。"
D.Strings[117108]="黑衣玛杜克的命运$B$B 玛杜克在第二次恶魔战争中活了下来，其邪恶的符文长剑造成了无数死亡和痛苦。虽然玛杜克还活着，但是他的剑已经在考林的十字路口的那次会战中遗失了。一个矮人中尉用他的盾牌震落了那把剑，并迫使玛杜克仓惶逃跑。$B$B 玛杜克的剑慢慢陷入入大地中，并开始腐蚀周围的土地，渐渐地形成了一座峡谷，就是今天的魔刃之痕。"
D.Strings[117109]="达维·莱法尔的命运$B$B 达维·莱法尔在达隆郡之战中阵亡，但是他的英勇事迹鼓舞了战场上的每个联盟士兵。$B$B 他的圣骑士宝典被血色十字军所保管，现在被存放在血色十字军控制的壁炉谷中，经常被那些崇敬他的十字军成员争相阅读。"
D.Strings[117110]="约瑟夫·雷德帕斯的命运$B$B 约瑟夫·雷德帕斯在达隆郡一战中阵亡。他的灵魂已经堕落，被扭曲成了另一个模样，这个新的亡灵在罗德隆散播着更多的邪恶。$B$B 在安多哈尔东部的盖罗恩农场，堕落的雷德帕斯最终被联盟部队击败。他的盾牌依然留在那座被瘟疫感染的农场谷仓旁边，天谴军团也不断向那个邪恶的地方聚集。"
D.Strings[117111]="卡林·雷德帕斯的命运$B$B 约瑟夫·雷德帕斯队长的兄弟，卡林·雷德帕斯在达隆郡的战斗中倒下了，他身负重伤，但是最终侥幸活了下来。$B$B 在大战过后的几天，银色黎明组织发现了奄奄一息的卡林·雷德帕斯，他又渴又累，而且还发着烧，倒在了考林的十字路口附近。他们治疗了他的伤势，并把他带到了圣光之愿礼拜堂。$B$B 由于对银色黎明的感激之情，卡林·雷德帕斯加入了银色黎明，并为了复仇而与天灾军团展开战斗。"
D.Strings[117112]="雪，刺眼……$B$B必须保护部族。让他们变得强壮。强壮。$B$B不知道……"
D.Strings[117113]="火酒。$B$B更多。制作更多火酒。$B$B火酒让冬泉部族更加强壮。打败敌人。$B$B冬泉部族没有盟友。冬泉部族非常强壮。拥有无穷的力量。"
D.Strings[117114]="更多的。必须要更多的……$B$B冬泉部族……不能……变弱……"
D.Strings[117115]="记录日期：未知$B$B 姓名：纳萨诺斯·玛瑞斯，人类游侠，洛丹伦的贵族。$B$B 记录：$B$B 凯尔萨斯·逐日者不同意纳萨诺斯·玛瑞斯进入组织。另外，纳萨诺斯是我遇到过的最具天赋的游侠，虽然他是个人类，但是我非常乐意训练他。$B$B （未完）"
D.Strings[117116]="我这些年来一直在从事这个行业，现在我第一次感觉如此自豪。对于刺客、间谍和密探的需求从来都没有如此强烈过。也许你认为战争期间会对这方面的人员有更大的需要，但事实上，战争并不很需要我们这样的人——只有在和平年代才会是我们大展身手的舞台。$B$B我听说你来到了这一区域，如果你有时间的话，就到教堂后的马厩旁边来找我。$B$B- 乔里克·克里丹，潜行者训练师"
D.Strings[117117]="我打赌你原以为这是一封由你的国王或者别的什么人书写的信件。好吧，我承认我对伪造信件略知一二，我只是希望你能收到这封信而已。现在你对我已经有所认识了，对吗？$B$B我在安威玛里面的壁炉旁边等着你。等你准备好了，就来找我说话吧。我只是想跟你互相认识一下。$B$B- 索姆·哈格林，潜行者训练师"
D.Strings[117118]="你好，$N。写这封信的时候，我陷入了沉思。$B$B我们中的许多人都认为萨满是我们的精神领袖，就好像我们的酋长一样。其他人会认为剑和斧才是更加高贵的追求，但是不要忘了战斗——甚至是战争——是要靠那些有一技之长的人获胜的。这就是我想要和你说的，$N。到试炼谷里的大兽穴来找我吧。$B$B- 鲁瓦格，潜行者训练师"
D.Strings[117119]="我的$g兄弟:姐妹;，希望这块符石能够安全地送到你手中。我费尽心机让这件事情看起来不是那么明显，你可能甚至都没有发现自己的背包中有这么一封信。看来我的计划不错，不是吗？$B$B我想要你知道，我在寒脊山谷的安威玛尔等你。我很清楚大家团结在一起的重要性，特别在眼下的紧张时期，我们更应该在一起。当你有时间的时候就来找我吧。$B$B- 索姆·哈格林，潜行者训练师"
D.Strings[117120]="记住我的话，$N。现在是一个到处都充满藉口和欺骗的时代……即使我们伟大的幽暗城也是一样。每个忠诚于希瓦娜斯的人都在为了开创一个新的时代而努力，一个由被遗忘者控制的时代。虽然我们不具有魔法技能，也不会拿起武器保卫边疆，但是这世上依然有许多事情只有我们才能做。$B$B到丧钟镇的旅店里来找我吧，我会和你讨论更多问题的。$B$B- 大卫·提亚斯，盗贼训练师"
D.Strings[117121]="你好，我的朋友。希望这个符记可以顺利地送到你手里。上级要求我为你服务，我眼下也在幽影谷里——就在泰达希尔的树顶，如果你需要接受训练，就来找我吧。$B$B在这个危险的时期，我希望我们之间保持秘密的联系，不然我们还能如何保护泰达希尔和我们的行规？$B$B你有空的时候就来找我吧。$B$B- 弗拉胡恩·影语者，潜行者训练师"
D.Strings[117122]="你好，我的$g兄弟:姐妹;。碎手氏族向你致意，并希望你在山谷中找到一个合适的接头人。现在是对你进行考验的时候了，所以，别以为没有人监视你。$B$B我的职责是代表碎手评估你的技能，然后告诉他们你是否已经准备接受更大的挑战了。$B$B当你准备好了之后，就到大兽穴最深处来找我，我会在那里等你的。$B$B- 鲁瓦格，潜行者训练师"
D.Strings[117123]="告诉我，$c，你有没有听过兽人的咆哮？也许你曾参与在家乡抵御过豺狼人的袭击，差点就被那些家伙撕破了喉咙？啊，这些听上去都很可怕，不是吗？$B$B好吧，如果你想要保护自己所热爱的东西，那你就需要我的帮助，到北郡的修道院里来找我吧。我的知识并非免费传授给你的，不过如果你拥有足够的阅历，那我就能教给你很多东西，帮助你与威胁着暴风城的邪恶势力作战。$B$B- 莱尼·拜舍尔，战士训练师"
D.Strings[117124]="注意：$B你必须立即向斯兰·库尔曼报到。他在A3区中，也就是当地居民所说的安威玛尔那里。在与库尔曼接头之后，你要着手准备参加即将来临的战斗——夺回我们的家园诺莫瑞根！$B$B我们所有的努力都是为了这个最终的目的。在完成此任务之后，新的任务会很快下达给你。"
D.Strings[117125]="许多部族认为使用魔法或者与我们的先祖对话的能力都是不可多得的天赋，但是你应该知道，$c，你也同样具有其他人不具备的天赋。有些人没有足够的力量来挥舞强大的武器，有些人没有躲避刺客致命一击的能力，或者无法承受一个法师所带来的伤害，但是你可以。你非常强壮，我会帮助你变得更加强壮。到纳拉其营地来找我吧。$B$B- 哈鲁特·雷角，战士训练师"
D.Strings[117126]="以玛格尼胡须的名义，我们有很多东西要谈，但是时间有些紧迫，$N。尽快到寒脊山脚下的的安威玛尔来找我，我们要马上开始。$B$B我可以告诉你一大堆事情，但是那些对我们都没有用……特别是对现在的我们来说。我们当前需要关注的东西很简单：如何抓紧一把斧子，我们护甲的重量，以及我们在战斗时所流的汗滴的味道。我们就从这些开始吧。$B$B- 斯兰·库尔曼，战士训练师"
D.Strings[117127]="我们的许多族人希望靠着秘法和神圣系的法术变得更加强大，但是我们知道有更好的方法，不是吗，$c？强大的武器是我们的圣印，坚固的盾牌是我们的法术书，致密的炼甲是我们的智慧。$B$B虽然我们已经变成了亡灵，但我们仍然很强大，而且我们会变得更加强大。$B$B到丧钟镇的旅店里来找我，我会和你谈谈更多与这有关的事情。$B$B- 丹纳尔·斯特恩，战士训练师"
D.Strings[117128]="我希望我的符印可以顺利地送到你的手上，$c。我之所以写信给你，是因为我们的人民需要那些擅长使用刀剑、月刃以及其它武器的战士。自从我们重新和艾泽拉斯的其他种族展开接触之后，我们身边发生了许多事情，我们也更加需要强大的卫士。$B$B这就是我写信给你的原因。我会告诉你更多相关的信息，但是我希望能与你进行面对面的交流。到泰达希尔的底层来找我吧。 $B$B- 奥莉希亚，战士训练师"
D.Strings[117129]="魔法四准则：$B$B   魔法是强大的。$B$B   魔法使人堕落。$B   魔法让人欲罢不能。$B   魔法会将那些扭曲虚空中的生物引至掌握魔法的人身边。$B$B这些规则总是成立的。如果你选择成为一名法师的话，这些规则会永远跟随着你。$B$B如果你愚蠢到忽视这些警告，那么就到北郡修道院的图书馆里来找我吧，我会在楼上等你的。$B$B- 凯尔登·布雷门，法师训练师"
D.Strings[117130]="孩子，你终于觉醒。在足够强大之后，你就可以掌握魔法的秘密了。 $B$B准备好了之后就去找迈安吧，她会教你使用各种魔法，摧毁那些胆敢反对你的人。$B$B迈安在试炼谷的大兽穴中。去那里找到她，然后你就能变得更加强大。向其他法师展示魔法是如何按照你的意志行事吧。"
D.Strings[117131]="人们——尤其是那些圣光的追随者们——经常会恐吓寻求真正力量的人，反复强调魔法的邪恶和可怕，但并不是所有本不属于这个世界的东西都是邪恶的，并不是所有的生物都想要主宰或听命于他人。如果你真的足够强大的话，他们会变成你的追随者。$B$B我希望能和你讨论更多的事情，到修道院右边的墓地里找我吧。$B$B- 杜希拉·拉萨雷，术士训练师"
D.Strings[117132]="注意：$B$B保持安静!不要四处张望!也许有人正在盯着你。$B$B我的名字叫做阿拉玛尔·格里姆，$N。我可以训练那些追寻真正的知识和力量的人。 上级授意我与你进行秘密的联系，然后向你传授真正的魔法。$B$B如果可以的话，就到安威玛的后方来找我。$B$B- 阿拉玛尔·格里姆，术士训练师"
D.Strings[117133]="我用我创造出的最强大的墨水来撰写这封信，$N。它会诅咒除你之外任何胆敢阅读这封信的人。我就是如此的强大。我可以从扭曲虚空中召唤恶魔，我在敌人睡眠时就对他们施放了致命的诅咒，也在战场上让他们灰飞烟灭。现在你看到了我强大的力量，我的兄弟对此感到很满意。$B$B到大兽穴里面来找我吧。我会和你交流更重要的事情。$B$B- 纳托克，术士训练师"
D.Strings[117134]="你赫然发现我们正处于困境之中，是不是，$N?被愚蠢的王子所污染，被我们所挚爱的人所抛弃。我们应该感谢美丽的希瓦娜斯，但对于我们来说这又如何呢?换一个主人对于我们来说没有什么区别，我们依然是奴隶，我就是这样认为的。$B$B但如果我们自己是主人的话，情况又会是怎样的呢?没错，你知道我说的是什么。$B$B我们甚至与其他的被遗忘者之间还有隔阂，$N。这就是我们要继续谈谈的原因。到丧钟镇的教堂里来找我吧。"
D.Strings[117135]="强大的战士守护着我们的家园，睿智的萨满指引我们的灵魂，并向我们展示祖先的丰功伟绩，德鲁伊向我们传达大地母亲的意愿。$B$B但你是我们猎人中的一员，我们了解世界上的种种力量，并使其为我们所用。你会找到你存在的价值以及我们人民的意愿——我们部族中的一些成员需要你的指引和保护，我的职责就是让你做好迎接这些挑战的准备。到纳拉其营地来找我吧。$B$B- 兰卡·远箭，猎人训练师"
D.Strings[117136]="孩子，你长大了。基沙知道你正在寻求猎人之道，她已经准备教你了……如果你自己准备好了的话。$B$B到试炼谷来找我。基沙会训练你，向你展示猎人是多么的强大。$B$B- 基沙，猎人训练师"
D.Strings[117137]="驯服野兽，强大的射击技巧，缜密的追踪技能——你此生还想要达成什么样的伟绩？以上我所说的这些都需要相当的智力和耐心才能成就。$B$B猎人之道并不简单，这一点是肯定的。即便只是要达到我们最低的要求，你也需要接受大量的训练。这就是我找你的原因。$B$B到寒脊山脚下的安威玛尔来找我吧，我会等着你的。$B$B- 索加斯·格瑞姆森，猎人训练师"
D.Strings[117138]="愿艾露恩与你同在，$N。我很高兴能直接参与培养下一代猎人的工作。$B$B根据我所了解到的情况，你就在泰达希尔附近。如果你有时间的话，我会在泰达希尔树上等你的。$B$B我们的长者要求我好好训练新的猎人，使他们有能力通过即将到来的试炼。你是我的新学生之一，希望你能够来找我。祝你一路顺风。$B$B- 阿亚娜·远途，猎人训练师"
D.Strings[117139]="很高兴得知又有一个基沙的$g兄弟:姐妹;到试炼谷来检验$g他:她;的能力，基沙很高兴！$B$B我无须再告诉你猎人有多么强壮和灵活——你已经知道这一点了。基沙要告诉你的是，你还需要变得更加强壮和灵活。$B$B你可以在试炼谷里找到基沙，她会教你很多东西。她会教你如何驯服最强大的野兽，以及更多其他的东西。$B$B- 基沙，猎人训练师"
D.Strings[117140]="昨天晚上，大地的精灵进入了我的梦乡，他们告诉我你要到来的消息，而我的任务就是帮助你。我们有很多要讨论的事情——讨论自然，大地之母，甚至还有夜精灵。但是在你到来之前，我们不会讨论这些东西，我要尽我所能保证你已经为将来的试炼做好了准备。$B$B愿智慧指引着你，我会在这里等着你。$B$B- 加尔特·迷雾行者，德鲁伊训练师"
D.Strings[117141]="当我听说你已经准备好了的时候，就马上寄出了这个符记。所有塞纳留斯的德鲁伊都会因为我们的队伍越来越壮大而感到高兴的，森林之魂的力量似乎也在随之变得更加强大。只要有足够的时间和耐心，我们的力量就应该可以恢复到原来的程度。如果你准备好了，就到泰达希尔树顶来找我。在你停留在幽暗谷的这段时间里，我会不断地指引你。$B$B- 玛丹特·硬木，德鲁伊训练师"
D.Strings[117142]="你好，年轻的$c。微风已经把你要到这里来的消息告诉我了，大地也在赞扬你的强壮。现在，我们先祖的灵魂告诉我你已经到了。我们同胞们总是需要睿智而伟大的领袖，他们经常因此而寻求我们萨满的帮助。如果你愿意的话，我会向你传授更多的知识。$B$B到红云台地的纳拉其营地来找我吧——我们可以进一步谈谈。$B$B- 米拉·晨行者，萨满训练师"
D.Strings[117143]="你好，我的$g兄弟:姐妹;。元素们告诉我你正在向这里旅行，它们要我向你展示萨满之道。我们先祖的灵魂在地下看着我们，并对你加入萨满的行列感到非常欣慰。$B$B当你准备好了之后，就到大兽穴的入口处来找我吧。我在这里负责训练萨满。希望你一路顺风。$B$B- 史克里克，萨满训练师"
D.Strings[117144]="你好，我的$g兄弟:姐妹;。自然的精灵告诉我，你已经做好协助我们盟友的准备了。你和元素有很深的联系，当你开始我的课程之后，你就变得越来越强大了。$B$B现在我要要派你去见试炼谷的萨满训练师，兽人史克里克。她已经知道你会去找她接受训练了。让我们的祖先为你而感到光荣吧。在我们再次见面之前，愿你一路顺风。"
D.Strings[117145]="我希望你可以顺利地收到这封信，$c。我很荣幸可以和你对话，因为很少有人能拥有如此坚定的信念，也很少有人能理解我们是保护艾泽拉斯大陆的精英力量这一事实。$B$B记住，最重要的一点是，你的职责就是与那些想要伤害我们这个世界的邪恶势力进行战斗。$B$B我已经被授权在这段时间内对你进行训练了。当你准备好了之后就到北郡修道院里来找我吧。$B$B- 萨缪尔修士，圣骑士训练师"
D.Strings[117146]="有些人害怕我们，就好像是害怕龙一般；有些人羡慕我们，甚至超过了他们对技艺最精湛的铁匠的羡慕；有些人赞美我们在战斗中爆发出的力量，其他人为我们坚定的信仰而赞叹；还有些人羡慕我们能把他们都喝到烂醉！但是除此之外，$c，你还应该知道自己是保护艾泽拉斯的中坚力量。圣光给予我们力量，而我们则扞卫它的荣光。$B$B如果你想要向我询问更多关于这片土地的事情，那我会知无不言的。到寒脊山脚下的安威玛尔来找我吧。$B$B- 布罗莫斯·格鲁诺尔，圣骑士训练师"
D.Strings[117147]="你和世界的联系，世界和你的联系，这些对一个成功的牧师来说都是非常重要的。智慧与怜悯将会让你帮助那些真正需要帮助的弱者，过于急躁和慌张的决定都会使其他人无法变得更加强壮，甚至会伤害他们。$B$B当你开始懂得以上这些话的意思时，你就需要学习新的技能和法术了。这时，就到北郡修道院的图书馆里来找我吧。$B$B- 安妮塔，牧师训练师"
D.Strings[117148]="有着圣光的支持和每天都有的新发现，现在你应该为自己是铁炉堡的$g儿子:女儿;而感到自豪了。探险者协会每天都在为那古老的问题找寻失落的答案，现在满怀信仰的你也加入了我们的行列，与石腭怪以及其它一切胆敢威胁我们领土的邪恶力量进行战斗。$B$B等你有空了就来找我吧，我在山脚下的安威玛尔。$B$B- 布兰斯托克·卡德尔，牧师训练师"
D.Strings[117149]="为你的灵魂未被放逐到扭曲虚空中而感到庆幸吧，$N。为你能值得我花时间亲自书写这个卷轴感到由衷的庆幸吧。$B$B你所认识的人，以及你曾经关心过的人，都已经不再存在了！你必须学会如何以你现在的状态“活”下去，我建议你首先学会这件事情。$B$B如果你准备迎接试炼的话，那就到丧钟镇的教堂里来找我。$B$B- 黑暗牧师杜斯滕，牧师训练师"
D.Strings[117150]="看来你成长得挺顺利，孩子。摆在你面前的考验很多，当你准备好的时候，我愿意和你分享我所有的经验。你能以多快的速度变得多么强大，这取决于你。只有当你准备好的时候，我才可以指导你。$B$B有些人进步速度很快，而其他的则慢得多。但是你不要担心那么多，当你见到我之后，我们可以进行更多的讨论。$B$B- 肯杰，牧师训练师"
D.Strings[117151]="数千年以来，我们一直把自己和外界隔绝开来。我将是我们当中第一个站出来承认我们过去曾犯过的错误的精灵。人类根本就不应该接触到魔法的知识，我对此并不否认，但是我也不会因这个由我们的前辈犯下的过错而责怪我们自己。奎尔多雷和世界上的其他种族是可以共存的。我们必须锻炼自己的耐心。$B$B （未完）"
D.Strings[117152]="就是因为这些，我拒绝了凯尔关于纳萨诺斯·玛瑞斯的请求。他是个无价的盟友。记住我的话。$B$B 希瓦娜斯·风行者$B 银月城游侠部队指挥官"
D.Strings[117153]="瑞什：$B$B你的请假要求已经被批准了。我会派候补的牛头人战士去你执勤的哨所接班，这样你就可以回家和亲友团聚了。在一个星期的假期过后回来报到!$B$B- 马格兰"
D.Strings[117154]="亲爱的札尔夫：B$B你送来的肉片很不错。烧烤的火候很好，切片也恰到好处，还包在肥得流油的野猪肉里！这正是我梦寐以求的美食。当我吃肉片的时候，我会想起你的。我会闭上眼睛想像你那双强壮而布满伤疤的手正在笨拙地剁着肉块……$B$B哈哈！这让我想起你上次不小心剁了自己的手指……哦，札尔夫！想想那天你把我逗得像个小女孩一样咯咯大笑。$B$B你流血的时候看起来真可爱！$B$B- 格雷什卡"
D.Strings[117155]="奥斯瑞克：    以下是我们所需要的护甲列表：    10件链甲衬衣  20顶头盔  30块护甲片  15双链甲靴    我们总是欠你的情。一旦西部荒野不再受到盗贼的威胁，我就可以请你来我家里做客，这样也能让我心里好过一些，这个地区的菜肴以前可是远近闻名的。    - 刘易斯  哨兵岭军需官"
D.Strings[117156]="尼莎：$B$B 很高兴收到你的信。$B$B 你送给我的那些骨头和鳞片真是让人难以置信。我从来没有在主大陆这边看见过这种尺寸的鱼，鲁瑟兰村每天是不是都可以轻松地打到一吨的鱼啊?$B$B 我羡慕这种鱼的尺寸，但是我同样有些疑惑。我们的新的世界之树可以培养出那么大的鱼吗?如果是的话，有没有什么副作用?$B$B 这些问题值得我们思考。$B - 赖尔德"
D.Strings[117157]="以下名单中的学生将获得布洛克矿工学校的白金奖章，以及一把荣誉矿工锄：$B$B 梅莉亚·震石$B 巴尔丁·铁环$B 乌米·冷铁$B 卢米·冷铁$B 沃雷尔·钢塔"
D.Strings[117158]="这三页的文件是空白的。"
D.Strings[117159]="莱耶：$B$B我们受到了这位冒险者的帮助。现在我派$g他:她;到希利苏斯来帮助你。请好好利用$g他:她;的能力，解开那个地区的谜团。议会急切地等待着你的进度报告。$B$B愿塞纳留斯永远守护着你……$B- 拉比恩"
D.Strings[117160]="冬幕节庆典$B$B艾泽拉斯一年中的最后一个季节在许多文化中被认为是变化的一个季节。矮人和牛头人都在这个白雪覆盖大地的时候传颂着一个古老的传说故事，并欢庆着一个辞旧迎新的时刻。艾泽拉斯的各个种族对于这个传说故事的理解各不相同，他们传颂这个故事的方式也因为各个种族的差异而显得不同。"
D.Strings[117161]="冬天爷爷的传奇$B$B“冬幕节”这个词在许多文化中都来源于一个超自然的事物：冬天爷爷。他会在岁末出现在世界各地，随之而来的是凛冽的寒风。他的苏醒意味着大地将笼罩在白雪之中，所以也有人说是冬天爷爷用冬幕笼罩了大地。虽然艾泽拉斯大陆覆盖在白雪之中，但是其孕育的是重生和新生命的开始。"
D.Strings[117162]="矮人$B$B矮人一直热衷于寻求他们的起源的秘密，他们将在这个季节举行庆祝来作为对冬天爷爷的赞美。他们是远古时期艾泽拉斯大陆上的泰坦的一个化身。他们宣称自己的血管中流淌着那些神秘的生物的血液，居住在白雪皑皑的丹莫洛的矮人理所当然地认为自己受到了冬天爷爷的祝福。"
D.Strings[117163]="牛头人$B$B牛头人以他们的萨满教义和最近融入的德鲁伊信仰来理解着冬天，理解着冬幕节的传奇。他们最主要注重于传奇的更新，然而，在他们看来别的种族只是对这个传奇简单的膜拜，而非与大自然万物和谐共存。许多牛头人选择这个时间来表达自己能够在莫高雷找到新的家园而心生感激。"
D.Strings[117164]="举行盛宴$B$B关于每年这个时候举行盛宴的概念是来自于这个传说本身。冬天爷爷在这个季节会漫步在艾泽拉斯大陆，将冬天作为其苏醒的标志，据说他会给与那些欢迎他的人奖励。所以，各地的人们会在冬幕节举行盛宴来分享他们所拥有的东西。一般来说，大家会花一整天的时间尽情欢乐，举行盛宴来辞旧迎新。"
D.Strings[117165]="在长矛谷中坐落着神圣的玛拉顿神殿。如果不是因为我犯了太多的过错，我是不会让你这样一个$r来帮助我的。$B$B在只有半人马的灵魂和我们最圣洁的祭司才能穿越的大门后面有一位无名的预言者。他是所有部族中掌管灵魂事务的最高领袖，也是所有部族中最年长的智者。"
D.Strings[117166]="那个预言者非常强大，他能和我们先祖的灵魂进行交流。但他是个彻头彻尾的蠢货!他不知道自己所拥有的真正力量。他带着灵魂坠饰——那是他力量的源泉。$B$B 我知道坠饰的力量有多么强大，但是它并不完整。"
D.Strings[117167]="坠饰上面的五颗宝石都遗失了。如果能找回那些宝石，并把它们安到坠饰上，那么它的力量将远远高于现在。我找到了那五块宝石，但是需要你这样强大的$c来拿回它们。杀了那个无名预言者无疑是极度罪恶的行为，但是我要让所有半人马从此打消对宝石的念头。"
D.Strings[117168]="在玛拉顿的洞穴中徘徊着我们最早的几位可汗的灵魂。他们是我们的父亲和母亲的第一批孩子，也是我们的伟大的领袖——格尔克、考尔克、玛格拉、玛劳杜斯和温格。他们每个人身上都带有一块遗失的宝石。"
D.Strings[117169]="使用灵魂坠饰的力量来强迫他们显形，并从他们那里取得宝石!在此之后，把宝石放入灵魂坠饰之中，然后把它交给我。当我有了联合坠饰之后，我就有足够的力量来对我们的部族进行改革了，那样我们就能完成先祖的遗愿了!"
D.Strings[117170]="欢迎来到魔兽世界！年轻的战士，不要害怕这个陌生而充满神秘的提防，你会惊奇的发现许多潜伏在阴影中的危险，许多歹徒为了蝇头小利而准备杀了你……因为，提防身边的危险，随时做好战斗的准备，你才能好好地活着！"
D.Strings[117171]="欢迎来到魔兽世界！年轻的士兵啊，你已经准备好了成为一名圣骑士了吗？很好……记住要勇敢，击败邪恶扞卫正义！最重要的是，要相信上帝，并且你是他的助手……"
D.Strings[117172]="欢迎来到魔兽世界！你管自己叫做盗贼？别搞笑了，如果你想成为一名真正的盗贼，就让我看看你有什么能耐，现在就去抢劫这座村庄给我看看！"
D.Strings[117173]="欢迎来到魔兽世界!孩子，如果你崇拜上帝，你将被救赎……如果你崇拜恶魔，你将获得力量，但却被上帝抛弃……所以，一定要当心，我的孩子，一定要当心！"
D.Strings[117174]="欢迎来到魔兽世界!这个世界对我们萨满来说太险恶了，但是我们仍然足够强大来赢得这场圣战……我们先得采取些措施，杀死这些讨厌的联盟。现在让我看看，我们萨满到底有多厉害！"
D.Strings[117175]="欢迎来到魔兽世界！我们法师是最强大的魔法使用者，我们将冰霜与火焰的力量发挥到极致，我们能够做任何想做的事！所以，来探索魔法的精髓吧！"
D.Strings[117176]="欢迎来到魔兽世界！术士是一个神秘的群体……我们有最强大的魔法，忘了那些法师们吹嘘说他们的法术多么厉害云云，记住，我们术士是从法师发展而来的，所以实际上我们是更强大的！"
D.Strings[117177]="欢迎来到魔兽世界！部落唤醒了你的力量，我的孩子……现在你已经成为一名善变的德鲁伊了。你集合了战士的力量、法师的智慧、萨满的精神……我们是独特的！你必须帮助你的朋友们，因为我们德鲁伊是支援力量的极致！"
D.Strings[117178]="……那就是你可以找到血色十字军领袖之剑的地方，灰烬之剑。$B$B 是不是很惊讶?"
D.Strings[117179]="<这个页面上写满了古代精灵文字。>$B$B 这些书页中记述了在制作强效秘药的过程中所发生的事件。$B$B 愿我的敌人永远无法得到这些资料。$B$B 愿我有生之年能够重见洁白的月光照耀奎尔萨拉斯。$B$B 愿我能以凯尔萨斯之名奋战。$B$B 愿我能为伊利丹的荣耀而战死。$B$B - 卡里尔·温萨鲁斯"
D.Strings[117180]="<你看不懂这些书页上的文字。>"
D.Strings[117181]="<书页上的字迹不断跳动变幻着。你觉得这本书正在嘲弄你。>"
D.Strings[117182]="<你刚刚瞥了这些书页一眼，就感受到了一阵灼热的疼痛。>"
D.Strings[117183]="……如果可以的话，躲在窗台或桥墩底下。找一面坚固的墙也是安全的办法。$B$B$B<更多模糊的文字。>$B$B在五到十五……之间，使用……治疗。$B$B<更多模糊的文字。>$B$B在成功的袭击之後，好好休息接受胜利。待确实过了十至十五秒後，前往城里展示你的……让人们观看崇敬。$B$B$B<瞄了一眼其余的文字概要後让你头疼不已。>"
D.Strings[117184]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">军阶概述</H1><BR/> <BR/><BR/> <BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRankAlliance\" align=\"left\"/><BR/> <BR/><BR/> <P align=\"right\">以下是</P><BR/> <P align=\"right\">联盟的</P><BR/> <P align=\"right\">军阶概述，</P><BR/> <P align=\"right\">其中包括</P><BR/> <P align=\"right\">部落</P><BR/> <P align=\"right\">种族熟知的</P><BR/> <P align=\"right\">信息。每一部分都</P><BR/> <P align=\"right\">包含两个</P><BR/> <P align=\"right\">章节，军官和士兵的军阶，都是按照由高到低的顺序排列的。联盟万岁!</P><BR/> </BODY><BR/> <"
D.Strings[117185]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">联盟士兵军阶</H1><BR/><BR/> <P align=\"center\">Part 1</P><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank14\" align=\"left\"/><BR/><BR/> <P align=\"right\">总元帅</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank13\" align=\"left\"/><BR/><BR/> <P align=\"right\">战场元帅</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank12\" align=\"left\"/><BR/><BR/> <P align=\"right\">元帅</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank11\" align=\"left\"/><BR/><BR/>"
D.Strings[117186]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">联盟士兵军阶</H1><BR/><BR/> <P align=\"center\">第二部分</P><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank09\" align=\"left\"/><BR/><BR/> <P align=\"right\">一等骑士</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank08\" align=\"left\"/><BR/><BR/> <P align=\"right\">上尉骑士</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank07\" align=\"left\"/><BR/><BR/> <P align=\"right\">中尉骑士</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank06\" align=\"left\"/><BR/><BR/"
D.Strings[117187]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">部落军官军阶</H1><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank05\" align=\"left\"/><BR/><BR/> <P align=\"right\">士官长</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank04\" align=\"left\"/><BR/><BR/> <P align=\"right\">上士</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank03\" align=\"left\"/><BR/><BR/> <P align=\"right\">士官</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank02\" align=\"left\"/><BR/><BR/> <P align=\"right\">下士</P><BR/><BR/><B"
D.Strings[117188]="当你凝视着眼珠时，脑海中便浮现出战争的场景。$B$B似乎这场可怕的冲突发生在洛丹伦的某处。$B$B在尸横遍野的战场上，隐约可见一名女性，独自与浩如烟海的天灾军团作战。她显得那么绝望无助。$B$B从她手中施放的光芒瞬间便砍杀数百名不死生物。"
D.Strings[117189]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">联盟与部落的军阶</H1><BR/> <BR/><BR/> <BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRankHorde\"/>align=\"left\"/><BR/> <BR/><BR/> <P align=\"right\">(兽人语)你好!在这本</P><BR/> <P align=\"right\">书中</P><BR/> <P align=\"right\">列出了</P><BR/> <P align=\"righ\">部落和</P><BR/> <P align=\"right\">弱小的联盟的</P><BR/> <P align=\"right\">军阶列表。</P><BR/> <P align=\"right\">首先</P><BR/> <P align=\"right\">是部落军阶，接下来是联盟的，</P><BR/> <P align=\"right\">其中囊括了军官和军阶列表。按等级的高低排列，等级最高的排在首位，等级低的列于下位。</P>"
D.Strings[117190]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">部落军官军阶</H1><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank05\" align=\"left\"/><BR/><BR/> <P align=\"right\">一等士官</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank04\" align=\"left\"/><BR/><BR/> <P align=\"right\">资深士官</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank03\" align=\"left\"/><BR/><BR/> <P align=\"right\">士官</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank02\" align=\"left\"/><BR/><BR/> <P align=\"right\">步兵</P><BR/><BR/"
D.Strings[117191]="一切似乎都是徒劳。很快女祭司周围就堆满了农夫的尸体……倒下的尸体又站起来了。"
D.Strings[117192]="迷人的西蒙妮：$B$B 西蒙妮正在污染安戈洛环形山。不要被她的伪装所迷惑。小心翼翼地接近她，向她发起挑战。"
D.Strings[117193]="疯狂的克林弗兰：$B$B 克林弗兰在燃烧平原上游荡。谨慎地接近他，迫使他现出原形。"
D.Strings[117194]="屠杀者索伦诺尔：$B$B 屠杀者索伦诺尔就潜伏在希利苏斯的废土上。他伪装得很巧妙，而且非常危险。接近他，令他现出真正的面目。"
D.Strings[117195]="摧毁者阿托留斯：$B$B 冬泉谷中的那些被阿托留斯接触过的生物全都被他毁灭了。找到他，杀死他。"
D.Strings[117196]="猎人，你要多加小心，那些恶魔都不会贸然行事。如果它们觉得自己没有绝对的胜算，就会选择逃跑。$B$B 你一定要独自行动。"
D.Strings[117197]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">联盟军阶</H1><BR/><BR/> <P align=\"center\">军官</P><BR/><BR/> <P align=\"center\">总元帅</P><BR/> <P align=\"center\">战场元帅</P><BR/> <P align=\"center\">元帅</P><BR/> <P align=\"center\">指挥官</P><BR/> <P align=\"center\">少校</P><BR/> <P align=\"center\">一等骑士</P><BR/> <P align=\"center\">上尉骑士</P><BR/> <P align=\"center\">中尉骑士</P><BR/> <P align=\"center\">骑士</P><BR/><BR/> <P align=\"center\">士兵</P><BR/><BR/> <P align=\"center\">士官长</P><BR/> <P align=\"center\">上士</P><BR/> <P al"
D.Strings[117198]="要束缚恐惧战马，你必须做三件事：$B$B 制造强力召唤法阵。$B$B 在法阵中打开通往克索诺斯的传送门，将恐惧战马引入我们的世界。$B$B 击败恐惧战马并控制它的灵魂。$B$B 下一页将详细描述要如何执行这些步骤。这可不是一件容易的事，但是你是有能力完成它。只要集中精神运用你的所有技能，我相信恐惧战马会属于你的。$B$B 继续读下去吧。$B - 莫苏尔·召血者"
D.Strings[117199]="仪式道具$B$B 在开始任务之前，你必须拥有以下魔法道具：$B$B 耶维尔的瓶子$B 一块黑色磁石$B 克索诺斯雕文$B 我的仆人戈瑟奇会为你提供这些道具，但是你得付钱。如果你还没有集齐所有的道具，就不要试图开始仪式。每件道具都是必需的。$B$B 在下一页，我将描述道具的使用方法。"
D.Strings[117200]="强力召唤法阵$B$B 必须在魔法强大的地方创造出强力召唤法阵。在埃德萨拉斯的废墟深处，就有这样一块地方，也叫做厄运之槌。在埃德萨拉斯关押着拥有强大力量的生物，伊莫塔尔。创造法阵的地方就在关押他的监狱底座上。$B$B 杀进厄运之槌吧，取回耶维尔的瓶子。"
D.Strings[117201]="铃铛、车轮和蜡烛$B$B 释放耶维尔之后，他将布置铃铛、车轮和蜡烛，为你构建法阵。仪式随即开始，你必须保持警惕，这些道具会引导出强大的魔法能量，而且很容易失效。在整个仪式失败之前，你必须快速使用黑色磁石来重新启动失效的道具。$B$B 如果三件道具都失效的话，仪式也就失败了，你就不得不从头再来。"
D.Strings[117202]="为了引导出仪式所需的能量，铃铛、车轮和蜡烛都具备独有的属性。$B$B 达斯莫拉的铃铛，一旦铃响，可赋予术士活力和能量的法阵。$B$B 黑暗战车之轮，一旦旋转，可保护法阵中的人物免受伤害。$B$B 末日蜡烛，一旦燃烧，可对进入法阵的敌人造成可怕的伤害。$B$B 因此在仪式中保持三种物品的正常运作是至关重要的。"
D.Strings[117203]="用于重新启动铃铛、车轮和蜡烛的黑色磁石需要灵魂碎片方可生效，这点你需要牢记。每次使用黑石磁石启动一件仪式道具时，都需要消耗一片灵魂碎片。因此，在开始仪式之前，你必须收集大量的灵魂碎片。"
D.Strings[117204]="完成仪式$B$B 你可在法阵边缘查看魔法符文。当九个符文全部出现时，仪式便结束了，你将看见巨大的能量从新生的法阵中涌出。$B$B 你可以在那里使用克索诺斯雕文，由此打开通往克索诺斯的传送门，引出一匹恐惧战马。$B$B 打败恐惧战马，释放它的灵魂。奴役这个灵魂，你就可以随心所欲地召唤恐惧战马了。"
D.Strings[117205]="<HTML><BODY><BR/><BR/><P align=\"left\">长眠于此的是霜狼氏族的第一任酋长，我们敬仰的部落酋长索尔的父亲-杜洛坦。他被那些想要让我们永远受到奴役的同胞背叛。杜洛坦为了我们的自由而献出了自己的生命，我们敬仰他，以及他留给我们的珍贵遗产，他伟大的儿子。</P><BR/><P align=\"left\">德雷克塔尔，霜狼氏族的先知 </P></BODY></HTML>"
D.Strings[117206]="剥洋葱  关于瓦解雷矛部族的指南  - 德雷克塔尔着    本指南记录了大量战术策略知识。有学识的士兵总是依靠丰富的作战经验行事。本书将成为奥特兰克山谷的战场指南。"
D.Strings[117207]="第一章：前线    瓦解雷矛军队跟剥洋葱很相似。你必须一层层地除去洋葱外皮，才能得到洋葱的嫩心。    主要由雷矛巡山人和联盟哨兵组成的前线阵营都归上尉管制。一旦前线受到攻击，巴琳达·斯通赫尔斯上尉将带领前线阵营加强防守。攻击上尉，前线阵营即可崩溃。"
D.Strings[117208]="第二章：双塔    别搞错了，范达尔·雷矛是个狡猾的敌人，他绝不是傻子。攻破前线之后，你还需要突破第二道防线。那就是控制着丹巴达尔之外的雷矛卫兵和雷矛巡逻兵的石炉和冰翼双塔。"
D.Strings[117209]="士兵，小心，双塔之上戒备森严，范达尔的精英指挥官驻守在这儿。一旦你的军队突破防线，请确保塔中的指挥官已经……永远地沉默了。这将是瓦解雷矛部队的第二步。"
D.Strings[117210]="第三章：四名指挥官    雷矛洋葱的第三层由四名指挥官组成。范达尔无非是模仿了我们霜狼的防御构造罢了。当然，他是不会承认这一点的……瞧，我离题了。    四名指挥官负责指挥守护丹巴达尔的所有雷矛卫兵。杀死他们，雷矛卫兵就会溃不成军了。    接下来便只剩最后一层了。"
D.Strings[117211]="第四章：丹巴达尔兵营    毫无疑问地，你已经注意到雷矛的防御布局是为了防止强大的力量摧毁整个军队。是的，这正是我们自己的军队结构，我是不会改变自己的防御布局的。他们模仿我们的布局，我们为什么要改变呢？"
D.Strings[117212]="我讲到哪儿了？哦，是的，丹巴达尔兵营（位于丹巴达尔内）驻扎有范达尔最信任的精英雷矛防御者。摧毁双塔，消灭那些企图增援范达尔的军队。"
D.Strings[117213]="尾声    至此，洋葱只剩下嫩心：孤身一人、毫无抵抗能力的范达尔·雷矛。在杀死他之前，我们必须按照军规要求他弃械投降。当你看到他时请记得提醒他这一点……否则就杀死他。"
D.Strings[117214]="霜狼洋葱：雷矛的光荣事迹$B ：范达尔·雷矛着$B$B 霜狼是什么?答案很简单：霜狼就是那些企图摧毁我们伟大的帝国的野蛮人。$B$B 霜狼跟洋葱非常相似，霜狼设立了层层防御力量；一旦外层被剥离，就会露出嫩心，这样我们便可以就着蒜汁食用了。$B$B 太美味了!"
D.Strings[117215]="第一章：前线$B$B 霜狼战士构成了霜狼的前线防御部队。加尔范上尉在冰血要塞统领着所有霜狼战士。要摧毁这层防御，最有效的方法是占领冰血要塞。$B$B 包围要塞，杀死加尔范上尉，前线将在顷刻之间崩溃。"
D.Strings[117216]="第二章：冰雪和哨塔高地$B$B 一旦首层防御被摧毁，“洋蓟”的第二层防御便暴露无遗。破坏前线附近的霜狼哨塔将削弱企图增援的军团和巡逻兵。$B$B 哨塔部有重兵把守，塔内驻扎着德雷克塔尔的精英指挥官。必须杀死这些指挥官。这将加速瓦解霜狼防御力量的进程。"
D.Strings[117217]="第三章：四名指挥官$B$B 如果你遵循该指南行事，那么现在，你已经杀死了德雷克塔尔的两名指挥官。干得好，士兵!他们的信心正在瓦解。你必须杀死剩下的两名指挥官，完成命令。$B$B 一旦四名指挥官阵亡，保卫霜狼要塞的霜狼军团将溃不成军，因为他们失去了战斗指挥的主心骨。现在是时候了!"
D.Strings[117218]="第四章：东部和西部霜狼哨塔$B$B 现在你离胜利只有一步之遥啦；德雷克塔尔最信任和最强大的守卫军队：霜狼守卫者。$B$B 霜狼守卫者驻守在东部和西部霜狼哨塔中。摧毁哨塔，看看那些四散逃跑的可耻的霜狼守卫者吧。"
D.Strings[117219]="尾声$B$B “将蒜汁黄油和蛋黄酱抹在洋蓟嫩心上，喝上一瓶陈年烈酒，这真是顿美餐啊。”$B$B 德雷克塔尔身边只剩下两个愚蠢的随从啦。占领霜狼急救站，杀死德雷克塔尔。那时，这片土地就完全属于强大的雷矛啦。"
D.Strings[117220]="我们请求你，赞达拉的赞札。$B$B 祝福那些请求你的帮助的人吧，赞札。祝福那些跟赞达拉人民结盟的人。$B$B 在这关键时刻帮助我们。赐予我们力量，打败敌人，再次消灭哈卡。"
D.Strings[117221]="荆棘谷钓鱼大赛!$B 时间：周日下午2点到4点。$B$B 在荆棘谷的海岸边寻找可口鱼群!记得向可口鱼群中投放鱼钩，这样你就能钓到特殊的鱼儿，而不是荆棘谷常见的鱼。最快钓到40条可口鱼的人可将它们交到藏宝海湾的钓鱼大师布鲁吉尔处换取奖励!$B$B 即使你不是最快的那个，也可以用它们换取奖金。如果你能钓到特殊的鱼儿，还可以获得神秘大奖!"
D.Strings[117222]="他的名字为黑暗的艾泽拉斯带来了光明。$B$B他的勇气推翻了痛苦的高墙。$B$B白银之手将继承骑士的事业，为世界造福。"
D.Strings[117223]="他既不醉心于名望，$B$B亦不想以此获得统治权。$B$B相反，他选择为洛丹伦而战$B$B只是希望他的同胞不再卷入战事。"
D.Strings[117224]="这位神圣的骑士的悲剧$B$B不会因他的逝去而终结。$B$B我们尊敬他，感谢他!$B$B乌瑟尔永远代表着荣耀和光明!"
D.Strings[117225]="他的名字不会褪色。$B他的奉献精神将$B永远为后人指明方向。$B$B曾经的枷锁再也无法$B阻止我们表达对他的尊敬。"
D.Strings[117226]="你能听到他的咆哮吗？$B一声惊醒部落的怒吼：$B胜利或是阵亡！$B$B我们必须牢记$B他在死亡面前爆发的力量。$B他的梦想终成现实。"
D.Strings[117227]="危机四伏。$B敌人想让我们$B$B再次受缚。$B$B在战斗时，让我们$B$B怀念葛罗·地狱吼$B他完成了自己的使命。$B永远的葛罗·地狱吼！"
D.Strings[117228]="从流沙之战到现在也将近一千年了。在这场战争中，希利苏斯沙漠的中心发生了一个重大的悲剧，而沉重的负担让范达尔·鹿盔苦恼不已。人们相信就是这些事件造成了大德鲁伊最后令人厌恶的性格。"
D.Strings[117229]="一支古老，敏锐的种族－－其拉，想要争夺卡利姆多大陆的统治权。而自负、专制的鹿盔和他的夜精灵军队正式与它们展开了激战。"
D.Strings[117230]="为了控制希利苏斯中大量出现的昆虫潮，不分男女老少都激烈地奋战。从安其拉的堡垒中，似乎永无止尽的异种蝎持续壮大着入侵的其拉军队。整个希利苏斯都被包围了。"
D.Strings[117231]="基于一个鹿盔自己都会后悔的决定，他将年轻的鹿盔，瓦尔斯坦派去防守夜精灵的前哨基地南风村。遗憾地，瓦尔斯坦在南风村败给安其拉的军队那天也失去了性命。"
D.Strings[117232]="抱着无畏及坚定的决心，想复仇的范达尔·鹿盔继续计划着一切。希利苏斯的战败会导致夜精灵种族重大的损失，甚至可能会失去整个世界。$B$B 战火延烧了好几个月。整个希利苏斯都被其拉军侵袭了。鹿盔和他的军队被逼回塔纳利斯。在大批军队被毁灭和无数无辜生命被屠杀之后，范达尔·鹿盔一直以来的自负被彻底地熄灭了。"
D.Strings[117233]="他的骄傲被完全地粉碎，这是鹿盔第二次在人生中感到彻底的恐惧。于是，在塔纳利斯，鹿盔找到了安纳克罗斯－－诺兹多姆之子，并请求青铜龙军团的协助。"
D.Strings[117234]="一开始，安纳克罗斯拒绝让青铜龙军团卷入次要种族的事务之中。直到其拉莽撞地攻击了时光洞穴，安纳克罗斯才同意加入夜精灵的军队。"
D.Strings[117235]="安纳克罗斯很快的了解到即使是强大的青铜龙军团也无法阻挠其拉军队的入侵。每当他一口气杀掉五十只虫兵，就会有一百只等着替补它们的位置。随着夜精灵阵线越来越衰弱，这个威胁将会蔓延至更北方的菲拉斯荒野的迹象就越来越清楚的浮现，安纳克罗斯决定是时候该让守护巨龙之子们都意识到这个情况。"
D.Strings[117236]="他首先召唤了伊瑟拉的军团。翡翠梦境的麦琳瑟拉回应了他的召唤，接着雅立史卓莎和玛里苟斯的军团也被唤醒。"
D.Strings[117237]="龙群在希利苏斯上空的最高处碰头：在安其拉堡垒上空的几千尺之上。$B$B 安纳克罗斯是时间之王诺兹多姆之子。$B$B 翡翠梦境则有麦琳瑟拉，自然之王伊瑟拉的孩子。$B$B 凯雷斯特拉兹，生命之王雅立史卓莎的孩子，代表红龙军团。$B$B 亚雷戈斯是魔法之王玛里苟斯的孩子，代表蓝龙军团。"
D.Strings[117238]="巨龙们看着其拉虫人和异种虫的大军源源不断地从安其拉涌出。他们明白，没有谁能终止这场战争。在神庙中，还有数以万计的虫类士兵严阵以待。随着时间的流逝，它们的军队数量还在继续膨胀，它们全部都蠢蠢欲动，想要投身血腥的杀戮。"
D.Strings[117239]="亚雷戈斯是第一个发现奇怪能量的人。从安其拉南边四分之一处庞大的神庙里放射出一丝微暗的魔法，是他们从未自其拉虫上感受到的。他们尽全力尝试，却没有人可以穿过神庙找到这股能量的来源。只有巨大的力量才能这样完整地保护它自己。或许……有某样东西正在控制着这些昆虫。有某样东西甚至还正控制着其拉虫类。"
D.Strings[117240]="龙群知道他们必须尽快做出回应，以免世界又要经历另一次史诗的大灾难。经过审慎的深思熟虑后，他们决定最好的行动方式就是阻止这些东西来源或其附近的军队。"
D.Strings[117241]="他们决定使用夜精灵和巨龙军团的本源建立一个巨大的屏障。一个可以遏制异种和安其拉城内的最高统治者，还可以防止未来的侵略的魔法屏障。安其拉将会因此成为一所监狱。"
D.Strings[117242]="第1天$B 我们的旅行结束。我们终于到达希利苏斯，也就是我们要建立联系的地方。我们来自许多地方，要一起为不朽的事业通力合作。$B$B 空气中弥漫着一股兴奋。明天我们就要将所有的精力拿来建造与“他们”进行沟通的东西。$B$B 我们将在明天建造一座风石!"
D.Strings[117243]="第2天$B 建造风石的位置引起了极大的争议。就连我们之中最聪明的人也无法百分之百确定，古老的预言里所指的确切位置究竟是哪里。$B$B 我跟原来的北边族群站在同一阵线，而时间绝对会证明我们是对的。说能量线会贯穿这个位置的不利角度实在是愚蠢又无知。$B$B 我们早已积极地在收集建构需要的材料。"
D.Strings[117244]="第15天$B 我们的付出有了代价。我们是第一个完成风石建构的军营。如果其他那些笨蛋跟我们一起，我们就可以在一个星期之内完成这项工程!$B$B 明天我们会开始召唤沃库仑大人的仪式。他要求第一个来测试系统，我们无法反驳他，因为他很容易生气。$B$B 我希望他会对我们很满意。"
D.Strings[117245]="暮光之锤紧急通告：$B$B 寻找背叛者奥泰尔的过程进展的相当顺利。我们的侦察兵已缩小范围到西部荒野的洞穴群。$B$B 奥泰尔的背叛不能被原谅，而他的逃脱显示了我们组织的安全性有极大的漏洞。$B$B 任何被发现藏有奥泰尔消息的人，将会受到适当的处分。$B$B - 暮光之王艾沃兰"
D.Strings[117246]="暮光之锤紧急通告：$B$B 就目前希利苏斯事务状况而言，所有真实信仰者文件的发送都必须有不低于四组的武装暮光之锤人员护航。$B$B 任何被发现违反此新政策的成员将会立刻被惩罚。$B$B - 暮光之王德萨克"
D.Strings[117247]="暮光之锤紧急通告：$B$B 以下资讯描述和我们的深渊议会的主人们沟通的风石之使用方法。$B$B 任何对风石没有意义的使用都将被处以最严厉的惩罚。$B$B - 暮光守护者哈弗斯"
D.Strings[117248]="深渊圣殿骑士$B$B 身为一个新加入者，你可以与深渊圣殿骑士建立联系以进行例行仪式。记得永远在使用风石时穿着适宜的服装，以免启动我们的防御魔法。$B$B 当预料之外的紧急事件发生时，若没有任何监督者在现场的话，你被允许可以召唤深渊圣殿骑士。$B$B 想知道更详细的召唤仪式可以参考上个月的《真实信仰者》。"
D.Strings[117249]="深渊公爵$B$B 惟有那些持有身份勋章的侍僧能与深渊公爵建立联系，只有身份勋章的持有者本人才能使用它。$B$B 如果暮光之锤的成员未经许可擅自与深渊公爵联系或使用身份勋章，我将亲自惩罚违规者。"
D.Strings[117250]="高阶深渊议会的首领$B$B 只有暮光之王能与斯卡德诺克斯王子、大元帅维拉希斯、卡苏姆男爵或斯古恩男爵联系。$B$B 任何情况下，低于暮光之王等级的任何暮光之锤成员都不能与高阶议会建立联系。若发现任何外来人员使用风石，他将立即被化为灰烬。"
D.Strings[117251]="教派的现状，第92卷$B$B 衷心地祝福你，我的兄弟，教派目前的状况对我们来说是最最重要的。我们是一支军团，我们的目标越来越接近实现。$B$B 新召集的成员正在不断聚集。赞美我们主的歌声出现在黑海岸，他们充满幻想地在灼热峡谷鞠躬，他们信奉主人派往黑暗深渊的仆人，阿库麦尔。事实上，我的兄弟和姐妹，我们所有具有这种真正信仰的人，将会遍布艾泽拉斯!"
D.Strings[117252]="教派的现状，第127卷$B$B 这真是一个令人高兴的一天!我们在希利苏斯接受特训，而且最终通过了这次特训!$B$B 报告说我们最北面营地的毁灭将会挑战不忠实者之心，但是这次屠杀不会被视为一次悲剧。决不!"
D.Strings[117253]="被一名高阶深渊议会的成员溅洒我们的鲜血，这是一种无上的祝福!我们必须羡慕我们倒下的朋友，他们的灵魂正安息在一头最荣耀的野兽的胃中!$B$B 赞美上古之神!赞美他们的仆人!赞美暮光之锤!"
D.Strings[117254]="教派的现状，第233卷$B$B 机会再次降临，我的兄弟姐妹!塞纳里奥议会，这个邪恶的自然爱好者组织现在派人来对抗我们。他们一定想要阻止我们来召唤红色的引诱石。我们决不允许他们这么做!$B$B 红色的石头对于我们新的联盟来说非常重要。我们绝对不能让那些塞纳里奥议会的蠢货挡路。团结起来，我忠诚的朋友。团结起来!"
D.Strings[117255]="我们怎么知道他们爱我们?$B$B 有些人可能要问，上古之神和他们的手下怎么会爱我们?他们难道不是经常杀戮我们吗?如此恶毒的生物的心中怎么会有爱?$B$B 对于这个问题只有一个答案，简单得都不需要说出来?"
D.Strings[117256]="信仰。信仰是所有给予我们臣服的快感的源泉。信仰可以让我们在希利苏斯最寒冷的夜晚感到温暖。信仰让我们在末日将临的时候感受我们主的仁慈。$B$B 信仰将会拯救我们。"
D.Strings[117257]="魔法账本"
D.Strings[117258]="亲爱的日记，$B$B 今天，我的头号敌人 - 纳里安，企图派他的密友在他处以死刑的场地欺骗我。他的死刑。你相信吗?$B$B我历经千辛万苦才想出这个恶魔般的计划，要把他从那个该死的茅屋里引诱出来而他却这样做?算了……我太生气，不想写了。下次再说。"
D.Strings[117259]="亲爱的日记，$B$B 我在愤怒中离开了藏身之处。我真的很生气。我决定重新设计奴仆们的制服以反映我的不安。我现在觉得好多了但是有个东西不见了。我马上就回来……"
D.Strings[117260]="亲爱的日记，$B$B 好了，我现在很好。我把一个佣人打到哭的跟个小女孩一样。$B$B嗯……我现在觉得有点糟。等一下!该死的，我是个邪恶的天才!邪恶，你懂吗?我对自己真是太失望了。下次再说。"
D.Strings[117261]="亲爱的日记，$B$B 我给了他一个拥抱并告诉他要继续努力工作。我现在觉得好多了。这是我们之间的秘密，日记。$B$B我上次说到哪了?喔，对，纳里安!哼!!!我恨那个家伙。毕竟，就是纳里安摧毁了所有我们在修补诺姆瑞根学院当学生时的测验曲线。$B$B他们会把我赶出学校吗?就我看来，诺姆瑞根已经得到它该有的教训了!$B$B今天就写到这里。好好睡，日记!"
D.Strings[117262]="亲爱的日记，$B$B 我一定是老了。我完全忘记我跟你说了纳里安和他的诡计的事。总之，当我看到扮成纳里安的诱饵，我真的很生气所以就命令二号把那个笨蛋给杀了!$B$B我进入飞行器里开始撕毁他宝贵、愚蠢、无知的龙语书。真是爱炫耀!谁会读龙语啊?我真是痛恨他!"
D.Strings[117263]="亲爱的日记，$B$B 抱歉，我睡着了。然后我就一边愤怒的开着飞行器，一边把那愚蠢的书一章章丢出去。我看到我下方的暗语峡谷里有个恶魔，便决定要将第一章变成魔法的纸龙卷风，把它的身体碎成好几百万片!这是解放。魔法 + 纸张 =乐趣。$B$B这让我非常开心所以我决定飞到东部王国。我的第一站是熔火之心。纳里安总是一直讲那边的事!“…熔火之心怎样怎样，拉格纳罗斯如何如何…”"
D.Strings[117264]="你知道吗?如果他那么喜欢它，或许他会去熔火之心试着把他的书拼凑起来，然后从一堆灰烬中让那些章节再复活过来!哈!$B$B当我还在邻近地区的时候，我发现有一些在奈法利斯实验室的技术人员可能会用到这个龙语的东西。把炸弹拿开!"
D.Strings[117265]="已经开始变成一种运动了。我真的撕这该死的书撕到上瘾了!$B$B接下来就简单了。$B$B幽暗城，恶臭腐烂死人的家，可能有着我吃过最棒的辣椒，这样是一章。暴风城，起司的首都，另一章。日记，你有把暴风城的起司拿来放在幽暗城的辣椒上过吗?嘿?这应该听起来有点警惕作用。"
D.Strings[117266]="我开始对这个地方感到厌倦，所以我把飞行器掉头往回家的路走，但是在那之前我还有两个地方要去。我载了卡札克和他的恶魔们一程，到腐烂之痕(他最讨厌我这样做)然后又去了女伯爵奥妮克希亚的烟囱。$B$B累了。去睡了。"
D.Strings[117267]="敬启者，$B$B 我真爱我们玩的这些游戏。$B$B 我只能猜想，如果你正在阅读这封信，你一定是因为奇迹或神的介入才击败了我。很荒谬，我知道，但是更奇怪的事都在这个世界发生过。"
D.Strings[117268]="伴随生命中所有事物，这个哀伤传说中的悲剧、混乱和邪恶，都有着光荣、银色的内衬。当你杀了我，因为你的动作是如此的缓慢无序，让我有足够的时间先摧毁你拯救世界唯一的希望再写下这封信。粉碎的红水晶粉末是你的权杖碎片唯一留下的东西。"
D.Strings[117269]="享用你在我贵重的收藏品中发现的复仇和怒风装备吧。相信我说的：我很高兴做了我父亲没有做的事……$B$B $B 由衷的敬上，$B$B 奈法利斯$B \"奈法利安\""
D.Strings[117270]="谨代表熏木牧场，再次感谢你的调查。我们不确定梅特森在谁的手里，但两个都去调查也许会是个不错的开始！$B$B时间就是金钱，朋友，我们可以解决这个案子的时间又少得非常宝贵。快点加把劲去解救它，因为这些团体都不是容易对付的。$B$B总之，接下来的2页就是我们收到的勒索信。祝你好运……"
D.Strings[117271]="如果你们想要麋鹿活着回来，你们就得赶快准备好赎金。南海海盗不会好心到让你们延迟付款，我们也知道对“你们”的象征意义有多么珍贵。$B$B带1000金到塔纳利斯的落帆海湾。任何企图拯救这只麋鹿的行为，都会让梅特森变成桌上的菜肴。$B$B哈哈……$B$B南海海盗。"
D.Strings[117272]="你们那珍贵的宠物在其热无比的灼热峡谷表现的不太好……你们最好聪明点，不要延迟完成我们的要求。$B$B你们必须带给我们5颗星红宝石和总数700金－－将两者置于同一个不加注记的素面包裹里。在一周内把包裹放在通往石坝小径的门前。$B$B若没有达到我们的要求，梅特森就会变成黑铁矮人冬幕节的主菜。$B$B嗯……麋鹿……"
D.Strings[117273]="他那些猎犬来的比老鹰还要快，$B$B然后他吹了声口哨，大吼，依序喊着它们的名字；“$B$B现在，毛瑟！现在，奇尔顿！现在，乔登跟卡普兰！$B$B上，纳格！上，帕度！上，古德曼跟梅特森！$B$B到门廊的顶端！到墙顶！$B$B现在冲过去！冲过去！冲过去啊”"
D.Strings[117274]="我衷心的期望透过我的努力研究可以发现一种魔术能量的补充来源，而它对我的人民而言是安全的。太阳之井消失后，我们必须想办法让生活继续，不向秘法魔法屈服。   我相信辛多雷的未来能再次成为大家钦羡亮丽的榜样!"
D.Strings[117275]="好运还没降临。我导入的法术一定要传导通过尖塔，不过我的确有一些有趣又吸引人的点子。我派我最聪明的学徒追随调查的路径，看看能发现什么。"
D.Strings[117276]="我记笔记已经好一阵子了，但还是没啥进展希望。我昨天在逐日岛听到其中一位学生法兰德伦说他没有谨记良师忠告，而向痛苦屈服。   我得加把劲、加倍努力。"
D.Strings[117277]="没事。我不会放弃任何一丝希望。我们包围了南方，而此刻辛多雷无法在这个魔法保护区放肆乱来。   假如我设计的全新方法成功的话，我就能顺利滤除邪恶、腐败法术中的「杂质」，我已经把法术力的资料藏起来。我得持续谨慎小心。"
D.Strings[117278]="太神奇了!我们成功了，我们所研究的魔法精髓数量虽然不是很多，我要停摆目前大部分学徒的实验，然后一起着手进行崭新、有前瞻希望的研究工作。   有了好运加持，我们应该要精炼研究过程，一石二鸟-我们全体要备足精力，以及迎接即将来临的恶魔法术难题。"
D.Strings[117279]="不!当新实验程序开始时，我的主要学徒:泰勒塞翁，突然无预警的在我眼前萎缩，屈服成这种状态着实折磨了我的兄弟。我极力想制止，但他就这样离我远远而去。除了让他从苦痛中幸免外，我也没别的选择了。   而这是研究与发明的代价，只不过这代价实在是太沉重了。"
D.Strings[117280]="我不能再容忍了…又有2个学徒向邪恶屈服。我们已经很小心翼翼了…但我不知道是哪里出差错。   我得放弃这些调查行动，从零开始。"
D.Strings[117281]="我来迟了。第3个学徒已不知不觉和其他人建立起邪恶的勾当。我必须容忍现状，但当务之急是避免让其他未受影响的学徒同流合污。   我要让所有人都知道我在远行者居所行周期安息日。这样一来，我就可以好好构思解决难题的办法。   我一定要想出正确的判断来弥补这个可怕的错误。"
D.Strings[117282]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">联盟军官军阶</H1><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank05\" align=\"left\"/><BR/><BR/> <P align=\"right\">士官长</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank04\" align=\"left\"/><BR/><BR/> <P align=\"right\">上士</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank03\" align=\"left\"/><BR/><BR/> <P align=\"right\">士官</P><BR/><BR/><BR/> <IMG src=\"InterfacePvPRankBadgesPvPRank02\" align=\"left\"/><BR/><BR/> <P align=\"right\">下士</P><BR/><BR/><B"
D.Strings[117283]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">祈愿火盆: 使用者操作手册</H1><BR/> <H3 align=\"center\">如何找到闹鬼地点</H3><BR/> <BR/><BR/> <H3 align=\"center\">介绍</H3><BR/> <BR/><BR/> <P>这些页面介绍，包括那些卷入瓦拉萨克护符事件的堕落腐败的鬼魂、灵魂之所在地点，虽然你救了我之前的同伴，据我推测，曾扭曲他们灵魂的恶魔厌恶回音，仍盘悬回荡在那些闹鬼之处。这就是心肠恶毒的瓦拉萨克灵魂的力量。</P><BR/> <BR/><BR/> <P>此外，火盆还可以召唤瓦拉萨克，不过，凡事还是得小心谨慎一些。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117284]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">介绍，继续……</H1><BR/> <BR/><BR/> <P>火盆的功能就像召唤火盆一样。只要把它放在五个闹鬼的地方之一，它就会召唤出亡者的灵魂。</P><BR/> <BR/><BR/> <P>另外告诉你，我知道你会有兴趣，挑衅旗帜也能在黑石深渊竞技场有类似的功用。到了那里，只要有机会就替我教训瑟尔伦和他的暴徒们。</P><BR/> <BR/><BR/> <BR/><BR/> <P>如果你有兴趣了解更多就继续读下去。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117285]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">依萨利恩</H1><BR/> <H3 align=\"center\">月亮的夜精灵女祭司</H3><BR/> <BR/><BR/> <BR/><BR/> <P>当依萨利恩决定离开公司，她是为了去厄运之槌朝圣，那个古老的夜精灵城市，埃德萨拉斯。在那里，有一个图书馆仍保留了丰富的知识，是少数夜精灵保存下来的圣所。她很想去那里找到命运的答案，或许还有护符块的事。我们该知道她也是法琳·树形者的好朋友。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117286]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">依萨利恩，继续……</H1><BR/> <BR/><BR/> <P>不幸地，当她和她的角鹰兽同伴，苍穹，正进入城里的时候，被奥兹恩和他的爪牙攻击。她倒在那里，再也没有爬起来了。依萨利恩从未解开任何瓦萨拉克在护符里施的邪恶魔法秘密，或许这是很好的事。</P><BR/> <BR/><BR/> <P>奥兹恩住的露天房间就是闹鬼的地点之一。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117287]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">莫尔·灰蹄</H1><BR/> <H3 align=\"center\">牛头人德鲁伊和第一个倒下的人</H3><BR/> <BR/><BR/> <BR/><BR/> <P>莫尔·灰蹄是隐刃里相当勇敢且值得信赖的同伴。他成为瓦萨拉克的邪恶爪牙下第一个牺牲的人实在令人惋惜。</P><BR/> <BR/><BR/> <P>当我们逃出瓦萨拉克的魔掌时，我们正被他的鬼魂刺客和捕猎者追赶。那场黑石塔的战斗十分混乱，只能这么说。不幸地，莫尔在路上错乱了他的脚步，虽然我猜他是被推倒的。总之，他跌进了塔的下层。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117288]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">莫尔·灰蹄，继续……</H1><BR/> <BR/><BR/> <P>后来，我们发现莫尔并未跌死。但是我的好友最后还是没有好下场；他被塔萨洛尔的食人妖掳为战俘。不久，就在他被指挥官沃恩折磨的时候，一群瓦萨拉克的刺客跳了出来结束了这个任务。</P><BR/> <BR/><BR/> <P>如果你想召唤出莫尔·灰蹄的灵魂，指挥官沃恩的房间就是闹鬼的地方。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117289]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">贾林和索索斯</H1><BR/> <H3 align=\"center\">欲成为血色十字军的姊弟</H3><BR/> <BR/><BR/> <BR/><BR/> <P>贾林和索索斯是我所认识最偏执的两个人。但是他们战斗的技能是相当杰出的，他们是用钱买来的，也是我推断隐刃领导者，安希恩会留住他们的原因。</P><BR/> <BR/><BR/> <P>这对姊弟最后终于找到令他们迷恋的血色十字军的教导和哲学。他们在我们的旅途中总是展现出极大的热诚来歼灭天灾军团，我们也怀疑他们的家人与那个组织有关连。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117290]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">贾林及索索斯，继续……</H1><BR/> <BR/><BR/> <P>他们发现自己面临的试炼是加入十字军必经的过程。他们特别有兴趣的位置是骑士身分；那是需要更艰难的考验的。后来发现索索斯其实没有通过他最后一项考验。贾林当然不会，她公然挑战，坚持让他加入她的骑士身分。据我们所了解，大十字军战士达索汉当场就在房间里把他们都杀了。</P><BR/> <BR/><BR/> <P>因此斯坦索姆的血色十字军堡垒里，赤色王座就是另一个闹鬼的地方。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117291]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">科尔莫克</H1><BR/> <H3 align=\"center\">双头巨魔巫师</H3><BR/> <BR/><BR/> <BR/><BR/> <P>科尔莫克有什么好说的？他是个有着多样魔法的双头巨魔，不是个很差劲的人。我们第一次带他进入坑洼时他是个囚犯，那是个在燃烧平原接下的任务。但是后来我们发现，他对帮助我们脱离棘手的状况并没有什么益处，然后他就成为公司最早的法师之一。</P><BR/> <BR/><BR/> <P>他奇怪的地方是他的两个头暀?着完全不同的个性。一个总是很开心，有一点傻气，另一个很狡猾算计，而且眼神很像死去的人。满吓人的。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117292]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">科尔莫克，继续……</H1><BR/> <BR/><BR/> <P>后来，因为我们长途跋涉，科尔莫克持续暴露于巫术的魔法下。不幸的是那个可怕的东西竟然有饲养亡者灵魂的喜好，在其中获得邪恶的喜悦，尤其在召唤赎罪岛被放逐的灵魂时。</P><BR/> <BR/><BR/> <P>在公司解散后，科尔莫克参加了通灵学院的进修课程。鬼魂刺客发现要进入学校实在是太容易了，便在他的新主人，莱斯·霜语面前杀了他。</P><BR/> <BR/><BR/> <P>这让莱斯·霜语的房间变成闹鬼的地方之一，也是火盆可以成功利用的地方。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117293]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">瓦萨拉克</H1><BR/> <H3 align=\"center\">龙语贵族和之前的黑石塔将军</H3><BR/> <BR/><BR/> <P>在达基萨斯将军之前，有瓦萨拉克，一个拥有强大力量的龙族术士。哨塔的领导权交替是常见的事，对我们而言不幸的是，我们正好处于最后一批的权力转换。</P><BR/> <BR/><BR/> <P>我们受一个藏宝海湾的哥布林走私者术士委任，他叫格雷姆尼克，去偷瓦萨拉克的魔法书。我们不知道他是想研读那本书还是把它卖掉(或者两者都有)，不过现在也不重要了。重要的是我们进入黑石塔上层，到瓦萨拉克的巢穴杀了他。乐趣现在才开始。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117294]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">瓦萨拉克，继续……</H1><BR/> <BR/><BR/> <P>我们不了解瓦萨拉克操纵灵魂的魔法有多强大，否则当初就不会接下这个任务了。但是我们已经接了，而且看来也是我们接的最后一个任务了。</P><BR/> <BR/><BR/> <P>杀了瓦萨拉克，拿走他的魔法书，科尔莫克一定感应到他的护符有点不对劲。他坚持把它视为战利品，很快地成为一个热烈的争论，他们甚至为了它大打出手。我们当时不知道护符里藏有瓦萨拉克的灵魂；是后来才知道的，也让我们很痛苦。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117295]="<HTML><BR/> <BODY><BR/> <H1 align=\"center\">瓦萨拉克，继续……</H1><BR/> <BR/><BR/> <P>分裂护符，我们从新生的瓦萨拉克鬼魂，和他的鬼魂刺客军队那里逃了出来。我们抢夺护符的声响引起了塔里剩下的防卫者注意！</P><BR/> <BR/><BR/> <P>我们几乎所有人都逃出黑石塔并以为自己安全了。但是，不管有多远，瓦萨拉克都会派他的爪牙来追我们。隐刃在那次任务后很快就四分五裂了，然后我们就成了俎上鱼肉。</P><BR/> <BR/><BR/> <P>你一定要知道，瓦萨拉克的住所就是现在黑石塔里比斯巨兽的房间，最后一个闹鬼的地方。</P><BR/> </BODY><BR/> </HTML>"
D.Strings[117296]="致所有强壮的男人和女人们：$B$B 天灾军团已经回来了而我们务必要将一切琐碎的争吵放在一边，并面对这个威胁。银色黎明会赞赏任何卷起袖子，加入对抗天灾军团威胁的人。$B$B 所有要保卫我们家园的人都会聚集在东瘟疫之地的圣光之愿礼拜堂。团结一致，我们就能获得胜利。$B$B 名册保管者$B 银色黎明"
D.Strings[117297]="我的艾米莉，$b$b几天前，我们闯入了这个被圣光遗忘的地方，听从国王的命令返家。虽然这周围很荒凉但我的心很轻松，因为在前往海岸严寒的长途跋涉和遥远辛劳的航海後我就知道，我会在你的怀中找到安慰。$b$b我们今天到海岸线找我们的船，我们回家的工具，已经是烧黑的外壳;我们无法离开，别无选择，只好往这深不可测的荒地中心走。$b$b我为了保护你已走到了世界的最尽头，艾米莉……而现在……我衷心希望我还和你留在罗德隆。$b$b每当我睁开眼想的都是你。你是我在这冰冷土地上的温暖，亲爱的，而且没有人可以改变这个事实。$b$b麦克斯韦尔"
D.Strings[117298]="鲁宾，$b$b我知道你可能永远都不会看到我写的这封信，只是我不能闲着，听着壁炉谷的城墙不断发出撞击声。不死族就在我们村子外面，不停袭击我们，而我们收到命令要保护镇民直到援军前来。$b$b我的腿在上一次的行动中断了，所以我坐在这里，一无是处，如果我们的防线被攻破了，我的剑就插在腰间。没有空闲开玩笑...只有打斗和死亡的声音。空气中弥漫着恐惧。$b$b阿尔萨斯王子在这里，和人们一同在前线打仗。如果他不在，我们很久以前就该死了。他对这片土地和人民的热爱是有感染力的; 我很荣幸能为他工作，也会一直跟随他直到老死。$b$b战争越演越烈；不管腿有没有断，我都不能坐在这里。我们需要每一个人。我希望你看到这些话的时候情况能乐观些。$b$b你的朋友，$b里格瑞$b$b"
D.Strings[117299]="$b$b海利安娜，$b$b我，瓦古斯，虽然与你的希望相违，不过我还活着。我鄙视自己穿着这可笑的护甲在乡间游荡。$b$b我们的上一个命令要我们前往安多哈尔寻找一些谷类或类似的狗屁东西。为什麽这麽多地方却偏要我找安多哈尔的食物?从军这整个想法真是有够可笑。$b$b好好安息吧，海利安娜阿姨，我会回去继承你的遗产的;即使我伤的极为严重，又饥又渴，坚定的恨意会驱使我继续向前进。$b$b瓦古斯$b$b"
D.Strings[117300]="最亲爱的亚蜜利亚，$b$b今晚我见到了会终生萦绕在我心中的事。$b$b斯坦索姆战火延烧，我们都要负起责任。$b$b今晚我们的王子带领我们到了城镇的街上;他命令我们闯入民宅然後……在他们熟睡时把他们杀光。阿萨斯主人说，他们得了瘟疫，所以要在他们杀死我们之前把他们杀了。$b$b那简直是大屠杀。几百人寂静地死在曾誓言要保护他们的剑下。我无法再忍受了;我逃了出来。$b$b我或许是个背弃者，但我无法做出那样残暴的事。在每个民宅里，我在受难者死去时看到了你的脸孔，和我们的孩子。如果我这样做是个卖国贼的话，那就是吧。$b$b我希望能及时找到路回到你身边，但路途并不安全。我不在的时候替我传达我的爱给我们的孩子。$b$b詹姆士$b$b"
D.Strings[117301]="珊拉，$b$b我越跟着我们的阿萨斯主人往北走，越北，我的心就越沉重。他虽然曾闪耀着圣光，我现在却感应到一股黑暗的年轻圣骑士灵魂。他的热诚被一股沉思笼罩着，在他的灵魂里有一些我无法理解的梦魇……$b$b我们很快就会着陆在冰冻荒原。虽然阿萨斯手下很多人都因受寒或与腐败的野兽搏斗而病倒，他告诉我们他要在冰地里寻找的东西会扭转战争情势。但我并没有因为他的话感到安慰，因为在他这样说之後……一抹阴森的微笑浮现在他有棱有角的嘴角，那股寒意比任何暴风雪还要让我冷的刺骨。$b$b为我们祷告吧，珊拉，也为我们的世界祷告，$b$b托尔哥$b$b"
D.Strings[117302]="亲爱的帕米拉，$b$b明天我们就要站上安多哈尔的战场，我怕这将是我写给你的最后一封信了，我的爱。那些不死族丝毫不见疲累，而我们只不过是凡人罢了。我们抵挡不了它们。但不必烦恼，因为我们虽然必定会死去，我们的希望仍然坚定。圣光将会战胜一切！$b$b我最亲爱的，虽然那些黑暗恐怖的家伙猛攻我们的墙垣撞击我们的心灵，最后浮现在我脑海的不会是死亡，我很安慰知道这点。我会想念着你，而我终将体验宁静。$b$b克里斯多夫"
D.Strings[117303]="嗨，$n。经过调查之后，我从那张便笺发现了一些讯息。$b$b关于詹姆士，恐怕，我只能找到一点点。不过我确实找到一些亚蜜利亚家人的事。$b$b虽然她或她的孩子们都没从战争中生还，但她的哥哥还活着，一个叫做亚历山大·考德尔的人; 你可以在铁炉堡荒弃的洞穴找到他，研究着燃烧军团危险的魔法。$b$b她还有一个亲密的表姊，一个叫迪兹·斯诺班的女人，她在奥格瑞玛筹划着阿拉希盆地的战役。$b$b你应该在下次前往那里时去拜访他们其中一人。我相信他们会很乐意听听逝去的亚蜜利亚的事。$b$b"
D.Strings[117304]="你好，$n。我想你一定会对我调查的结果很有兴趣。$b$b事实证明，鲁宾和里格瑞还活着 - 换句话说 - 还有家庭。即使他们已经知道死去的士兵的事，拜访他们其中一人都会是值得的冒险。$b$b你可以在幽暗城的军事区找到鲁宾的前妻，琼安娜·怀特豪尔，她大部分时间都在那里。我不知道她能不能接受这个事实，要小心。$b$b至於里格瑞，他的阿姨成了暴风城的孤儿监护人，是个值得钦佩的职务。$b$b不管你生命中的道路是什麽，我希望你的努力都能有好运气。$b$b"
D.Strings[117305]="$n，我希望这封信对你有所帮助。在探究了一阵子之後，我发现了一些消息，关於写下你找到的便笺的那个人。$b$b珊拉的父亲带领着跟随他信念到雷霆崖朝圣的被遗忘者和食人妖。他的名字是麦尔斯·威尔什，你会在预见之池找到他和他的不死族朋友。$b$b同时，托尔哥是被他的表姐埃丽莎救活的。据我了解她是个很低调的人;她都在达纳苏斯的月神殿里。$b$b我强烈建议你去拜访任何一个人，$n。他们永远都不会了解托尔哥或珊拉的命运的。$b$b"
D.Strings[117306]="保管者将你发现的信给大家传阅了，$n，我想你可能想要了解最新的情况。$b$b最后一位仅存的“瓦古斯”家族成员住在塞纳里奥城堡，希利苏斯的沙漠里。他以卡隆．海金斯的名字自居。$b$b你应该在下次旅行至荒地时和他谈谈。他或许会对我们发现的事情有兴趣。$b$b"
D.Strings[117307]="你好。我终于找到时间仔细研究你在天灾军团发现的公文。虽然花了点时间，但我相信我找到了一名死者的亲戚。$b$b玛克斯韦尔的姊姊，一个叫萨瑞娜·克罗姆温德的女人，在藏宝海湾经营一家小型武器店。我不确定她和她弟弟的关系亲不亲密，但如果你预先知道你将前往该处，你就该安排一次会面。这类事情能有结果在现今是珍贵且稀有的。$b$b"
D.Strings[117308]="我终于发现一些先前与你打斗的士兵们的消息。线索很难追，因为他们的家谱没有正确的记载所有资讯，但我最后仍找到一个血亲。$b$b你相信圣光之愿礼拜堂的护理者奥林事实上是克里斯多夫的儿子吗?听到父亲的消息他应会比较放心。如果你再次至瘟疫之地为银色黎明服务，拜托你，与他谈谈。这会是件善行。$b$b"
D.Strings[117309]="纪念联盟最高指挥官安度因·洛萨，一个为了扞卫他的国王、他的臣民和他的家园而不惜牺牲一切的英雄……  让我们的敌人记住我们的名字，让我们的伙伴为我们的牺牲而感到荣耀，我们是洛萨之子。  - 图拉扬将军"
D.Strings[117310]="这里长眠着一个勇敢的苦工。他试图抵抗，但只来得及放了个屁。"
D.Strings[117311]="这里有一个灰烬之罐。这些灰烬是我的精神，我的热情，和我的本能需要。全部，都被他们摧毁了。愿所有来到地狱火这凄凉土地的人都记得这死去的苦工。他为了联盟流血流汗，被部落逼的彻底发疯，因为那些邪恶，没有灵魂的人将他的最爱毁灭。他们因为他的苦力而享受，愿他们也因为他的愤怒而痛苦。或许不是在这个世界，而是在之後的每一个世界。这是我的宣言，我严肃的誓约，也是我永恒的承诺。我会为我的苦难报复。"
D.Strings[117312]="侦察岛屿区域并返回报告。$B$B切记千万别被抓住！$B$B不要让我失望，卡蒂瑞丝！"
D.Strings[117313]="这份草图用X记号标出了沙德拉洛和其他三座神殿以及被偷走的狮鹫卵的所在地。这些记号分布在东部神殿的南边、东部神殿东北边的一座小房子、接近位于中央湖东边的圣坛，以及南部神殿的斜面，靠近“流亡”字样的地方。$B$B羽须的日记写着他打算将该信息传递给弗斯塔德·蛮锤，并希望他能派出一批战士来夺回被偷走的狮鹫卵。"
D.Strings[117314]="迪亚索鲁斯，   我相信这封信最终一定会到你手上。这些恶魔真是无脑。他们脑袋里想的只有他们的爪子，鞭子，或是用他们的头钉刺穿什么东西。我不敢使用任何一个地狱火否则一切都会被烧成灰烬!   很令人伤心，我怀念那些奴役兽人的日子。至少他们有一半的脑袋还会听从命令。或许有机会从附近再找一些新的奴隶来?"
D.Strings[117315]="有关夜精灵协助德莱尼的报告是真的。他们想在北边萨提纳尔附近的林歌神殿建立一个新的运作基地。我们应该协商一下，在这可悲的世界下一次月圆前联合我们的军队做一次攻击。如果我们现在制服他们，他们才会记得「部落」这个词真正的意义为何!   戈甘诺恩  致意  备注-不要再用血墨水写情书给我的鞭笞者!夜精灵处女最近很短缺"
D.Strings[117316]="迪亚索鲁斯，   我相信这封信最终一定会到你手上。这些恶魔真是无脑。他们脑袋里想的只有他们的爪子，鞭子，或是用他们的头钉刺穿什么东西。我不敢使用任何一个地狱火否则一切都会被烧成灰烬!   很令人伤心，我怀念那些奴役兽人的日子。至少他们有一半的脑袋还会听从命令。或许有机会从附近再找一些新的奴隶来?   是时候夺回一些次要种族了，我想。西北边的碎木岗哨是个很诱人的目标。我们应该协商一下，在这可悲的世界下一次月圆前联合我们的军队做一次攻击。如果我们现在制服他们，他们才会记得「部落」这个词真正的意义为何!   戈甘诺恩  致意  备注-不要再用血墨水写情书给我的鞭笞者!夜精灵处女最近很短缺。"
D.Strings[117317]="是时候夺回一些次要种族了，我想。西北边的碎木岗哨是个很诱人的目标。我们应该协商一下，在这可悲的世界下一次月圆前联合我们的军队做一次攻击。如果我们现在制服他们，他们才会记得「部落」这个词真正的意义为何!   戈甘诺恩  致意  备注-不要再用血墨水写情书给我的鞭笞者!夜精灵处女最近很短缺。"
D.Strings[117318]="虽然几乎被击败$B他的勇气仍然坚强$B拔剑出鞘$B命令地狱人群向前冲锋$B$B因为那些暴力的日子$B不要箭，也不要剑$B寻找，不在战斗中也不在冲突里，$B这是矮人领主的方法"
D.Strings[117319]="……但她已经知道了。在她将自己的灵魂一点一滴的交换出去后，她已经认命的过着贱民的生活了。复仇已经值得了，或是她这样想。$B$B但现在有个机会让她重拾人性，所有的陌生人要交换的就是她的信任。$B$B“让我来”，卡崔恩说。“我没什么好怕的。”"
D.Strings[117320]="维斯路登，$B$B 由于黑暗之门再次开启，荣耀堡和萨尔玛都从艾泽拉斯接获了强大的援军。我看过报告暗示他们正计划要攻击堡垒，而我们也一定要对付燃烧军团。这是无法令人接受的!$B$B 不要让血熔炉的运作冒险!在那里制造出来的地狱兽人就是我们成功的关键。加强堡垒的防御并立刻分派更多周边守卫!$B$B 相信我，你不会想让我亲自去拜访你的。$B$B -伊利丹"
D.Strings[117321]="我做了这件事。我不记得我有做，但也没有别的可能了。$B$B我以前犯过罪。我甚至还杀过一个无辜的人。但这次不同。$B$B我改变了。$B$B这些谋杀不是我的选择。有一只野兽住在我心里。$B$B我会被追捕和回避。我要躲起来。逃跑。埋葬尸体。$B$B当我真正了解是什么在困扰着我时，我开始到外面走动。$B$B我感觉不到罪恶。"
D.Strings[117322]="仆人，$B$B 值得计划的几年已经过去了。德莱尼和他们可悲的领导者又再次从主人的手里逃走了!更重要的是，他们偷走了我的飞船还让它在艾泽拉斯坠毁!$B$B 虽然主人的埃雷达尔密探失败了，但她能将艾克索达的地点传送给我们。很幸运，她的身份对德莱尼而言仍是个谜，我们还是可以利用她来达到我们的目的。"
D.Strings[117323]="联络我们的间谍并准备全面性突击德莱尼。杀光他们并取回我的飞船。你是艾泽拉斯上唯一可以修补那些畜生对艾克索达造成的损坏的人，又是我唯一的连系。$B$B 不要让我失望，地精。如果你对财富的渴望干扰了我的命令，你来世就等着祷告吧。如果你失败了我会让你痛不欲生，你会祈求死亡快点到来将你从痛苦中释放。$B$B -逐日者之王"
D.Strings[117324]="空间飞船维修傻瓜指南，作者：加姆斯·凯斯  <这本书的书页是用某种闪闪发光的材料制作的，上面的高科技图表详细描述了维修空间飞船的技术细节。这本小册子的开篇题目是“矢量线圈破裂的应对及避免措施”。>"
D.Strings[117325]="$B$B备注 - 我们的大师常收到外域捎来消息回覆萨尔的问题。答案是，当然，是的。"
D.Strings[117326]="备注 - 我们的大师常收到外域捎来消息回覆索尔的问题。答案是，当然，是的。$B$B<这封信额外印着希瓦娜斯·风行者的封印>"
D.Strings[117327]="$N，$B$B 血铸三叉矛的创造需要许多稀有又易变的材料，才能制作出最佳手工的可怕武器。我会将材料清单从最容易到最难取得的顺序排列。$B$B 别忘记你也一定要在材料被接受，开始铸造之前取得你的血骑士徽记。"
D.Strings[117328]="愤怒之血 - 为了恰当地锻炼武器的金属，它一定要在愤怒之血里被冷却。虽然大部份恶魔的血液都有实质力量，但普通的血却不足以铸造你的三叉矛。$B$B 谨慎询问奥格瑞玛的术士之后对寻找鲜血的补给有了帮助。怒焰裂谷里的燃刃祭司拥有一种充满鲜血的宝珠，那就是我们要制造你武器所需的东西。我听说那颗宝珠由一个自称祈求者耶戈什的兽人守卫着。$B$B 小心行动，所有和恶魔力量的往来都要注意。握有这样强大的物体时你永远也不知道会发生什么事。"
D.Strings[117329]="一箱血铸锭 - 只有一箱，钢铁是很好的金属，但由它铸造的武器则不值得注意。血铸锭代表一种极好的金属，而它的制作过程一直是个秘密。传说任何敢触碰并使用这个金属的铁匠都被诅咒了，但我们的工匠已证明这是个谬论。$B$B 这个金属的名声增加了它的稀有度，但被遗忘者却声称在影牙城堡可能有补给。一个叫做蓝登·史帝威尔技艺高超的铁匠非常好奇，便走私了一箱血铸锭。没人知道他把东西藏在哪里，但我们的消息告诉我们那名铁匠现在被囚禁在城堡的地下城里。用尽所有方法取得那箱血铸锭。"
D.Strings[117330]="一颗被污染的科尔宝石 - 博学者的墓碑记载着这些宝石曾被一些施法者用来保留他们的魔法能量，让他们更致命。虽然纯净的宝石可以安全地被中级施法者使用，但它们对我们的目的而言仍嫌太弱。$B$B 在黑暗深渊的洞穴中，纳迦施法者将科尔宝石注入他们自己的黑暗力量，增强它们的力量，以便在你的三叉矛中完美地被使用。在你弄到需要的宝石之前先无情的杀了他们。"
D.Strings[117331]="你将戴上的徽记最后一次是被晨星家族中一个勇敢无惧的血骑士所配戴。他典范的奉献是你在军队中生活的好预兆。$B$B 血骑士晨星对死亡之域的天灾军团要塞率领了一次大胆，但不成功的攻击。他的尸体就在他死去的地方安息，与我们最强劲的敌手锁在战斗中。找到他，$N，并将他的徽记带来给我。你的成功会为他，为你，为所有真正的血骑士带来荣耀。"
D.Strings[117332]="你发现了神殿的位置!进一步的检查之后，你感觉到一股更强大的陌生力量控制了岛屿。你觉得站在神殿旁有点不舒服……甚至有点心乱。   神殿旁的青铜色公告牌上写着:   「这是达斯雷玛神殿，对最高尚的精灵们致上最高的敬意。让所有景仰过这个纪念碑的人都会记得他对抗天谴军团的牺牲及对我们继续生存的事业贡献。所有让奎尔萨拉斯繁荣的人们也都感谢他。」"
D.Strings[117333]="我看着他们无情的鞭打他。他们残酷的中尉一举一动就好像残暴是正常的事一样。经过野蛮的鞭打之后，我可以感觉我已经崩溃了。 $B$B看着复仇者萨鲁安忍受他们的殴打，我开始哭泣。并不是因为害怕……而是因为悲伤。看到三头政治的德莱尼被这样对待。要是我能打破我的束缚就好了。要是可以的话……"
D.Strings[117334]="希隆娜丝计划把撒鲁安……  <由于作者死去，故事突然中断了。接下去的记录是一片空白。>"
D.Strings[117335]="女公爵·莉雅淳，$B$B 最近被俘虏的生物制造了一些麻烦，让我们一些最重要的装备遭到损坏。恢复一切的工作让我的博学者和资源都大大的减少。我已将事件报告呈交给大博学者洛摩斯，但他回覆的速度很慢。我担心没有下列的物品我们会被迫缩减运作，而你知道那对你的骑士们而言代表着什么。$B$B 如果你可以有任何的帮助，我已在下一页列好了材料清单。我们会感谢你的军队所能提供的任何协助。$B$B 博学者阿斯塔乐·血誓"
D.Strings[117336]="*40块符文布$B$B *6条奥金锭$B$B *10根太阳草$B$B *5个黑暗符文$B$B *150金"
D.Strings[117337]="太阳之王的公告  炎鹰部队——我亲爱而忠诚的孩子们——我为你们而骄傲。你们在艾泽拉斯世界中执行的任务对于我和主人来说都是至关重要的。  再过不久，风暴要塞的增援就将通过太阳之门到达秘血岛。  我们将夺取埃索达，干掉所有蓝皮肤的杂种。维伦将会为他的罪行付出代价。  - 太阳之王，凯尔萨斯·逐日者"
D.Strings[117338]="<HTML>$B<BODY>$B$B$B$B$B<H1 align=\"center\">荆棘谷的青山"
D.Strings[117339]="接下来的几年，在暴风城背叛了石匠公会後，艾尔加丁爵士开始厌恶他的贵族身份。他不愿因继承了他父亲的高贵血统而在贵族中获得崇高的地位。不过我离题了。这个故事的主题不是政治文章或者人物传记，而是要叙述我在荆棘谷的青山中猎捕的经历……"
D.Strings[117340]="他把枪重重地往手臂上抛。枪管歪向一边，正好落在艾耶克的枪下面。艾耶克选了精确的时机扣下她的扳机。来福枪的准心笨拙地锁定在林木线上，发出一声清楚的巨响。一群小鸟从天空中尖叫着飞过，分散在各个方向。一条羽状的烟雾从树中往天上划过。我们畏怯地看着巨大的树枝直直地掉落在逃跑的猎豹身上，压断了牠的背。"
D.Strings[117341]="我们一路狂奔回到了营地，丝毫不敢放慢速度。深夜，我们围着篝火静静地坐在一起，大家心里都明白，我们是被奇异的命运所拯救，这就是狩猎高手活动所带来的风险:我们在和命运玩游戏。然而，我们之中的每一个人都可能会在未来的某一时刻面对命运严峻的考验。我这个老矮人感到高兴的是，这一时刻并非发生在荆棘谷的青山中。$B$B--完--"
D.Strings[117342]="蠢货，$B$B去找食物。蓝色的味道很好。兰特瑞索说找到蓝色的就行。把食物带回去给拉普。他吃了后蠢货再吃。没问题吧？动作快一些，否则拉普会把你吃掉的。$B$B - 拉普"
D.Strings[117343]="(1)酒鬼拉利克：巨魔。他从未离开小酒店。很坏。很丑。很胖。很坏。又很胖。$B$B [下一页]"
D.Strings[117344]="(2)库库许：这个从赞格沼泽来的讨厌小孢子人在赞格沼泽和泰洛卡的边界有一个蘑菇园。在“那是什么味道”的游戏中输了很多金子给沙萨拉毕恩。想用叫做空茎的蠢蘑菇付给沙萨拉毕恩。跟他说这跟黄金一样好!哈!$B$B [下一页]"
D.Strings[117345]="(3)服伦：阿拉卡。输给沙萨拉毕恩许多金子。鸟人因为没有付钱就被沙萨拉毕恩杀死了。现在鬼魂鸟人在白骨荒野的西南方走着。"
D.Strings[117346]="奥莱姆贝根茎是泰洛卡森林里一种普遍的根茎植物。到构成泰洛卡森林的奥莱姆贝树丛附近搜寻向上翻起的根茎。$B$B 沼泽莓只生长在赞格沼泽。只能在安格拉斯要塞找到它，就在沼泽的西北区。小心那些守卫珍贵莓子的巨魔。$B$B 泰拉蕊藻叶或许是这清单上最容易取得的草药。你可以在泰拉蕊盆地的卡拉达尔南方找到藻叶。它们生长在水边。$B$B 清单上最后一种草药是剑刃山脉特有的植物。你可以在赞格沼泽北边找到剑刃山脉。龙脊生长在守卫着剑刃山脉峡谷的锯齿状岩石地形尽头。等你见到了剑刃山脉就会知道我在说什么了。那个岩石地形就像是一排排的尖锐牙齿。"
D.Strings[117347]="我的仆人，这些兽人正遇上一个小小的麻烦，我想要你亲自去搞定它，我们的部队正在进攻黑暗之门的守卫，他们的精力都被浪费在了萨尔玛。这是命令！——阿拉修斯"
D.Strings[117348]="要让饮用者看见彩色幻象的亡灵，就一定要收集到一些特定的材料。$B$B 首先，西纳葛兰的山地古罗眼球，靠近燃烧军团被诅咒的炼冶场，战锤山丘南方。$B$B 在西纳葛兰也可以找到巨型风翼猫头鹰。只有完美的品种才行!$B$B 最后，在纳葛兰西边和西南边有老迈的裂蹄油。$B$B 收集这些物品再回来找我!动作快!$B$B -奈崔恩"
D.Strings[117349]="<翻过数页你根本无法理解的“科学论文”后，最后一页末有几行字迹潦草的记录……>  对不起，老大。看起来虚空风暴即将要爆炸，这场爆炸会席卷外域的大部分地区。  我不能完全肯定，但我想这应该和血精灵在法力熔炉所做的一切有关。  幸好您建造了一艘火箭！  - 哥白尼  又及，我能与您一起离开吗？在您经过扭曲虚空的时候一定会需要一个虚空学家的！"
D.Strings[117350]="将军，$B$B我们正守住命运阶梯的战线，但军团派出了一波又一波的人马来攻击我们军队。他们在附近一定有个集结地是我们侦察兵尚未找到的。虽然这里的联盟军队是站在我们的阵线，我担心军团的众多数量会超出我们的防御。尽量伸出你的援手，否则传送门瘫痪 - 我们就要永远被困在这个梦魇世界了。$B$B欧莱恩中将"
D.Strings[117351]="当纳尼滑上来时，这位沧桑的战士给了她一个严厉的眼神。“我想你待在这里是为了搜集杀死鱼人的奖励吧?”$B$B 她的眼神移到了他身边闪亮的阔剑。“马库斯，这要看奖励是什么。”她玩弄着她的头发，假装没有注意到他对她的存在感到不自在。“我可能并不想要这个奖励。”"
D.Strings[117352]="马库斯走向她，恐惧与愤怒的情绪交织地站着。“这个奖励是没得商量的!”他稍微停顿，整理一下紧张的心情，然后逼近她娇小的身躯。他们的双唇火热地交缠着，激情的气息满溢，融化了她的冰霜护甲法术。$B$B “所以，这个任务有下一个步骤吗?”她的双眼闪着兴奋的光芒，挑逗着他。$B$B <这样的情节持续了数百页，完全没有任何进一步的剧情。>"
D.Strings[117353]="这个奇怪的物体看起来有点像是一个工程学的装置，但应该是你之前从未见过的装置。  从它的外表上看，不管你觉得它是什么东西，它一定是已经被使用过的。  从附近的尸体来看，你不由得认为它就是这一切惨剧的罪魁祸首。"
D.Strings[117354]="指挥官，$B$B 这个密码要被送到祖鲁希德那里。在进一步的通知之前，这个物品必须在他的保管之下。$B$B -伊利丹王怒风"
D.Strings[117355]="<HTML> <BODY> <BR/> <H1 align=\"center\">上层精灵的挽歌</H1> <BR/> <IMG src=\"InterfaceFlavorImagesBloodElfLogo-small\"/> </BODY> </HTML>"
D.Strings[117356]="<HTML> <BODY> <BR/> <P>简略翻译版……</P> <BR/> <P>以光芒之名，以太阳的光芒之名，</P> <P>血之后裔们啊，</P> <P>敌人正长驱直入。</P> <P>血之后裔们啊，</P> <P>以光芒之名，</P> <P>消亡的血之后裔啊，</P> <P>敌人正长驱直入。</P> <P>啊，血之后裔们啊，</P> <P>以太阳的光芒之名。</P> <P>消亡的血之后裔们啊，</P> <P>他们正长驱直入。</P> <P>啊，血之后裔们啊，</P> <P>以太阳的光芒之名。</P> <P>太阳的光芒。</P> </BODY> </HTML>"
D.Strings[117357]="<HTML> <BODY> <BR/> <P>萨拉斯语版本……</P> <BR/> <P>Anar'alah, anar'alah belore,</P> <P>Sin'dorei,</P> <P>Shindu fallah na.</P> <P>Sin'dorei,</P> <P>Anar'alah,</P> <P>Shindu sin'dorei,</P> <P>Shindu fallah na.</P> <P>Sin'dorei,</P> <P>Anar'alah belore.</P> <P>Shindu sin'dorei,</P> <P>Shindu fallah na.</P> <P>Sin'dorei,</P> <P>Anar'alah belore,</P> <P>Belore.</P> </BODY> </HTML>"
D.Strings[117358]="亲爱的大臣，$B$B 把暗影之月的巨人们带到峡谷的任务现在已经落在了你的肩上，运用你血精灵的魅力，使他们用我的方式看事情。如果你无法做到这一点，就把他们杀得鸡犬不留……$B$B 伊利丹·怒风"
D.Strings[117359]="无论如何，圣骑士的行为必须与圣光对应，圣光是我们力量的来源。我们其中的一员为了神而奋战，并不代表我们为了神性而奋战，我们一切的行动都是为了努力追求至善。"
D.Strings[117360]="就算在这个艰困的时局中被号召前来打击邪恶，你必须永远记住，帮助别人才会真正地让你与众不同。同情心，耐心与勇气就是圣骑士作战时的最大力量。$B$B清楚地了解这个道理，永远也不要忘记。"
D.Strings[117361]="免责声明。  试飞员对使用风动电容器（以下简称“设备”）的过程中可能引发的粉碎性骨折、触电身亡、重要器官损伤、被当地野兽吞食、时间和/或空间幻觉等致伤、致残或者死亡事件表示完全理解。试飞员自愿进入设备，并自愿承担上述风险。  试飞员同意，如果$g他:她;不幸罹难，将免除并永远放弃对塔利·萨普纳波及其家人提起诉讼的权利；并同意将$g他:她;的遗体捐献给萨普纳波进行研究。  签名： ___$n"
D.Strings[117362]="您好，学有所成的安拓维奇：$B$B 我希望你能在萨尔玛收到这封信，并且对你的研究有所帮助。虽然我还是希望能回到幽暗城，因为那边有全面性的工具与仆人可以协助我，但是我在断脊氏族的关系已经足以应付我的实验。$B$B 啊，死者的挽歌。$B$B 顺道一提，我有一些有趣的消息---$N从地狱兽人身体上采集的血液出现了恶魔腐化的浓缩体。这几乎与原来艾泽拉斯上受到恶魔腐化的地狱兽人完全相同……玛诺洛斯的腐化之血。$B$B 玛诺洛斯的影响不可能来到外域，这个地狱领主已经死了好几年了，但是，我担心有另外一个地狱领主正在此地肆虐。一个有着玛诺洛斯力量的地狱领主……一个可以腐化本地兽人的存在。$B$B 我会继续我对血之谷鲜血的研究，但是我极需你去追捕那个目标。我害怕这个目标将会引导你深入地狱火堡垒。$B$B 你勤奋好学的，$B 药剂师艾柏瑞克"
D.Strings[117363]="$N，  诅咒密码事实上是一组十分强大的咒文。它代表着古老的混沌力量，我们的世界那边的多起重大惨剧都与这组密码有关。是的，这也就是说，它并非是德拉诺所独有的。$B$B这个燃烧着的火焰符号代表凯尔萨斯，他渊博的古文知识可以完全理解这一切。$B$B你的发现已经惊动了纳鲁，阿达尔邀请你前往沙塔斯城与他会面。请你立刻到这里来，我们可以在圣光广场会面。  你谦恭的朋友，  卡德加"
D.Strings[117364]="安拓维奇，$B$B 首先，让我们来说说你上一个派来的人，$n，$g他:她;在工作上的表现已经远超过我的预期了。我已经占据了$g他:她;的身体，并且用$g他:她;的手来写这封信。这对我来说是多大的享受啊，我希望有一天我能有幸占据你的身体，强大的巫医!$B$B 所以，你要求我所做的报告如下：在地狱火堡垒内肆虐的恶魔比我过去遭遇过的强大许多。我猜想在第三次大战时着名的地狱领主玛诺洛斯就掌握了同样的力量，但拥有这股力量的生物屈指可数。然而，我感觉到有一股禁锢之风围绕着这个恶魔。如果它做出了违背其意愿的事情，我一点都不会感到惊讶，也许他是被囚禁或是在更强大的力量控制之下。$B$B 时间会证明一切的…………"
D.Strings[117365]="在地狱火堡垒的高墙内，我也感觉到命运的移转，就像他们说的一样，时间会证明一切。$B$B 你将会在此见识到恶魔的面容，来自艾泽拉斯的外来者，那里的繁茂生机，对于我来说就像是充满圣光与生命的地狱。如果你能允许我用比喻的话，你会明白在地狱火堡垒中的邪恶生物，只不过是巨大冰山的一角。$B$B 喔，在我面前的是一场多么荣耀的战斗啊!也许只有我可以品尝到即将被执行的痛苦与恐怖!$B$B 呃，我应该结束我们之间乏味的对话，并且让你慢慢想清楚以下的文字，亲爱的药剂师：你的身体可能是死的，安拓维奇，但是你的灵魂仍然十分完整，在你的防守发生失误，并且让我有机会接近你的那天，我应该啃食你的灵魂，并且在极佳的开胃菜搭配下，尽情的享用!如果必须的话，我会等到审判的第四天，但是，你会是我的!$B$B 晚安,$B -D"
D.Strings[117366]="自从你离开永恒树林后，我继续进行乌鸦圣典的研究，并发现一些有助于你打败乌鸦神的资讯。   解放这些灵魂已经将他们跟你绑束在一起，因此我认为他们可以自由的在对抗乌鸦神的战斗中提供他们的协助。   当你第一次解放灵魂时，他们将会处于休眠状态，因为他们几世纪以来都是如此。使用你的持续性疗愈法术，你可以以能量灌注他们，给予他们生命并在战斗中得到他们的协助。当魔法消退，他们将回复休眠状态。   接下来就是一系列我对每个鸟灵的注记:"
D.Strings[117367]="猎隼灵魂  猎隼灵魂充满了惊人的速度跟敏捷，在阿拉卡所关注的猎人技术当中受到高度的重视。如果你以持续性疗愈法术给予灵魂能量，它将赋予你于法术施放及近身战斗方面有一定程度的速度。"
D.Strings[117368]="战鹰灵魂  阿拉卡传统将战鹰灵魂配置得不似它的猎隼兄弟一样迅速，不过它所掌管却是狩猎中最高超的技术。如果你使用持续性疗愈法术使他从休眠中苏醒，战鹰灵魂将会使用它的技术来对抗你的敌人。   。"
D.Strings[117369]="猎鹰灵魂  石板上谈到很多有关猎鹰的事，好像他曾经是乌鸦的盟友。一个远古阿拉卡的复仇符号，猎鹰灵魂常常被罪恶的受害者召唤。使用持续性疗愈法术来唤醒这个灵魂将会使你能够分享它的力量，毁坏那些伤害你的人。"
D.Strings[117370]="以我们伟大主人之名……伊利丹大人万岁！  莫格霍尔：  我现在将这个废物派遣给你，让他在你那里继续为伊利丹大人效力。他没有成为死亡骑士的才能，不过，或许具备学习你那些能力的潜质。殴打他，羞辱他，去得到他的服从吧。让他成为一名真正的伊利达雷战士。  假如他失败了的话……那么一切都归咎于他自身的懦弱与愚蠢……那时候直接抛弃他好了。把他扔进深渊！  死亡骑士领主，塔隆·血魔"
D.Strings[117371]="不要绝望。你的特殊巨魔就在那里的某个地方。"
D.Strings[117372]="放下你的剑，你的槌，和你的矛。水晶告诉我们给和平一次机会。"
D.Strings[117373]="你不用怕一个满脑子啤酒的人!"
D.Strings[117374]="三个臭皮匠胜过一个诸葛亮!然后你就会永远都有朋友。"
D.Strings[117375]="智慧有很多种表现，但它永远源自水晶。"
D.Strings[117376]="正面点思考!一个人的垃圾会是另一个人的珍宝。"
D.Strings[117377]="你明天会遇到一个特别的人，所以记住:和蔼可亲会比拳打脚踢为你带来更多朋友。"
D.Strings[117378]="幸运号码: 13 9 17 4 n"
D.Strings[117379]="你跳舞的动作让大家脸上都浮现一抹微笑。"
D.Strings[117380]="你很特别，不管你的朋友，亲戚，同事，路上的陌生人，或是你的良心是怎么告诉你的"
D.Strings[117381]="当所有人都失败的时候，就是你大展身手的时候。"
D.Strings[117382]="酒醉就离天国不远了。"
D.Strings[117383]="警告:内脏不适人类食用。"
D.Strings[117384]="你被天空中最棒的金属之手选中!现在快去工作。"
D.Strings[117385]="让沉睡的古罗死去。"
D.Strings[117386]="这则讯息是欧格利拉开发委员会带给你的。加基森制造"
D.Strings[117387]="生命的意义是......(剩下的讯息意外地被吃掉了。)"
D.Strings[117388]="抱歉，这次你不是赢家。请再玩一次"
D.Strings[117389]="你今天会树敌，并立刻杀了它。"
D.Strings[117390]="寻找生命中更崇高的一条道路。在那条路上，你可以避开一些鄙恶之人"
D.Strings[117391]="以我们伟大主人之名……伊利丹大人万岁！  这些灵魂火炮的一般零件都是直接由各类工匠直接制造出来的。比如，技师和矿工能供应魔钢锭、氪金能量核心和精金框架给你。  但如果要想得到完美的奥术精华，就要去泰罗卡森林了。在森林中央那处部落据点裂石堡的上方有一面湖泊——尤鲁恩湖，你可以在那里找到一位名叫萨提斯的鸦人，他被放逐了，躲避在那里。  去和他谈谈，然后把你的需要告诉他。记得说明是我派你去的，因为他欠我不少东西，这么说肯定对你有所帮助。  之后，按照萨提斯说的去做，你就一定能得到精华。  - 巴塔斯"
D.Strings[117392]="在我的记忆中，利爪之王艾吉斯总是随身携带着泰罗克的羽毛。他将这羽毛视为自身王权的象征，或许还用来向他的追随者显示他就是泰罗克的转世。$B$B而我的兄弟黑暗编织者塞斯则一直戴着泰罗克的面具，领导着大厅内的塞泰克仪式。$B$B至于泰罗克的传说，则一直保存在利爪之王艾吉斯自己的房间旁边的一处宝库里，放置在数个符石组成的法阵中央。"
D.Strings[117393]="玛诺洛斯的影响范围没有那么大，绝对不可能达到外域。再说了，那只巨兽早就已经死了。所以，我认为这里恐怕还有其他的深渊领主，而且至少是玛诺洛斯那一级别的深渊领主……强大到足以腐蚀这里的兽人。  我会继续研究我手中的血环氏族血样，不过，我也建议你继续追究调查下去。根据我的推测，线索应该会将你领向地狱火堡垒的深处。  你睿智的顾问， 药剂师阿尔布雷克"
D.Strings[117394]="听着，霸德!$B$B这是最後一个我送去给你的傻瓜，除非你把欠债付清。$B$B不准再拖延了!$B$B格利夫塔"
D.Strings[117395]="加尔恩，$B$B我应该不需要提醒你，你的任务有多重要 -- 不计代价保护你珍贵的货物。如我所承诺过，成功与谨慎将会获得财富的回报。$B$B别对你的「夥伴」饶舌，看紧那些船员，那一切都会很顺利。我等着你成功的消息。"
D.Strings[117396]="我送去了一批可观的武力给你，长老，但你一定要小心注意你的活动。你的首要目标就是终止联盟对我们土地的扩张。某些为数不少的人类已经开始在贫瘠之地的边境上构筑一个巨大建筑物。$B$B一定要让他们知道自己在可悲的塞拉摩边界之外并不受欢迎。最後，告诫你一句话，长老:别让你的计画给蕨墙村的那些巨魔知道。那些野蛮的东西连最低程度的谨慎都办不到。$B$B - 亚加席姆"
D.Strings[117397]="我这辈子亲眼看过最可怕的生物就是泰瑟尔。我只看过那个怪物一次，我想我是真的够幸运才能活下来!$B$B那是个黑暗而且风暴肆虐的夜晚。大海翻腾，暴雨交加，塞拉摩灯塔的光线几乎看不见。我们尽力地往灯塔前进，突然间，那只恶兽就从波涛间冲向我们的船只!"
D.Strings[117398]="这个强大的生物张开血盆大口，向我们的船吐出冰弹，可怕的爪子抓住船弦，把船往山上撞击，水手和货物都被震到了海里，船也被撞成碎片，$B$B我能记得的最后一件事就是从断裂的船体里飞出来，掉到了海水中，被海浪淹没，世界变成漆黑一片，我想我就这么玩完了。当我醒来的时候，我正躺在塞拉摩的医务室里，我知道得有人把我们的经历讲出来。$B"
D.Strings[117399]="那个强大的怪物张开牠的血盆大口，对我们的船舰喷出冰冷的水箭。牠恐怖的大嘴一咬就把船头给咬了下来，扯裂了船体。水手与货物被猛力地甩离船，船只的残骸接着就被波涛所吞没。$B$B我记得的最後一件事，就是从破裂的船身上腾飞出去，接着摔进漆黑的大海中，在大浪间载沉载浮。世界逐渐变得黑暗，我想我咽下了我最後一口气。等我在塞拉摩的医院醒来时，我知道有人得说出我们的故事。"
D.Strings[117400]="小孩:乔艾与吉娜。妻子:苏珊娜"
D.Strings[117401]="刻在箱子侧的是预言符文…"
